           (Test-R47Provenance $r47u3c 'G-R47-CHUNK' 'G-R47' $r47Chunk '0') -and ($r47u3.rep.fields_passed -eq '31'))
$r47Rows += Format-R2xRow -Id 'U3 one write, two TALLY lines' -RowOk $r47ok3 -Said (Get-R47Said $r47u3) `
    -Text ("tally file [{0}]  (expect chunk=one, chunk=two, then EXIT tally_count=2)" -f ($r47u3c.tallyLines -join ' || '))

# ---- U4: an INDENTED and a MID-LINE TALLY are not counted (the controls) --------------------------
$r47u4 = Invoke-R47Helper -Label 'u4-controls' -Helper $r47Cured -Instrument $r47Controls -Root $r47RootU -RunKey 'G-R47-CTL' -Goal 'G-R47'
$r47Runs += $r47u4
$r47u4c = $r47u4.cap
$r47u4NotCounted = (-not $r47u4c.tallyText.Contains('passed=900')) -and (-not $r47u4c.tallyText.Contains('passed=901'))
$r47u4Kept = ($null -ne $r47u4c.body) -and $r47u4c.body.Contains('  TALLY passed=900') -and $r47u4c.body.Contains('echo TALLY passed=901')
$r47ok4 = ($r47u4.reported -and (Test-R47EveryTally $r47u4c $r47ExpCtl) -and (Test-R47ExitBeside $r47u4c '0' '1') -and
           $r47u4NotCounted -and $r47u4Kept -and ($r47u4.rep.tally_count -eq '1') -and ($r47u4.rep.fields_passed -eq '41'))
$r47Rows += Format-R2xRow -Id 'U4 indented + mid-line TALLY are controls' -RowOk $r47ok4 -Said (Get-R47Said $r47u4) `
    -Text ("tally file [{0}] indented/mid-line kept OUT of the tally file={1} and kept IN the verbatim body={2}  (expect column0=yes then EXIT tally_count=1, True, True)" -f `
           ($r47u4c.tallyLines -join ' || '), $r47u4NotCounted, $r47u4Kept)

# ---- U5 / U6: SILENT exit 0 and SILENT exit 5 -- the silence is STATED ---------------------------
$r47u5 = Invoke-R47Helper -Label 'u5-silent0' -Helper $r47Cured -Instrument $r47Silent0 -Root $r47RootU -RunKey 'G-R47-SIL0' -Goal 'G-R47'
