           ($r47u5c.first -ceq 'NO-TALLY exit_code=0') -and ($r47u5c.tallyLines.Count -eq 2) -and (Test-R47ExitBeside $r47u5c '0' '0') -and
           (Test-R47Provenance $r47u5c 'G-R47-SIL0' 'G-R47' $r47Silent0 '0') -and (Test-R47Clean $r47u5c) -and ($r47u5.rep.lastexitcode -eq '0'))
$r47Rows += Format-R2xRow -Id 'U5 silent, exit 0' -RowOk $r47ok5 -Said (Get-R47Said $r47u5) `
    -Text ("sentence stated={0} header body_bytes={1} tally file [{2}] lastexitcode={3}  (expect True, 0, NO-TALLY exit_code=0 then EXIT exit_code=0, 0)" -f `
           $r47u5c.statement, $r47u5c.header['body_bytes'], ($r47u5c.tallyLines -join ' || '), $r47u5.rep.lastexitcode)
# U6 IS THE DETECTOR'S LITERAL LINE: $null = Save-LamInstrumentRun ..., then $LASTEXITCODE.
$r47u6 = Invoke-R47Helper -Label 'u6-silent5' -Helper $r47Cured -Instrument $r47Silent5 -Root $r47RootU -RunKey 'G-R47-SIL5' -Goal 'G-R47' -Shape 'detector'
$r47Runs += $r47u6
$r47u6c = $r47u6.cap
$r47ok6 = ($r47u6.reported -and (Test-R47Stated $r47u6c) -and ($r47u6c.header['body_bytes'] -eq '0') -and
           ($r47u6c.first -ceq 'NO-TALLY exit_code=5') -and (Test-R47ExitBeside $r47u6c '5' '0') -and
           (Test-R47Provenance $r47u6c 'G-R47-SIL5' 'G-R47' $r47Silent5 '5') -and (Test-R47Clean $r47u6c) -and ($r47u6.rep.lastexitcode -eq '5'))
$r47Rows += Format-R2xRow -Id 'U6 silent, exit 5, detector call shape' -RowOk $r47ok6 -Said (Get-R47Said $r47u6) `
    -Text ("sentence stated={0} header body_bytes={1} exit_code={2} tally file [{3}] LASTEXITCODE after return={4}  (expect True, 0, 5, NO-TALLY exit_code=5 then EXIT exit_code=5, 5)" -f `
           $r47u6c.statement, $r47u6c.header['body_bytes'], $r47u6c.header['exit_code'], ($r47u6c.tallyLines -join ' || '), $r47u6.rep.lastexitcode)

# ---- U7: a TALLY carrying pytest_exit=0 from an instrument that EXITS 7 ---------------------------
$r47u7 = Invoke-R47Helper -Label 'u7-exit7' -Helper $r47Cured -Instrument $r47Exit7 -Root $r47RootU -RunKey 'G-R47-EXIT7' -Goal 'G-R47'
