$r47Runs += $r47u7d
$r47ok7 = ($r47u7.reported -and $r47u7d.reported -and (Test-R47EveryTally $r47u7c $r47ExpExit7) -and (Test-R47ExitBeside $r47u7c '7' '1') -and
           (Test-R47Provenance $r47u7c 'G-R47-EXIT7' 'G-R47' $r47Exit7 '7') -and ($r47u7.rep.exit_code -eq '7') -and ($r47u7.rep.lastexitcode -eq '7') -and
           ($r47u7d.rep.lastexitcode -eq '7') -and (Test-R47ExitBeside $r47u7d.cap '7' '1') -and (-not $r47u7c.last.Contains('pytest_exit')))
$r47Rows += Format-R2xRow -Id 'U7 TALLY pytest_exit=0, instrument exit 7' -RowOk $r47ok7 -Said (Get-R47Said $r47u7) `
    -Text ("tally file [{0}] header exit_code={1} LASTEXITCODE object/detector shape={2}/{3}  (expect the TALLY line then EXIT exit_code=7 -- never 0; 7; 7/7)" -f `
           ($r47u7c.tallyLines -join ' || '), $r47u7c.header['exit_code'], $r47u7.rep.lastexitcode, $r47u7d.rep.lastexitcode)

# ---- U8: the CONTROL that prints the sentence -- body_bytes tells the two apart -------------------
$r47u8 = Invoke-R47Helper -Label 'u8-says' -Helper $r47Cured -Instrument $r47Says -Root $r47RootU -RunKey 'G-R47-SAYS' -Goal 'G-R47'
$r47Runs += $r47u8
$r47u8c = $r47u8.cap
$r47ok8 = ($r47u8.reported -and $r47u8c.statement -and ([int]$r47u8c.header['body_bytes'] -gt 0) -and ([int]$r47u8.rep.body_bytes -gt 0) -and
           ($r47u8c.bodySha -eq $r47u8c.header['body_sha256']) -and ($r47u8c.first -ceq 'NO-TALLY exit_code=0'))
$r47Rows += Format-R2xRow -Id 'U8 control: an instrument PRINTS the sentence' -RowOk $r47ok8 -Said (Get-R47Said $r47u8) `
    -Text ("sentence present={0} header body_bytes={1} body sha matches header={2}  (expect True, >0, True -- a printed sentence is not a silent run)" -f `
