$r47u9Bound = @($r47u9c.tallyLines | Where-Object { $_ -cmatch '^BOUND tally_lines_kept=64 tally_count=100 ' })
$r47ok9 = ($r47u9.reported -and ($r47u9Tally.Count -eq 64) -and ($r47u9Tally[0] -ceq 'TALLY seq=1') -and ($r47u9Tally[63] -ceq 'TALLY seq=64') -and
