           $r47u9Tally.Count, $r47u9Bound.Count, $r47u9c.tallyLines.Count, $r47u9.rep.tally_count)

# ---- U10: an ORPHAN -- a stale capture of another key keeps its own key and captured_at -----------
# The second detector's key (G-R47-ORPH.2) is written first; the first detector's key is written
# after it WITHOUT cleaning, which is what a goal that lost its second detector leaves on disk.
$r47u10a = Invoke-R47Helper -Label 'u10-orphan-old' -Helper $r47Cured -Instrument $r47Two -Root $r47RootU -RunKey 'G-R47-ORPH.2' -Goal 'G-R47-ORPH'
$r47u10b = Invoke-R47Helper -Label 'u10-orphan-new' -Helper $r47Cured -Instrument $r47Three -Root $r47RootU -RunKey 'G-R47-ORPH' -Goal 'G-R47-ORPH'
$r47Runs += $r47u10a
$r47Runs += $r47u10b
$r47u10Stale = Read-R47Capture -Paths (Get-LamInstrumentRunPath -MissionRoot $r47RootU -InstrumentPath $r47Two -RunKey 'G-R47-ORPH.2' -Goal 'G-R47-ORPH')
$r47u10New   = $r47u10b.cap
$r47u10AtOld = ConvertFrom-R47Utc $r47u10Stale.header['captured_at']
$r47u10AtNew = ConvertFrom-R47Utc $r47u10New.header['captured_at']
$r47ok10 = ($r47u10a.reported -and $r47u10b.reported -and
            (Test-R47Provenance $r47u10Stale 'G-R47-ORPH.2' 'G-R47-ORPH' $r47Two '1') -and (Test-R47Provenance $r47u10New 'G-R47-ORPH' 'G-R47-ORPH' $r47Three '0') -and
            ($null -ne $r47u10AtOld) -and ($null -ne $r47u10AtNew) -and ($r47u10AtOld -lt $r47u10b.t0) -and ($r47u10AtNew -ge $r47u10b.t0) -and
            (Test-R47ExitBeside $r47u10Stale '1' '2') -and (Test-R47ExitBeside $r47u10New '0' '3') -and
            ($r47u10Stale.exit.at -cne $r47u10New.exit.at) -and ($r47u10Stale.path -ne $r47u10New.path))
$r47Rows += Format-R2xRow -Id 'U10 orphan: stale key beside a fresh one' -RowOk $r47ok10 -Said (Get-R47Said $r47u10b) `
    -Text ("stale run_key={0} captured_at={1} (before the fresh run began={2}) fresh run_key={3} captured_at={4}; each tally file pairs with its own header={5}  (expect G-R47-ORPH.2, older, True, G-R47-ORPH, newer, True)" -f `
           $r47u10Stale.header['run_key'], $r47u10Stale.header['captured_at'], ($r47u10AtOld -lt $r47u10b.t0), $r47u10New.header['run_key'], $r47u10New.header['captured_at'],
           ((Test-R47ExitBeside $r47u10Stale '1' '2') -and (Test-R47ExitBeside $r47u10New '0' '3')))

# ---- U11: HEADER INJECTION through Goal and RunKey --------------------------------------------------
$r47InjKey  = "K-R47-INJ`nTALLY passed=998 failed=0 skipped=0`nFAILED y::forged"
$r47InjGoal = "G-R47-INJ`r`nTALLY passed=999 failed=0 skipped=0`r`nFAILED x::forged"
$r47InjKeyScrub  = $r47InjKey -replace "[`r`n]", ' '
$r47InjGoalScrub = $r47InjGoal -replace "[`r`n]", ' '
$r47u11 = Invoke-R47Helper -Label 'u11-inject' -Helper $r47Cured -Instrument $r47Exit7 -Root $r47RootU -RunKey $r47InjKey -Goal $r47InjGoal
$r47Runs += $r47u11
$r47u11c = $r47u11.cap
$r47u11Forged = @($r47u11c.tallyLines | Where-Object { ($_ -match 'passed=99[89]') -or ($_ -cmatch '^FAILED') }).Count
$r47u11Recorded = $r47u11c.text.Contains('TALLY passed=999') -and $r47u11c.text.Contains('FAILED y::forged')
$r47ok11 = ($r47u11.reported -and ($r47u11c.col0Tally -eq 1) -and ($r47u11c.col0Failed -eq 0) -and ($r47u11Forged -eq 0) -and $r47u11Recorded -and
            (Test-R47Provenance $r47u11c $r47InjKeyScrub $r47InjGoalScrub $r47Exit7 '7') -and (Test-R47EveryTally $r47u11c $r47ExpExit7) -and
            (Test-R47ExitBeside $r47u11c '7' '1') -and ($r47u11.rep.fields_passed -eq '3') -and ($r47u11.rep.failed_ids -ceq ''))
$r47Rows += Format-R2xRow -Id 'U11 CR/LF + TALLY/FAILED injected via key/goal' -RowOk $r47ok11 -Said (Get-R47Said $r47u11) `
    -Text ("column-0 TALLY lines in stdout file={0} column-0 FAILED={1} forged lines in tally file={2} injected text still RECORDED inside header values={3} header CR={4} fields.passed={5}  (expect 1, 0, 0, True, 0, 3)" -f `
           $r47u11c.col0Tally, $r47u11c.col0Failed, $r47u11Forged, $r47u11Recorded, $r47u11c.headerCr, $r47u11.rep.fields_passed)

# ---- U12: a MissionRoot that cannot be written -- no throw, exit code intact -----------------------
$r47u12 = Invoke-R47Helper -Label 'u12-unwritable' -Helper $r47Cured -Instrument $r47Silent5 -Root $r47NotDir -RunKey 'G-R47-NOWRITE' -Goal 'G-R47'
$r47Runs += $r47u12
$r47ok12 = ($r47u12.reported -and ($r47u12.rep.persisted -eq 'False') -and ($r47u12.rep.persist_note -like 'not persisted:*') -and
            ($r47u12.rep.exit_code -eq '5') -and ($r47u12.rep.lastexitcode -eq '5') -and ($r47u12.rep.body_bytes -eq '0') -and (-not $r47u12.cap.exists))
$r47Rows += Format-R2xRow -Id 'U12 unwritable MissionRoot' -RowOk $r47ok12 -Said (Get-R47Said $r47u12) `
    -Text ("returned={0} persisted={1} exit_code={2} LASTEXITCODE={3}  (expect True, False, 5, 5 -- persistence is a side effect)" -f `
           $r47u12.reported, $(if ($r47u12.reported) { $r47u12.rep.persisted } else { '(none)' }), $(if ($r47u12.reported) { $r47u12.rep.exit_code } else { '(none)' }), $(if ($r47u12.reported) { $r47u12.rep.lastexitcode } else { '(none)' }))

# ---- U13: ONE EMPTY LINE -- body_bytes 0, and the sentence says an empty line, never silence -------
$r47u13 = Invoke-R47Helper -Label 'u13-blank1' -Helper $r47Cured -Instrument $r47Blank1 -Root $r47RootU -RunKey 'G-R47-BLANK' -Goal 'G-R47'
$r47Runs += $r47u13
$r47u13c = $r47u13.cap
$r47u13Told = ($null -ne $r47u13c.body) -and $r47u13c.body.Contains($r47EmptyLineNeedle) -and (-not $r47u13c.body.Contains($r47Statement))
$r47ok13 = ($r47u13.reported -and $r47u13Told -and ($r47u13c.header['body_bytes'] -ceq '0') -and ($r47u13.rep.body_bytes -eq '0') -and
            (Test-R47NoTally $r47u13c '0') -and (Test-R47ExitBeside $r47u13c '0' '0') -and
            (Test-R47Provenance $r47u13c 'G-R47-BLANK' 'G-R47' $r47Blank1 '0') -and (Test-R47Clean $r47u13c) -and ($r47u13.rep.lastexitcode -eq '0'))
$r47Rows += Format-R2xRow -Id 'U13 one empty line is not silence' -RowOk $r47ok13 -Said (Get-R47Said $r47u13) `
    -Text ("header body_bytes={0} sentence says one empty line={1} silence sentence present={2} tally file [{3}]  (expect 0, True, False, NO-TALLY exit_code=0 then EXIT exit_code=0)" -f `
           $r47u13c.header['body_bytes'], $(if ($null -ne $r47u13c.body) { $r47u13c.body.Contains($r47EmptyLineNeedle) } else { '(no body)' }), $r47u13c.statement, ($r47u13c.tallyLines -join ' || '))

# ---- U14: A 5038-CHARACTER TALLY LINE -- the tally file keeps 2048 of it and SAYS so --------------
$r47u14 = Invoke-R47Helper -Label 'u14-long' -Helper $r47Cured -Instrument $r47Long -Root $r47RootU -RunKey 'G-R47-LONG' -Goal 'G-R47'
$r47Runs += $r47u14
$r47u14c = $r47u14.cap
$r47u14First = [string]$r47u14c.first
$r47u14Cut = ($r47u14First.Length -gt 2048) -and $r47u14First.StartsWith($r47LongWhole.Substring(0, 2048), [System.StringComparison]::Ordinal) -and
             ($r47u14First.Substring(2048) -cmatch '\A \[TRUNCATED [^=\]]*\b5038 characters\b[^=\]]*\b2048\b[^=\]]*\]\z')
$r47u14Tally = @($r47u14c.tallyLines | Where-Object { $_ -cmatch '^TALLY ' })
$r47ok14 = ($r47u14.reported -and $r47u14Cut -and ($r47u14Tally.Count -eq 2) -and ($r47u14Tally[1] -ceq $r47LongShort) -and ($r47u14c.tallyLines.Count -eq 3) -and
            (Test-R47ExitBeside $r47u14c '0' '2') -and ($r47u14c.tallyText.Length -lt 4096) -and
            ($r47u14.rep.tally_line -ceq $r47LongWhole) -and ($r47u14.rep.fields_passed -eq '9') -and ($r47u14.rep.tally_lines -ceq ($r47u14First + [string][char]10 + $r47LongShort)) -and
            ($null -ne $r47u14c.body) -and $r47u14c.body.Contains($r47LongWhole) -and
            (Test-R47Provenance $r47u14c 'G-R47-LONG' 'G-R47' $r47Long '0') -and (Test-R47SilenceTold $r47u14c $false))
$r47Rows += Format-R2xRow -Id 'U14 a 5038-character TALLY line is cut, said' -RowOk $r47ok14 -Said (Get-R47Said $r47u14) `
    -Text ("tally file line 1 chars={0} cut at 2048 with the note={1} tally file chars={2} tally_line returned chars={3} fields.passed={4} whole line in the body={5}  (expect above 2048 and below 2300, True, below 4096, 5038, 9, True)" -f `
           $r47u14First.Length, $r47u14Cut, $r47u14c.tallyText.Length, $(if ($r47u14.reported) { ([string]$r47u14.rep.tally_line).Length } else { '(none)' }), $(if ($r47u14.reported) { $r47u14.rep.fields_passed } else { '(none)' }),
           $(if ($null -ne $r47u14c.body) { $r47u14c.body.Contains($r47LongWhole) } else { '(no body)' }))

# ---- U15: an instrument that prints EXACTLY the helper's silence sentence -- the cured header tells -
# it from U5's silent run by body_bytes (the control K2S / K2P need)
$r47u15 = Invoke-R47Helper -Label 'u15-says-exact' -Helper $r47Cured -Instrument $r47SaysExact -Root $r47RootU -RunKey 'G-R47-SAYSX' -Goal 'G-R47'
$r47Runs += $r47u15
$r47u15c = $r47u15.cap
$r47ok15 = ($r47u15.reported -and ($r47SilenceSentence.Contains($r47Statement)) -and ($null -ne $r47u15c.body) -and ($r47u15c.body -ceq $r47SilenceSentence) -and
            ($r47u15c.header['body_bytes'] -cmatch '\A[1-9][0-9]*\z') -and ($r47u15c.bodySha -eq $r47u15c.header['body_sha256']) -and
            ($null -ne $r47u5c.body) -and ($r47u15c.body -ceq $r47u5c.body) -and ($r47u5c.header['body_bytes'] -ceq '0') -and
            (Test-R47NoTally $r47u15c '0') -and (Test-R47ExitBeside $r47u15c '0' '0') -and (Test-R47Provenance $r47u15c 'G-R47-SAYSX' 'G-R47' $r47SaysExact '0'))
$r47Rows += Format-R2xRow -Id 'U15 control: prints EXACTLY the silence sentence' -RowOk $r47ok15 -Said (Get-R47Said $r47u15) `
    -Text ("sentence read out of the helper={0} body is that sentence={1} and equals U5's silent body={2} header body_bytes U15/U5={3}/{4}  (expect True, True, True, above 0 / 0 -- the header tells them apart, the body alone cannot)" -f `
           ($r47SilenceSentence.Contains($r47Statement)), $(if ($null -ne $r47u15c.body) { $r47u15c.body -ceq $r47SilenceSentence } else { '(no body)' }),
           $(if (($null -ne $r47u15c.body) -and ($null -ne $r47u5c.body)) { $r47u15c.body -ceq $r47u5c.body } else { '(no body)' }), $r47u15c.header['body_bytes'], $r47u5c.header['body_bytes'])

# ---- O1 / O2 / O3: THE DETECTOR ORDINAL, DERIVED FROM run_key UNDER THE GOAL EVALUATOR'S FOLD -------
# mission-goal-check.ps1 passes RunKey = the goal for its first instrument_exit0 capture and
# goal + '.' + n for the n-th (n of 2 or more). U10 wrote both shapes under goal G-R47-ORPH; U1 and
# U11 wrote keys outside the fold. The table drives near-miss keys through the CURED function R-38a
# dot-sourced into this scope -- never a planted copy, which only ever runs in a child.
$r47o1 = Get-R47Ordinal $r47u10New
$r47okO1 = ($r47u10b.reported -and ($r47o1 -ceq '1') -and (Test-R47Provenance $r47u10New 'G-R47-ORPH' 'G-R47-ORPH' $r47Three '0'))
$r47Rows += Format-R2xRow -Id 'O1 ordinal 1: run_key equals goal' -RowOk $r47okO1 -Said (Get-R47Said $r47u10b) `
    -Text ("run_key={0} goal={1} detector_ordinal parsed={2} says DERIVED={3}  (expect G-R47-ORPH, G-R47-ORPH, 1, True)" -f `
           $r47u10New.header['run_key'], $r47u10New.header['goal'], $r47o1, ([string]$r47u10New.header['detector_ordinal']).Contains('DERIVED'))
$r47o2 = Get-R47Ordinal $r47u10Stale
$r47okO2 = ($r47u10a.reported -and ($r47o2 -ceq '2') -and (Test-R47Provenance $r47u10Stale 'G-R47-ORPH.2' 'G-R47-ORPH' $r47Two '1'))
$r47Rows += Format-R2xRow -Id 'O2 ordinal 2: run_key is goal.2' -RowOk $r47okO2 -Said (Get-R47Said $r47u10a) `
    -Text ("run_key={0} goal={1} detector_ordinal parsed={2} says DERIVED={3}  (expect G-R47-ORPH.2, G-R47-ORPH, 2, True)" -f `
           $r47u10Stale.header['run_key'], $r47u10Stale.header['goal'], $r47o2, ([string]$r47u10Stale.header['detector_ordinal']).Contains('DERIVED'))
$r47OrdCases = New-Object System.Collections.Generic.List[object]
function Add-R47OrdCase { param([string]$Key, [string]$Goal, [string]$Expect) [void]$script:r47OrdCases.Add([pscustomobject]@{ key = $Key; goal = $Goal; expect = $Expect }) }
Add-R47OrdCase -Key 'G-R47-O'       -Goal 'G-R47-O'   -Expect '1'
Add-R47OrdCase -Key 'G-R47-O.2'     -Goal 'G-R47-O'   -Expect '2'
Add-R47OrdCase -Key 'G-R47-O.17'    -Goal 'G-R47-O'   -Expect '17'
Add-R47OrdCase -Key 'G-R47-O.2.3'   -Goal 'G-R47-O.2' -Expect '3'
Add-R47OrdCase -Key 'G-R47-O.2'     -Goal 'G-R47-O.2' -Expect '1'
Add-R47OrdCase -Key 'G-R47-O.1'     -Goal 'G-R47-O'   -Expect 'not derivable'
Add-R47OrdCase -Key 'G-R47-O.02'    -Goal 'G-R47-O'   -Expect 'not derivable'
Add-R47OrdCase -Key 'G-R47-O.x'     -Goal 'G-R47-O'   -Expect 'not derivable'
Add-R47OrdCase -Key 'G-R47-O.'      -Goal 'G-R47-O'   -Expect 'not derivable'
Add-R47OrdCase -Key 'g-r47-o.2'     -Goal 'G-R47-O'   -Expect 'not derivable'
Add-R47OrdCase -Key "G-R47-O.2`n"   -Goal 'G-R47-O'   -Expect 'not derivable'
Add-R47OrdCase -Key 'G-R47-O.2 '    -Goal 'G-R47-O'   -Expect 'not derivable'
Add-R47OrdCase -Key 'G-R47-OTHER'   -Goal 'G-R47-O'   -Expect 'not derivable'
Add-R47OrdCase -Key ''              -Goal 'G-R47-O'   -Expect 'not derivable'
Add-R47OrdCase -Key 'G-R47-O.2'     -Goal ''          -Expect 'not derivable'
$r47OrdTableRows = @()
$r47OrdTableBad = 0
foreach ($oc in $r47OrdCases) {
    $ocGot = ConvertFrom-R47OrdinalText -Text (Get-LamCaptureDetectorOrdinal -RunKey $oc.key -Goal $oc.goal)
    if ($ocGot -cne $oc.expect) { $r47OrdTableBad++ }
    $r47OrdTableRows += ("        run_key [{0}] goal [{1}] -> {2}  (expect {3}) {4}" -f ($oc.key -replace "`n", '<LF>'), $oc.goal, $ocGot, $oc.expect, $(if ($ocGot -ceq $oc.expect) { 'ok' } else { 'MISMATCH' }))
}
$r47o3u1  = Get-R47Ordinal $r47u1c
$r47o3u11 = Get-R47Ordinal $r47u11c
$r47okO3 = ($r47u1.reported -and $r47u11.reported -and ($r47o3u1 -ceq 'not derivable') -and ($r47o3u11 -ceq 'not derivable') -and
            ($r47OrdCases.Count -eq 15) -and ($r47OrdTableBad -eq 0))
$r47Rows += Format-R2xRow -Id 'O3 a run_key outside the fold: not derivable' -RowOk $r47okO3 -Said (Get-R47Said $r47u1) `
    -Text ("U1 key G-R47-TWO under G-R47 -> {0}; U11 injected key -> {1}; near-miss table {2} of {3} as expected  (expect not derivable, not derivable, 15 of 15 -- nothing guessed)" -f `
           $r47o3u1, $r47o3u11, ($r47OrdCases.Count - $r47OrdTableBad), $r47OrdCases.Count)
$r47Rows += ($r47OrdTableRows -join "`n")

# ---- THE KILLS: one planted revert per guarantee, each on the SAME instrument as its cured row ------
$r47HelperIn = 'tools\lam\lam-instrument-run.ps1'
$r47g1Copy = New-UncuredCopy -Name 'uncured47g1' -InFile $r47HelperIn `
    -CuredLine '        for ($tallyAt = 1; $tallyAt -lt $tallyKept.Count; $tallyAt++) { [void]$tallyOut.Add([string]$tallyKept[$tallyAt]) }' `
    -OldLine   '        # PLANTED REVERT (R-47 G1): only the first TALLY line reaches the tally file'
$r47g2Copy = New-UncuredCopy -Name 'uncured47g2' -InFile $r47HelperIn `
    -CuredLine '        $stdoutText = $headerText + $bodyBlock' `
    -OldLine   '        $stdoutText = $bodyBlock'
$r47g3Copy = New-UncuredCopy -Name 'uncured47g3' -InFile $r47HelperIn `
    -CuredLine '        if ($flat.Length -eq 0) { $bodyInner = $silentStatement }' `
    -OldLine   '        if ($false) { $bodyInner = $silentStatement }'
$r47g4Copy = New-UncuredCopy -Name 'uncured47g4' -InFile $r47HelperIn `
    -CuredLine '        [void]$tallyOut.Add("EXIT exit_code=$code ran=$($res.ran) tally_count=$($res.tally_count) captured_at=$capturedAt")' `
    -OldLine   '        # PLANTED REVERT (R-47 G4): no exit line beside the tally'
$r47lecCopy = New-UncuredCopy -Name 'uncured47lec' -InFile $r47HelperIn `
    -CuredLine '    $global:LASTEXITCODE = $code' `
    -OldLine   '    $null = & cmd.exe /c exit 0'
$r47ordCopy = New-UncuredCopy -Name 'uncured47ord' -InFile $r47HelperIn `
    -CuredLine '        [void]$header.Add(''detector_ordinal: '' + (Get-LamCaptureDetectorOrdinal -RunKey $RunKey -Goal $Goal))' `
    -OldLine   '        # PLANTED REVERT (R-47 K6): no detector_ordinal line in the header'
$r47guessCopy = New-UncuredCopy -Name 'uncured47guess' -InFile $r47HelperIn `
    -CuredLine '    return (''not derivable (run_key is neither goal nor goal.<n> for an n of 2 or more, the only two keys '' + $lamFold + '' writes; no ordinal is guessed)'')' `
    -OldLine   '    return (''1 (DERIVED from run_key, not passed by the caller: PLANTED REVERT (R-47 K7) guesses the first detector for a key outside the fold)'')'
$r47blankCopy = New-UncuredCopy -Name 'uncured47blank' -InFile $r47HelperIn `
    -CuredLine '        if ($res.ran -and ($rawItemCount -gt 0)) { $silentStatement = $emptyLineStatement }' `
    -OldLine   '        # PLANTED REVERT (R-47 K8): one empty line is recorded as silence'
$r47lenCopy = New-UncuredCopy -Name 'uncured47len' -InFile $r47HelperIn `
    -CuredLine '        if ($keptLine.Length -gt $lamTallyLineMax) { $keptLine = ConvertTo-LamBoundedTallyLine -Line $keptLine -Max $lamTallyLineMax }' `
    -OldLine   '        # PLANTED REVERT (R-47 K9): a kept TALLY line keeps its whole length'
function Get-R47CopyHelper { param($Copy) return (Join-Path (Split-Path -Parent $Copy.runner) 'lam-instrument-run.ps1') }

# EVERY KILL ROW CHECKS ALL THREE OTHER GUARANTEES, each in the form its input allows: guarantee 1 is
# Test-R47EveryTally for a speaking input and Test-R47NoTally for a silent one; guarantee 3 is
# Test-R47SilenceTold, silent or speaking. What contract (h) says a line ALSO carries is asserted GONE.

# K1 -- G1 reverted, U2's instrument: the 2nd and 3rd TALLY lines are GONE; 2, 3 and 4 stand.
$r47k1 = if ($r47g1Copy.parses) { Invoke-R47Helper -Label 'k1-g1' -Helper (Get-R47CopyHelper $r47g1Copy) -Instrument $r47Three -Root $r47RootU -RunKey 'G-R47-K1' -Goal 'G-R47' } else { $null }
$r47Runs += $r47k1
$r47okK1 = ($r47g1Copy.planted -and $r47g1Copy.parses -and ($null -ne $r47k1) -and $r47k1.reported -and
            (-not (Test-R47EveryTally $r47k1.cap $r47ExpThree)) -and ($r47k1.cap.first -ceq $r47ExpThree[0]) -and
            (Test-R47Provenance $r47k1.cap 'G-R47-K1' 'G-R47' $r47Three '0') -and (Test-R47ExitBeside $r47k1.cap '0' '3') -and
            (Test-R47SilenceTold $r47k1.cap $false) -and
            ($r47k1.instrumentSha -eq $r47u2.instrumentSha))
$r47Rows += Format-R2xRow -Id 'K1 planted revert of G1, U2 input' -RowOk $r47okK1 -Said $(if ($r47k1) { Get-R47Said $r47k1 } else { '(not run)' }) `
    -Text ("plant located={0} parses={1} every TALLY kept={2} tally file [{3}] header, silence-told and EXIT still stand={4}  (expect True, True, False, first line then EXIT only, True)" -f `
           $r47g1Copy.planted, $r47g1Copy.parses, $(if ($r47k1) { Test-R47EveryTally $r47k1.cap $r47ExpThree } else { '(not run)' }), $(if ($r47k1) { $r47k1.cap.tallyLines -join ' || ' } else { '' }),
           $(if ($r47k1) { (Test-R47Provenance $r47k1.cap 'G-R47-K1' 'G-R47' $r47Three '0') -and (Test-R47ExitBeside $r47k1.cap '0' '3') -and (Test-R47SilenceTold $r47k1.cap $false) } else { '(not run)' }))

# K2 -- G2 reverted, U1's instrument: NO header, so guarantee 2 AND guarantee 3's numeric half are
# gone (no column-0 body_bytes line anywhere); both TALLY lines, the EXIT line, and the sentence half of
# 3 (a speaking body carries no silence sentence) stand.
$r47k2 = if ($r47g2Copy.parses) { Invoke-R47Helper -Label 'k2-g2' -Helper (Get-R47CopyHelper $r47g2Copy) -Instrument $r47Two -Root $r47RootU -RunKey 'G-R47-K2' -Goal 'G-R47' } else { $null }
$r47Runs += $r47k2
$r47okK2 = ($r47g2Copy.planted -and $r47g2Copy.parses -and ($null -ne $r47k2) -and $r47k2.reported -and
            (-not (Test-R47Provenance $r47k2.cap 'G-R47-K2' 'G-R47' $r47Two '1')) -and (-not $r47k2.cap.text.Contains('captured_at:')) -and
            ((Get-R47Ordinal $r47k2.cap) -ceq '(absent)') -and (-not ($r47k2.cap.text -cmatch '(?m)^body_bytes: ')) -and
            (Test-R47EveryTally $r47k2.cap $r47ExpTwo) -and (Test-R47ExitBeside $r47k2.cap '1' '2') -and
            ($null -ne $r47k2.cap.body) -and $r47k2.cap.body.Contains('FAILED tests/r47.py::test_one') -and (-not $r47k2.cap.body.Contains($r47Statement)) -and
            ($r47k2.instrumentSha -eq $r47u1.instrumentSha))
$r47Rows += Format-R2xRow -Id 'K2 planted revert of G2, U1 input' -RowOk $r47okK2 -Said $(if ($r47k2) { Get-R47Said $r47k2 } else { '(not run)' }) `
    -Text ("plant located={0} parses={1} provenance header present={2} column-0 body_bytes line present={3} TALLY lines and EXIT still stand={4}  (expect True, True, False, False -- 3's numeric half goes with the header, True)" -f `
           $r47g2Copy.planted, $r47g2Copy.parses, $(if ($r47k2) { $r47k2.cap.hasHeader } else { '(not run)' }), $(if ($r47k2) { $r47k2.cap.text -cmatch '(?m)^body_bytes: ' } else { '(not run)' }),
           $(if ($r47k2) { (Test-R47EveryTally $r47k2.cap $r47ExpTwo) -and (Test-R47ExitBeside $r47k2.cap '1' '2') } else { '(not run)' }))

# K2S / K2P -- G2 reverted, U5's SILENT input and U15's input that PRINTS the silence sentence. With the
# header gone the sentence is the only silence signal left, and it is forgeable: the two stdout files
# come out byte-identical, where the cured U5 and U15 differ by body_bytes. 1 and 4 stand for both.
$r47k2s = if ($r47g2Copy.parses) { Invoke-R47Helper -Label 'k2s-g2-silent' -Helper (Get-R47CopyHelper $r47g2Copy) -Instrument $r47Silent0 -Root $r47RootU -RunKey 'G-R47-K2S' -Goal 'G-R47' } else { $null }
$r47k2p = if ($r47g2Copy.parses) { Invoke-R47Helper -Label 'k2p-g2-prints' -Helper (Get-R47CopyHelper $r47g2Copy) -Instrument $r47SaysExact -Root $r47RootU -RunKey 'G-R47-K2P' -Goal 'G-R47' } else { $null }
$r47Runs += $r47k2s
$r47Runs += $r47k2p
$r47k2sSame = ($null -ne $r47k2s) -and ($null -ne $r47k2p) -and $r47k2s.cap.exists -and $r47k2p.cap.exists -and ($r47k2s.cap.sha -ceq $r47k2p.cap.sha)
$r47okK2s = ($r47g2Copy.planted -and $r47g2Copy.parses -and ($null -ne $r47k2s) -and ($null -ne $r47k2p) -and $r47k2s.reported -and $r47k2p.reported -and
             (-not (Test-R47Provenance $r47k2s.cap 'G-R47-K2S' 'G-R47' $r47Silent0 '0')) -and
             ($null -ne $r47k2s.cap.body) -and $r47k2s.cap.body.Contains($r47Statement) -and
             (-not ($r47k2s.cap.text -cmatch '(?m)^body_bytes: ')) -and (-not (Test-R47SilenceTold $r47k2s.cap $true)) -and
             $r47k2sSame -and $r47ok5 -and $r47ok15 -and
             (Test-R47NoTally $r47k2s.cap '0') -and (Test-R47ExitBeside $r47k2s.cap '0' '0') -and
             (Test-R47NoTally $r47k2p.cap '0') -and (Test-R47ExitBeside $r47k2p.cap '0' '0') -and
             ($r47k2s.instrumentSha -eq $r47u5.instrumentSha) -and ($r47k2p.instrumentSha -eq $r47u15.instrumentSha))
$r47Rows += Format-R2xRow -Id 'K2S/K2P G2 reverted: silent vs printed sentence' -RowOk $r47okK2s -Said $(if ($r47k2s) { Get-R47Said $r47k2s } else { '(not run)' }) `
    -Text ("silent capture still carries the sentence={0} column-0 body_bytes present={1} silent and printed-sentence stdout files byte-identical={2} cured U5/U15 told apart by body_bytes={3} NO-TALLY and EXIT stand for both={4}  (expect True, False, True, True, True)" -f `
           $(if (($null -ne $r47k2s) -and ($null -ne $r47k2s.cap.body)) { $r47k2s.cap.body.Contains($r47Statement) } else { '(not run)' }),
           $(if ($r47k2s) { $r47k2s.cap.text -cmatch '(?m)^body_bytes: ' } else { '(not run)' }), $r47k2sSame, ($r47ok5 -and $r47ok15),
           $(if ($r47k2s -and $r47k2p) { (Test-R47NoTally $r47k2s.cap '0') -and (Test-R47ExitBeside $r47k2s.cap '0' '0') -and (Test-R47NoTally $r47k2p.cap '0') -and (Test-R47ExitBeside $r47k2p.cap '0' '0') } else { '(not run)' }))

# K3 -- G3 reverted, U6's instrument: the sentence is GONE and the body is empty; the header
# (body_bytes: 0), NO-TALLY and EXIT stand.
$r47k3 = if ($r47g3Copy.parses) { Invoke-R47Helper -Label 'k3-g3' -Helper (Get-R47CopyHelper $r47g3Copy) -Instrument $r47Silent5 -Root $r47RootU -RunKey 'G-R47-K3' -Goal 'G-R47' -Shape 'detector' } else { $null }
$r47Runs += $r47k3
$r47okK3 = ($r47g3Copy.planted -and $r47g3Copy.parses -and ($null -ne $r47k3) -and $r47k3.reported -and
            (-not (Test-R47Stated $r47k3.cap)) -and ($r47k3.cap.header['body_bytes'] -eq '0') -and ($r47k3.cap.body -ceq '') -and
            (Test-R47Provenance $r47k3.cap 'G-R47-K3' 'G-R47' $r47Silent5 '5') -and (Test-R47ExitBeside $r47k3.cap '5' '0') -and
            (Test-R47NoTally $r47k3.cap '5') -and
            ($r47k3.instrumentSha -eq $r47u6.instrumentSha))
$r47Rows += Format-R2xRow -Id 'K3 planted revert of G3, U6 input' -RowOk $r47okK3 -Said $(if ($r47k3) { Get-R47Said $r47k3 } else { '(not run)' }) `
    -Text ("plant located={0} parses={1} silence stated={2} header, NO-TALLY and EXIT still stand={3}  (expect True, True, False, True)" -f `
           $r47g3Copy.planted, $r47g3Copy.parses, $(if ($r47k3) { Test-R47Stated $r47k3.cap } else { '(not run)' }),
           $(if ($r47k3) { (Test-R47Provenance $r47k3.cap 'G-R47-K3' 'G-R47' $r47Silent5 '5') -and (Test-R47ExitBeside $r47k3.cap '5' '0') -and (Test-R47NoTally $r47k3.cap '5') } else { '(not run)' }))

# K4 -- G4 reverted, U7's instrument: NO exit line; the header's exit_code 7, the TALLY line and the
# silence-told body stand.
$r47k4 = if ($r47g4Copy.parses) { Invoke-R47Helper -Label 'k4-g4' -Helper (Get-R47CopyHelper $r47g4Copy) -Instrument $r47Exit7 -Root $r47RootU -RunKey 'G-R47-K4' -Goal 'G-R47' } else { $null }
$r47Runs += $r47k4
$r47okK4 = ($r47g4Copy.planted -and $r47g4Copy.parses -and ($null -ne $r47k4) -and $r47k4.reported -and
            (-not (Test-R47ExitBeside $r47k4.cap '7' '1')) -and (-not $r47k4.cap.tallyText.Contains('EXIT exit_code=')) -and
            (Test-R47Provenance $r47k4.cap 'G-R47-K4' 'G-R47' $r47Exit7 '7') -and (Test-R47EveryTally $r47k4.cap $r47ExpExit7) -and
            (Test-R47SilenceTold $r47k4.cap $false) -and
            ($r47k4.instrumentSha -eq $r47u7.instrumentSha))
$r47Rows += Format-R2xRow -Id 'K4 planted revert of G4, U7 input' -RowOk $r47okK4 -Said $(if ($r47k4) { Get-R47Said $r47k4 } else { '(not run)' }) `
    -Text ("plant located={0} parses={1} exit beside the tally={2} tally file [{3}] header, TALLY and silence-told still stand={4}  (expect True, True, False, the TALLY line alone, True)" -f `
           $r47g4Copy.planted, $r47g4Copy.parses, $(if ($r47k4) { Test-R47ExitBeside $r47k4.cap '7' '1' } else { '(not run)' }), $(if ($r47k4) { $r47k4.cap.tallyLines -join ' || ' } else { '' }),
           $(if ($r47k4) { (Test-R47Provenance $r47k4.cap 'G-R47-K4' 'G-R47' $r47Exit7 '7') -and (Test-R47EveryTally $r47k4.cap $r47ExpExit7) -and (Test-R47SilenceTold $r47k4.cap $false) } else { '(not run)' }))

# K5 -- contract (a) reverted (a native call where the re-assertion stood), U6's input and call shape:
# the detector's next line reads the wrong exit code. Proves U6's LASTEXITCODE row can go red. All
# four capture guarantees stand.
$r47k5 = if ($r47lecCopy.parses) { Invoke-R47Helper -Label 'k5-lec' -Helper (Get-R47CopyHelper $r47lecCopy) -Instrument $r47Silent5 -Root $r47RootU -RunKey 'G-R47-K5' -Goal 'G-R47' -Shape 'detector' } else { $null }
$r47Runs += $r47k5
$r47okK5 = ($r47lecCopy.planted -and $r47lecCopy.parses -and ($null -ne $r47k5) -and $r47k5.reported -and
            ($r47k5.rep.lastexitcode -ne '5') -and (Test-R47Stated $r47k5.cap) -and (Test-R47ExitBeside $r47k5.cap '5' '0') -and
            (Test-R47SilenceTold $r47k5.cap $true) -and (Test-R47NoTally $r47k5.cap '5') -and (Test-R47Provenance $r47k5.cap 'G-R47-K5' 'G-R47' $r47Silent5 '5') -and
            ($r47k5.instrumentSha -eq $r47u6.instrumentSha))
$r47Rows += Format-R2xRow -Id 'K5 planted native call after the run, U6 input' -RowOk $r47okK5 -Said $(if ($r47k5) { Get-R47Said $r47k5 } else { '(not run)' }) `
    -Text ("plant located={0} parses={1} LASTEXITCODE the detector reads={2} the capture itself still says exit 5={3}  (expect True, True, NOT 5, True)" -f `
           $r47lecCopy.planted, $r47lecCopy.parses, $(if ($r47k5 -and $r47k5.reported) { $r47k5.rep.lastexitcode } else { '(none)' }), $(if ($r47k5) { Test-R47ExitBeside $r47k5.cap '5' '0' } else { '(not run)' }))

# K6 -- the detector_ordinal header line reverted, U10's old input under a goal.2 key: the ordinal is
# GONE from the header while every other header key, both TALLY lines, EXIT and silence-told stand.
$r47k6 = if ($r47ordCopy.parses) { Invoke-R47Helper -Label 'k6-ordinal' -Helper (Get-R47CopyHelper $r47ordCopy) -Instrument $r47Two -Root $r47RootU -RunKey 'G-R47-K6.2' -Goal 'G-R47-K6' } else { $null }
$r47Runs += $r47k6
$r47okK6 = ($r47ordCopy.planted -and $r47ordCopy.parses -and ($null -ne $r47k6) -and $r47k6.reported -and
            ((Get-R47Ordinal $r47k6.cap) -ceq '(absent)') -and (-not (Test-R47Provenance $r47k6.cap 'G-R47-K6.2' 'G-R47-K6' $r47Two '1')) -and
            (Test-R47Provenance $r47k6.cap 'G-R47-K6.2' 'G-R47-K6' $r47Two '1' -SkipOrdinal) -and
            (Test-R47EveryTally $r47k6.cap $r47ExpTwo) -and (Test-R47ExitBeside $r47k6.cap '1' '2') -and (Test-R47SilenceTold $r47k6.cap $false) -and
            ($r47k6.instrumentSha -eq $r47u10a.instrumentSha))
$r47Rows += Format-R2xRow -Id 'K6 planted revert of the ordinal line, U10 input' -RowOk $r47okK6 -Said $(if ($r47k6) { Get-R47Said $r47k6 } else { '(not run)' }) `
    -Text ("plant located={0} parses={1} detector_ordinal={2} every other header key, TALLY, EXIT and silence-told still stand={3}  (expect True, True, (absent), True)" -f `
           $r47ordCopy.planted, $r47ordCopy.parses, $(if ($r47k6) { Get-R47Ordinal $r47k6.cap } else { '(not run)' }),
           $(if ($r47k6) { (Test-R47Provenance $r47k6.cap 'G-R47-K6.2' 'G-R47-K6' $r47Two '1' -SkipOrdinal) -and (Test-R47EveryTally $r47k6.cap $r47ExpTwo) -and (Test-R47ExitBeside $r47k6.cap '1' '2') -and (Test-R47SilenceTold $r47k6.cap $false) } else { '(not run)' }))

# K7 -- a GUESS planted where 'not derivable' stood, U1's input under a key outside the fold: the header
# now claims ordinal 1 for a key the fold never wrote, which is O3's defect; 1, 3 and 4 stand.
$r47k7 = if ($r47guessCopy.parses) { Invoke-R47Helper -Label 'k7-guess' -Helper (Get-R47CopyHelper $r47guessCopy) -Instrument $r47Two -Root $r47RootU -RunKey 'G-R47-K7' -Goal 'G-R47' } else { $null }
$r47Runs += $r47k7
$r47okK7 = ($r47guessCopy.planted -and $r47guessCopy.parses -and ($null -ne $r47k7) -and $r47k7.reported -and
            ((Get-R47Ordinal $r47k7.cap) -cne 'not derivable') -and ((Get-R47Ordinal $r47k7.cap) -ceq '1') -and
            (Test-R47Provenance $r47k7.cap 'G-R47-K7' 'G-R47' $r47Two '1') -and
            (Test-R47EveryTally $r47k7.cap $r47ExpTwo) -and (Test-R47ExitBeside $r47k7.cap '1' '2') -and (Test-R47SilenceTold $r47k7.cap $false) -and
            ($r47k7.instrumentSha -eq $r47u1.instrumentSha))
$r47Rows += Format-R2xRow -Id 'K7 planted guess for a non-fold key, U1 input' -RowOk $r47okK7 -Said $(if ($r47k7) { Get-R47Said $r47k7 } else { '(not run)' }) `
    -Text ("plant located={0} parses={1} detector_ordinal for G-R47-K7 under G-R47={2} header, TALLY, EXIT and silence-told still stand={3}  (expect True, True, 1 -- the guess O3 refuses, True)" -f `
           $r47guessCopy.planted, $r47guessCopy.parses, $(if ($r47k7) { Get-R47Ordinal $r47k7.cap } else { '(not run)' }),
           $(if ($r47k7) { (Test-R47Provenance $r47k7.cap 'G-R47-K7' 'G-R47' $r47Two '1') -and (Test-R47EveryTally $r47k7.cap $r47ExpTwo) -and (Test-R47ExitBeside $r47k7.cap '1' '2') -and (Test-R47SilenceTold $r47k7.cap $false) } else { '(not run)' }))

# K8 -- the one-empty-line line reverted, U13's input: the empty line is recorded as SILENCE again,
# which is the review's defect; header (body_bytes 0), NO-TALLY and EXIT stand.
$r47k8 = if ($r47blankCopy.parses) { Invoke-R47Helper -Label 'k8-blank' -Helper (Get-R47CopyHelper $r47blankCopy) -Instrument $r47Blank1 -Root $r47RootU -RunKey 'G-R47-K8' -Goal 'G-R47' } else { $null }
$r47Runs += $r47k8
$r47okK8 = ($r47blankCopy.planted -and $r47blankCopy.parses -and ($null -ne $r47k8) -and $r47k8.reported -and
            ($null -ne $r47k8.cap.body) -and $r47k8.cap.body.Contains($r47Statement) -and (-not $r47k8.cap.body.Contains($r47EmptyLineNeedle)) -and
            ($r47k8.cap.header['body_bytes'] -ceq '0') -and (Test-R47Provenance $r47k8.cap 'G-R47-K8' 'G-R47' $r47Blank1 '0') -and
            (Test-R47NoTally $r47k8.cap '0') -and (Test-R47ExitBeside $r47k8.cap '0' '0') -and
            ($r47k8.instrumentSha -eq $r47u13.instrumentSha))
$r47Rows += Format-R2xRow -Id 'K8 planted revert of the empty-line line, U13 input' -RowOk $r47okK8 -Said $(if ($r47k8) { Get-R47Said $r47k8 } else { '(not run)' }) `
    -Text ("plant located={0} parses={1} one empty line recorded as silence={2} header, NO-TALLY and EXIT still stand={3}  (expect True, True, True, True)" -f `
           $r47blankCopy.planted, $r47blankCopy.parses, $(if (($null -ne $r47k8) -and ($null -ne $r47k8.cap.body)) { $r47k8.cap.body.Contains($r47Statement) } else { '(not run)' }),
           $(if ($r47k8) { (Test-R47Provenance $r47k8.cap 'G-R47-K8' 'G-R47' $r47Blank1 '0') -and (Test-R47NoTally $r47k8.cap '0') -and (Test-R47ExitBeside $r47k8.cap '0' '0') } else { '(not run)' }))

# K9 -- the TALLY length bound reverted, U14's input: the 5038-character line reaches the tally file
# whole again; both TALLY lines in order, the header, EXIT and silence-told stand.
$r47k9 = if ($r47lenCopy.parses) { Invoke-R47Helper -Label 'k9-length' -Helper (Get-R47CopyHelper $r47lenCopy) -Instrument $r47Long -Root $r47RootU -RunKey 'G-R47-K9' -Goal 'G-R47' } else { $null }
$r47Runs += $r47k9
$r47k9Tally = @(if ($r47k9) { $r47k9.cap.tallyLines | Where-Object { $_ -cmatch '^TALLY ' } })
$r47okK9 = ($r47lenCopy.planted -and $r47lenCopy.parses -and ($null -ne $r47k9) -and $r47k9.reported -and
            ($r47k9.cap.first -ceq $r47LongWhole) -and (-not $r47k9.cap.tallyText.Contains('[TRUNCATED')) -and
            ($r47k9Tally.Count -eq 2) -and ($r47k9Tally[1] -ceq $r47LongShort) -and (Test-R47ExitBeside $r47k9.cap '0' '2') -and
            (Test-R47Provenance $r47k9.cap 'G-R47-K9' 'G-R47' $r47Long '0') -and (Test-R47SilenceTold $r47k9.cap $false) -and
            ($r47k9.instrumentSha -eq $r47u14.instrumentSha))
$r47Rows += Format-R2xRow -Id 'K9 planted revert of the length bound, U14 input' -RowOk $r47okK9 -Said $(if ($r47k9) { Get-R47Said $r47k9 } else { '(not run)' }) `
    -Text ("plant located={0} parses={1} tally file line 1 chars={2} header, TALLY order, EXIT and silence-told still stand={3}  (expect True, True, 5038 -- uncut, True)" -f `
           $r47lenCopy.planted, $r47lenCopy.parses, $(if ($r47k9) { ([string]$r47k9.cap.first).Length } else { '(not run)' }),
           $(if ($r47k9) { ($r47k9Tally.Count -eq 2) -and (Test-R47ExitBeside $r47k9.cap '0' '2') -and (Test-R47Provenance $r47k9.cap 'G-R47-K9' 'G-R47' $r47Long '0') -and (Test-R47SilenceTold $r47k9.cap $false) } else { '(not run)' }))

# ---- ROUTE R: THE RUNNER'S OWN CAPTURE --------------------------------------------------------------
$r47Id        = 'D-WP2-R47'
$r47DispatchP = Join-Path $missionRoot ".mission\dispatches\$r47Id.yaml"
$r47Anchors   = Join-Path $missionRoot ".mission\dispatches\$r47Id.anchors.yaml"
$r47Created   = Join-Path (Get-FixtureWorktreePath -Id $r47Id) 'worker-created.txt'
$r47SuiteMulti = Join-Path $stubDir 'r47-suite-multi.ps1'
Write-Utf8 -Path $r47SuiteMulti -Text @'
Write-Output 'r47 runner suite prelude'
Write-Output 'TALLY passed=41 failed=2 skipped=3 pytest_exit=0 series=first'
Write-Output 'PASS M1 -- a member line between two tallies'
Write-Output 'TALLY passed=99 failed=0 skipped=0 pytest_exit=0 series=second'
Write-Output 'TALLY passed=7 failed=7 skipped=7 pytest_exit=0 series=third'
exit 7
'@
$r47SuiteSilent = Join-Path $stubDir 'r47-suite-silent5.ps1'
Write-Utf8 -Path $r47SuiteSilent -Text "exit 5`n"
$r47ExpRunner = @('TALLY passed=41 failed=2 skipped=3 pytest_exit=0 series=first', 'TALLY passed=99 failed=0 skipped=0 pytest_exit=0 series=second', 'TALLY passed=7 failed=7 skipped=7 pytest_exit=0 series=third')
$r47ArityR = ($r47ExpRunner.Count -eq 3)

function Invoke-R47RunnerRow {
    # Invoke-R38Row's shape, under this member's own dispatch id, returning the anchors' suite members
    # AND the capture the runner's call to the helper wrote.
    param([string]$RunnerPath, [string]$SuiteStub)
    Write-Utf8 -Path $r47DispatchP -Text ("id: $r47Id`nmission_id: mission-wp2-fixture`nworker_id: w-wp2-r47`nkind: mainline`nfeature_id: F-001`nassertion_targets: [A-001]`nspec_version: 1`nworktree_id: wt-r47`nsuite_command: $SuiteStub`nmodel_class: coding-strong`ntool_scope: [repo.read, worktree.write]`nbudget:`n  cost_cap_usd: 1.00`n  wallclock_cap_minutes: 5`ngoal_condition: `"the R-47 fixture dispatch`"`n")
    if (Test-Path -LiteralPath $r47Anchors) { Remove-Item -LiteralPath $r47Anchors -Force }
    Remove-Item -LiteralPath $r47Created -Force -ErrorAction SilentlyContinue
    $pp = Get-LamInstrumentRunPath -MissionRoot $missionRoot -InstrumentPath $SuiteStub -RunKey $r47Id
    foreach ($stale in @($pp.stdout, $pp.tally)) { if (Test-Path -LiteralPath $stale) { Remove-Item -LiteralPath $stale -Force } }
    $argv = @('-NoProfile','-ExecutionPolicy','Bypass','-File',$RunnerPath,
              '-MissionRoot',$missionRoot,'-Dispatch',$r47Id,'-AllowIdReuse',
              '-VerifyCommand',$verifyPass,'-WorkerCommand',$workerOk)
    $prevEap = $ErrorActionPreference
    $ErrorActionPreference = 'Continue'
    try {
        $out = & powershell @argv 2>&1
        $code = $LASTEXITCODE
    } finally { $ErrorActionPreference = $prevEap }
    $anchorsText = if (Test-Path -LiteralPath $r47Anchors) { [System.IO.File]::ReadAllText($r47Anchors) } else { '' }
    return [pscustomobject]@{
        out     = ((@($out) | ForEach-Object { "$_" }) -join "`n")
        exit    = $code
        spawned = (Test-Path -LiteralPath $r47Created)
        block   = [bool]($anchorsText -match '(?m)^\s{2}suite:')
        passed  = (Read-R27SuiteMember -AnchorsPath $r47Anchors -Name 'passed')
        failed  = (Read-R27SuiteMember -AnchorsPath $r47Anchors -Name 'failed')
        skipped = (Read-R27SuiteMember -AnchorsPath $r47Anchors -Name 'skipped')
        source  = (Read-R27SuiteMember -AnchorsPath $r47Anchors -Name 'tally_source')
        series  = (Read-R27SuiteMember -AnchorsPath $r47Anchors -Name 'tally_series')
        pyexit  = (Read-R27SuiteMember -AnchorsPath $r47Anchors -Name 'tally_pytest_exit')
        sha     = (Read-R27SuiteMember -AnchorsPath $r47Anchors -Name 'tally_stdout_sha256')
        bytes   = (Read-R27SuiteMember -AnchorsPath $r47Anchors -Name 'tally_stdout_bytes')
        excode  = (Read-R27SuiteMember -AnchorsPath $r47Anchors -Name 'exit_code')
        cap     = (Read-R47Capture -Paths $pp)
        suiteSha = (Get-R47FileSha -Path $SuiteStub)
    }
}

# R1 -- three TALLY lines through the cured runner, exit 7
$r47r1 = Invoke-R47RunnerRow -RunnerPath $runner -SuiteStub $r47SuiteMulti
$r47r1c = $r47r1.cap
$r47r1Cwd = ([string]$r47r1c.header['cwd']) -match [regex]::Escape("wt-$r47Id")
$r47okR1 = ($r47r1.block -and ($r47r1.passed -eq '41') -and ($r47r1.failed -eq '2') -and ($r47r1.skipped -eq '3') -and
            ($r47r1.source -eq 'instrument-tally') -and ($r47r1.series -eq 'first') -and ($r47r1.excode -eq '7') -and ($r47r1.pyexit -eq '0') -and
            ($r47r1.sha -eq $r47r1c.sha) -and ($r47r1.bytes -eq [string]$r47r1c.bytes) -and
            (Test-R47EveryTally $r47r1c $r47ExpRunner) -and (Test-R47Provenance $r47r1c $r47Id '' $r47SuiteMulti '7') -and $r47r1Cwd -and
            (Test-R47ExitBeside $r47r1c '7' '3') -and (Test-R47Clean $r47r1c) -and ((Get-R47Ordinal $r47r1c) -ceq 'not derivable'))
$r47Rows += Format-R2xRow -Id 'R1 runner: three TALLY lines, exit 7' -RowOk $r47okR1 -Said (Get-R28Said $r47r1.out) `
    -Text ("anchors passed/failed/skipped={0}/{1}/{2} tally_series={3} exit_code={4} tally_pytest_exit={5} anchors sha is the file's={6} tally file [{7}] header run_key={8} cwd is the worktree={9} detector_ordinal={10}  (expect 41/2/3 -- the FIRST line, first, 7, 0, True, all three then EXIT exit_code=7 tally_count=3, $r47Id, True, not derivable -- the runner passes no goal)" -f `
           $r47r1.passed, $r47r1.failed, $r47r1.skipped, $r47r1.series, $r47r1.excode, $r47r1.pyexit, ($r47r1.sha -eq $r47r1c.sha), ($r47r1c.tallyLines -join ' || '), $r47r1c.header['run_key'], $r47r1Cwd, (Get-R47Ordinal $r47r1c))

# R2 -- a silent suite through the cured runner, exit 5
$r47r2 = Invoke-R47RunnerRow -RunnerPath $runner -SuiteStub $r47SuiteSilent
$r47r2c = $r47r2.cap
$r47okR2 = ($r47r2.block -and ($r47r2.source -eq 'exit-code-fallback') -and ($r47r2.excode -eq '5') -and
            ([int]$r47r2.bytes -gt 0) -and ($r47r2.bytes -eq [string]$r47r2c.bytes) -and ($r47r2.sha -eq $r47r2c.sha) -and
            (Test-R47Stated $r47r2c) -and ($r47r2c.header['body_bytes'] -eq '0') -and ($r47r2c.first -ceq 'NO-TALLY exit_code=5') -and
            (Test-R47ExitBeside $r47r2c '5' '0') -and (Test-R47Provenance $r47r2c $r47Id '' $r47SuiteSilent '5'))
$r47Rows += Format-R2xRow -Id 'R2 runner: silent suite, exit 5' -RowOk $r47okR2 -Said (Get-R28Said $r47r2.out) `
    -Text ("anchors tally_source={0} exit_code={1} tally_stdout_bytes={2} silence stated={3} header body_bytes={4} tally file [{5}]  (expect exit-code-fallback, 5, >0 and the file's, True, 0, NO-TALLY exit_code=5 then EXIT exit_code=5)" -f `
           $r47r2.source, $r47r2.excode, $r47r2.bytes, $r47r2c.statement, $r47r2c.header['body_bytes'], ($r47r2c.tallyLines -join ' || '))

# R3 -- the KILL through the runner: a runner copy whose helper has G1 reverted, R1's own suite
$r47rCopy = New-UncuredCopy -Name 'uncured47r' -InFile $r47HelperIn `
    -CuredLine '        for ($tallyAt = 1; $tallyAt -lt $tallyKept.Count; $tallyAt++) { [void]$tallyOut.Add([string]$tallyKept[$tallyAt]) }' `
    -OldLine   '        # PLANTED REVERT (R-47 G1): only the first TALLY line reaches the tally file'
$r47r3 = if ($r47rCopy.parses) { Invoke-WithHookRepointed -Decider $r47rCopy.decider -Body { Invoke-R47RunnerRow -RunnerPath $r47rCopy.runner -SuiteStub $r47SuiteMulti } } else { $null }
$r47okR3 = ($r47rCopy.planted -and $r47rCopy.parses -and ($null -ne $r47r3) -and $r47r3.block -and
            (-not (Test-R47EveryTally $r47r3.cap $r47ExpRunner)) -and ($r47r3.cap.first -ceq $r47ExpRunner[0]) -and
            ($r47r3.passed -eq '41') -and (Test-R47ExitBeside $r47r3.cap '7' '3') -and (Test-R47Provenance $r47r3.cap $r47Id '' $r47SuiteMulti '7') -and
            (Test-R47SilenceTold $r47r3.cap $false) -and
            ($r47r3.suiteSha -eq $r47r1.suiteSha))
$r47Rows += Format-R2xRow -Id 'R3 runner copy with G1 reverted, R1 input' -RowOk $r47okR3 -Said $(if ($r47r3) { Get-R28Said $r47r3.out } else { '(not run)' }) `
    -Text ("plant located={0} parses={1} every TALLY kept={2} tally file [{3}] anchors passed={4}  (expect True, True, False, the first line then EXIT only, 41 -- the plant reaches the runner's capture and moves no figure)" -f `
           $r47rCopy.planted, $r47rCopy.parses, $(if ($r47r3) { Test-R47EveryTally $r47r3.cap $r47ExpRunner } else { '(not run)' }), $(if ($r47r3) { $r47r3.cap.tallyLines -join ' || ' } else { '' }), $(if ($r47r3) { $r47r3.passed } else { '(not run)' }))

# NON-VACUITY, counted over what the child runs and the runner DID.
$r47ChildRuns = @($r47Runs | Where-Object { $null -ne $_ })
$r47Reported  = @($r47ChildRuns | Where-Object { $_.reported }).Count
$r47AllReported = ($r47ChildRuns.Count -eq 28) -and ($r47Reported -eq 28)
$r47Codes = @($r47ChildRuns | Where-Object { $_.reported } | ForEach-Object { [string]$_.rep.lastexitcode } | Select-Object -Unique)
$r47CodeSplit = (@('0', '1', '5', '7') | Where-Object { $r47Codes -contains $_ }).Count -eq 4
$r47SilentRows = @(@($r47u5c, $r47u6c, $r47r2c) | Where-Object { $_.header['body_bytes'] -eq '0' }).Count
$r47SpokeRows  = @(@($r47u1c, $r47u2c, $r47u8c, $r47r1c, $r47u15c) | Where-Object { ([string]$_.header['body_bytes']) -match '^[1-9]\d*$' }).Count
$r47EmptyRows  = @(@($r47u13c) | Where-Object { ($_.header['body_bytes'] -eq '0') -and ($null -ne $_.body) -and $_.body.Contains($r47EmptyLineNeedle) }).Count
$r47BytesSplit = ($r47SilentRows -eq 3) -and ($r47SpokeRows -eq 5) -and ($r47EmptyRows -eq 1)
$r47OrdSeen = @(@($r47u10New, $r47u10Stale, $r47u1c, $r47r1c) | ForEach-Object { Get-R47Ordinal $_ } | Select-Object -Unique)
$r47OrdSplit = (@('1', '2', 'not derivable') | Where-Object { $r47OrdSeen -ccontains $_ }).Count -eq 3
$r47SentenceRead = ($r47SilenceHits.Count -eq 1) -and $r47SilenceSentence.Contains($r47Statement)
$r47Blocks = @(@($r47r1, $r47r2, $r47r3) | Where-Object { ($null -ne $_) -and $_.block }).Count
$r47Spawned = @(@($r47r1, $r47r2, $r47r3) | Where-Object { ($null -ne $_) -and $_.spawned }).Count
$r47NonVacuous = $r47Arity -and $r47ArityR -and $r47AllReported -and $r47CodeSplit -and $r47BytesSplit -and $r47OrdSplit -and $r47SentenceRead -and ($r47Blocks -eq 3)

$r47detail = @"
    THE ROWS. U rows drive the helper in a CHILD powershell exactly as the detector calls it; O rows read the derived detector ordinal; R rows drive the real runner; K rows are planted reverts, one line each, over the SAME instrument bytes as their cured row:
$($r47Rows -join "`n")
    child runs: $($r47ChildRuns.Count) of 28 (17 cured, 11 planted), reported: $r47Reported    distinct LASTEXITCODE values seen: $($r47Codes -join ',') (0, 1, 5 and 7 all present: $r47CodeSplit)
    silent captures with body_bytes 0: $r47SilentRows of 3    speaking captures with body_bytes above 0: $r47SpokeRows of 5    one-empty-line captures with body_bytes 0 and the empty-line sentence: $r47EmptyRows of 1    runner suite blocks written: $r47Blocks of 3 (spawned: $r47Spawned)
    detector_ordinal values read off captures: $($r47OrdSeen -join ', ') (1, 2 and not derivable all present: $r47OrdSplit)    silence sentence read out of the cured helper once: $r47SentenceRead
    expectation arity held: $($r47Arity -and $r47ArityR)
    (counted over what the runs DID, not over this table's expectations)
    THE CAPTURES THIS MEMBER READ, kept under the sandbox when -KeepSandbox is given:
      U1 stdout : $($r47u1c.path)
      U6 stdout : $($r47u6c.path)
      R1 stdout : $($r47r1c.path)
    WHAT THIS MEMBER DOES NOT ASSERT:
      * the private capture's leading-whitespace 'TALLY passed=' grammar. The helper's grammar is column 0, any key (contract (d)); U4 holds that an indented or mid-line TALLY is NOT counted, on purpose.
      * that the helper ever RECEIVES one pipeline item carrying two lines. U3's instrument writes both in one call, but a native child's stdout reaches the helper already split into lines.
      * stdout_sha256 reproducibility across identical runs. It measures the file as written, header and captured_at included, and differs run to run by design; body_sha256 is the stable figure.
      * anything about mission-goal-check.ps1 beyond its call shape, which U6, U7 and K5 reproduce. WP-3 C-1j drives the real detector.
      * that detector_ordinal is a position among ALL of a goal's detectors. It is the fold's own counter, which counts only the instrument_exit0 detectors that reach the helper; the real detector's ordinal is not driven here.
      * the ran=False sentence. The invocation catch always returns a non-empty text, so an empty body with ran False is unreachable and no row drives it.
      * a TALLY line cut inside a UTF-16 surrogate pair. The helper keeps one character fewer rather than split a pair; U14's cut falls between two ASCII characters.
    the planted copies : $($r47g1Copy.runner), and beside it uncured47g2, uncured47g3, uncured47g4, uncured47lec, uncured47ord, uncured47guess, uncured47blank, uncured47len and uncured47r
"@
Check -Id 'R-47' -Title 'the shared instrument helper''s capture keeps its four guarantees in both callers: every column-0 TALLY line in order, bounded in count and in length, with the first still the anchors'' figures; a provenance header no key or goal can forge a line into, stating the detector ordinal derived from run_key under the goal evaluator''s fold or that it is not derivable; silence told from speech and from one empty line by the header''s body_bytes; and the instrument''s own exit code beside the tally -- each one red under a planted revert of its one line with the other guarantees checked, on the runner''s capture as on the detector''s call shape (rows 181 and 187, review)' `
      -Ok ($r47ok1 -and $r47ok2 -and $r47ok3 -and $r47ok4 -and $r47ok5 -and $r47ok6 -and $r47ok7 -and $r47ok8 -and $r47ok9 -and $r47ok10 -and $r47ok11 -and $r47ok12 -and
           $r47ok13 -and $r47ok14 -and $r47ok15 -and $r47okO1 -and $r47okO2 -and $r47okO3 -and
           $r47okK1 -and $r47okK2 -and $r47okK2s -and $r47okK3 -and $r47okK4 -and $r47okK5 -and $r47okK6 -and $r47okK7 -and $r47okK8 -and $r47okK9 -and
           $r47okR1 -and $r47okR2 -and $r47okR3 -and $r47NonVacuous) -Detail $r47detail

# =============================================================================================
# R-48 -- THE ANCHORS RECORD A DISPATCH KIND VERIFY CAN SCOPE, WITH THE TOKEN BESIDE IT
# =============================================================================================
# From a rider on an earlier row. mission-verify, run WITHOUT --dispatch-kind,
# scopes its gate by the top-level dispatch_kind of the --against artifact, and its scoping table
# admits build, rework, close, read-only and micro-ceremony and nothing else. The runner wrote the
# dispatch artifact's own kind token there verbatim, so an anchors file from a mainline dispatch
# refused at ANCHOR/dispatch_kind before a single arm ran -- while the runner's own gate translated
# mainline to build in the argv it passed verify (R-29 reads that argv).
#
# THE ROW'S STATED CAUSE IS AN ERRATUM, RECORDED AND BUILT PAST. The register attributes the 14
# mainline anchors on disk to the runner's 'mainline' FALLBACK for a dispatch declaring no kind. Every
# one of the 14 is its dispatch artifact's OWN declared kind: mainline, written verbatim. Every
# DISPATCH ARTIFACT declares a kind -- counted over the top level of .mission/dispatches when this was
# written: all 39 <id>.yaml artifacts, and all 52 files there that are neither a handoff nor an
# anchors file, carry a kind: line, while the 54 handoff files carry none -- and each of the 36 plain
# anchors records its own artifact's token. The fallback never fired on disk, and a cure confined to
# the fallback literal would have cured none of them.
#
# THE CURE: the writer records THIS dispatch's own declared kind (mainline when none is declared)
# through the runner's existing translation, ConvertTo-VerifyClass, now defined at script scope so the
# vacuous-first path can call it; and it records the declared token beside it as dispatch_kind_token,
# a column-0 key the runner's '^dispatch_kind:' reader does not match, written as a SINGLE-QUOTED
# scalar because it is the artifact's own string. The earlier note that the anchors writer keeps
# recording the kind token was an inventory of that patch's scope; it no longer describes the writer.
#
# THE ROWS:
#   1 CURED     -- a kind: mainline dispatch through the real runner writes dispatch_kind: build and
#                  dispatch_kind_token: 'mainline', one line each, the token single-quoted. This
#                  instrument applies a COPY of the runner's reader pattern to the file and lands on
#                  build; row 7 is where the runner's own reader is run
#   2 VERIFY    -- the REAL tools/mission-verify.ps1, WITHOUT --dispatch-kind, over row 1's anchors and
#                  over a CONTROL that is those same bytes with the one dispatch_kind line put back to
#                  mainline: the cured file does not refuse at ANCHOR/dispatch_kind and nothing is NOT
#                  REACHED; the control still refuses there with its arms NOT REACHED. Verify is
#                  reached through a shim that records the argv its process RECEIVED, so flagless is a
#                  reading, and a fourth run -- the control WITH --dispatch-kind build -- reads it
#                  False and no longer refuses at the kind. The gate is NOT asserted PASS: the fixture
#                  refuses on other subjects, and that is not this row's question.
#   3 KILL      -- row 1's input through a runner copy whose writer line is planted back to the token:
#                  the anchors read mainline, and the same flagless verify refuses at ANCHOR/dispatch_kind
#   4 VACUOUS   -- a genuinely-first dispatch, every prior and marker set aside and verify never
#                  invoked, still writes the translated kind: the writer works where the gate's
#                  else-branch never ran
#   5 PASS-THRU -- read-only and rework are written unchanged, a dispatch declaring no kind writes build
#                  with token mainline, an unknown word passes through for verify to refuse, and a kind
#                  carrying an apostrophe is written with the apostrophe doubled inside the quotes
#   6 KILL      -- THE HOIST PLANTED BACK OUT: the script-scope definition renamed, and the same body
#                  defined again inside the gate's else-branch, where it stood before the cure. On row
#                  1's input (a prior exists, the else-branch runs) that copy still writes build, so
#                  the plant removed the hoist and nothing else; on row 4's empty directory the same
#                  copy dies at the writer through the runner's trap, naming ConvertTo-VerifyClass,
#                  with no anchors written. What the hoist is for is driven here, not argued
#   7 GATE      -- the runner's OWN gate over a post-185 prior: row 1's runner-written anchors, made
#                  the newest file in the directory, and a read-only dispatch. The verify argv carries
#                  --against that file and --dispatch-kind build. The readings are distinct by
#                  construction: the prior's class is build, this dispatch's fallback is read-only,
#                  and the token line holds 'mainline' in quotes
#   8 KILL      -- row 7's input through a copy whose reader is pointed at the token key. This is a
#                  planted MUTATION, not a revert (no runner ever read that key): the kind passed is
#                  no longer build
#   9 KILL      -- row 5's apostrophe input through a copy whose token line is planted back to bare
#                  interpolation: the token line is written unquoted
#
# FORWARD ONLY: the anchors already committed are not rewritten, so a flagless verify against one that
# records mainline still refuses -- row 2's control is exactly that shape.
$r48Id      = 'D-WP2-R48'
$r48Dp      = Join-Path $missionRoot ".mission\dispatches\$r48Id.yaml"
$r48An      = Join-Path $missionRoot ".mission\dispatches\$r48Id.anchors.yaml"
$r48Created = Join-Path (Get-FixtureWorktreePath -Id $r48Id) 'worker-created.txt'
$r48Prior   = Join-Path $missionRoot '.mission\dispatches\D-R48PRIOR.anchors.yaml'
$r48GateId  = 'D-WP2-R48G'
$r48GatePrior = Join-Path $missionRoot '.mission\dispatches\D-R48P185.anchors.yaml'
$r48Saved   = Join-Path $sandbox 'r48-saved'
New-Item -ItemType Directory -Path $r48Saved -Force | Out-Null
$r48Head    = ''
$prevEap = $ErrorActionPreference
$ErrorActionPreference = 'Continue'
try { $r48Head = ("$(& git -C $missionRoot rev-parse HEAD 2>&1)").Trim() } finally { $ErrorActionPreference = $prevEap }
Write-Utf8 -Path $r48Prior -Text "dispatch_id: D-R48PRIOR`ndispatch_kind: read-only`nhead_sha: $r48Head`nworktree_tip_sha: $r48Head`ncapture_gaps_count: 0`n"

# THE VERIFY SHIM. It records the argv its own process received, one token per line, then runs the
# real mission-verify with exactly those tokens and relays its output and exit code. Written from a
# single-quoted here-string with two placeholders, so nothing in it is expanded by this instrument.
$r48Mv        = Join-Path $repoRoot 'tools\mission-verify.ps1'
$r48Shim      = Join-Path $stubDir 'r48-verify-shim.ps1'
$r48ShimArgv  = Join-Path $stubDir 'r48-verify-shim.argv.txt'
$r48ShimText  = @'
[System.IO.File]::WriteAllText('R48ARGVFILE', ($args -join [string][char]10))
$out = & powershell -NoProfile -ExecutionPolicy Bypass -File 'R48VERIFYPS1' @args 2>&1
$code = $LASTEXITCODE
if ($null -ne $out) { foreach ($l in @($out)) { Write-Output ([string]$l) } }
exit $code
'@
Write-Utf8 -Path $r48Shim -Text ($r48ShimText.Replace('R48ARGVFILE', $r48ShimArgv).Replace('R48VERIFYPS1', $r48Mv))

function Read-R48Kinds {
    # READ FROM THE BYTES THE RUNNER WROTE. readerSees applies a COPY of the runner's pattern text for a
    # prior's kind, character for character; it is not the runner's reader running (row 7 is).
    param([string]$Path)
    $res = [pscustomobject]@{ found = $false; kind = '(no anchors)'; token = '(no anchors)'; tokenRaw = '(no anchors)'; tokenQuoted = $false; kindLines = 0; tokenLines = 0; readerSees = '(no anchors)'; outcome = '(no anchors)' }
    if ((-not $Path) -or (-not (Test-Path -LiteralPath $Path))) { return $res }
    $text = [System.IO.File]::ReadAllText($Path)
    $res.found = $true
    $km = [regex]::Matches($text, '(?m)^dispatch_kind:[ \t]*(\S+)[ \t]*\r?$')
    $tm = [regex]::Matches($text, '(?m)^dispatch_kind_token:[ \t]*(\S.*?)[ \t]*\r?$')
    $res.kindLines  = $km.Count
    $res.tokenLines = $tm.Count
    $res.kind     = if ($km.Count -gt 0) { $km[0].Groups[1].Value } else { '(absent)' }
    $res.tokenRaw = if ($tm.Count -gt 0) { $tm[0].Groups[1].Value } else { '(absent)' }
    # A single-quoted YAML scalar: opening and closing quote, and every inner quote doubled.
    $res.tokenQuoted = [bool]($res.tokenRaw -match "^'(?:[^']|'')*'$")
    $res.token = if ($res.tokenQuoted) { $res.tokenRaw.Substring(1, $res.tokenRaw.Length - 2).Replace("''", "'") } else { $res.tokenRaw }
    $res.readerSees = if ($text -match '(?m)^dispatch_kind:[ \t]*(\S+)') { $Matches[1] } else { '(no match)' }
    $res.outcome = if ($text -match '(?m)^\s*outcome:[ \t]*(\S+)') { $Matches[1] } else { '(absent)' }
    return $res
}
function Save-R48Anchors {
    param([string]$Name)
    if (-not (Test-Path -LiteralPath $r48An)) { return '' }
    $dst = Join-Path $r48Saved $Name
    Copy-Item -LiteralPath $r48An -Destination $dst -Force
    if (-not (Test-Path -LiteralPath $dst)) { return '' }
    return $dst
}
function Get-R48DocSha {
    if (-not (Test-Path -LiteralPath $r48Dp)) { return '' }
    return (Get-FileHash -Algorithm SHA256 -LiteralPath $r48Dp).Hash.ToLowerInvariant()
}
function Invoke-R48KindRow {
    # Invoke-R2xRow's shape exactly, except the dispatch doc's kind line is the variable -- an empty
    # -Kind writes NO kind line at all, which is the case the fallback exists for -- and the id, the
    # runner and the verify stub may be named. The argv the scoping stub recorded is returned.
    param([string]$Kind, [string]$Id = $r48Id, [string]$RunnerPath = $runner, [string]$VerifyStub = $verifyPass)
    $dp = Join-Path $missionRoot ".mission\dispatches\$Id.yaml"
    $an = Join-Path $missionRoot ".mission\dispatches\$Id.anchors.yaml"
    $cr = Join-Path (Get-FixtureWorktreePath -Id $Id) 'worker-created.txt'
    $kindLine = if ($Kind) { "kind: $Kind`n" } else { '' }
    Write-Utf8 -Path $dp -Text ("id: $Id`nmission_id: mission-wp2-fixture`nworker_id: w-wp2-$($Id.ToLower())`n" + $kindLine + "feature_id: F-001`nassertion_targets: [A-001]`nspec_version: 1`nworktree_id: wt-$($Id.ToLower())`nmodel_class: coding-strong`ngoal_condition: `"the $Id fixture dispatch`"`n")
    $docSha = (Get-FileHash -Algorithm SHA256 -LiteralPath $dp).Hash.ToLowerInvariant()
    if (Test-Path -LiteralPath $an) { Remove-Item -LiteralPath $an -Force }
    Remove-Item -LiteralPath $cr -Force -ErrorAction SilentlyContinue
    if (Test-Path -LiteralPath $r2xArgvFile) { Remove-Item -LiteralPath $r2xArgvFile -Force }
    $argv = @('-NoProfile','-ExecutionPolicy','Bypass','-File',$RunnerPath,
              '-MissionRoot',$missionRoot,'-Dispatch',$Id,'-AllowIdReuse',
              '-VerifyCommand',$VerifyStub,'-WorkerCommand',$workerOk)
    $prevEap = $ErrorActionPreference
    $ErrorActionPreference = 'Continue'
    try {
        $out = & powershell @argv 2>&1
        $code = $LASTEXITCODE
    } finally { $ErrorActionPreference = $prevEap }
    $recorded = if (Test-Path -LiteralPath $r2xArgvFile) { [System.IO.File]::ReadAllText($r2xArgvFile) } else { '' }
    return [pscustomobject]@{ out = ((@($out) | ForEach-Object { "$_" }) -join "`n"); exit = $code; spawned = (Test-Path -LiteralPath $cr); kinds = (Read-R48Kinds -Path $an); argv = $recorded; docSha = $docSha }
}
function Add-R48Plant {
    # A SECOND plant into a copy New-UncuredCopy already made, under New-UncuredCopy's own rules: the
    # cured line must occur exactly once, the file is written UTF-8 without a BOM, and it must parse.
    param([string]$Target, [string]$CuredLine, [string]$OldLine)
    $text = [System.IO.File]::ReadAllText($Target)
    $hits = ([regex]::Matches($text, [regex]::Escape($CuredLine))).Count
    $planted = ($hits -eq 1)
    if ($planted) { [System.IO.File]::WriteAllText($Target, $text.Replace($CuredLine, $OldLine), (New-Object System.Text.UTF8Encoding($false))) }
    $pe = $null; $pt = $null
    if ($planted) { [void][System.Management.Automation.Language.Parser]::ParseFile($Target, [ref]$pt, [ref]$pe) }
    return [pscustomobject]@{ planted = $planted; parses = ($planted -and ($null -eq $pe -or $pe.Count -eq 0)) }
}
function Set-R48GatePrior {
    # Row 1's runner-written bytes under a prior's name, stamped newer than every other file in the
    # directory so the runner's newest-anchors pick is this file and no other.
    if ((-not $r48s1) -or (-not (Test-Path -LiteralPath $r48s1))) { return $false }
    [System.IO.File]::WriteAllBytes($r48GatePrior, [System.IO.File]::ReadAllBytes($r48s1))
    $others = @(Get-ChildItem -LiteralPath (Join-Path $missionRoot '.mission\dispatches') -File -ErrorAction SilentlyContinue |
                Where-Object { $_.FullName -ne $r48GatePrior } | Sort-Object LastWriteTimeUtc -Descending)
    $stamp = [DateTime]::UtcNow
    if (($others.Count -gt 0) -and ($others[0].LastWriteTimeUtc -gt $stamp)) { $stamp = $others[0].LastWriteTimeUtc }
    (Get-Item -LiteralPath $r48GatePrior).LastWriteTimeUtc = $stamp.AddSeconds(10)
    return $true
}
# THE CONSUMER, RUN FOR REAL, THROUGH THE SHIM. Every reading is taken from what the shim recorded and
# from the report verify printed: refused_by by entry, the report's own dispatch_kind, every NOT REACHED.
function Invoke-R48Verify {
    param([string]$AnchorsPath, [string]$Tag, [string]$DispatchKind = '')
    $res = [pscustomobject]@{ ran = $false; flagless = $false; argvSeen = '(not run)'; exit = '(not run)'; gate = '(none)'; reportKind = '(none)'; refusedBy = @(); kindRefused = $false; notReached = 0 }
    if (-not (Test-Path -LiteralPath $r48Mv)) { return $res }
    if (-not (Test-Path -LiteralPath $r48Shim)) { return $res }
    if ((-not $AnchorsPath) -or (-not (Test-Path -LiteralPath $AnchorsPath))) { return $res }
    $ev = Join-Path $sandbox ('r48-verify-' + $Tag)
    # --dispatch-kind is added ONLY when a kind is named; the flagless rows name none, and verify must
    # then take the kind from the artifact.
    $argv = @('-NoProfile','-ExecutionPolicy','Bypass','-File',$r48Shim,
              '--against',$AnchorsPath,'--evidence-root',$ev,'--format','yaml')
    if ($DispatchKind) { $argv = @($argv + @('--dispatch-kind', $DispatchKind)) }
    if (Test-Path -LiteralPath $r48ShimArgv) { Remove-Item -LiteralPath $r48ShimArgv -Force }
    $out = @()
    $code = $null
    $prevEap = $ErrorActionPreference
    $ErrorActionPreference = 'Continue'
    Push-Location $missionRoot
    try {
        $out = & powershell @argv 2>&1
        $code = $LASTEXITCODE
    } finally { Pop-Location; $ErrorActionPreference = $prevEap }
    $seen = @()
    if (Test-Path -LiteralPath $r48ShimArgv) { $seen = @([System.IO.File]::ReadAllText($r48ShimArgv) -split "`n") }
    $res.argvSeen = if ($seen.Count -gt 0) { $seen -join ' ' } else { '(the shim recorded nothing)' }
    # FLAGLESS IS READ FROM WHAT THE PROCESS RECEIVED: the shim wrote its argv, and it can say either.
    $res.flagless = (($seen -contains '--against') -and (-not ($seen -contains '--dispatch-kind')))
    $joined = ((@($out) | ForEach-Object { "$_" }) -join "`n")
    $res.exit = $code
    $res.ran  = [bool]($joined -match '(?m)^arms_not_run:')
    if ($joined -match '(?m)^gate:[ \t]*(\S+)') { $res.gate = $Matches[1] }
    if ($joined -match '(?m)^dispatch_kind:[ \t]*[''"]?([^''"\s]+)') { $res.reportKind = $Matches[1] }
    $rb = @()
    $inBlock = $false
    foreach ($l in ($joined -split '\r?\n')) {
        if ($l -match '^refused_by:[ \t]*$') { $inBlock = $true; continue }
        if ($inBlock) {
            if ($l -match '^\s+-\s+[''"]?([A-Za-z0-9_./-]+)') { $rb += $Matches[1] } else { $inBlock = $false }
        }
    }
    $res.refusedBy   = $rb
    $res.kindRefused = ($rb -contains 'ANCHOR/dispatch_kind')
    $res.notReached  = ([regex]::Matches($joined, 'NOT REACHED')).Count
    return $res
}

# ---- row 1: CURED -- a kind: mainline dispatch through the real runner -----------------------------
$r48r1   = Invoke-R2xRow -Id $r48Id -RunnerPath $runner -VerifyStub $verifyPass
$r48k1   = Read-R48Kinds -Path $r48An
$r48p1   = Test-R35Parses -Path $r48An
$r48doc1 = Get-R48DocSha
$r48s1   = Save-R48Anchors -Name 'cured.anchors.yaml'
$r48ok1  = (($r48r1.exit -eq 0) -and $r48r1.spawned -and ($r48k1.kind -ceq 'build') -and ($r48k1.token -ceq 'mainline') -and
            $r48k1.tokenQuoted -and ($r48k1.tokenRaw -ceq "'mainline'") -and
            ($r48k1.kindLines -eq 1) -and ($r48k1.tokenLines -eq 1) -and ($r48k1.readerSees -ceq 'build') -and
            ($r48k1.outcome -ceq 'verified-pass') -and $r48p1 -and ($r48s1 -ne ''))

# ---- row 3: THE PLANTED-REVERT KILL -- row 1's input, the writer line put back to the token --------
$r48Copy = New-UncuredCopy -Name 'uncured48' `
    -CuredLine '[void]$sb.AppendLine("dispatch_kind: $(ConvertTo-VerifyClass -KindToken $anchorsKindToken)")' `
    -OldLine   '[void]$sb.AppendLine("dispatch_kind: $anchorsKindToken")'
$r48r3   = Invoke-WithHookRepointed -Decider $r48Copy.decider -Body { Invoke-R2xRow -Id $r48Id -RunnerPath $r48Copy.runner -VerifyStub $verifyPass }
$r48k3   = Read-R48Kinds -Path $r48An
$r48doc3 = Get-R48DocSha
$r48s3   = Save-R48Anchors -Name 'uncured.anchors.yaml'

# ---- row 6, first half: THE HOIST PLANTED BACK OUT, on row 1's input -------------------------------
# Plant one renames the script-scope definition so it defines nothing the runner calls; plant two puts
# the same body back inside the gate's else-branch, immediately before the line that first uses it
# there. The body lines are the shipped body, re-indented one level.
$r48HoistBody = @(
    '        function ConvertTo-VerifyClass {',
    '            param([string]$KindToken)',
    '            switch ($KindToken) {',
    "                'mainline'  { 'build' }",
    "                'fanout'    { 'build' }",
    "                'build'     { 'build' }",
    "                'rework'    { 'rework' }",
    "                'close'     { 'close' }",
    "                'read-only' { 'read-only' }",
    '                default     { $KindToken }',
    '            }',
    '        }'
)
$r48KindRawLine = '        $kindRaw = if ($dispatchDoc[''kind'']) { [string]$dispatchDoc[''kind''] } else { ''mainline'' }'
$r48HoistLines  = @($r48HoistBody) + @($r48KindRawLine)
$r48Unhoisted   = $r48HoistLines -join "`r`n"
$r48CopyH  = New-UncuredCopy -Name 'unhoisted48' -CuredLine 'function ConvertTo-VerifyClass {' -OldLine 'function ConvertTo-VerifyClassNotHoisted {'
$r48PlantH = Add-R48Plant -Target $r48CopyH.runner -CuredLine $r48KindRawLine -OldLine $r48Unhoisted
$r48r6a  = Invoke-WithHookRepointed -Decider $r48CopyH.decider -Body { Invoke-R2xRow -Id $r48Id -RunnerPath $r48CopyH.runner -VerifyStub $verifyPass }
$r48k6a  = Read-R48Kinds -Path $r48An
$r48doc6 = Get-R48DocSha

# ---- row 4: VACUOUS-FIRST -- every prior and every marker set aside, byte for byte ------------------
# The set-aside is this member's own and is put back the same way; R-37's reset is not reused because
# it backs up only on its first call. Row 6's second half runs inside the same set-aside.
$r48Aside = @()
foreach ($f in @(Get-ChildItem -LiteralPath (Join-Path $missionRoot '.mission\dispatches') -File -ErrorAction SilentlyContinue |
                 Where-Object { $_.Name -notlike "$r48Id.*" })) {
    $r48Aside += [pscustomobject]@{ path = $f.FullName; bytes = [System.IO.File]::ReadAllBytes($f.FullName) }
}
foreach ($d in @((Join-Path $missionRoot '.mission'), (Join-Path $missionRoot '.mission-runtime'))) {
    foreach ($f in @(Get-ChildItem -LiteralPath $d -Recurse -File -Filter '*.superseded.yaml' -ErrorAction SilentlyContinue)) {
        if (@($r48Aside | Where-Object { $_.path -eq $f.FullName }).Count -eq 0) {
            $r48Aside += [pscustomobject]@{ path = $f.FullName; bytes = [System.IO.File]::ReadAllBytes($f.FullName) }
        }
    }
}
foreach ($a in $r48Aside) { Remove-Item -LiteralPath $a.path -Force }
$r48AsideCount = @($r48Aside).Count
$r48r4  = Invoke-R2xRow -Id $r48Id -RunnerPath $runner -VerifyStub $verifyScoping
$r48k4  = Read-R48Kinds -Path $r48An
$r48p4  = Test-R35Parses -Path $r48An
$r48Vac4 = ($r48r4.argv -eq '')
$r48doc4 = Get-R48DocSha
# ---- row 6, second half: the un-hoisted copy on the same empty directory ---------------------------
$r48Left6 = @(Get-ChildItem -LiteralPath (Join-Path $missionRoot '.mission\dispatches') -File -ErrorAction SilentlyContinue |
              Where-Object { $_.Name -notlike "$r48Id.*" }).Count
$r48r6b  = Invoke-WithHookRepointed -Decider $r48CopyH.decider -Body { Invoke-R2xRow -Id $r48Id -RunnerPath $r48CopyH.runner -VerifyStub $verifyScoping }
$r48k6b  = Read-R48Kinds -Path $r48An
$r48doc6b = Get-R48DocSha
$r48Trap6  = [bool]($r48r6b.out -match 'UNHANDLED ERROR')
$r48Named6 = [bool]($r48r6b.out -match 'ConvertTo-VerifyClass')
foreach ($a in $r48Aside) {
    if (-not (Test-Path -LiteralPath $a.path)) {
        New-Item -ItemType Directory -Path (Split-Path -Parent $a.path) -Force | Out-Null
        [System.IO.File]::WriteAllBytes($a.path, $a.bytes)
    }
}
$r48Back = @($r48Aside | Where-Object { Test-Path -LiteralPath $_.path }).Count
$r48ok4 = (($r48r4.exit -eq 0) -and $r48r4.spawned -and $r48Vac4 -and ($r48k4.outcome -ceq 'vacuous-first') -and
           ($r48k4.kind -ceq 'build') -and ($r48k4.token -ceq 'mainline') -and $r48k4.tokenQuoted -and ($r48k4.kindLines -eq 1) -and ($r48k4.tokenLines -eq 1) -and
           $r48p4 -and ($r48AsideCount -ge 1) -and ($r48Back -eq $r48AsideCount))
$r48ok6 = ($r48CopyH.planted -and $r48CopyH.parses -and $r48PlantH.planted -and $r48PlantH.parses -and
           ($r48r6a.exit -eq 0) -and $r48r6a.spawned -and ($r48k6a.kind -ceq 'build') -and ($r48k6a.token -ceq 'mainline') -and ($r48doc6 -ne '') -and ($r48doc6 -eq $r48doc1) -and
           ($r48Left6 -eq 0) -and ($r48r6b.exit -ne 0) -and ($r48r6b.argv -eq '') -and (-not $r48k6b.found) -and $r48Trap6 -and $r48Named6 -and
           ($r48doc6b -eq $r48doc4) -and ($r48r4.exit -eq 0))

# ---- row 5: PASS-THROUGH -- the translation's other arms, each through the real runner ---------------
$r48Cases = @(
    [pscustomobject]@{ declared = 'read-only'; kind = 'read-only'; token = 'read-only'; raw = "'read-only'" }
    [pscustomobject]@{ declared = 'rework';    kind = 'rework';    token = 'rework';    raw = "'rework'" }
    [pscustomobject]@{ declared = '';          kind = 'build';     token = 'mainline';  raw = "'mainline'" }
    [pscustomobject]@{ declared = 'banana';    kind = 'banana';    token = 'banana';    raw = "'banana'" }
    [pscustomobject]@{ declared = "it's";      kind = "it's";      token = "it's";      raw = "'it''s'" }
)
$r48CaseArity = ($r48Cases.Count -eq 5)
$r48Pass = @()
foreach ($c in $r48Cases) {
    $run = Invoke-R48KindRow -Kind $c.declared
    $okc = (($run.exit -eq 0) -and $run.spawned -and ($run.kinds.kind -ceq $c.kind) -and ($run.kinds.token -ceq $c.token) -and
            $run.kinds.tokenQuoted -and ($run.kinds.tokenRaw -ceq $c.raw) -and
            ($run.kinds.kindLines -eq 1) -and ($run.kinds.tokenLines -eq 1))
    $label = if ($c.declared) { 'kind: ' + $c.declared } else { '(no kind line)' }
    $r48Pass += [pscustomobject]@{ label = $label; ok = $okc; run = $run; want = $c }
}
$r48ok5 = ($r48CaseArity -and (@($r48Pass).Count -eq 5) -and (@($r48Pass | Where-Object { $_.ok }).Count -eq 5))
$r48Apos = @($r48Pass | Where-Object { $_.want.declared -ceq "it's" })

# ---- row 9: THE QUOTING KILL -- the apostrophe input, the token line planted back to bare --------------
$r48CopyQ = New-UncuredCopy -Name 'unquoted48' `
    -CuredLine '[void]$sb.AppendLine("dispatch_kind_token: $(ConvertTo-YamlSingleQuoted $anchorsKindToken)")' `
    -OldLine   '[void]$sb.AppendLine("dispatch_kind_token: $anchorsKindToken")'
$r48r9 = Invoke-WithHookRepointed -Decider $r48CopyQ.decider -Body { Invoke-R48KindRow -Kind "it's" -RunnerPath $r48CopyQ.runner }
$r48ok9 = ($r48CopyQ.planted -and $r48CopyQ.parses -and ($r48r9.exit -eq 0) -and $r48r9.spawned -and
           ($r48r9.kinds.tokenLines -eq 1) -and (-not $r48r9.kinds.tokenQuoted) -and ($r48r9.kinds.tokenRaw -ceq "it's") -and
           ($r48Apos.Count -eq 1) -and ($r48r9.docSha -eq $r48Apos[0].run.docSha))

# ---- row 7: THE RUNNER'S OWN GATE over a post-185 prior ----------------------------------------------
$r48GateSet7 = Set-R48GatePrior
$r48kg       = Read-R48Kinds -Path $r48GatePrior
$r48r7 = Invoke-R48KindRow -Kind 'read-only' -Id $r48GateId -VerifyStub $verifyScoping
$r48Kind7  = if ($r48r7.argv -match '--dispatch-kind\s+(\S+)') { $Matches[1] } else { '(none)' }
$r48Basis7 = Get-R37Basis -R $r48r7
$r48Said7  = [bool]($r48r7.out -match "prior's recorded dispatch_kind 'build'")
$r48ok7 = ($r48GateSet7 -and ($r48kg.kind -ceq 'build') -and $r48kg.tokenQuoted -and ($r48kg.token -ceq 'mainline') -and
           ($r48Basis7 -ceq 'D-R48P185.anchors.yaml') -and ($r48Kind7 -ceq 'build') -and $r48Said7)

# ---- row 8: THE READER MUTATION -- row 7's input, the gate's reader pointed at the token key ---------
$r48CopyG = New-UncuredCopy -Name 'reader48' `
    -CuredLine '            if ($priorText -match ''(?m)^dispatch_kind:[ \t]*(\S+)'') { $priorKind = $Matches[1] }' `
    -OldLine   '            if ($priorText -match ''(?m)^dispatch_kind_token:[ \t]*(\S+)'') { $priorKind = $Matches[1] }'
$r48GateSet8 = Set-R48GatePrior
$r48r8 = Invoke-WithHookRepointed -Decider $r48CopyG.decider -Body { Invoke-R48KindRow -Kind 'read-only' -Id $r48GateId -RunnerPath $r48CopyG.runner -VerifyStub $verifyScoping }
$r48Kind8  = if ($r48r8.argv -match '--dispatch-kind\s+(\S+)') { $Matches[1] } else { '(none)' }
$r48Basis8 = Get-R37Basis -R $r48r8
$r48ok8 = ($r48CopyG.planted -and $r48CopyG.parses -and $r48GateSet8 -and ($r48Basis8 -ceq 'D-R48P185.anchors.yaml') -and
           ($r48Kind8 -cne 'build') -and ($r48Kind8 -cne '(none)') -and [bool]($r48Kind8 -match 'mainline') -and ($r48r8.docSha -eq $r48r7.docSha))

# ---- row 2 and row 3's consumer: THE REAL VERIFY, through the shim, after every runner row -------------
# Verify resolves its repository root and the normative manifest schema from its working directory,
# so it runs from the fixture root; both were put there by earlier members and are ensured, not assumed.
$r48Schema = Join-Path $missionRoot 'docs\framework\evidence-manifest.schema.json'
if (-not (Test-Path -LiteralPath $r48Schema)) {
    New-Item -ItemType Directory -Path (Split-Path -Parent $r48Schema) -Force | Out-Null
    Copy-Item -LiteralPath (Join-Path $repoRoot 'docs\framework\evidence-manifest.schema.json') -Destination $r48Schema -Force
}
$r48MissionYaml = Join-Path $missionRoot '.mission\mission.yaml'
if (-not (Test-Path -LiteralPath $r48MissionYaml)) { Write-Utf8 -Path $r48MissionYaml -Text "id: mission-wp2-fixture`n" }
# THE CONTROL IS ROW 1'S OWN BYTES WITH ONE LINE CHANGED, so the kind is the only variable between them.
$r48Control   = Join-Path $r48Saved 'control-mainline.anchors.yaml'
$r48CtlSwaps  = 0
$r48CtlDelta  = -1
if ($r48s1) {
    $r48CuredText = [System.IO.File]::ReadAllText($r48s1)
    $r48CtlSwaps  = ([regex]::Matches($r48CuredText, '(?m)^dispatch_kind: build(?=\r?$)')).Count
    if ($r48CtlSwaps -eq 1) {
        [System.IO.File]::WriteAllText($r48Control, ([regex]::Replace($r48CuredText, '(?m)^dispatch_kind: build(?=\r?$)', 'dispatch_kind: mainline')), (New-Object System.Text.UTF8Encoding($false)))
        $r48CtlDelta = (Get-Item -LiteralPath $r48Control).Length - (Get-Item -LiteralPath $r48s1).Length
    }
}
$r48CtlPath = if ($r48CtlSwaps -eq 1) { $r48Control } else { '' }
$r48v1 = Invoke-R48Verify -AnchorsPath $r48s1 -Tag 'cured'
$r48v2 = Invoke-R48Verify -AnchorsPath $r48CtlPath -Tag 'control'
$r48v3 = Invoke-R48Verify -AnchorsPath $r48s3 -Tag 'uncured'
$r48v4 = Invoke-R48Verify -AnchorsPath $r48CtlPath -Tag 'control-flagged' -DispatchKind 'build'

$r48ok2 = ($r48v1.ran -and $r48v1.flagless -and ($r48v1.reportKind -ceq 'build') -and (-not $r48v1.kindRefused) -and ($r48v1.notReached -eq 0) -and
           $r48v2.ran -and $r48v2.flagless -and ($r48v2.reportKind -ceq 'mainline') -and $r48v2.kindRefused -and ($r48v2.notReached -ge 1) -and
           $r48v4.ran -and (-not $r48v4.flagless) -and ($r48v4.reportKind -ceq 'build') -and (-not $r48v4.kindRefused) -and ($r48v4.notReached -eq 0) -and
           ($r48CtlSwaps -eq 1) -and ($r48CtlDelta -eq 3))
$r48ok3 = ($r48Copy.planted -and $r48Copy.parses -and ($r48r3.exit -eq 0) -and $r48r3.spawned -and
           ($r48k3.kind -ceq 'mainline') -and ($r48k3.token -ceq 'mainline') -and ($r48k3.kindLines -eq 1) -and
           ($r48doc1 -ne '') -and ($r48doc3 -eq $r48doc1) -and
           $r48v3.ran -and $r48v3.flagless -and ($r48v3.reportKind -ceq 'mainline') -and $r48v3.kindRefused -and ($r48v3.notReached -ge 1))

$r48Rows = @()
$r48Rows += Format-R2xRow -Id '1 CURED kind: mainline, real runner' -RowOk $r48ok1 -Text ("exit={0} spawned={1} dispatch_kind={2} dispatch_kind_token line={3} quoted={4} lines={5}/{6} the runner's pattern, applied here, sees={7} gate outcome={8} parses={9}  (expect 0, True, build, 'mainline', True, 1/1, build, verified-pass, True)" -f $r48r1.exit, $r48r1.spawned, $r48k1.kind, $r48k1.tokenRaw, $r48k1.tokenQuoted, $r48k1.kindLines, $r48k1.tokenLines, $r48k1.readerSees, $r48k1.outcome, $r48p1) -Said (Get-R28Said $r48r1.out)
$r48Rows += Format-R2xRow -Id '2 REAL verify, argv read by the shim' -RowOk $r48ok2 -Text ("cured: ran={0} flagless={1} report kind={2} refused at dispatch_kind={3} NOT REACHED={4} | control: ran={5} flagless={6} report kind={7} refused at dispatch_kind={8} NOT REACHED={9} | control WITH --dispatch-kind build: ran={10} flagless={11} report kind={12} refused at dispatch_kind={13} NOT REACHED={14} | control lines swapped={15} bytes added={16}  (expect True True build False 0 | True True mainline True >=1 | True False build False 0 | 1, 3)" -f $r48v1.ran, $r48v1.flagless, $r48v1.reportKind, $r48v1.kindRefused, $r48v1.notReached, $r48v2.ran, $r48v2.flagless, $r48v2.reportKind, $r48v2.kindRefused, $r48v2.notReached, $r48v4.ran, $r48v4.flagless, $r48v4.reportKind, $r48v4.kindRefused, $r48v4.notReached, $r48CtlSwaps, $r48CtlDelta) -Said ''
$r48Rows += Format-R2xRow -Id '3 planted revert of the writer, row 1 input' -RowOk $r48ok3 -Text ("plant located={0} parses={1} exit={2} spawned={3} dispatch_kind={4} token={5} same dispatch doc as row 1={6} | verify: ran={7} flagless={8} report kind={9} refused at dispatch_kind={10} NOT REACHED={11}  (expect True, True, 0, True, mainline, mainline, True | True True mainline True >=1 -- the kill)" -f $r48Copy.planted, $r48Copy.parses, $r48r3.exit, $r48r3.spawned, $r48k3.kind, $r48k3.token, ($r48doc3 -eq $r48doc1), $r48v3.ran, $r48v3.flagless, $r48v3.reportKind, $r48v3.kindRefused, $r48v3.notReached) -Said (Get-R28Said $r48r3.out)
$r48Rows += Format-R2xRow -Id '4 VACUOUS-FIRST, verify never invoked' -RowOk $r48ok4 -Text ("exit={0} spawned={1} verify never invoked={2} gate outcome={3} dispatch_kind={4} token={5} quoted={6} lines={7}/{8} parses={9} set aside={10} put back={11}  (expect 0, True, True, vacuous-first, build, mainline, True, 1/1, True, >=1, equal)" -f $r48r4.exit, $r48r4.spawned, $r48Vac4, $r48k4.outcome, $r48k4.kind, $r48k4.token, $r48k4.tokenQuoted, $r48k4.kindLines, $r48k4.tokenLines, $r48p4, $r48AsideCount, $r48Back) -Said (Get-R28Said $r48r4.out)
foreach ($p in $r48Pass) {
    $r48Rows += Format-R2xRow -Id ('5 PASS-THRU ' + $p.label) -RowOk $p.ok -Text ("exit={0} spawned={1} dispatch_kind={2} token={3} token line={4} quoted={5} lines={6}/{7}  (expect 0, True, {8}, {9}, {10}, True, 1/1)" -f $p.run.exit, $p.run.spawned, $p.run.kinds.kind, $p.run.kinds.token, $p.run.kinds.tokenRaw, $p.run.kinds.tokenQuoted, $p.run.kinds.kindLines, $p.run.kinds.tokenLines, $p.want.kind, $p.want.token, $p.want.raw) -Said (Get-R28Said $p.run.out)
}
$r48Rows += Format-R2xRow -Id '6 planted revert of the hoist, both paths' -RowOk $r48ok6 -Text ("rename located={0} parses={1} else-branch body located={2} parses={3} | row 1 input: exit={4} spawned={5} dispatch_kind={6} token={7} same doc as row 1={8} | row 4 staging: other files={9} exit={10} verify never invoked={11} anchors written={12} runner trap={13} names ConvertTo-VerifyClass={14} same doc as row 4={15} (row 4 itself exit={16})  (expect True, True, True, True | 0, True, build, mainline, True | 0, non-zero, True, False, True, True, True (0) -- the kill)" -f $r48CopyH.planted, $r48CopyH.parses, $r48PlantH.planted, $r48PlantH.parses, $r48r6a.exit, $r48r6a.spawned, $r48k6a.kind, $r48k6a.token, ($r48doc6 -eq $r48doc1), $r48Left6, $r48r6b.exit, ($r48r6b.argv -eq ''), $r48k6b.found, $r48Trap6, $r48Named6, ($r48doc6b -eq $r48doc4), $r48r4.exit) -Said (Get-R28Said $r48r6b.out)
$r48Rows += Format-R2xRow -Id '7 GATE the runner reads a post-185 prior' -RowOk $r48ok7 -Text ("prior staged={0} prior dispatch_kind={1} prior token={2} quoted={3} | this dispatch kind: read-only | basis passed={4} --dispatch-kind passed={5} runner named the prior's build={6} (exit={7} spawned={8}, reported only)  (expect True, build, mainline, True | D-R48P185.anchors.yaml, build, True)" -f $r48GateSet7, $r48kg.kind, $r48kg.token, $r48kg.tokenQuoted, $r48Basis7, $r48Kind7, $r48Said7, $r48r7.exit, $r48r7.spawned) -Said (Get-R28Said $r48r7.out)
$r48Rows += Format-R2xRow -Id '8 planted mutation of the reader, row 7 input' -RowOk $r48ok8 -Text ("plant located={0} parses={1} prior staged={2} basis passed={3} --dispatch-kind passed={4} same dispatch doc as row 7={5}  (expect True, True, True, D-R48P185.anchors.yaml, not build and naming mainline, True -- the kill)" -f $r48CopyG.planted, $r48CopyG.parses, $r48GateSet8, $r48Basis8, $r48Kind8, ($r48r8.docSha -eq $r48r7.docSha)) -Said (Get-R28Said $r48r8.out)
$r48Rows += Format-R2xRow -Id '9 planted revert of the quoting, apostrophe' -RowOk $r48ok9 -Text ("plant located={0} parses={1} exit={2} spawned={3} token line={4} quoted={5} lines={6} same dispatch doc as row 5's apostrophe case={7}  (expect True, True, 0, True, it's, False, 1, True -- the kill)" -f $r48CopyQ.planted, $r48CopyQ.parses, $r48r9.exit, $r48r9.spawned, $r48r9.kinds.tokenRaw, $r48r9.kinds.tokenQuoted, $r48r9.kinds.tokenLines, (($r48Apos.Count -eq 1) -and ($r48r9.docSha -eq $r48Apos[0].run.docSha))) -Said (Get-R28Said $r48r9.out)

# NON-VACUITY, counted over what verify and the runner DID.
$r48VerifyAll     = @($r48v1, $r48v2, $r48v3, $r48v4)
$r48RefusedAtKind = @($r48VerifyAll | Where-Object { $_.kindRefused }).Count
$r48VerifyRan     = @($r48VerifyAll | Where-Object { $_.ran }).Count
$r48FlaglessTrue  = @($r48VerifyAll | Where-Object { $_.flagless }).Count
$r48VerifySplit   = (($r48VerifyRan -eq 4) -and ($r48RefusedAtKind -eq 2) -and ($r48FlaglessTrue -eq 3))
$r48Written       = @(@($r48k1.kind, $r48k3.kind, $r48k4.kind) + @($r48Pass | ForEach-Object { $_.run.kinds.kind }))
$r48Distinct      = @($r48Written | Select-Object -Unique).Count
$r48WrittenArity  = ($r48Written.Count -eq 8)
$r48QuotedRuns    = @(@($r48k1, $r48k3, $r48k4, $r48k6a, $r48r9.kinds) + @($r48Pass | ForEach-Object { $_.run.kinds }))
$r48QuotedCount   = @($r48QuotedRuns | Where-Object { $_.tokenQuoted }).Count
$r48QuoteSplit    = (($r48QuotedRuns.Count -eq 10) -and ($r48QuotedCount -eq 9))
$r48RowOks        = @($r48ok1, $r48ok2, $r48ok3, $r48ok4, $r48ok5, $r48ok6, $r48ok7, $r48ok8, $r48ok9)
$r48RowArity      = (($r48RowOks.Count -eq 9) -and (@($r48Rows).Count -eq 13))

Remove-Item -LiteralPath $r48Prior -Force -ErrorAction SilentlyContinue
Remove-Item -LiteralPath $r48GatePrior -Force -ErrorAction SilentlyContinue

$r48detail = @"
    THE ROWS, each a real run of the real runner, a planted copy of it, or the real mission-verify in the sandbox, every value READ from what they wrote, printed or received:
$($r48Rows -join "`n")
    verify runs that produced a report: $r48VerifyRan of 4   refused at ANCHOR/dispatch_kind: $r48RefusedAtKind (expect 2 -- the flagless control and the kill, never the cured file, never the flagged control)
      flagless as read by the shim: $r48FlaglessTrue of 4 (expect 3 -- the flagged control reads False)   split: $r48VerifySplit
    dispatch_kind values the runner wrote across rows 1, 3, 4 and 5 (8 runs): $($r48Written -join ', ')   distinct: $r48Distinct (expect 6)   arity held: $r48WrittenArity
    token lines single-quoted across 10 runs (rows 1, 3, 4, 5, row 6's first half, row 9): $r48QuotedCount (expect 9 -- row 9 is the one bare line)   split: $r48QuoteSplit
    row arity held: $r48RowArity
    (counted over what the runs DID, not over this table's expectations)
    what verify refused on, by artifact (the gate is not asserted; only where the kind lands is):
      cured           gate=$($r48v1.gate) exit=$($r48v1.exit) refused_by: $($r48v1.refusedBy -join ', ')
      control         gate=$($r48v2.gate) exit=$($r48v2.exit) refused_by: $($r48v2.refusedBy -join ', ')
      uncured         gate=$($r48v3.gate) exit=$($r48v3.exit) refused_by: $($r48v3.refusedBy -join ', ')
      control flagged gate=$($r48v4.gate) exit=$($r48v4.exit) refused_by: $($r48v4.refusedBy -join ', ')
    the argv the shim recorded for the flagged control: $($r48v4.argvSeen)
    the verify argv row 7 recorded: $($r48r7.argv)
    the verify argv row 8 recorded: $($r48r8.argv)
    the artifacts: cured=$r48s1
                   control=$r48Control
                   uncured=$r48s3
    WHAT THIS MEMBER DOES NOT ASSERT:
      * that a flagless verify PASSES on a runner-written anchors file. It reaches its arms; in this
        fixture it then refuses on other subjects, as the refused_by lists above show.
      * anything about the anchors already committed in .mission/dispatches. The cure is forward only:
        they are not rewritten, and a flagless verify against one recording mainline still refuses,
        which is the control's shape.
      * any change to tools/mission-verify.ps1. None was made; the control refusing is the evidence.
      * that the 14 mainline anchors on disk came from the fallback, as the register row words it.
        They are declared tokens written verbatim, and rows 1 and 5 drive both cases.
      * that the dispatch_kind line is quoted. It is not: the gate's reader takes a prior's kind with
        (\S+), so a quoted class would carry its quotes into the translation. An unknown word still
        reaches that line bare, as before the cure.
      * that row 8 is a revert. No runner ever read the token key; it is a planted mutation that shows
        row 7 can tell which key the reader lands on.
      * the exit code of row 6's vacuous half beyond non-zero. The runner's trap names the error; its
        exit is reported above.
    the planted copies : $($r48Copy.runner)
                         $($r48CopyH.runner)
                         $($r48CopyG.runner)
                         $($r48CopyQ.runner)
"@
Check -Id 'R-48' -Title 'the anchors record a dispatch kind mission-verify can scope: a mainline dispatch writes dispatch_kind build with a single-quoted dispatch_kind_token, a verify that received no --dispatch-kind no longer refuses at ANCHOR/dispatch_kind while a mainline control still does and the same control with the flag does not, the vacuous-first path writes the class and a runner with the hoist planted back out dies there, the runner''s own gate reads build off a post-cure prior, and runners with the writer, the reader or the quoting planted back each go red on the same input' `
      -Ok ($r48ok1 -and $r48ok2 -and $r48ok3 -and $r48ok4 -and $r48ok5 -and $r48ok6 -and $r48ok7 -and $r48ok8 -and $r48ok9 -and
           $r48VerifySplit -and ($r48Distinct -eq 6) -and $r48WrittenArity -and $r48QuoteSplit -and $r48RowArity) -Detail $r48detail

# =============================================================================================
# R-49 -- A DISPATCH THAT RAN DENIES VACUITY, NOT ONLY A DISPATCH THAT WAS REJECTED
# =============================================================================================
# A RESIDUAL, from an earlier revision's deferrals, taken on the lead's ruling. It
# is NOT a registered row: its candidate is listed under NOT REGISTERED HERE. R-37b made the
# vacuity denial read the WIDE name rule, but that denial still fired only on a record carrying
# 'status: rejected'. A record that a dispatch RAN with no such line, under a name the narrow rule
# refuses as a basis, denied nothing: the runner took the vacuous-first path, never invoked verify,
# and recorded prior_artifacts: 0 beside it.
#
# THE DISPATCH'S WORDING IS AN ERRATUM, RECORDED AND BUILT PAST. It names "four archived-name
# handoffs". The four *.handoff.aborted-seq* files in .mission/dispatches carry 'status: rejected' and
# already refused; the gap is the four *.anchors.aborted-seq* files, which carry no status line at all.
# The deferral says so, and the census at the end of this member re-measures it.
#
# THE CURE (tools/lam/mission-dispatch.ps1): a new pre-spawn denial, exit 2, placed AFTER the
# rejected-handoff denial and AFTER the marker denial so both keep their messages, that fires when
# there is no basis and rule 2 sees any ran record that is not a rejection; its message names each
# record. The vacuous-first record's prior_artifacts is COUNTED over rule 2's set, no longer a literal.
#
# THE ROWS:
#   1 CURED     -- an archived anchors file with no status line is the only prior: refused, exit 2,
#                  not spawned, verify never invoked, nothing written, the file named
#   2 CURED     -- the runner's own retained <id>.handoff.worktree-placed.yaml alone, its rejection
#                  stub AND its dispatch's plain anchors gone: refused the same way. That is an
#                  operator-altered directory, not the runner's write shape -- a rejecting run writes
#                  its plain anchors before the retained handoff, and those anchors are a basis for
#                  every other id; row 5 is the write shape
#   3 CONTROL   -- nothing on disk: still vacuous-first, verify never invoked, prior_artifacts: 0
#   4 UNCHANGED -- R-37a row 3's shape (a rejected handoff and a newer RENAMED retained handoff): still
#                  the REJECTED handoff refusal, the retained name nowhere, the new sentence absent
#   5 UNCHANGED -- the runner's real rejection write shape (the stub plus <id>.handoff.worktree-placed.yaml):
#                  the same
#   6 NO-FIRE   -- a plain anchors basis beside an archived one: verify is invoked against the plain file
#                  and the new sentence is absent
#   7 KILL      -- row 1's bytes through a runner whose new denial is planted back to the rejection-only
#                  test: exit 0, spawned, verify never invoked, and the counted record says 1
#   8 KILL      -- row 2's bytes through the same copy: the same walk through the gate
#   9 RECORD    -- row 1's bytes through a copy with the denial AND the count planted back: it walks the
#                  gate and records prior_artifacts: 0 beside the archived anchors, the false derivation
# plus a READ-ONLY census over this repository's .mission/dispatches, with the two name rules extracted
# from the shipped runner by the parser: which dispatch ids this cure would change. Reported, never
# asserted to a number -- the directory grows.
$r49Id       = 'D-WP2-R49'
$r49Dir      = Join-Path $missionRoot '.mission\dispatches'
$r49An       = Join-Path $r49Dir "$r49Id.anchors.yaml"
$r49Sentence = 'record\(s\) of a dispatch that RAN exist'
$r49DenialLine = 'if ((-not $against) -and ($ranNotRejected.Count -gt 0)) {'
$r49RejOnly    = 'if ((-not $against) -and ($rejectedPriors.Count -gt 0)) {'

# THE SET-ASIDE IS THIS MEMBER'S OWN, byte for byte, taken ONCE before the first clear and put back at
# the end -- R-48 row 4's shape. Every earlier member leaves anchors behind, and any plain anchors file
# sets the basis and skips every branch these rows are about.
$r49Aside = @()
foreach ($f in @(Get-ChildItem -LiteralPath $r49Dir -File -ErrorAction SilentlyContinue |
                 Where-Object { $_.Name -notlike "$r49Id.*" })) {
    $r49Aside += [pscustomobject]@{ path = $f.FullName; bytes = [System.IO.File]::ReadAllBytes($f.FullName) }
}
foreach ($d in @((Join-Path $missionRoot '.mission'), (Join-Path $missionRoot '.mission-runtime'))) {
    foreach ($f in @(Get-ChildItem -LiteralPath $d -Recurse -File -Filter '*.superseded.yaml' -ErrorAction SilentlyContinue)) {
        if (@($r49Aside | Where-Object { $_.path -eq $f.FullName }).Count -eq 0) {
            $r49Aside += [pscustomobject]@{ path = $f.FullName; bytes = [System.IO.File]::ReadAllBytes($f.FullName) }
        }
    }
}
$r49AsideCount = @($r49Aside).Count

function Clear-R49Dir {
    # Every file that is not this member's own dispatch, and every marker in either plane. The originals
    # are already held above; after the first call this only removes the previous row's staging.
    $n = 0
    foreach ($f in @(Get-ChildItem -LiteralPath $r49Dir -File -ErrorAction SilentlyContinue |
                     Where-Object { $_.Name -notlike "$r49Id.*" })) {
        Remove-Item -LiteralPath $f.FullName -Force
        $n = $n + 1
    }
    foreach ($d in @((Join-Path $missionRoot '.mission'), (Join-Path $missionRoot '.mission-runtime'))) {
        foreach ($f in @(Get-ChildItem -LiteralPath $d -Recurse -File -Filter '*.superseded.yaml' -ErrorAction SilentlyContinue)) {
            Remove-Item -LiteralPath $f.FullName -Force
            $n = $n + 1
        }
    }
    return $n
}
function Write-R49Anchors {
    # The shape of the four real *.anchors.aborted-seq* files: an anchors document recording a passing
    # gate and carrying NO status line. The same writer stages row 6's plain basis.
    param([string]$Name, [string]$Prior)
    Write-Utf8 -Path (Join-Path $r49Dir $Name) -Text "dispatch_id: $Prior`ndispatch_kind: read-only`nhead_sha: $fixtureHead`nworktree_tip_sha: $fixtureHead`ncapture_gaps_count: 0`nverify_gate:`n  outcome: verified-pass`n  verify_exit: 0`n"
}
function Write-R49Handoff {
    param([string]$Name, [string]$Prior, [switch]$Rejected)
    if ($Rejected) {
        Write-Utf8 -Path (Join-Path $r49Dir $Name) -Text "status: rejected`ndispatch_id: $Prior`nrejected_at: 2026-09-12T00:00:00Z`nproblems:`n  - 'the fixture rejection'`n"
    } else {
        Write-Utf8 -Path (Join-Path $r49Dir $Name) -Text "id: handoff-$Prior`ndispatch_id: $Prior`nfrom_worker: fixture`nterminated_reason: completed`n"
    }
}
function Get-R49StagedSha {
    param([string]$Name)
    $staged = Join-Path $r49Dir $Name
    if (-not (Test-Path -LiteralPath $staged)) { return '' }
    return (Get-FileHash -Algorithm SHA256 -LiteralPath $staged).Hash.ToLowerInvariant()
}
function Test-R49HasStatus {
    param([string]$Name)
    $staged = Join-Path $r49Dir $Name
    if (-not (Test-Path -LiteralPath $staged)) { return $true }
    return [bool]([System.IO.File]::ReadAllText($staged) -match '(?m)^status:')
}
function Get-R49Record {
    # READ FROM THE BYTES THE RUNNER WROTE: the verify_gate outcome and the two derivation figures.
    $res = [pscustomobject]@{ written = $false; outcome = '(no anchors)'; priors = '(absent)'; markers = '(absent)' }
    if (-not (Test-Path -LiteralPath $r49An)) { return $res }
    $text = [System.IO.File]::ReadAllText($r49An)
    $res.written = $true
    if ($text -match '(?m)^verify_gate:[ \t]*\r?\n[ \t]+outcome:[ \t]*(\S+)') { $res.outcome = $Matches[1] }
    if ($text -match '(?m)^[ \t]+vacuity_derivation:[ \t]*\r?\n[ \t]+prior_artifacts:[ \t]*(\S+)[ \t]*\r?\n[ \t]+markers:[ \t]*(\S+)') {
        $res.priors  = $Matches[1]
        $res.markers = $Matches[2]
    }
    return $res
}
function Add-R49Plant {
    # A SECOND plant into a copy New-UncuredCopy already made, under New-UncuredCopy's own rules: the
    # cured line must occur exactly once, the file is written UTF-8 without a BOM, and it must parse.
    param([string]$Target, [string]$CuredLine, [string]$OldLine)
    $text = [System.IO.File]::ReadAllText($Target)
    $hits = ([regex]::Matches($text, [regex]::Escape($CuredLine))).Count
    $planted = ($hits -eq 1)
    if ($planted) { [System.IO.File]::WriteAllText($Target, $text.Replace($CuredLine, $OldLine), (New-Object System.Text.UTF8Encoding($false))) }
    $pe = $null; $pt = $null
    if ($planted) { [void][System.Management.Automation.Language.Parser]::ParseFile($Target, [ref]$pt, [ref]$pe) }
    return [pscustomobject]@{ planted = $planted; parses = ($planted -and ($null -eq $pe -or $pe.Count -eq 0)) }
}

$r49Cleared = Clear-R49Dir
$r49Rows = @()

# ---- row 1: CURED -- an archived anchors file with no status line is the only prior -----------------
Write-R49Anchors -Name 'D-R49PA.anchors.aborted-seq1.yaml' -Prior 'D-R49PA'
$r49sha1  = Get-R49StagedSha -Name 'D-R49PA.anchors.aborted-seq1.yaml'
$r49Stat1 = Test-R49HasStatus -Name 'D-R49PA.anchors.aborted-seq1.yaml'
$r49r1    = Invoke-R2xRow -Id $r49Id -RunnerPath $runner -VerifyStub $verifyScoping
$r49rec1  = Get-R49Record
$r49Named1 = [bool]($r49r1.out -match 'D-R49PA\.anchors\.aborted-seq1\.yaml')
$r49New1   = [bool]($r49r1.out -match $r49Sentence)
$r49Other1 = [bool]($r49r1.out -match 'REJECTED handoff|none is an anchors file|supersession marker')
$r49ok1 = (($r49r1.exit -eq 2) -and (-not $r49r1.spawned) -and ($r49r1.argv -eq '') -and (-not $r49rec1.written) -and
           $r49Named1 -and $r49New1 -and (-not $r49Other1) -and (-not $r49Stat1) -and ($r49sha1 -ne ''))
$r49Rows += Format-R2xRow -Id '1 CURED archived anchors, no status line' -RowOk $r49ok1 -Text ("exit={0} spawned={1} verify never invoked={2} anchors written={3} file named={4} ran-record refusal={5} another refusal={6} staged has status line={7}  (expect 2, False, True, False, True, True, False, False)" -f $r49r1.exit, $r49r1.spawned, ($r49r1.argv -eq ''), $r49rec1.written, $r49Named1, $r49New1, $r49Other1, $r49Stat1) -Said (Get-R28Said $r49r1.out)

# ---- row 2: CURED -- the retained worktree-placed handoff alone, its rejection stub gone ------------
$null = Clear-R49Dir
Write-R49Handoff -Name 'D-R49PB.handoff.worktree-placed.yaml' -Prior 'D-R49PB'
$r49sha2  = Get-R49StagedSha -Name 'D-R49PB.handoff.worktree-placed.yaml'
$r49Stat2 = Test-R49HasStatus -Name 'D-R49PB.handoff.worktree-placed.yaml'
$r49r2    = Invoke-R2xRow -Id $r49Id -RunnerPath $runner -VerifyStub $verifyScoping
$r49rec2  = Get-R49Record
$r49Named2 = [bool]($r49r2.out -match 'D-R49PB\.handoff\.worktree-placed\.yaml')
$r49New2   = [bool]($r49r2.out -match $r49Sentence)
$r49Other2 = [bool]($r49r2.out -match 'REJECTED handoff|none is an anchors file|supersession marker')
$r49ok2 = (($r49r2.exit -eq 2) -and (-not $r49r2.spawned) -and ($r49r2.argv -eq '') -and (-not $r49rec2.written) -and
           $r49Named2 -and $r49New2 -and (-not $r49Other2) -and (-not $r49Stat2) -and ($r49sha2 -ne ''))
$r49Rows += Format-R2xRow -Id '2 CURED retained handoff, no stub' -RowOk $r49ok2 -Text ("exit={0} spawned={1} verify never invoked={2} anchors written={3} file named={4} ran-record refusal={5} another refusal={6} staged has status line={7}  (expect 2, False, True, False, True, True, False, False)" -f $r49r2.exit, $r49r2.spawned, ($r49r2.argv -eq ''), $r49rec2.written, $r49Named2, $r49New2, $r49Other2, $r49Stat2) -Said (Get-R28Said $r49r2.out)

# ---- row 3: CONTROL -- a genuinely-first dispatch is still lawful ------------------------------------
$null = Clear-R49Dir
$r49Empty = @(Get-ChildItem -LiteralPath $r49Dir -File -ErrorAction SilentlyContinue | Where-Object { $_.Name -notlike "$r49Id.*" }).Count
$r49r3    = Invoke-R2xRow -Id $r49Id -RunnerPath $runner -VerifyStub $verifyScoping
$r49rec3  = Get-R49Record
$r49New3  = [bool]($r49r3.out -match $r49Sentence)
$r49ok3 = (($r49Empty -eq 0) -and ($r49r3.exit -eq 0) -and $r49r3.spawned -and ($r49r3.argv -eq '') -and (-not $r49New3) -and
           ($r49rec3.outcome -ceq 'vacuous-first') -and ($r49rec3.priors -eq '0') -and ($r49rec3.markers -eq '0'))
$r49Rows += Format-R2xRow -Id '3 CONTROL nothing on disk' -RowOk $r49ok3 -Text ("other files on disk={0} exit={1} spawned={2} verify never invoked={3} ran-record refusal={4} outcome={5} prior_artifacts={6} markers={7}  (expect 0, 0, True, True, False, vacuous-first, 0, 0)" -f $r49Empty, $r49r3.exit, $r49r3.spawned, ($r49r3.argv -eq ''), $r49New3, $r49rec3.outcome, $r49rec3.priors, $r49rec3.markers) -Said (Get-R28Said $r49r3.out)

# ---- row 4: UNCHANGED -- R-37a row 3's shape ---------------------------------------------------------
$null = Clear-R49Dir
Write-R49Handoff -Name 'D-R49PC.handoff.yaml' -Prior 'D-R49PC' -Rejected
Write-R49Handoff -Name 'D-R49PC.worktree-placed.handoff.yaml' -Prior 'D-R49PC'
(Get-Item -LiteralPath (Join-Path $r49Dir 'D-R49PC.worktree-placed.handoff.yaml')).LastWriteTimeUtc =
    (Get-Item -LiteralPath (Join-Path $r49Dir 'D-R49PC.handoff.yaml')).LastWriteTimeUtc.AddSeconds(5)
$r49r4    = Invoke-R2xRow -Id $r49Id -RunnerPath $runner -VerifyStub $verifyScoping
$r49Rej4   = [bool]($r49r4.out -match 'REJECTED handoff')
$r49Clean4 = (-not [bool]($r49r4.out -match 'worktree-placed'))
$r49New4   = [bool]($r49r4.out -match $r49Sentence)
$r49ok4 = (($r49r4.exit -eq 2) -and (-not $r49r4.spawned) -and $r49Rej4 -and $r49Clean4 -and (-not $r49New4))
$r49Rows += Format-R2xRow -Id '4 UNCHANGED R-37a row 3 shape' -RowOk $r49ok4 -Text ("exit={0} spawned={1} REJECTED handoff refusal={2} retained name printed={3} ran-record refusal={4}  (expect 2, False, True, False, False)" -f $r49r4.exit, $r49r4.spawned, $r49Rej4, (-not $r49Clean4), $r49New4) -Said (Get-R28Said $r49r4.out)

# ---- row 5: UNCHANGED -- the runner's real rejection write shape -------------------------------------
$null = Clear-R49Dir
Write-R49Handoff -Name 'D-R49PD.handoff.worktree-placed.yaml' -Prior 'D-R49PD'
Write-R49Handoff -Name 'D-R49PD.handoff.yaml' -Prior 'D-R49PD' -Rejected
$r49r5    = Invoke-R2xRow -Id $r49Id -RunnerPath $runner -VerifyStub $verifyScoping
$r49Rej5   = [bool]($r49r5.out -match 'REJECTED handoff')
$r49Clean5 = (-not [bool]($r49r5.out -match 'worktree-placed'))
$r49New5   = [bool]($r49r5.out -match $r49Sentence)
$r49ok5 = (($r49r5.exit -eq 2) -and (-not $r49r5.spawned) -and $r49Rej5 -and $r49Clean5 -and (-not $r49New5))
$r49Rows += Format-R2xRow -Id '5 UNCHANGED stub plus retained handoff' -RowOk $r49ok5 -Text ("exit={0} spawned={1} REJECTED handoff refusal={2} retained name printed={3} ran-record refusal={4}  (expect 2, False, True, False, False)" -f $r49r5.exit, $r49r5.spawned, $r49Rej5, (-not $r49Clean5), $r49New5) -Said (Get-R28Said $r49r5.out)

# ---- row 6: NO-FIRE -- a plain anchors basis beside an archived one ----------------------------------
# The gate's own outcome here is not this row's question (the verify stub refuses on its own terms);
# only that the basis is the plain file, the archived one is never offered, and the new denial is silent.
$null = Clear-R49Dir
Write-R49Anchors -Name 'D-R49PE.anchors.yaml' -Prior 'D-R49PE'
Write-R49Anchors -Name 'D-R49PE.anchors.aborted-seq1.yaml' -Prior 'D-R49PE'
(Get-Item -LiteralPath (Join-Path $r49Dir 'D-R49PE.anchors.aborted-seq1.yaml')).LastWriteTimeUtc =
    (Get-Item -LiteralPath (Join-Path $r49Dir 'D-R49PE.anchors.yaml')).LastWriteTimeUtc.AddSeconds(5)
$r49r6    = Invoke-R2xRow -Id $r49Id -RunnerPath $runner -VerifyStub $verifyScoping
$r49Basis6    = Get-R37Basis -R $r49r6
$r49Archived6 = [bool]($r49r6.argv -match 'aborted-seq')
$r49New6      = [bool]($r49r6.out -match $r49Sentence)
$r49ok6 = (($r49Basis6 -eq 'D-R49PE.anchors.yaml') -and (-not $r49Archived6) -and (-not $r49New6))
$r49Rows += Format-R2xRow -Id '6 NO-FIRE plain basis beside an archived one' -RowOk $r49ok6 -Text ("basis={0} archived offered to verify={1} ran-record refusal={2} (exit={3} spawned={4}, reported only)  (expect D-R49PE.anchors.yaml, False, False)" -f $r49Basis6, $r49Archived6, $r49New6, $r49r6.exit, $r49r6.spawned) -Said (Get-R28Said $r49r6.out)

# ---- row 7: THE PLANTED-REVERT KILL -- the new denial put back to the rejection-only test, row 1's bytes
# The planted condition is the denial above it word for word, so the block can never fire: exactly the
# runner as it stood before this cure, with vacuity denied on rejection records only.
$r49Copy = New-UncuredCopy -Name 'uncured49' -CuredLine $r49DenialLine -OldLine $r49RejOnly
$null = Clear-R49Dir
Write-R49Anchors -Name 'D-R49PA.anchors.aborted-seq1.yaml' -Prior 'D-R49PA'
$r49sha7 = Get-R49StagedSha -Name 'D-R49PA.anchors.aborted-seq1.yaml'
$r49r7   = Invoke-WithHookRepointed -Decider $r49Copy.decider -Body { Invoke-R2xRow -Id $r49Id -RunnerPath $r49Copy.runner -VerifyStub $verifyScoping }
$r49rec7 = Get-R49Record
$r49ok7 = ($r49Copy.planted -and $r49Copy.parses -and ($r49r7.exit -eq 0) -and $r49r7.spawned -and ($r49r7.argv -eq '') -and
           ($r49rec7.outcome -ceq 'vacuous-first') -and ($r49rec7.priors -eq '1') -and ($r49sha7 -eq $r49sha1))
$r49Rows += Format-R2xRow -Id '7 planted revert of the denial, row 1 bytes' -RowOk $r49ok7 -Text ("plant located={0} parses={1} exit={2} spawned={3} verify never invoked={4} outcome={5} prior_artifacts={6} same staged bytes as row 1={7}  (expect True, True, 0, True, True, vacuous-first, 1, True -- the kill)" -f $r49Copy.planted, $r49Copy.parses, $r49r7.exit, $r49r7.spawned, ($r49r7.argv -eq ''), $r49rec7.outcome, $r49rec7.priors, ($r49sha7 -eq $r49sha1)) -Said (Get-R28Said $r49r7.out)

# ---- row 8: THE SAME KILL on row 2's bytes -----------------------------------------------------------
$null = Clear-R49Dir
Write-R49Handoff -Name 'D-R49PB.handoff.worktree-placed.yaml' -Prior 'D-R49PB'
$r49sha8 = Get-R49StagedSha -Name 'D-R49PB.handoff.worktree-placed.yaml'
$r49r8   = Invoke-WithHookRepointed -Decider $r49Copy.decider -Body { Invoke-R2xRow -Id $r49Id -RunnerPath $r49Copy.runner -VerifyStub $verifyScoping }
$r49rec8 = Get-R49Record
$r49ok8 = ($r49Copy.planted -and $r49Copy.parses -and ($r49r8.exit -eq 0) -and $r49r8.spawned -and ($r49r8.argv -eq '') -and
           ($r49rec8.outcome -ceq 'vacuous-first') -and ($r49rec8.priors -eq '1') -and ($r49sha8 -eq $r49sha2))
$r49Rows += Format-R2xRow -Id '8 planted revert of the denial, row 2 bytes' -RowOk $r49ok8 -Text ("exit={0} spawned={1} verify never invoked={2} outcome={3} prior_artifacts={4} same staged bytes as row 2={5}  (expect 0, True, True, vacuous-first, 1, True -- the kill)" -f $r49r8.exit, $r49r8.spawned, ($r49r8.argv -eq ''), $r49rec8.outcome, $r49rec8.priors, ($r49sha8 -eq $r49sha2)) -Said (Get-R28Said $r49r8.out)

# ---- row 9: THE RECORD KILL -- denial AND count planted back, row 1's bytes --------------------------
# What the pre-cure runner wrote for this input: vacuous-first with prior_artifacts: 0 beside a record
# that a dispatch ran. Row 7 is the same bytes with only the denial reverted and records 1, so the
# counted line is what separates a true derivation from a false one.
$r49CopyR = New-UncuredCopy -Name 'uncured49r' -CuredLine '    $vacuityPriors  = @($ranRecords).Count' -OldLine '    $vacuityPriors  = 0'
$r49PlantR = Add-R49Plant -Target $r49CopyR.runner -CuredLine $r49DenialLine -OldLine $r49RejOnly
$null = Clear-R49Dir
Write-R49Anchors -Name 'D-R49PA.anchors.aborted-seq1.yaml' -Prior 'D-R49PA'
$r49sha9 = Get-R49StagedSha -Name 'D-R49PA.anchors.aborted-seq1.yaml'
$r49r9   = Invoke-WithHookRepointed -Decider $r49CopyR.decider -Body { Invoke-R2xRow -Id $r49Id -RunnerPath $r49CopyR.runner -VerifyStub $verifyScoping }
$r49rec9 = Get-R49Record
$r49ok9 = ($r49CopyR.planted -and $r49CopyR.parses -and $r49PlantR.planted -and $r49PlantR.parses -and
           ($r49r9.exit -eq 0) -and $r49r9.spawned -and ($r49r9.argv -eq '') -and
           ($r49rec9.outcome -ceq 'vacuous-first') -and ($r49rec9.priors -eq '0') -and ($r49sha9 -eq $r49sha1))
$r49Rows += Format-R2xRow -Id '9 denial and count planted back, row 1' -RowOk $r49ok9 -Text ("count plant located={0} parses={1} denial plant located={2} parses={3} exit={4} spawned={5} verify never invoked={6} outcome={7} prior_artifacts={8} same staged bytes as row 1={9}  (expect True, True, True, True, 0, True, True, vacuous-first, 0, True -- the false record)" -f $r49CopyR.planted, $r49CopyR.parses, $r49PlantR.planted, $r49PlantR.parses, $r49r9.exit, $r49r9.spawned, ($r49r9.argv -eq ''), $r49rec9.outcome, $r49rec9.priors, ($r49sha9 -eq $r49sha1)) -Said (Get-R28Said $r49r9.out)

# ---- put the directory back ---------------------------------------------------------------------------
$null = Clear-R49Dir
foreach ($a in $r49Aside) {
    if (-not (Test-Path -LiteralPath $a.path)) {
        New-Item -ItemType Directory -Path (Split-Path -Parent $a.path) -Force | Out-Null
        [System.IO.File]::WriteAllBytes($a.path, $a.bytes)
    }
}
$r49Back = @($r49Aside | Where-Object { Test-Path -LiteralPath $_.path }).Count

# ---- THE CENSUS: READ-ONLY, over this repository's own dispatch directory ------------------------------
# The two name rules are taken from the SHIPPED runner by the parser and defined only inside this block's
# own scope. The gate's order is re-implemented twice -- before this cure and after it -- for every
# <id>.yaml artifact on disk plus one fresh id. Supersession is not simulated; markers under .mission are
# counted. Ignoring a marker can only turn a marker refusal into another outcome, so with markers present
# the mover count is an upper bound, and with none it is exact for the vacuity branch. Nothing is written.
# WHERE THIS CHECKOUT HAS NO DISPATCH DIRECTORY OF ITS OWN -- the framework repository runs no mission --
# the census reads the real dispatch directory of the mission it does carry, the smoke mission's (Get-WP2SmokeRoot), and
# says so. The asserted part is unchanged: the rules extracted from the shipped runner, agreeing with the rows, and a
# real directory read.
$r49CensusRoot = $repoRoot
$r49CensusFrom = 'this repository''s own mission plane'
$r49Smoke = $null
if (@(Get-ChildItem -LiteralPath (Join-Path $repoRoot '.mission\dispatches') -File -ErrorAction SilentlyContinue).Count -eq 0) {
    $r49Smoke = Get-WP2SmokeRoot
    $r49CensusRoot = $r49Smoke.root
    $r49CensusFrom = 'the smoke mission at ' + $r49Smoke.root + ' (' + $r49Smoke.from + '): this checkout has no dispatch directory of its own'
}
$r49Census = & {
    $ptoks = $null; $perrs = $null
    $past = [System.Management.Automation.Language.Parser]::ParseFile($runner, [ref]$ptoks, [ref]$perrs)
    $want = @('Test-IsVerifyBasisCandidate', 'Test-IsDispatchRanRecord')
    $fns = @($past.FindAll({ param($node) $node -is [System.Management.Automation.Language.FunctionDefinitionAst] }, $true) |
             Where-Object { $want -contains $_.Name })
    foreach ($fn in $fns) { . ([scriptblock]::Create($fn.Extent.Text)) }
    $out = [pscustomobject]@{ extracted = $fns.Count; agree = $false; files = 0; wide = 0; narrow = 0; rejWide = 0; gap = @(); markers = 0; ids = 0; movers = @(); cfIds = 0; cfMovers = 0 }
    if ($fns.Count -ne 2) { return $out }
    $out.agree = ((Test-IsDispatchRanRecord -Name 'D-R49PA.anchors.aborted-seq1.yaml') -and (-not (Test-IsVerifyBasisCandidate -Name 'D-R49PA.anchors.aborted-seq1.yaml')) -and
                  (Test-IsDispatchRanRecord -Name 'D-R49PB.handoff.worktree-placed.yaml') -and (-not (Test-IsVerifyBasisCandidate -Name 'D-R49PB.handoff.worktree-placed.yaml')) -and
                  (Test-IsVerifyBasisCandidate -Name 'D-R49PE.anchors.yaml'))
    $realDir = Join-Path $r49CensusRoot '.mission\dispatches'
    $all = @(Get-ChildItem -LiteralPath $realDir -File -ErrorAction SilentlyContinue)
    $rej = @{}
    foreach ($x in $all) { $rej[$x.Name] = [bool]([System.IO.File]::ReadAllText($x.FullName) -match '(?m)^status:[ \t]*rejected') }
    $out.files   = $all.Count
    $out.wide    = @($all | Where-Object { Test-IsDispatchRanRecord -Name $_.Name }).Count
    $out.narrow  = @($all | Where-Object { Test-IsVerifyBasisCandidate -Name $_.Name }).Count
    $out.rejWide = @($all | Where-Object { (Test-IsDispatchRanRecord -Name $_.Name) -and $rej[$_.Name] }).Count
    $gapFiles    = @($all | Where-Object { (Test-IsDispatchRanRecord -Name $_.Name) -and (-not (Test-IsVerifyBasisCandidate -Name $_.Name)) -and (-not $rej[$_.Name]) })
    $out.gap     = @($gapFiles | ForEach-Object { $_.Name })
    $out.markers = @(Get-ChildItem -LiteralPath (Join-Path $r49CensusRoot '.mission') -Recurse -File -Filter '*.superseded.yaml' -ErrorAction SilentlyContinue).Count
    $decide = {
        param([object[]]$Files, [string]$Id, [int]$Markers)
        $df     = @($Files | Where-Object { $_.Name -notlike "$Id.*" })
        $prior  = @($df | Where-Object { (Test-IsVerifyBasisCandidate -Name $_.Name) -and (-not $rej[$_.Name]) })
        $ran    = @($df | Where-Object { Test-IsDispatchRanRecord -Name $_.Name })
        $ranRej = @($ran | Where-Object { $rej[$_.Name] })
        $ranOk  = @($ran | Where-Object { -not $rej[$_.Name] })
        if (@($prior | Where-Object { $_.Name -like '*.anchors.yaml' }).Count -gt 0) { return 'basis|basis' }
        if ($prior.Count -gt 0)  { return 'refused-no-anchors|refused-no-anchors' }
        if ($ranRej.Count -gt 0) { return 'refused-rejected|refused-rejected' }
        if ($Markers -gt 0)      { return 'refused-markers|refused-markers' }
        if ($ranOk.Count -gt 0)  { return 'vacuous-first|refused-ran-record' }
        return 'vacuous-first|vacuous-first'
    }
    $ids = @(@($all | Where-Object { (@($_.Name -split '\.').Count -eq 2) -and ($_.Name -like '*.yaml') } | ForEach-Object { ($_.Name -split '\.')[0] } | Sort-Object -Unique) + @('D-R49-CENSUS-FRESH'))
    $out.ids = $ids.Count
    foreach ($id in $ids) {
        $v = (& $decide $all $id $out.markers) -split '\|'
        if ($v[0] -ne $v[1]) { $out.movers += $id }
    }
    $cf = @(@($gapFiles | ForEach-Object { ($_.Name -split '\.')[0] } | Sort-Object -Unique) + @('D-R49-CENSUS-FRESH'))
    $out.cfIds = $cf.Count
    foreach ($id in $cf) {
        $v = (& $decide $gapFiles $id 0) -split '\|'
        if ($v[0] -ne $v[1]) { $out.cfMovers = $out.cfMovers + 1 }
    }
    return $out
}
$r49CensusOk = (($r49Census.extracted -eq 2) -and $r49Census.agree -and ($r49Census.files -ge 1) -and ($r49Census.ids -ge 2))

$r49RowOks  = @($r49ok1, $r49ok2, $r49ok3, $r49ok4, $r49ok5, $r49ok6, $r49ok7, $r49ok8, $r49ok9)
$r49Arity   = (($r49RowOks.Count -eq 9) -and (@($r49Rows).Count -eq 9))
$r49Spawned = @(@($r49r1.spawned, $r49r2.spawned, $r49r3.spawned, $r49r4.spawned, $r49r5.spawned, $r49r6.spawned, $r49r7.spawned, $r49r8.spawned, $r49r9.spawned) | Where-Object { $_ }).Count
$r49Split   = (($r49Spawned -ge 1) -and ((9 - $r49Spawned) -ge 1))
$r49RestoreOk = (($r49AsideCount -ge 1) -and ($r49Back -eq $r49AsideCount))

$r49detail = @"
    THE NINE ROWS, each through a real runner in the sandbox, every value READ from what the runner printed, the argv it passed the verify stub, or the anchors it wrote:
$($r49Rows -join "`n")
    rows that spawned: $r49Spawned   rows that did not: $(9 - $r49Spawned)   split: $r49Split   row arity held: $r49Arity
    (counted over what the runner DID, not over this table's expectations)
    ROWS 1, 7 AND 9 ARE THE SAME STAGED BYTES THROUGH THREE RUNNERS (sha256 $(if ($r49sha1) { $r49sha1.Substring(0,16) } else { '(none)' })):
      shipped            -- refuses before anything is written, naming the archived anchors
      denial reverted    -- walks the gate unrun, and the counted derivation says prior_artifacts: 1
      denial and count   -- walks the gate unrun and records prior_artifacts: 0 beside the archived anchors
    the dispatch directory set aside and put back: $r49AsideCount files, $r49Back back   (cleared on the first row: $r49Cleared)
    THE CENSUS, READ-ONLY, over $(Join-Path $r49CensusRoot '.mission\dispatches') -- $($r49CensusFrom):
      name rules extracted from the shipped runner by the parser : $($r49Census.extracted) of 2   agree with the rows' fixture names: $($r49Census.agree)
      top-level files $($r49Census.files)   wide ran records $($r49Census.wide)   narrow candidates $($r49Census.narrow)   rejection records (wide) $($r49Census.rejWide)
      supersession markers under .mission: $($r49Census.markers)   (with 0 the census is exact for the vacuity branch; otherwise an upper bound)
      ran records that are neither a basis candidate nor a rejection -- the class this cure refuses on: $(@($r49Census.gap).Count)
        $(@($r49Census.gap) -join ', ')
      dispatch ids examined (every id.yaml artifact plus one fresh id) : $($r49Census.ids)
      ids whose gate outcome this cure CHANGES                          : $(@($r49Census.movers).Count)   $(@($r49Census.movers) -join ', ')
      counterfactual, a directory holding only that class              : $($r49Census.cfMovers) of $($r49Census.cfIds) ids change outcome
      (reported, not asserted to a number: the directory grows. Asserted only: the rules were extracted, they agree with the rows, and the directory was read)
    WHAT THIS MEMBER DOES NOT ASSERT:
      * that any id on disk could actually be dispatched again: the id-reuse guard runs before this gate, and the census does not consult it.
      * anything about rejection records: they refused before this cure and still do, by the unchanged denial rows 4 and 5 reach.
    the planted copies : $($r49Copy.runner)
                         $($r49CopyR.runner)
"@
# THE CENSUS CANNOT BE READ WHERE NOTHING NAMED A SMOKE MISSION AND NONE STANDS AT THE DEFAULT. The nine rows were
# driven all the same; the member SKIPs by name only if every one of them held.
$r49SmokeSkip = $(if ($r49Smoke -and (-not $r49Smoke.named) -and (-not $r49Smoke.found)) { "no smoke mission found -- $($r49Smoke.from) -- so the census of a real dispatch directory was not read" } else { '' })
$r49Ok = ($r49ok1 -and $r49ok2 -and $r49ok3 -and $r49ok4 -and $r49ok5 -and $r49ok6 -and $r49ok7 -and $r49ok8 -and $r49ok9 -and
          $r49Arity -and $r49Split -and $r49RestoreOk -and ($r49CensusOk -or [bool]$r49SmokeSkip))
Check -Id 'R-49' -Title ('a dispatch that ran denies vacuity, not only a dispatch that was rejected: an archived anchors file or a retained handoff with no status line refuses before anything is written and is named, a genuinely-first dispatch is still vacuous-first with prior_artifacts 0, the rejected-handoff refusal is unchanged in both retained spellings, a plain basis beside an archived one is untouched, and a runner with the new denial reverted walks the gate unrun on the same bytes' + $(if ($r49SmokeSkip -and $r49Ok) { '   [SKIPPED -- ' + $r49SmokeSkip + ']' } else { '' })) `
      -Ok $r49Ok -Skipped:([bool]($r49SmokeSkip -and $r49Ok)) -Detail $(if ($r49SmokeSkip) { "    SKIPPED: $r49SmokeSkip`n" + $r49detail } else { $r49detail })

# =============================================================================================
# R-50 -- A FIXTURE WHOSE git init FAILED IS REFUSED BEFORE ANY git config WRITE (item 7, operator)
# =============================================================================================
# THE INCIDENT is written up at Assert-FixtureGitDir, beside the seed. What this member measures is
# the operator's build instruction -- "a case that a fixture whose init failed is refused before any
# config write" -- and, because a refusal never tried against the uncured sequence proves nothing,
# that the uncured sequence DOES write through on the same bytes.
#
# EVERYTHING RUNS INSIDE A DECOY. %TEMP% is first asked, with discovery unbounded, and must resolve
# to no repository. A throwaway parent repository is then created under it with a GUID name, and
# every git call in the member runs with GIT_CEILING_DIRECTORIES set to the decoy's parent and with
# GIT_DIR, GIT_WORK_TREE and GIT_COMMON_DIR cleared -- so the nearest repository any fixture here can
# fall through to is the decoy, never this checkout and never main. The planted revert's write lands
# in the decoy's .git/config. The decoy is removed afterwards and asserted gone; the environment is
# put back as it was found.
#
# THE INIT FAILURE IS DETERMINISTIC AND PROVEN, NOT ASSUMED: 'git init --object-format=bogus' exits
# 128 ("unknown hash algorithm") and creates nothing (measured before this member was written, git
# 2.54). Row 6 reads the exit code out of the refusal and the absence of .git from the disk.
#
# THE ROWS:
#   1 DEFECT         -- the failing init inside the decoy, through the shipped Initialize-FixtureRepo:
#                       refused, naming the fixture root and the DECOY's git dir; GIT_TRACE shows init
#                       and rev-parse ran and no 'git config' did; the decoy's config sha256 unchanged.
#   2 CONTROL        -- a good init inside the decoy: admitted, the write lands in the fixture's own
#                       .git/config (read back with --file), the decoy's config unchanged.
#   3 FALSE POSITIVE -- a linked worktree of the good fixture, asked from the worktree: admitted, git
#                       dir under <root>/.git/worktrees/, common dir <root>/.git, and a write through
#                       it lands in the fixture. A check of "git dir equals <root>/.git" refuses this.
#   4 PREFIX TRAP    -- a root whose .git FILE points at a sibling named like the root plus a suffix:
#                       refused. The resolved git dir BEGINS with the root's characters (asserted), so
#                       a comparison without the trailing separator would admit it.
#   5 PLANTED REVERT -- the text of Assert-FixtureGitDir and Initialize-FixtureRepo, taken from this
#                       process, written to a child script with the assertion line replaced, driven on
#                       row 1's fixture: it WRITES THROUGH -- the decoy's config sha256 changes and the
#                       probe key reads back from it. The same child with the text unplanted refuses
#                       on the same bytes first, so the plant is the only difference between the two.
#   6 NON-VACUITY    -- %TEMP% outside any repository, the decoy a real repository, the failing init's
#                       exit non-zero with no .git in the fixture, outcomes split, the decoy gone.
function Get-R50Sha {
    param([string]$Path)
    if (-not (Test-Path -LiteralPath $Path)) { return '(absent)' }
    return (Get-FileHash -Algorithm SHA256 -LiteralPath $Path).Hash.ToLowerInvariant()
}
function Invoke-R50Git {
    # every git call the member makes itself: EAP Continue, stdout strings apart from stderr, exit kept
    param([string[]]$Argv)
    $prevEap = $ErrorActionPreference
    $ErrorActionPreference = 'Continue'
    try { $o = @(& git @Argv 2>&1); $x = $LASTEXITCODE } finally { $ErrorActionPreference = $prevEap }
    $so = @($o | Where-Object { $_ -is [string] } | ForEach-Object { $_.Trim() })
    $se = @($o | Where-Object { $_ -isnot [string] } | ForEach-Object { ("$_" -replace '\s+', ' ').Trim() })
    return [pscustomobject]@{ exit = $x; out = ($so -join "`n"); said = ($se -join ' | ') }
}
function Get-R50TraceCount {
    param([string]$Path, [string]$Verb)
    if (-not (Test-Path -LiteralPath $Path)) { return -1 }
    return @([System.IO.File]::ReadAllLines($Path) | Where-Object { $_ -match ('trace: built-in: git ' + [regex]::Escape($Verb) + '(\s|$)') }).Count
}
function ConvertTo-R50Full {
    param([string]$P)
    if (-not $P) { return '' }
    try { return [System.IO.Path]::GetFullPath(($P -replace '/', '\')).TrimEnd('\') } catch { return '' }
}
function Test-R50Contains {
    param([string]$Hay, [string]$Needle)
    if ((-not $Hay) -or (-not $Needle)) { return $false }
    return ($Hay.IndexOf($Needle, [System.StringComparison]::OrdinalIgnoreCase) -ge 0)
}
function Invoke-R50Child {
    param([string]$Script, [string]$Trace)
    [System.Environment]::SetEnvironmentVariable('GIT_TRACE', $Trace, 'Process')
    $prevEap = $ErrorActionPreference
    $ErrorActionPreference = 'Continue'
    try { $o = @(& powershell -NoProfile -ExecutionPolicy Bypass -File $Script 2>&1); $x = $LASTEXITCODE }
    finally { $ErrorActionPreference = $prevEap; [System.Environment]::SetEnvironmentVariable('GIT_TRACE', $null, 'Process') }
    $joined = ((@($o) | ForEach-Object { "$_" }) -join "`n")
    $m = [regex]::Match($joined, '(?m)^R50CHILD\|(admitted|refused)\|(.*)$')
    return [pscustomobject]@{
        exit    = $x
        verdict = $(if ($m.Success) { $m.Groups[1].Value } else { '(no verdict)' })
        rest    = $(if ($m.Success) { $m.Groups[2].Value.Trim() } else { '' })
    }
}

$r50Rows = New-Object System.Collections.Generic.List[string]
$r50Temp = ''
try { $r50Temp = [System.IO.Path]::GetFullPath([System.IO.Path]::GetTempPath()).TrimEnd('\') } catch { $r50Temp = '' }
$r50Decoy = if ($r50Temp) { Join-Path $r50Temp ('wp2-r50-decoy-' + [guid]::NewGuid().ToString('N')) } else { '' }
$r50EnvNames = @('GIT_DIR', 'GIT_WORK_TREE', 'GIT_COMMON_DIR', 'GIT_CEILING_DIRECTORIES', 'GIT_TRACE')
$r50EnvSave = @{}
foreach ($n in $r50EnvNames) { $r50EnvSave[$n] = [System.Environment]::GetEnvironmentVariable($n, 'Process') }
$r50Key = 'wp2r50.probe'
$r50Val = 'r50-' + [guid]::NewGuid().ToString('N')
$r50ok1 = $false; $r50ok2 = $false; $r50ok3 = $false; $r50ok4 = $false; $r50ok5 = $false
$r50TempClear = $false; $r50TempSaid = ''; $r50DecoyReal = $false; $r50Gone = $false; $r50Unexpected = ''
$r50Refused1 = ''; $r50Refused2 = ''; $r50Refused3 = ''; $r50Refused4 = ''
$r50Exit1 = $null; $r50NoGit1 = $false; $r50ChildCured = $null; $r50ChildUncured = $null
$r50CheckoutCfg = ''; $r50CheckoutSha0 = ''; $r50CheckoutSha1 = ''
try {
    foreach ($n in $r50EnvNames) { [System.Environment]::SetEnvironmentVariable($n, $null, 'Process') }
    # REPORTED, NOT ASSERTED: the common config of the checkout this instrument runs from, before and
    # after. Another hand may legitimately edit that file while a run is in flight, so a changed
    # hash here is information for the reader, not a verdict on this member.
    $r50cc = Invoke-R50Git -Argv @('-C', $repoRoot, 'rev-parse', '--path-format=absolute', '--git-common-dir')
    if (($r50cc.exit -eq 0) -and $r50cc.out) {
        $r50CheckoutCfg = Join-Path (ConvertTo-R50Full $r50cc.out) 'config'
        $r50CheckoutSha0 = Get-R50Sha $r50CheckoutCfg
    }
    # %TEMP% ITSELF RESOLVES TO NO REPOSITORY, asked with no ceiling, so nothing above it is one either.
    if ($r50Temp) {
        $r50tp = Invoke-R50Git -Argv @('-C', $r50Temp, 'rev-parse', '--absolute-git-dir')
        $r50TempSaid = $r50tp.said
        $r50TempClear = (($r50tp.exit -ne 0) -and ($r50tp.said -match 'not a git repository'))
    }
    if ($r50TempClear) {
        [System.Environment]::SetEnvironmentVariable('GIT_CEILING_DIRECTORIES', $r50Temp, 'Process')
        $null = New-Item -ItemType Directory -Path $r50Decoy -Force
        $r50di = Invoke-R50Git -Argv @('init', '--quiet', $r50Decoy)
        $r50dg = Invoke-R50Git -Argv @('-C', $r50Decoy, 'rev-parse', '--absolute-git-dir')
        $r50Cfg = Join-Path $r50Decoy '.git\config'
        $r50DecoyReal = (($r50di.exit -eq 0) -and ($r50dg.exit -eq 0) -and ((ConvertTo-R50Full $r50dg.out) -ieq (Join-Path $r50Decoy '.git')) -and (Test-Path -LiteralPath $r50Cfg))
        $r50DecoyGitSlash = ((Join-Path $r50Decoy '.git') -replace '\\', '/')

        # ---- row 1: THE DEFECT -- a fixture whose init FAILED, inside the decoy ----------------------
        $r50Bad = Join-Path $r50Decoy 'fx'
        $null = New-Item -ItemType Directory -Path $r50Bad -Force
        $r50Trace1 = Join-Path $r50Decoy 'trace-row1.txt'
        $r50Sha1a = Get-R50Sha $r50Cfg
        [System.Environment]::SetEnvironmentVariable('GIT_TRACE', $r50Trace1, 'Process')
        try {
            $null = Initialize-FixtureRepo -Root $r50Bad -InitArgs @('--object-format=bogus') -Config ([ordered]@{ $r50Key = $r50Val })
        } catch { $r50Refused1 = $_.Exception.Message }
        finally { [System.Environment]::SetEnvironmentVariable('GIT_TRACE', $null, 'Process') }
        $r50Sha1b = Get-R50Sha $r50Cfg
        $r50T1Init = Get-R50TraceCount $r50Trace1 'init'
        $r50T1Rev  = Get-R50TraceCount $r50Trace1 'rev-parse'
        $r50T1Cfg  = Get-R50TraceCount $r50Trace1 'config'
        if ($r50Refused1 -match '\[git init exit (-?\d+)\]') { $r50Exit1 = [int]$Matches[1] }
        $r50NoGit1 = -not (Test-Path -LiteralPath (Join-Path $r50Bad '.git'))
        $r50k1 = Invoke-R50Git -Argv @('config', '--file', $r50Cfg, '--get', $r50Key)
        $r50NamesRoot1  = Test-R50Contains $r50Refused1 $r50Bad
        $r50NamesDecoy1 = Test-R50Contains $r50Refused1 $r50DecoyGitSlash
        $r50ok1 = ([bool]$r50Refused1 -and ($r50Refused1 -match 'refusing before any git config write') -and $r50NamesRoot1 -and $r50NamesDecoy1 -and
                   ($r50T1Init -ge 1) -and ($r50T1Rev -ge 1) -and ($r50T1Cfg -eq 0) -and ($r50Sha1a -eq $r50Sha1b) -and ($r50k1.exit -ne 0))
        $r50Rows.Add(('    {0,-30} refused={1} names root={2} names decoy git dir={3} trace init/rev-parse/config={4}/{5}/{6} decoy config unchanged={7} probe key in decoy={8}  (expect True, True, True, >=1/>=1/0, True, False)  {9}' -f `
                      '1 DEFECT init failed', [bool]$r50Refused1, $r50NamesRoot1, $r50NamesDecoy1, $r50T1Init, $r50T1Rev, $r50T1Cfg, ($r50Sha1a -eq $r50Sha1b), ($r50k1.exit -eq 0), $(if ($r50ok1) { 'ok' } else { 'MISMATCH' })))
        $r50Rows.Add(('        the refusal: {0}' -f $(if ($r50Refused1) { $r50Refused1 } else { '(none -- the helper admitted)' })))

        # ---- row 2: THE CONTROL -- a good init inside the decoy; the write lands in the fixture -------
        $r50Good = Join-Path $r50Decoy 'fx-good'
        $null = New-Item -ItemType Directory -Path $r50Good -Force
        $r50Sha2a = Get-R50Sha $r50Cfg
        $r50Res2 = $null
        try { $r50Res2 = Initialize-FixtureRepo -Root $r50Good -Config ([ordered]@{ $r50Key = $r50Val }) } catch { $r50Refused2 = $_.Exception.Message }
        $r50Sha2b = Get-R50Sha $r50Cfg
        $r50GoodCfg = Join-Path $r50Good '.git\config'
        $r50k2 = Invoke-R50Git -Argv @('config', '--file', $r50GoodCfg, '--get', $r50Key)
        # ASSIGNED, NOT RETURNED FROM AN if: a one-element array out of an if statement unrolls to a
        # scalar, and this instrument runs under the StrictMode Latest that evidence-common.ps1 sets,
        # where a scalar's .Count throws (the first run of this member died here, row 1 printed).
        $r50Exits2 = @()
        if ($null -ne $r50Res2) { $r50Exits2 = @($r50Res2.ConfigExits) }
        $r50GitDir2 = if ($null -ne $r50Res2) { ConvertTo-R50Full $r50Res2.GitDir } else { '' }
        $r50ok2 = ((-not $r50Refused2) -and ($null -ne $r50Res2) -and ($r50Res2.InitExit -eq 0) -and ($r50GitDir2 -ieq (Join-Path $r50Good '.git')) -and
                   ($r50Exits2.Count -eq 1) -and (@($r50Exits2 | Where-Object { $_ -ne 0 }).Count -eq 0) -and
                   ($r50k2.exit -eq 0) -and ($r50k2.out -eq $r50Val) -and ($r50Sha2a -eq $r50Sha2b))
        $r50Rows.Add(('    {0,-30} admitted={1} git dir is the fixture .git={2} config exits={3} key in the fixture config={4} decoy config unchanged={5}  (expect True, True, 0, True, True)  {6}' -f `
                      '2 CONTROL good init', (-not $r50Refused2), ($r50GitDir2 -ieq (Join-Path $r50Good '.git')), ($r50Exits2 -join ','), ($r50k2.out -eq $r50Val), ($r50Sha2a -eq $r50Sha2b), $(if ($r50ok2) { 'ok' } else { 'MISMATCH' })))

        # ---- row 3: THE FALSE POSITIVE -- a linked worktree of the good fixture, asked from there -----
        $r50Wt = Join-Path $r50Good 'wt'
        $r50cm = Invoke-R50Git -Argv @('-C', $r50Good, '-c', 'user.name=wp2-r50', '-c', 'user.email=r50@wp2.invalid', 'commit', '--allow-empty', '-q', '-m', 'r50 seed')
        $r50wa = Invoke-R50Git -Argv @('-C', $r50Good, 'worktree', 'add', '--detach', $r50Wt)
        $r50Sha3a = Get-R50Sha $r50Cfg
        $r50Res3 = $null
        try { $r50Res3 = Assert-FixtureGitDir -Root $r50Good -From $r50Wt } catch { $r50Refused3 = $_.Exception.Message }
        $r50w3 = $null
        if ($null -ne $r50Res3) { $r50w3 = Invoke-R50Git -Argv @('-C', $r50Wt, 'config', '--local', 'wp2r50.worktree', 'admitted') }
        $r50k3 = Invoke-R50Git -Argv @('config', '--file', $r50GoodCfg, '--get', 'wp2r50.worktree')
        $r50Sha3b = Get-R50Sha $r50Cfg
        $r50GitDir3 = if ($null -ne $r50Res3) { ConvertTo-R50Full $r50Res3.GitDir } else { '' }
        $r50Common3 = if ($null -ne $r50Res3) { ConvertTo-R50Full $r50Res3.CommonDir } else { '' }
        $r50Under3 = $r50GitDir3.StartsWith(((Join-Path $r50Good '.git\worktrees') + '\'), [System.StringComparison]::OrdinalIgnoreCase)
        $r50ok3 = (($r50cm.exit -eq 0) -and ($r50wa.exit -eq 0) -and (-not $r50Refused3) -and ($null -ne $r50Res3) -and $r50Under3 -and
                   ($r50Common3 -ieq (Join-Path $r50Good '.git')) -and ($r50GitDir3 -ine (Join-Path $r50Good '.git')) -and
                   ($null -ne $r50w3) -and ($r50w3.exit -eq 0) -and ($r50k3.out -eq 'admitted') -and ($r50Sha3a -eq $r50Sha3b))
        $r50Rows.Add(('    {0,-30} worktree made={1} admitted={2} git dir under .git/worktrees={3} common dir is the fixture .git={4} write through it landed in the fixture={5} decoy config unchanged={6}  (expect True x6)  {7}' -f `
                      '3 FALSE POSITIVE worktree', ($r50wa.exit -eq 0), (-not $r50Refused3), $r50Under3, ($r50Common3 -ieq (Join-Path $r50Good '.git')), ($r50k3.out -eq 'admitted'), ($r50Sha3a -eq $r50Sha3b), $(if ($r50ok3) { 'ok' } else { 'MISMATCH' })))

        # ---- row 4: THE PREFIX TRAP -- the root's .git FILE points at a sibling named root + suffix ---
        $r50Trap = Join-Path $r50Decoy 'fxtrap'
        $r50Sib  = Join-Path $r50Decoy 'fxtrap-sibling'
        $null = New-Item -ItemType Directory -Path $r50Trap -Force
        $r50si = Invoke-R50Git -Argv @('init', '--quiet', $r50Sib)
        [System.IO.File]::WriteAllText((Join-Path $r50Trap '.git'), ('gitdir: ' + ((Join-Path $r50Sib '.git') -replace '\\', '/') + "`n"), (New-Object System.Text.UTF8Encoding($false)))
        $r50tg = Invoke-R50Git -Argv @('-C', $r50Trap, 'rev-parse', '--absolute-git-dir')
        $r50TrapFull = ConvertTo-R50Full $r50tg.out
        $r50TrapIsSib = ($r50TrapFull -ieq (Join-Path $r50Sib '.git'))
        $r50TrapPrefix = ([bool]$r50TrapFull -and $r50TrapFull.StartsWith($r50Trap, [System.StringComparison]::OrdinalIgnoreCase))
        $r50Sha4a = Get-R50Sha $r50Cfg
        $r50Res4 = $null
        try { $r50Res4 = Assert-FixtureGitDir -Root $r50Trap } catch { $r50Refused4 = $_.Exception.Message }
        $r50Sha4b = Get-R50Sha $r50Cfg
        $r50NamesSib4 = Test-R50Contains $r50Refused4 ((Join-Path $r50Sib '.git') -replace '\\', '/')
        $r50ok4 = (($r50si.exit -eq 0) -and ($r50tg.exit -eq 0) -and $r50TrapIsSib -and $r50TrapPrefix -and
                   [bool]$r50Refused4 -and ($null -eq $r50Res4) -and $r50NamesSib4 -and ($r50Sha4a -eq $r50Sha4b))
        $r50Rows.Add(('    {0,-30} git resolves the sibling={1} which begins with the root characters={2} refused={3} names the sibling git dir={4} decoy config unchanged={5}  (expect True x6)  {6}' -f `
                      '4 PREFIX TRAP sibling', $r50TrapIsSib, $r50TrapPrefix, [bool]$r50Refused4, $r50NamesSib4, ($r50Sha4a -eq $r50Sha4b), $(if ($r50ok4) { 'ok' } else { 'MISMATCH' })))

        # ---- row 5: THE PLANTED REVERT -- the seed's own text, the assertion line removed, row 1's bytes
        $r50SeedText = ('function Assert-FixtureGitDir {' + (Get-Item -LiteralPath 'function:Assert-FixtureGitDir').ScriptBlock.ToString() + "}`r`n" +
                        'function Initialize-FixtureRepo {' + (Get-Item -LiteralPath 'function:Initialize-FixtureRepo').ScriptBlock.ToString() + "}`r`n")
        $r50CuredLine = '    try { $admitted = Assert-FixtureGitDir -Root $Root } catch { throw (''{0} [git init exit {1}]'' -f $_.Exception.Message, $initExit) }'
        $r50OldLine   = '    $admitted = [pscustomobject]@{ GitDir = ''(planted revert: not asserted)''; CommonDir = ''(planted revert: not asserted)'' }'
        $r50Hits = ([regex]::Matches($r50SeedText, [regex]::Escape($r50CuredLine))).Count
        $r50Planted = ($r50Hits -eq 1)
        $r50ChildTemplate = @'
$ErrorActionPreference = 'Stop'
__SEED__
try {
    $r = Initialize-FixtureRepo -Root '__FIXTURE__' -InitArgs @('--object-format=bogus') -Config ([ordered]@{ '__KEY__' = '__VAL__' })
    'R50CHILD|admitted|' + $r.InitExit + '|' + (@($r.ConfigExits) -join ',')
} catch {
    'R50CHILD|refused|' + ($_.Exception.Message -replace '\s+', ' ')
}
'@
        $r50ChildBase = $r50ChildTemplate.Replace('__FIXTURE__', ($r50Bad -replace "'", "''")).Replace('__KEY__', $r50Key).Replace('__VAL__', $r50Val)
        $r50CuredChild   = Join-Path $r50Decoy 'r50-cured-seed.ps1'
        $r50UncuredChild = Join-Path $r50Decoy 'r50-uncured-seed.ps1'
        [System.IO.File]::WriteAllText($r50CuredChild, $r50ChildBase.Replace('__SEED__', $r50SeedText), (New-Object System.Text.UTF8Encoding($false)))
        $r50pe = $null; $r50pt = $null
        [void][System.Management.Automation.Language.Parser]::ParseFile($r50CuredChild, [ref]$r50pt, [ref]$r50pe)
        $r50CuredParses = ($null -eq $r50pe -or $r50pe.Count -eq 0)
        $r50Parses = $false
        if ($r50Planted) {
            [System.IO.File]::WriteAllText($r50UncuredChild, $r50ChildBase.Replace('__SEED__', $r50SeedText.Replace($r50CuredLine, $r50OldLine)), (New-Object System.Text.UTF8Encoding($false)))
            $r50upe = $null; $r50upt = $null
            [void][System.Management.Automation.Language.Parser]::ParseFile($r50UncuredChild, [ref]$r50upt, [ref]$r50upe)
            $r50Parses = ($null -eq $r50upe -or $r50upe.Count -eq 0)
        }
        $r50NoGit5a = -not (Test-Path -LiteralPath (Join-Path $r50Bad '.git'))
        $r50Trace5c = Join-Path $r50Decoy 'trace-row5-cured.txt'
        $r50Trace5u = Join-Path $r50Decoy 'trace-row5-uncured.txt'
        $r50Sha5a = Get-R50Sha $r50Cfg
        $r50ChildCured = Invoke-R50Child -Script $r50CuredChild -Trace $r50Trace5c
        $r50Sha5b = Get-R50Sha $r50Cfg
        if ($r50Planted -and $r50Parses) { $r50ChildUncured = Invoke-R50Child -Script $r50UncuredChild -Trace $r50Trace5u }
        $r50Sha5c = Get-R50Sha $r50Cfg
        $r50T5cCfg = Get-R50TraceCount $r50Trace5c 'config'
        $r50T5uCfg = Get-R50TraceCount $r50Trace5u 'config'
        $r50k5 = Invoke-R50Git -Argv @('config', '--file', $r50Cfg, '--get', $r50Key)
        $r50NoGit5b = -not (Test-Path -LiteralPath (Join-Path $r50Bad '.git'))
        $r50UVerdict = if ($null -ne $r50ChildUncured) { $r50ChildUncured.verdict } else { '(not run)' }
        $r50URest    = if ($null -ne $r50ChildUncured) { $r50ChildUncured.rest } else { '' }
        $r50UInitFailedConfigOk = [bool]($r50URest -match '^[1-9][0-9]*\|0$')
        $r50ok5 = ($r50Planted -and $r50Parses -and $r50CuredParses -and $r50NoGit5a -and
                   ($r50ChildCured.verdict -eq 'refused') -and ($r50Sha5a -eq $r50Sha5b) -and ($r50T5cCfg -eq 0) -and
                   ($r50UVerdict -eq 'admitted') -and $r50UInitFailedConfigOk -and ($r50Sha5c -ne $r50Sha5b) -and ($r50T5uCfg -ge 1) -and
                   ($r50k5.exit -eq 0) -and ($r50k5.out -eq $r50Val) -and $r50NoGit5b)
        $r50Rows.Add(('    {0,-30} plant located={1} parses={2} (unplanted child parses={3}); UNPLANTED child on row 1 fixture: verdict={4} git config traced={5} decoy config unchanged={6}  (expect True, True, True; refused, 0, True)' -f `
                      '5 PLANTED REVERT', $r50Planted, $r50Parses, $r50CuredParses, $r50ChildCured.verdict, $r50T5cCfg, ($r50Sha5a -eq $r50Sha5b)))
        $r50Rows.Add(('    {0,-30} PLANTED child on the same fixture: verdict={1} init exit and config exit={2} git config traced={3} decoy config CHANGED={4} probe key read back from the DECOY={5} fixture still has no .git={6}  (expect admitted, non-zero and 0, >=1, True, True, True -- the write-through, inside the decoy)  {7}' -f `
                      '', $r50UVerdict, $(if ($r50URest) { $r50URest } else { '(none)' }), $r50T5uCfg, ($r50Sha5c -ne $r50Sha5b), ($r50k5.out -eq $r50Val), $r50NoGit5b, $(if ($r50ok5) { 'ok' } else { 'MISMATCH' })))
    }
} catch {
    $r50Unexpected = $_.Exception.Message
} finally {
    if ($r50Decoy -and (Test-Path -LiteralPath $r50Decoy)) {
        try { Remove-Item -LiteralPath $r50Decoy -Recurse -Force -ErrorAction Stop } catch { }
        if (Test-Path -LiteralPath $r50Decoy) {
            try {
                Get-ChildItem -LiteralPath $r50Decoy -Recurse -Force -ErrorAction SilentlyContinue | ForEach-Object { $_.Attributes = 'Normal' }
                [System.IO.Directory]::Delete($r50Decoy, $true)
            } catch { }
        }
    }
    $r50Gone = ([bool]$r50Decoy -and (-not (Test-Path -LiteralPath $r50Decoy)))
    foreach ($n in $r50EnvNames) { [System.Environment]::SetEnvironmentVariable($n, $r50EnvSave[$n], 'Process') }
}
if ($r50CheckoutCfg) { $r50CheckoutSha1 = Get-R50Sha $r50CheckoutCfg }

# NON-VACUITY, counted over what the helper and the children DID, not over what this table wanted.
$r50Outcomes = @(
    $(if ($r50Refused1) { 'refused' } else { 'admitted' }),
    $(if ($r50Refused2) { 'refused' } else { 'admitted' }),
    $(if ($r50Refused3) { 'refused' } else { 'admitted' }),
    $(if ($r50Refused4) { 'refused' } else { 'admitted' }),
    $(if ($null -ne $r50ChildCured) { $r50ChildCured.verdict } else { '(not run)' }),
    $(if ($null -ne $r50ChildUncured) { $r50ChildUncured.verdict } else { '(not run)' })
)
$r50RefusedN  = @($r50Outcomes | Where-Object { $_ -eq 'refused' }).Count
$r50AdmittedN = @($r50Outcomes | Where-Object { $_ -eq 'admitted' }).Count
$r50Split = (($r50Outcomes.Count -eq 6) -and ($r50RefusedN -ge 1) -and ($r50AdmittedN -ge 1))
$r50InitFailed = (($null -ne $r50Exit1) -and ($r50Exit1 -ne 0) -and $r50NoGit1)
$r50ok6 = ($r50TempClear -and $r50DecoyReal -and $r50InitFailed -and $r50Split -and $r50Gone -and (-not $r50Unexpected))
$r50Rows.Add(('    {0,-30} TEMP outside any repository={1} decoy a real repository={2} failing init exit={3} with no .git in the fixture={4} outcomes refused/admitted={5}/{6} of {7} decoy gone={8} unexpected error={9}  (expect True, True, non-zero, True, >=1/>=1 of 6, True, none)  {10}' -f `
              '6 NON-VACUITY', $r50TempClear, $r50DecoyReal, $(if ($null -ne $r50Exit1) { $r50Exit1 } else { '(unread)' }), $r50NoGit1, $r50RefusedN, $r50AdmittedN, $r50Outcomes.Count, $r50Gone,
              $(if ($r50Unexpected) { $r50Unexpected } else { 'none' }), $(if ($r50ok6) { 'ok' } else { 'MISMATCH' })))

$r50detail = @"
    THE SIX ROWS, all inside a decoy repository under TEMP with GIT_CEILING_DIRECTORIES at its parent, every value READ from git, its trace, or the disk:
$($r50Rows -join "`n")
    decoy               : $r50Decoy   (removed: $r50Gone)
    TEMP probe said     : $(if ($r50TempSaid) { $r50TempSaid } else { '(nothing)' })
    this checkout's common config, REPORTED NOT ASSERTED (another hand may edit it mid-run):
      $(if ($r50CheckoutCfg) { $r50CheckoutCfg } else { '(unresolved)' })
      sha256 before $(if ($r50CheckoutSha0) { $r50CheckoutSha0.Substring(0, [Math]::Min(16, $r50CheckoutSha0.Length)) } else { '(none)' })   after $(if ($r50CheckoutSha1) { $r50CheckoutSha1.Substring(0, [Math]::Min(16, $r50CheckoutSha1.Length)) } else { '(none)' })
    WHAT THIS MEMBER DOES NOT CLAIM:
      * that every git config write in this instrument is guarded: the guarded sites are the seed, R-24's child, R-26 (both
        its main-tree writes and its worktree write) and R-44's remote writes. The census behind that list was taken by hand
        when item 7 was built; nothing here re-derives it on each run. R-51's and R-52's fixture seeds
        were added after it and go through Initialize-FixtureRepo like the seed.
      * anything about other instruments (WP-1, WP-3, WP-4, WP-6, tools/framework/tests), which carry unguarded fixture writes.
      * any row for a root spelled unlike git's own spelling. Driven outside this member on PS 5.1: an 8.3 short name in an
        EXISTING root (the root itself, or a parent component) is expanded by GetFullPath to the long spelling git prints and
        is ADMITTED -- a second spelling of the same directory; a junction root is REFUSED, because git prints the resolved
        target and the helper does not resolve links. Symlinks were not driven.
      * the runner's own git calls (mission-dispatch.ps1): only this instrument's fixture writes are asserted.
"@
Check -Id 'R-50' -Title 'a fixture whose git init failed is refused before any git config write: inside a decoy repository the failing init is refused with no config call traced and the decoy config unchanged, a good fixture and its linked worktree are admitted with the writes landing in the fixture, a sibling-prefix trap is refused, and the seed with its assertion planted out writes through to the decoy config' `
      -Ok ($r50ok1 -and $r50ok2 -and $r50ok3 -and $r50ok4 -and $r50ok5 -and $r50ok6) -Detail $r50detail

# =============================================================================================
# R-51 -- THE WORKER'S TREE LIVES BESIDE THE MISSION ROOT AND IS THE WORKER'S WORKING DIRECTORY
# =============================================================================================
# THE RULING. The row closed as NOT CURABLE BY EXEMPTION after four
# refutations: a worker tree under the mission root's .claude/ -- and, measured through the real guard,
# one under .mission-runtime/worktrees/ just the same -- sits in the guard's parent tier, which refuses
# every metacharacter-bearing or destructive command a worker aims at its own tree. The operator
# relocated the tree to <parent>\<leaf>-worktrees\wt-<id> and chose to hand the CLI that tree as its
# WORKING DIRECTORY rather than by --worktree, which takes a name and would create the retired home.
#
# TEN ROWS, in fixture repositories of this member's own (seeded the way the main fixture is, through
# Initialize-FixtureRepo), so nothing here disturbs any member above. WHAT EACH ROW DRIVES, stated per row
# because this header once said all of them were "a real runner or a real git" and row 2 is neither
# (found in review): rows 1, 3, 4, 6, 7, 8, 9 and 10 drive the REAL RUNNER; rows 5 and 8 ask
# REAL GIT for its own answer at the same path; row 2 READS THE DISK.
#   1 THE RELOCATION -- a dispatch runs AFTER two sibling ids' trees already exist: wt-D-R51B, the prefix
#     shape, and wt-D-R50-wt-D-R51, a name that CONTAINS this tree's name and that git lists BEFORE it
#     (git lists linked worktrees in the order of their admin directories, and 'wt-D-R50-' sorts before
#     'wt-D-R51'). The plan's argv carries no --worktree and names the sibling tree; the run exits 0; the
#     tree is there, on its branch, listed once by `git worktree list --porcelain` and NOT locked; the
#     stub's own process working directory IS the tree; the anchors name THIS tree and not a sibling; and
#     nothing exists under <root>\.claude. THE KILL (found in review): the old `-like "*wt-<id>*"` selection,
#     planted into a copy through New-UncuredCopy, names the listed-first sibling in the anchors. Measured
#     first: with wt-D-R51B alone, git lists this tree before it and the planted copy agreed with the cure
#     on every conjunct, so the row could not see the revert; the embedded-name sibling is what lets it.
#   2 THE MAIN FIXTURE never grew a .claude/ over every run above (a disk read) -- the measurement behind
#     R-9's and R-10's declarations no longer carrying '?? .claude/'.
#   3 A LEAFLESS ROOT -- the drive root this sandbox sits on -- is REFUSED, naming why, before anything
#     is read from it (the runner is asked to dispatch there for real; it is read-only by construction).
#   4 A 216-BYTE COMPOSED PATH (ASCII, so also 216 characters) is REFUSED before any `worktree add`: no
#     directory, no branch, no worktree registered, and no run record opened.
#   5 GIT ITSELF refuses a linked worktree at that same path -- the premise of row 4, asserted rather
#     than cited, so row 4 cannot be a runner being stricter than git.
#   6 THE CONTROL -- the 215-byte path, one byte shorter, runs to exit 0 through the same runner, the
#     worker's file in the tree, and every path under that fixture root and its worktree home is shorter
#     than 260 characters. Without it, rows 3, 4 and 8 would also pass on a runner that refuses everything.
#   7 A '[' AND ']' IN THE DISPATCH ID (found in review) -- 'D-R51[1]' runs to exit 0, is not refused for the
#     bracket, and the stub's process working directory IS the tree. THE KILL: the pre-cure plain
#     `Push-Location $workerCwd`, planted back, runs the stub OUTSIDE the tree. This row drives the
#     WORKER-SITE entry only; row 9 drives the suite site and row 10 the read-back refusal.
#   8 A NON-ASCII COMPOSED PATH OF 215 CHARACTERS AND 216 UTF-8 BYTES (found in review) is REFUSED before any
#     `worktree add`, naming bytes, with no directory, branch or run record -- and git itself refuses a
#     linked worktree at that path WITH ITS CEILING'S OWN ANSWER, exit 128 and '$GIT_DIR' too big, not
#     merely some non-zero exit (found in review: any unrelated git failure would have passed that).
#     THE GIT-LEVEL CONTROL: a non-ASCII path one byte shorter, 214 characters and 215 bytes, git ACCEPTS
#     (exit 0); that tree is removed through git and pruned at once. (On the uncured runner, which counted
#     characters, -PlanOnly printed the 216-byte path, the run opened its record, and git's '$GIT_DIR' too
#     big left a branch behind: measured.)
#   9 THE SUITE SITE IN A BRACKETED TREE (found in review) -- 'D-R51[2]' declares a suite_command, a stub
#     that records its own process working directory: the run exits 0, the worker ran, and the suite ran IN
#     the tree. THE KILL: the suite site's pre-cure plain `Push-Location $worktreePath`, planted back into a
#     copy, reaches the worker and does not run the suite in the tree -- AND fails AT THAT SITE (review
#     round 3): exit 5, with the top-level trap's own lines naming the bracketed tree as a path not found
#     (ItemNotFoundException). Measured in review round 3: that push prints "UNHANDLED ERROR -- Cannot find
#     path '<the tree>' because it does not exist." with that type; and in a copy where the same plant was
#     still located, an unrelated throw after the worker (exit 5, another message) and an unrelated exit 4
#     each passed the kill as it stood, and neither passes it now.
#  10 A LOCATION READ BACK THAT IS NOT THE TREE (found in review) -- a copy whose Enter-WorktreeLocation
#     pushes the MISSION ROOT instead of the location it is handed: the dispatch is REFUSED, exit 2, naming a
#     working directory that is not the worker worktree; the tree exists but the worker never spawned in it;
#     the run record reads finished rc 2. The row turns red if the read-back comparison is removed from the
#     runner under test (measured when this row was written, not planted here: the worker then spawns and
#     the run exits 0).
# Rows 4, 5, 6 and 8 run in a second fixture whose root is lengthened to exactly 197 characters with
# nested short directories (found in review; see the row-182 band comment at the seed): at that root the
# runner's evidence directory is 236 characters, under CreateDirectory's 248, and the longest file it
# writes there, runner-stream.jsonl, is 256 -- measured, and asserted by row 6 rather than assumed.
$r51Base = Join-Path $sandbox 'r51'
$r51Root = Join-Path $r51Base 'm'
$r51Rows = @()
$r51Worker = Join-Path $stubDir 'worker-r51-cwd.ps1'
# THE STUB RECORDS ITS OWN PROCESS WORKING DIRECTORY -- what a native CLI is handed -- read from inside
# the child and never told to it. NOT Get-Location (found in review; measured on PS 5.1): a
# powershell.exe child started in a directory whose name holds '[' or ']' cannot set its OWN initial
# location there and reports $PSHOME from Get-Location, while its process working directory IS that
# directory (cmd.exe's `cd` agrees). Get-Location is written beside it, for a reader.
Write-Utf8 -Path $r51Worker -Text @'
$root = $env:LAM_WORKTREE
[System.IO.File]::WriteAllText((Join-Path $root 'worker-created.txt'), 'created by the worker stub')
[System.IO.File]::WriteAllText((Join-Path $root 'worker-cwd.txt'), [Environment]::CurrentDirectory)
[System.IO.File]::WriteAllText((Join-Path $root 'worker-psloc.txt'), (Get-Location).ProviderPath)
Write-Output 'WORKER-MARKER-OK'
[System.IO.File]::WriteAllText($env:LAM_HANDOFF, ("id: handoff-wp2-r5x`nfrom_worker: w-wp2-r5x`ndispatch_id: " + $env:LAM_DISPATCH + "`nfeature_id: F-001`nspec_version: 1`ncompleted_assertions: [A-001]`nunfinished: []`ncommits: []`ncommands_run: []`nissues_observed: []`nprocedure_adherence: confirmed`nterminated_reason: completed`n"))
exit 0
'@
# ROW 9's SUITE STUB records its own process working directory the same way, into the tree the runner names.
$r51Suite = Join-Path $stubDir 'suite-r51-cwd.ps1'
Write-Utf8 -Path $r51Suite -Text @'
[System.IO.File]::WriteAllText((Join-Path $env:LAM_WORKTREE 'suite-cwd.txt'), [Environment]::CurrentDirectory)
Write-Output 'R51-SUITE-RAN'
exit 0
'@

function ConvertTo-R5xKey {
    param([string]$PathText)
    if (-not $PathText) { return '' }
    try { return ([System.IO.Path]::GetFullPath(($PathText.Trim() -replace '/', '\'))).TrimEnd('\').ToUpperInvariant() } catch { return '' }
}
function Invoke-R5xRunner {
    param([string]$RunnerPath, [string]$Root, [string]$Id, [string[]]$Extra = @())
    $argv = @('-NoProfile', '-ExecutionPolicy', 'Bypass', '-File', $RunnerPath, '-MissionRoot', $Root, '-Dispatch', $Id, '-AllowIdReuse') + @($Extra)
    $prevEap = $ErrorActionPreference
    $ErrorActionPreference = 'Continue'
    try { $out = & powershell @argv 2>&1; $code = $LASTEXITCODE }
    finally { $ErrorActionPreference = $prevEap }
    return [pscustomobject]@{ out = ((@($out) | ForEach-Object { "$_" }) -join "`n"); exit = $code; argc = $argv.Count }
}
function Get-R5xGit {
    param([string]$Root, [string[]]$GitArgs)
    $prevEap = $ErrorActionPreference
    $ErrorActionPreference = 'Continue'
    try { $o = @(& git -C $Root @GitArgs 2>&1); $code = $LASTEXITCODE }
    finally { $ErrorActionPreference = $prevEap }
    return [pscustomobject]@{ exit = $code; lines = @(@($o) | Where-Object { $_ -is [string] }); said = ((@($o) | ForEach-Object { "$_" }) -join ' | ') }
}
function Write-R5xDispatch {
    param([string]$Root, [string]$Id, [string]$Extra = '')
    Write-Utf8 -Path (Join-Path $Root ".mission\dispatches\$Id.yaml") -Text ("id: $Id`nmission_id: mission-wp2-r5x`nworker_id: w-wp2-r5x`nkind: mainline`nfeature_id: F-001`nassertion_targets: [A-001]`nspec_version: 1`nworktree_id: wt-r5x`nmodel_class: coding-strong`n" + $Extra + "goal_condition: `"the $Id fixture dispatch`"`n")
}
# A FIXTURE MISSION REPOSITORY, THE SEED'S SEQUENCE: files, Initialize-FixtureRepo (git init, the item-7
# assertion, then config through the verified -C), one commit, the shipped decider. Returns the seed's
# refusal text instead of throwing, so a refused seed fails ITS member and not the instrument.
function New-R5xFixture {
    param([string]$Root, [string]$GitIgnore, [System.Collections.IDictionary]$Files)
    New-Item -ItemType Directory -Path $Root -Force | Out-Null
    Write-Utf8 -Path (Join-Path $Root '.mission\mission.yaml') -Text "id: mission-wp2-r5x`nstate: executing`n"
    Write-Utf8 -Path (Join-Path $Root 'src\seed.txt') -Text "seed`n"
    Write-Utf8 -Path (Join-Path $Root '.gitignore') -Text $GitIgnore
    if ($Files) { foreach ($k in @($Files.Keys)) { Write-Utf8 -Path (Join-Path $Root $k) -Text ([string]$Files[$k]) } }
    try {
        $null = Initialize-FixtureRepo -Root $Root -Config ([ordered]@{ 'user.email' = 'wp2@instrument.local'; 'user.name' = 'WP2 Instrument'; 'core.longpaths' = 'true' })
    } catch {
        if ($_.Exception.Message -match 'refusing before any git config write') { return [pscustomobject]@{ refusal = $_.Exception.Message; head = '' } }
        throw
    }
    $null = Get-R5xGit -Root $Root -GitArgs @('add', '-A')
    $null = Get-R5xGit -Root $Root -GitArgs @('commit', '-q', '-m', 'fixture seed')
    $h = Get-R5xGit -Root $Root -GitArgs @('rev-parse', 'HEAD')
    Install-DeciderIn -Repo $Root
    return [pscustomobject]@{ refusal = ''; head = $(if ($h.exit -eq 0 -and $h.lines.Count -gt 0) { $h.lines[0].Trim() } else { '' }) }
}
function Get-R5xAnchor {
    param([string]$Root, [string]$Id, [string]$Key)
    $an = Join-Path $Root ".mission\dispatches\$Id.anchors.yaml"
    if (-not (Test-Path -LiteralPath $an)) { return '(no anchors)' }
    if ([System.IO.File]::ReadAllText($an) -match ("(?m)^" + [regex]::Escape($Key) + ":\s*(.*?)\s*$")) { return $Matches[1] }
    return '(absent)'
}
# A RUN THROUGH A PLANTED COPY needs the fixture's decider wrapper to name the COPY's decider (the runner
# checks it), so the hook is repointed for that one run and restored in a finally, as R-52 row 2 does.
function Invoke-R5xWithDecider {
    param([string]$Root, [string]$Decider, [scriptblock]$Body)
    $r5xHook = Join-Path $Root '.git\hooks\pre-push'
    $r5xSave = [System.IO.File]::ReadAllText($r5xHook)
    [System.IO.File]::WriteAllText($r5xHook, (Get-EvidencePrePushWrapperText -DeciderPath $Decider), (New-Object System.Text.UTF8Encoding($false)))
    try { return (& $Body) } finally { [System.IO.File]::WriteAllText($r5xHook, $r5xSave, (New-Object System.Text.UTF8Encoding($false))) }
}
# JUNCTIONS (found in review) are made with `cmd /c mklink /J` and removed with `cmd /c rmdir`, which
# removes the link and never its target. Every target in this file lies INSIDE the sandbox, and every
# link is removed in a finally right after its row, before any recursive delete -- which follows one.
function New-R5xJunction {
    param([string]$Link, [string]$Target)
    $prevEap = $ErrorActionPreference
    $ErrorActionPreference = 'Continue'
    try { $r5xSaid = @(& cmd.exe /c mklink /J $Link $Target 2>&1); $r5xCode = $LASTEXITCODE }
    finally { $ErrorActionPreference = $prevEap }
    $r5xIsLink = $false
    try { $r5xIsLink = ([System.IO.File]::GetAttributes($Link)).HasFlag([System.IO.FileAttributes]::ReparsePoint) } catch { $r5xIsLink = $false }
    return [pscustomobject]@{ exit = $r5xCode; isLink = $r5xIsLink; said = ((@($r5xSaid) | ForEach-Object { "$_" }) -join ' ') }
}
function Remove-R5xJunction {
    param([string]$Link)
    $r5xIsLink = $false
    try { $r5xIsLink = ([System.IO.File]::GetAttributes($Link)).HasFlag([System.IO.FileAttributes]::ReparsePoint) } catch { $r5xIsLink = $false }
    if (-not $r5xIsLink) { return $false }
    $prevEap = $ErrorActionPreference
    $ErrorActionPreference = 'Continue'
    try { $null = @(& cmd.exe /c rmdir $Link 2>&1) } finally { $ErrorActionPreference = $prevEap }
    return (-not (Test-Path -LiteralPath $Link))
}
# HARD LINKS (found in review) are made with `cmd /c mklink /H`; both names lie inside the sandbox. A hard
# link is a second NAME for one file record, so removing either name (the sandbox's recursive delete included)
# never touches the other name's bytes. Get-R5xLinkNames counts the names `fsutil hardlink list` reports for a
# file (read-only); -1 means fsutil could not answer.
function Get-R5xLinkNames {
    param([string]$PathText)
    if (-not (Test-Path -LiteralPath $PathText -PathType Leaf)) { return 0 }
    $prevEap = $ErrorActionPreference
    $ErrorActionPreference = 'Continue'
    try { $r5xOut = @(& fsutil.exe hardlink list $PathText 2>&1); $r5xCode = $LASTEXITCODE }
    finally { $ErrorActionPreference = $prevEap }
    if ($r5xCode -ne 0) { return -1 }
    return @($r5xOut | Where-Object { ($_ -is [string]) -and $_.Trim() }).Count
}
function New-R5xHardLink {
    param([string]$Link, [string]$Target)
    $prevEap = $ErrorActionPreference
    $ErrorActionPreference = 'Continue'
    try { $r5xSaid = @(& cmd.exe /c mklink /H $Link $Target 2>&1); $r5xCode = $LASTEXITCODE }
    finally { $ErrorActionPreference = $prevEap }
    return [pscustomobject]@{ exit = $r5xCode; names = (Get-R5xLinkNames -PathText $Link); said = ((@($r5xSaid) | ForEach-Object { "$_" }) -join ' ') }
}
# A SECOND PLANT INTO A COPY New-UncuredCopy already made, for a pre-cure shape that spans two lines. The line
# must be located exactly once and the copy must still parse, or the plant counts as not made.
function Add-R5xSecondPlant {
    param([string]$RunnerPath, [string]$CuredLine, [string]$OldLine)
    $r5xText = [System.IO.File]::ReadAllText($RunnerPath)
    if (([regex]::Matches($r5xText, [regex]::Escape($CuredLine))).Count -ne 1) { return $false }
    [System.IO.File]::WriteAllText($RunnerPath, $r5xText.Replace($CuredLine, $OldLine), (New-Object System.Text.UTF8Encoding($false)))
    $r5xPe = $null; $r5xPt = $null
    [void][System.Management.Automation.Language.Parser]::ParseFile($RunnerPath, [ref]$r5xPt, [ref]$r5xPe)
    return ($null -eq $r5xPe -or $r5xPe.Count -eq 0)
}

$r51Seed = New-R5xFixture -Root $r51Root -GitIgnore ".mission-runtime/`n"
$r51ok1 = $false; $r51ok2 = $false; $r51ok3 = $false; $r51ok4 = $false; $r51ok5 = $false; $r51ok6 = $false; $r51ok7 = $false; $r51ok8 = $false; $r51ok9 = $false; $r51ok10 = $false
$r51cRoot = ''; $r51cLongLen = 0; $r51cLongest = @()
if ($r51Seed.refusal -or (-not $r51Seed.head)) {
    $r51Rows += ("    the R-51 fixture was not seeded: {0}" -f $(if ($r51Seed.refusal) { $r51Seed.refusal } else { 'no HEAD after the seed commit' }))
} else {
    # ---- row 1: THE RELOCATION ----------------------------------------------------------------------
    $r51Id   = 'D-R51'
    $r51IdB  = 'D-R51B'
    $r51IdE  = 'D-R50-wt-D-R51'
    $r51Tree  = Get-FixtureWorktreePath -Id $r51Id -Root $r51Root
    $r51TreeB = Get-FixtureWorktreePath -Id $r51IdB -Root $r51Root
    $r51TreeE = Get-FixtureWorktreePath -Id $r51IdE -Root $r51Root
    Write-R5xDispatch -Root $r51Root -Id $r51IdB
    $r51runB = Invoke-R5xRunner -RunnerPath $runner -Root $r51Root -Id $r51IdB -Extra @('-VerifyCommand', $verifyPass, '-WorkerCommand', $r51Worker)
    Write-R5xDispatch -Root $r51Root -Id $r51IdE
    $r51runE = Invoke-R5xRunner -RunnerPath $runner -Root $r51Root -Id $r51IdE -Extra @('-VerifyCommand', $verifyPass, '-WorkerCommand', $r51Worker)
    Write-R5xDispatch -Root $r51Root -Id $r51Id
    $r51plan = Invoke-R5xRunner -RunnerPath $runner -Root $r51Root -Id $r51Id -Extra @('-VerifyCommand', $verifyPass, '-PlanOnly')
    $r51argvLine = @(@($r51plan.out -split "`n") | Where-Object { $_ -match '^\s*argv\s*:' })
    $r51treeLine = @(@($r51plan.out -split "`n") | Where-Object { $_ -match '^\s*worktree path\s*:' })
    $r51planNoWt = (($r51argvLine.Count -eq 1) -and ($r51argvLine[0] -notmatch '--worktree'))
    $r51planTree = (($r51treeLine.Count -eq 1) -and ((($r51treeLine[0] -replace '^\s*worktree path\s*:\s*', '').Trim()) -eq $r51Tree))
    $r51run = Invoke-R5xRunner -RunnerPath $runner -Root $r51Root -Id $r51Id -Extra @('-VerifyCommand', $verifyPass, '-WorkerCommand', $r51Worker)
    $r51made  = Test-Path -LiteralPath (Join-Path $r51Tree 'worker-created.txt')
    $r51cwdFile = Join-Path $r51Tree 'worker-cwd.txt'
    $r51cwd   = if (Test-Path -LiteralPath $r51cwdFile) { [System.IO.File]::ReadAllText($r51cwdFile).Trim() } else { '(the stub recorded no cwd)' }
    $r51cwdIsTree = ((ConvertTo-R5xKey $r51cwd) -eq (ConvertTo-R5xKey $r51Tree))
    $r51wl = Get-R5xGit -Root $r51Root -GitArgs @('worktree', 'list', '--porcelain')
    $r51blocks = @()
    $r51cur = $null
    foreach ($l in $r51wl.lines) {
        if ($l -match '^worktree (.+)$') { $r51cur = [pscustomobject]@{ path = $Matches[1].Trim(); locked = $false; branch = '' }; $r51blocks += $r51cur }
        elseif ($r51cur -and ($l -match '^locked')) { $r51cur.locked = $true }
        elseif ($r51cur -and ($l -match '^branch (.+)$')) { $r51cur.branch = $Matches[1].Trim() }
    }
    $r51mine = @($r51blocks | Where-Object { (ConvertTo-R5xKey $_.path) -eq (ConvertTo-R5xKey $r51Tree) })
    $r51order = @($r51blocks | ForEach-Object { ConvertTo-R5xKey $_.path })
    $r51atE   = [array]::IndexOf([object[]]$r51order, [object](ConvertTo-R5xKey $r51TreeE))
    $r51atMe  = [array]::IndexOf([object[]]$r51order, [object](ConvertTo-R5xKey $r51Tree))
    $r51eFirst = (($r51atE -ge 0) -and ($r51atMe -ge 0) -and ($r51atE -lt $r51atMe))
    $r51listedOnce = ($r51mine.Count -eq 1)
    $r51notLocked  = ($r51listedOnce -and (-not $r51mine[0].locked))
    $r51branchOk   = ($r51listedOnce -and ($r51mine[0].branch -ceq "refs/heads/worktree-wt-$r51Id"))
    $r51anchPath   = Get-R5xAnchor -Root $r51Root -Id $r51Id -Key 'worktree_path'
    $r51anchIsMine = ((ConvertTo-R5xKey $r51anchPath) -eq (ConvertTo-R5xKey $r51Tree))
    $r51noClaude   = (-not (Test-Path -LiteralPath (Join-Path $r51Root '.claude')))
    $r51gitErrs    = Get-R5xAnchor -Root $r51Root -Id $r51Id -Key 'git_errors'
    # THE KILL (found in review): the old `-like "*wt-<id>*"` selection, planted into the porcelain loop of a copy.
    $r51LikeCopy = New-UncuredCopy -Name 'uncured51like' `
        -CuredLine "                    if ((ConvertTo-WorktreePathKey `$wlPath) -eq `$wantKey) { `$resolved = (`$wlPath -replace '/', '\'); break }" `
        -OldLine   "                    if (`"`$wlPath`" -like `"*`$worktreeName*`") { `$resolved = (`$wlPath -replace '/', '\'); break }"
    $r51runK  = Invoke-R5xWithDecider -Root $r51Root -Decider $r51LikeCopy.decider -Body { Invoke-R5xRunner -RunnerPath $r51LikeCopy.runner -Root $r51Root -Id $r51Id -Extra @('-VerifyCommand', $verifyPass, '-WorkerCommand', $r51Worker) }
    $r51anchK = Get-R5xAnchor -Root $r51Root -Id $r51Id -Key 'worktree_path'
    $r51killed = ($r51LikeCopy.planted -and $r51LikeCopy.parses -and ((ConvertTo-R5xKey $r51anchK) -eq (ConvertTo-R5xKey $r51TreeE)))
    $r51ok1 = (($r51runB.exit -eq 0) -and (Test-Path -LiteralPath $r51TreeB) -and ($r51runE.exit -eq 0) -and $r51eFirst -and $r51planNoWt -and $r51planTree -and ($r51run.exit -eq 0) -and $r51made -and
               $r51cwdIsTree -and $r51listedOnce -and $r51notLocked -and $r51branchOk -and $r51anchIsMine -and $r51noClaude -and ($r51gitErrs -eq '[]') -and $r51killed)
    $r51Rows += Format-R2xRow -Id '1 the relocation' -RowOk $r51ok1 `
        -Text ("siblings wt-$r51IdB exit={0} and wt-$r51IdE exit={1}, the latter listed BEFORE this tree={2}; plan: no --worktree={3} names the sibling tree={4}; run exit={5} worker file in the tree={6} the stub's process cwd IS the tree={7} listed once={8} not locked={9} branch worktree-wt-{10}={11} anchors name THIS tree={12} <root>\.claude absent={13} anchors git_errors={14}; planted -like selection: located={15} parses={16} anchors name the listed-first sibling={17}  (expect 0, 0, True; True, True; 0, True x8, []; True, True, True -- the kill)" -f `
               $r51runB.exit, $r51runE.exit, $r51eFirst, $r51planNoWt, $r51planTree, $r51run.exit, $r51made, $r51cwdIsTree, $r51listedOnce, $r51notLocked, $r51Id, $r51branchOk, $r51anchIsMine, $r51noClaude, $r51gitErrs, $r51LikeCopy.planted, $r51LikeCopy.parses, $r51killed) `
        -Said (Get-R28Said $r51run.out)
    $r51Rows += ("        the stub's process cwd: {0}" -f $r51cwd)
    $r51Rows += ("        porcelain order: {0}" -f ((@($r51blocks | ForEach-Object { Split-Path -Leaf ($_.path -replace '/', '\') })) -join ' , '))
    $r51Rows += ("        planted -like run exit={0}, its anchors worktree_path: {1}" -f $r51runK.exit, $r51anchK)

    # ---- row 3: A LEAFLESS ROOT -----------------------------------------------------------------------
    $r51Drive = [System.IO.Path]::GetPathRoot($sandbox)
    $r51leaf = Invoke-R5xRunner -RunnerPath $runner -Root $r51Drive -Id $r51Id -Extra @('-VerifyCommand', $verifyPass, '-WorkerCommand', $r51Worker)
    $r51leafNamed = [bool]($r51leaf.out -match 'has no parent directory and leaf name')
    $r51ok3 = (($r51leaf.exit -eq 2) -and $r51leafNamed -and ($r51leaf.out -notmatch 'WORKER-MARKER-OK'))
    $r51Rows += Format-R2xRow -Id '3 a leafless mission root' -RowOk $r51ok3 `
        -Text ("root '{0}': exit={1} refusal names the missing parent/leaf={2} nothing spawned={3}  (expect 2, True, True)" -f $r51Drive, $r51leaf.exit, $r51leafNamed, ($r51leaf.out -notmatch 'WORKER-MARKER-OK')) `
        -Said (Get-R28Said $r51leaf.out)

    # ---- row 7: A '[' AND ']' IN THE DISPATCH ID (found in review) ------------------------------------------
    $r51IdBr   = 'D-R51[1]'
    $r51TreeBr = Get-FixtureWorktreePath -Id $r51IdBr -Root $r51Root
    Write-R5xDispatch -Root $r51Root -Id $r51IdBr
    $r51brRun  = Invoke-R5xRunner -RunnerPath $runner -Root $r51Root -Id $r51IdBr -Extra @('-VerifyCommand', $verifyPass, '-WorkerCommand', $r51Worker)
    $r51brCwdFile = Join-Path $r51TreeBr 'worker-cwd.txt'
    $r51brCwd  = if (Test-Path -LiteralPath $r51brCwdFile) { [System.IO.File]::ReadAllText($r51brCwdFile).Trim() } else { '(the stub recorded no cwd)' }
    $r51brMade = Test-Path -LiteralPath (Join-Path $r51TreeBr 'worker-created.txt')
    $r51brIsTree  = ((ConvertTo-R5xKey $r51brCwd) -eq (ConvertTo-R5xKey $r51TreeBr))
    $r51brRefused = [bool]($r51brRun.out -match 'REFUSED')
    if (Test-Path -LiteralPath $r51brCwdFile) { Remove-Item -LiteralPath $r51brCwdFile -Force }
    $r51brCopy = New-UncuredCopy -Name 'uncured51cwd' `
        -CuredLine '$workerCwdDenial = Enter-WorktreeLocation -Location $workerCwd -Tree $worktreePath' `
        -OldLine   'Push-Location $workerCwd; $workerCwdDenial = '''''
    $r51brRunK = Invoke-R5xWithDecider -Root $r51Root -Decider $r51brCopy.decider -Body { Invoke-R5xRunner -RunnerPath $r51brCopy.runner -Root $r51Root -Id $r51IdBr -Extra @('-VerifyCommand', $verifyPass, '-WorkerCommand', $r51Worker) }
    $r51brCwdK = if (Test-Path -LiteralPath $r51brCwdFile) { [System.IO.File]::ReadAllText($r51brCwdFile).Trim() } else { '(the stub recorded no cwd)' }
    $r51brOutside = ((Test-Path -LiteralPath $r51brCwdFile) -and ((ConvertTo-R5xKey $r51brCwdK) -ne (ConvertTo-R5xKey $r51TreeBr)))
    $r51ok7 = (($r51brRun.exit -eq 0) -and (-not $r51brRefused) -and $r51brMade -and $r51brIsTree -and $r51brCopy.planted -and $r51brCopy.parses -and $r51brOutside)
    $r51Rows += Format-R2xRow -Id "7 a '[' and ']' in the dispatch id" -RowOk $r51ok7 `
        -Text ("id '{0}': exit={1} refused={2} worker file in the tree={3} the stub's process cwd IS the tree={4}; planted plain Push-Location: located={5} parses={6} the stub ran OUTSIDE the tree={7}  (expect 0, False, True, True; True, True, True -- the kill)" -f `
               $r51IdBr, $r51brRun.exit, $r51brRefused, $r51brMade, $r51brIsTree, $r51brCopy.planted, $r51brCopy.parses, $r51brOutside) `
        -Said (Get-R28Said $r51brRun.out)
    $r51Rows += ("        the stub's process cwd, cured: {0}   planted (exit {1}): {2}" -f $r51brCwd, $r51brRunK.exit, $r51brCwdK)

    # ---- row 9: THE SUITE SITE IN A BRACKETED TREE (found in review) -------------------------------
    $r51IdSu   = 'D-R51[2]'
    $r51TreeSu = Get-FixtureWorktreePath -Id $r51IdSu -Root $r51Root
    Write-R5xDispatch -Root $r51Root -Id $r51IdSu -Extra "suite_command: $r51Suite`n"
    $r51suRun  = Invoke-R5xRunner -RunnerPath $runner -Root $r51Root -Id $r51IdSu -Extra @('-VerifyCommand', $verifyPass, '-WorkerCommand', $r51Worker)
    $r51suCwdFile = Join-Path $r51TreeSu 'suite-cwd.txt'
    $r51suMadeFile = Join-Path $r51TreeSu 'worker-created.txt'
    $r51suCwd  = if (Test-Path -LiteralPath $r51suCwdFile) { [System.IO.File]::ReadAllText($r51suCwdFile).Trim() } else { '(the suite recorded no cwd)' }
    $r51suInTree  = ((Test-Path -LiteralPath $r51suCwdFile) -and ((ConvertTo-R5xKey $r51suCwd) -eq (ConvertTo-R5xKey $r51TreeSu)))
    $r51suWorker  = Test-Path -LiteralPath $r51suMadeFile
    $r51suRefused = [bool]($r51suRun.out -match 'REFUSED|suite not invoked')
    foreach ($r51suStale in @($r51suCwdFile, $r51suMadeFile)) { if (Test-Path -LiteralPath $r51suStale) { Remove-Item -LiteralPath $r51suStale -Force } }
    $r51suCopy = New-UncuredCopy -Name 'uncured51suite' `
        -CuredLine '    $suiteCwdDenial = Enter-WorktreeLocation -Location $worktreePath -Tree $worktreePath' `
        -OldLine   '    Push-Location $worktreePath; $suiteCwdDenial = '''''
    $r51suRunK = Invoke-R5xWithDecider -Root $r51Root -Decider $r51suCopy.decider -Body { Invoke-R5xRunner -RunnerPath $r51suCopy.runner -Root $r51Root -Id $r51IdSu -Extra @('-VerifyCommand', $verifyPass, '-WorkerCommand', $r51Worker) }
    $r51suCwdK = if (Test-Path -LiteralPath $r51suCwdFile) { [System.IO.File]::ReadAllText($r51suCwdFile).Trim() } else { '(the suite recorded no cwd)' }
    $r51suWorkerK = Test-Path -LiteralPath $r51suMadeFile
    $r51suNotInTreeK = (-not ((Test-Path -LiteralPath $r51suCwdFile) -and ((ConvertTo-R5xKey $r51suCwdK) -eq (ConvertTo-R5xKey $r51TreeSu))))
    # TIED TO THE PLANTED SITE (found in review): the trap's line names the bracketed tree as not found, and its type line agrees.
    $r51suAtSiteK = ([bool]($r51suRunK.out -match ('(?m)^mission-dispatch: UNHANDLED ERROR -- .*''' + [regex]::Escape($r51TreeSu) + '''')) -and
                     [bool]($r51suRunK.out -match '(?m)^\s*type\s*:\s*System\.Management\.Automation\.ItemNotFoundException\s*$'))
    $r51suKilled = ($r51suCopy.planted -and $r51suCopy.parses -and $r51suWorkerK -and $r51suNotInTreeK -and ($r51suRunK.exit -eq 5) -and $r51suAtSiteK)
    $r51ok9 = (($r51suRun.exit -eq 0) -and (-not $r51suRefused) -and $r51suWorker -and $r51suInTree -and $r51suKilled)
    $r51Rows += Format-R2xRow -Id "9 the suite site in a bracketed tree" -RowOk $r51ok9 `
        -Text ("id '{0}' with a suite_command: exit={1} refused or suite not invoked={2} worker ran={3} the suite's process cwd IS the tree={4}; planted plain Push-Location at the suite site: located={5} parses={6} exit={7} worker ran={8} the suite did NOT run in the tree={9} the trap names the bracketed tree not found={10}  (expect 0, False, True, True; True, True, 5, True, True, True -- the kill)" -f `
               $r51IdSu, $r51suRun.exit, $r51suRefused, $r51suWorker, $r51suInTree, $r51suCopy.planted, $r51suCopy.parses, $r51suRunK.exit, $r51suWorkerK, $r51suNotInTreeK, $r51suAtSiteK) `
        -Said (Get-R28Said $r51suRun.out)
    $r51Rows += ("        the suite's process cwd, cured: {0}   planted (exit {1}): {2}" -f $r51suCwd, $r51suRunK.exit, $r51suCwdK)

    # ---- row 10: A LOCATION READ BACK THAT IS NOT THE TREE (found in review) -------------------------
    $r51IdRb   = 'D-R51R'
    $r51TreeRb = Get-FixtureWorktreePath -Id $r51IdRb -Root $r51Root
    Write-R5xDispatch -Root $r51Root -Id $r51IdRb
    $r51rbCopy = New-UncuredCopy -Name 'planted51readback' `
        -CuredLine '    try { Push-Location -LiteralPath $Location -ErrorAction Stop }' `
        -OldLine   '    try { Push-Location -LiteralPath $MissionRoot -ErrorAction Stop }'
    $r51rbRun  = Invoke-R5xWithDecider -Root $r51Root -Decider $r51rbCopy.decider -Body { Invoke-R5xRunner -RunnerPath $r51rbCopy.runner -Root $r51Root -Id $r51IdRb -Extra @('-VerifyCommand', $verifyPass, '-WorkerCommand', $r51Worker) }
    $r51rbRr   = Invoke-R5xRunner -RunnerPath $runner -Root $r51Root -Id $r51IdRb -Extra @('-CheckRunRecord')
    $r51rbState = if ($r51rbRr.out -match '(?m)^run-record:\s*(\S+)') { $Matches[1] } else { '(unreadable)' }
    $r51rbRc    = if ($r51rbRr.out -match '(?m)^\s*rc\s*:\s*(\S+)') { $Matches[1] } else { '(unreadable)' }
    $r51rbNamed = [bool]($r51rbRun.out -match 'REFUSED -- the working directory reached was .*which is not the worker worktree')
    $r51rbTree  = Test-Path -LiteralPath $r51TreeRb
    $r51rbSpawn = Test-Path -LiteralPath (Join-Path $r51TreeRb 'worker-created.txt')
    $r51ok10 = ($r51rbCopy.planted -and $r51rbCopy.parses -and ($r51rbRun.exit -eq 2) -and $r51rbNamed -and $r51rbTree -and (-not $r51rbSpawn) -and ($r51rbState -eq 'finished') -and ($r51rbRc -eq '2'))
    $r51Rows += Format-R2xRow -Id '10 a location read back that is not the tree' -RowOk $r51ok10 `
        -Text ("planted push of the mission root: located={0} parses={1} exit={2} refusal names a working directory that is not the worker worktree={3} tree exists={4} worker spawned={5} run record={6} rc={7}  (expect True, True, 2, True, True, False, finished, 2)" -f `
               $r51rbCopy.planted, $r51rbCopy.parses, $r51rbRun.exit, $r51rbNamed, $r51rbTree, $r51rbSpawn, $r51rbState, $r51rbRc) `
        -Said (Get-R28Said $r51rbRun.out)
}

# ---- rows 4, 5, 6 and 8: GIT'S CEILING, IN A ROOT BUILT TO EXACTLY 197 CHARACTERS (found in review) -------------
# composed = <root> + '-worktrees\wt-' (14) + <id>. The root is nested eight-character directories and a
# short leaf, so the ids are 'D-Cxx' (216), 'D-Cx' (215) and 'D-C' + an e-acute (215 characters, 216 UTF-8
# bytes). The depth of this checkout decides only whether that root can be built at all.
$r51cBase = Join-Path $sandbox 'r51c'
$r51cRoot = $r51cBase
while (($r51cRoot.Length + 9) -lt 196) { $r51cRoot = $r51cRoot + '\' + ('s' * 8) }
$r51cLeaf = 197 - $r51cRoot.Length - 1
if ($r51cLeaf -lt 1) {
    $r51Rows += ("    rows 4, 5, 6 and 8 NOT CONSTRUCTIBLE: the sandbox's r51c directory is already {0} characters, so no 197-character root can be built under it" -f $r51cBase.Length)
} else {
    $r51cRoot = $r51cRoot + '\' + ('m' * $r51cLeaf)
    $r51cSeed = New-R5xFixture -Root $r51cRoot -GitIgnore ".mission-runtime/`n"
    if ($r51cSeed.refusal -or (-not $r51cSeed.head)) {
        $r51Rows += ("    the R-51 ceiling fixture was not seeded: {0}" -f $(if ($r51cSeed.refusal) { $r51cSeed.refusal } else { 'no HEAD after the seed commit' }))
    } else {
        $r51Id216 = 'D-Cxx'
        $r51Id215 = 'D-Cx'
        $r51IdU   = 'D-C' + [string][char]0x00E9
        $r51Tree216 = Get-FixtureWorktreePath -Id $r51Id216 -Root $r51cRoot
        $r51Tree215 = Get-FixtureWorktreePath -Id $r51Id215 -Root $r51cRoot
        $r51TreeU   = Get-FixtureWorktreePath -Id $r51IdU -Root $r51cRoot

        # row 4: the runner at a 216-byte path.
        $r51wlBefore = Get-R5xGit -Root $r51cRoot -GitArgs @('worktree', 'list', '--porcelain')
        Write-R5xDispatch -Root $r51cRoot -Id $r51Id216
        $r51c216 = Invoke-R5xRunner -RunnerPath $runner -Root $r51cRoot -Id $r51Id216 -Extra @('-VerifyCommand', $verifyPass, '-WorkerCommand', $r51Worker)
        $r51wlAfter = Get-R5xGit -Root $r51cRoot -GitArgs @('worktree', 'list', '--porcelain')
        $r51br216 = Get-R5xGit -Root $r51cRoot -GitArgs @('rev-parse', '--verify', '--quiet', "refs/heads/worktree-wt-$r51Id216")
        $r51rec216 = Join-Path $r51cRoot ".mission-runtime\evidence\session-$r51Id216\$r51Id216.started"
        $r51names216 = [bool](($r51c216.out -match 'is 216 bytes') -and ($r51c216.out -match '216 bytes or more'))
        $r51untouched = (($r51wlBefore.exit -eq 0) -and ($r51wlAfter.exit -eq 0) -and (($r51wlBefore.lines -join "`n") -eq ($r51wlAfter.lines -join "`n")))
        $r51ok4 = (($r51Tree216.Length -eq 216) -and ([System.Text.Encoding]::UTF8.GetByteCount($r51Tree216) -eq 216) -and ($r51c216.exit -eq 2) -and $r51names216 -and (-not (Test-Path -LiteralPath $r51Tree216)) -and
                   ($r51br216.exit -ne 0) -and $r51untouched -and (-not (Test-Path -LiteralPath $r51rec216)) -and ($r51c216.out -notmatch 'WORKER-MARKER-OK'))
        $r51Rows += Format-R2xRow -Id '4 a 216-byte composed path' -RowOk $r51ok4 `
            -Text ("path length={0} bytes={1} exit={2} refusal names the ceiling and the length in bytes={3} no directory={4} no branch={5} worktree list unchanged={6} no run record={7}  (expect 216, 216, 2, True x5)" -f `
                   $r51Tree216.Length, [System.Text.Encoding]::UTF8.GetByteCount($r51Tree216), $r51c216.exit, $r51names216, (-not (Test-Path -LiteralPath $r51Tree216)), ($r51br216.exit -ne 0), $r51untouched, (-not (Test-Path -LiteralPath $r51rec216))) `
            -Said (Get-R28Said $r51c216.out)

        # row 5: git's own answer at that path. Its leftovers are pruned and removed at once.
        $null = Assert-FixtureGitDir -Root $r51cRoot
        $r51git216 = Get-R5xGit -Root $r51cRoot -GitArgs @('worktree', 'add', '--detach', $r51Tree216, 'HEAD')
        $r51gitRefused = ($r51git216.exit -ne 0)
        if (Test-Path -LiteralPath $r51Tree216) { Remove-Item -LiteralPath $r51Tree216 -Recurse -Force -ErrorAction SilentlyContinue }
        $null = Get-R5xGit -Root $r51cRoot -GitArgs @('worktree', 'prune')
        $r51ok5 = $r51gitRefused
        $r51Rows += Format-R2xRow -Id '5 git itself at the same path' -RowOk $r51ok5 `
            -Text ("git worktree add --detach <216-byte path> exit={0} said={1}  (expect non-zero -- row 4 refuses nothing git would have accepted)" -f $r51git216.exit, $(if ($r51git216.said) { ($r51git216.said -replace '\s+', ' ').Substring(0, [Math]::Min(160, ($r51git216.said -replace '\s+', ' ').Length)) } else { '(nothing)' })) -Said ''

        # row 6: the control, and the longest path it wrote.
        Write-R5xDispatch -Root $r51cRoot -Id $r51Id215
        $r51c215 = Invoke-R5xRunner -RunnerPath $runner -Root $r51cRoot -Id $r51Id215 -Extra @('-VerifyCommand', $verifyPass, '-WorkerCommand', $r51Worker)
        $r51made215 = Test-Path -LiteralPath (Join-Path $r51Tree215 'worker-created.txt')
        $r51cUnderRoot = @(Get-ChildItem -LiteralPath $r51cRoot -Recurse -Force -ErrorAction SilentlyContinue | ForEach-Object { $_.FullName })
        $r51cUnderHome = @(Get-ChildItem -LiteralPath (Split-Path -Parent $r51Tree215) -Recurse -Force -ErrorAction SilentlyContinue | ForEach-Object { $_.FullName })
        $r51cPaths = @($r51cUnderRoot) + @($r51cUnderHome)
        $r51cLongest = @($r51cPaths | Sort-Object { $_.Length } -Descending | Select-Object -First 1)
        $r51cLongLen = if ($r51cLongest.Count -gt 0) { $r51cLongest[0].Length } else { 0 }
        $r51ok6 = (($r51Tree215.Length -eq 215) -and ([System.Text.Encoding]::UTF8.GetByteCount($r51Tree215) -eq 215) -and ($r51c215.exit -eq 0) -and $r51made215 -and ($r51cUnderRoot.Count -gt 0) -and ($r51cUnderHome.Count -gt 0) -and ($r51cLongLen -lt 260))
        $r51Rows += Format-R2xRow -Id '6 the control: 215 bytes' -RowOk $r51ok6 `
            -Text ("path length={0} exit={1} worker file in the tree={2} longest path under the root and its worktree home={3} characters  (expect 215, 0, True, under 260 -- the same runner and fixture, one byte shorter)" -f $r51Tree215.Length, $r51c215.exit, $r51made215, $r51cLongLen) `
            -Said (Get-R28Said $r51c215.out)

        # row 8: a non-ASCII path of 215 characters and 216 bytes -- the runner, then git itself.
        $r51wlBeforeU = Get-R5xGit -Root $r51cRoot -GitArgs @('worktree', 'list', '--porcelain')
        Write-R5xDispatch -Root $r51cRoot -Id $r51IdU
        $r51cU = Invoke-R5xRunner -RunnerPath $runner -Root $r51cRoot -Id $r51IdU -Extra @('-VerifyCommand', $verifyPass, '-WorkerCommand', $r51Worker)
        $r51wlAfterU = Get-R5xGit -Root $r51cRoot -GitArgs @('worktree', 'list', '--porcelain')
        $r51brU = Get-R5xGit -Root $r51cRoot -GitArgs @('rev-parse', '--verify', '--quiet', "refs/heads/worktree-wt-$r51IdU")
        $r51recU = Join-Path $r51cRoot ".mission-runtime\evidence\session-$r51IdU\$r51IdU.started"
        $r51bytesU = [System.Text.Encoding]::UTF8.GetByteCount($r51TreeU)
        $r51namesU = [bool](($r51cU.out -match 'is 216 bytes in UTF-8 \(215 characters') -and ($r51cU.out -match '216 bytes or more'))
        $r51untouchedU = (($r51wlBeforeU.exit -eq 0) -and ($r51wlAfterU.exit -eq 0) -and (($r51wlBeforeU.lines -join "`n") -eq ($r51wlAfterU.lines -join "`n")))
        $null = Assert-FixtureGitDir -Root $r51cRoot
        $r51gitU = Get-R5xGit -Root $r51cRoot -GitArgs @('worktree', 'add', '--detach', $r51TreeU, 'HEAD')
        if (Test-Path -LiteralPath $r51TreeU) { Remove-Item -LiteralPath $r51TreeU -Recurse -Force -ErrorAction SilentlyContinue }
        $null = Assert-FixtureGitDir -Root $r51cRoot
        $null = Get-R5xGit -Root $r51cRoot -GitArgs @('worktree', 'prune')
        # GIT'S CEILING'S OWN ANSWER, NOT ANY NON-ZERO EXIT (found in review). Measured at this length: exit 128,
        # "fatal: '$GIT_DIR' too big". THE GIT-LEVEL CONTROL: 'D-' + e-acute composes 214 characters and 215 bytes,
        # which git ACCEPTS (measured: exit 0); that tree is removed through git and pruned, the git dir asserted first.
        $r51gitUCeiling = (($r51gitU.exit -eq 128) -and ($r51gitU.said -match 'too big'))
        $r51IdU215    = 'D-' + [string][char]0x00E9
        $r51TreeU215  = Get-FixtureWorktreePath -Id $r51IdU215 -Root $r51cRoot
        $r51bytesU215 = [System.Text.Encoding]::UTF8.GetByteCount($r51TreeU215)
        $null = Assert-FixtureGitDir -Root $r51cRoot
        $r51gitU215   = Get-R5xGit -Root $r51cRoot -GitArgs @('worktree', 'add', '--detach', $r51TreeU215, 'HEAD')
        $r51madeU215  = Test-Path -LiteralPath (Join-Path $r51TreeU215 '.git') -PathType Leaf
        $null = Assert-FixtureGitDir -Root $r51cRoot
        $r51rmU215    = Get-R5xGit -Root $r51cRoot -GitArgs @('worktree', 'remove', '--force', $r51TreeU215)
        if (Test-Path -LiteralPath $r51TreeU215) { Remove-Item -LiteralPath $r51TreeU215 -Recurse -Force -ErrorAction SilentlyContinue }
        $null = Assert-FixtureGitDir -Root $r51cRoot
        $null = Get-R5xGit -Root $r51cRoot -GitArgs @('worktree', 'prune')
        $r51goneU215  = (-not (Test-Path -LiteralPath $r51TreeU215))
        $r51controlU  = (($r51TreeU215.Length -eq 214) -and ($r51bytesU215 -eq 215) -and ($r51gitU215.exit -eq 0) -and $r51madeU215 -and ($r51rmU215.exit -eq 0) -and $r51goneU215)
        $r51ok8 = (($r51TreeU.Length -eq 215) -and ($r51bytesU -eq 216) -and ($r51cU.exit -eq 2) -and $r51namesU -and (-not (Test-Path -LiteralPath $r51recU)) -and
                   ($r51brU.exit -ne 0) -and $r51untouchedU -and ($r51cU.out -notmatch 'WORKER-MARKER-OK') -and $r51gitUCeiling -and $r51controlU)
        $r51Rows += Format-R2xRow -Id '8 a non-ASCII 215-character, 216-byte path' -RowOk $r51ok8 `
            -Text ("path length={0} bytes={1} exit={2} refusal names 216 bytes and 215 characters={3} no run record={4} no branch={5} worktree list unchanged={6}; git worktree add at that path exit={7} says too big={8}; git control at {9} characters / {10} bytes: exit={11} tree made={12} removed through git exit={13} gone after prune={14}  (expect 215, 216, 2, True x4; 128, True; 214, 215, 0, True, 0, True)" -f `
                   $r51TreeU.Length, $r51bytesU, $r51cU.exit, $r51namesU, (-not (Test-Path -LiteralPath $r51recU)), ($r51brU.exit -ne 0), $r51untouchedU, $r51gitU.exit, [bool]($r51gitU.said -match 'too big'), $r51TreeU215.Length, $r51bytesU215, $r51gitU215.exit, $r51madeU215, $r51rmU215.exit, $r51goneU215) `
            -Said (Get-R28Said $r51cU.out)
        $r51Rows += ("        git at 216 bytes said: {0}" -f $(if ($r51gitU.said) { ($r51gitU.said -replace '\s+', ' ').Substring(0, [Math]::Min(160, ($r51gitU.said -replace '\s+', ' ').Length)) } else { '(nothing)' }))
        $r51Rows += ("        git control at 215 bytes said: {0}" -f $(if ($r51gitU215.said) { ($r51gitU215.said -replace '\s+', ' ').Substring(0, [Math]::Min(160, ($r51gitU215.said -replace '\s+', ' ').Length)) } else { '(nothing)' }))
    }
}
# ---- row 2: THE MAIN FIXTURE never grew a .claude/ ----------------------------------------------------
$r51mainClaude = Test-Path -LiteralPath (Join-Path $missionRoot '.claude')
$r51mainOld    = Test-Path -LiteralPath (Join-Path $missionRoot '.claude\worktrees')
$r51mainHome   = Test-Path -LiteralPath (Split-Path -Parent $wtRoot)
$r51ok2 = ((-not $r51mainClaude) -and (-not $r51mainOld) -and $r51mainHome)
$r51Rows += Format-R2xRow -Id '2 the main fixture, after every run above' -RowOk $r51ok2 `
    -Text ("<root>\.claude exists={0} <root>\.claude\worktrees exists={1} the sibling home exists={2}  (expect False, False, True -- R-9 and R-10 declare no '?? .claude/' on the strength of this)" -f $r51mainClaude, $r51mainOld, $r51mainHome) -Said ''
$r51detail = @"
    THE ROWS -- 1, 3, 4, 6, 7, 8, 9 and 10 drive the real runner; 5 and 8 ask real git at the same path; 2 reads the disk. Paths and exits read back from the disk and from git:
$($r51Rows -join "`n")
    fixture root : $r51Root   ($($r51Root.Length) characters)
    ceiling root : $r51cRoot   ($($r51cRoot.Length) characters; rows 4, 5, 6 and 8)
    longest path written under the ceiling root and its worktree home, after row 6: $r51cLongLen characters$(if ($r51cLongest.Count -gt 0) { "`n      $($r51cLongest[0])" })
    main fixture sibling home : $(Split-Path -Parent $wtRoot)
    WHAT THIS MEMBER DOES NOT CLAIM: that a real claude CLI honours its working directory as its tree. The stub proves the
      runner spawns its child IN the tree; the lead's single real spawn of CLI 2.1.258 (recorded in the runner's argv comment) is
      the evidence for the CLI, and WP-6 S-1 is where a live run is asserted.
"@
Check -Id 'R-51' -Title 'the runner creates each dispatch''s worktree beside the mission root at <leaf>-worktrees\wt-<id> and spawns the worker IN it: no --worktree in the argv, the worker''s own process cwd is the tree -- for a ''['' '']'' dispatch id too, where the plain Push-Location planted back runs it outside, and for its suite in such a tree, where the suite site''s plain Push-Location planted back does not run the suite there; a location read back that is not the tree refuses before the spawn with the run record closed -- the tree is listed once, unlocked, and resolved exactly (the old -like selection planted back names a listed-first sibling), nothing appears under <root>\.claude, a leafless root, a 216-byte path and a non-ASCII 215-character 216-byte path are refused before any worktree add (git itself answering ''$GIT_DIR'' too big at 216 bytes and accepting a non-ASCII 215-byte path), and 215 bytes still runs with every written path under 260 characters' `
      -Ok ($r51ok1 -and $r51ok2 -and $r51ok3 -and $r51ok4 -and $r51ok5 -and $r51ok6 -and $r51ok7 -and $r51ok8 -and $r51ok9 -and $r51ok10) -Detail $r51detail

# =============================================================================================
# R-52 -- THE RUNNER PLACES .worktreeinclude's IGNORED ENTRIES, AND NOTHING ELSE (LAM-ACCEPT WP-5 K-2)
# =============================================================================================
# With --worktree gone, nothing but the runner copies what .worktreeinclude names into a tree -- and
# the entry that matters most is the ignored .claude/, without which a worker has no evidence plane.
# The rule the runner implements: a file is placed iff it is untracked AND ignored in the mission root
# AND matched by .worktreeinclude; a directory entry, anything under a directory holding a .git entry,
# and anything committed at the tree's HEAD are never copied.
#
# THE FIXTURE IS THE REAL SHAPE IN MINIATURE. The main checkout's .claude/ holds settings next to
# .claude/worktrees/ full of linked worktrees; this one holds a settings.json and a hook script, a
# LINKED WORKTREE of the fixture under .claude/worktrees/n (a file inside it), and a NESTED REPOSITORY
# at .claude/nested (a file inside it). .mission/contract/c.yaml is TRACKED and listed, and its working
# copy is made DIVERGENT from its base; r52-plain.txt is listed but NOT ignored.
#   1 FIRES   -- the two ignored files are placed byte-equal; the linked worktree's file, the nested
#                repository's file and the not-ignored file are absent from the tree; the tracked entry
#                in the tree is still its BASE content; the runner names the count; the worker ran. (The
#                tracked c.yaml is in NEITHER ls-files list, so this row never reaches the runner's
#                "committed at the tree's HEAD" exclusion -- measured: that exclusion planted out left it green.
#                Row 6 is the row that reaches it; found in review.)
#   2 KILL    -- a planted short copy (the copy loop skips one planned file) fails the dispatch CLOSED:
#                rc 2 naming the shortfall, the worker never spawned, and the run record reads finished.
#   3 ABSENT  -- no .worktreeinclude: the dispatch proceeds and says, in one line, that nothing was placed.
#   4 A LINK IN A REUSED TREE (found in review) -- after row 1, tree A's placed .claude\hooks is replaced by a
#                junction to a directory outside every tree, and the same dispatch runs again, reusing the
#                tree: REFUSED naming the link, NOTHING written at the junction's target, the worker never
#                spawned, and the run record reads finished rc 2. (Measured on the uncured runner: exit 0,
#                and the file written through the junction.)
#   5 A LINK AMONG THE MISSION ROOT'S IGNORED ENTRIES (found in review) -- an ignored junction .claude\ext to a
#                directory outside the repository, whose file git lists as an ordinary ignored entry: NOT
#                placed, and named among the skipped entries; the two real files are still placed.
#   6 A DECLARED OLDER BASE TRACKS WHAT THE MISSION ROOT HAS SINCE UNTRACKED AND IGNORED, IN ANOTHER CASE
#                (found in review) -- base X tracks Cfg/app.json; HEAD untracks it, ignores cfg/, lists
#                cfg/ in .worktreeinclude, and on disk the directory is cfg with divergent bytes. The
#                dispatch declares X: the tree keeps its BASE bytes and the runner names the entry skipped
#                as committed at the tree's HEAD. THE KILL: the exclusion planted out through New-UncuredCopy overwrites the base
#                bytes. (Measured on the uncured runner, whose comparison was ordinal: the same overwrite,
#                from the case difference alone.)
#   7 A HARD LINK IN A REUSED TREE (found in review) -- tree A's placed .claude\settings.json is replaced by
#                a hard link to a file outside every tree, and the same dispatch runs again: exit 0, the
#                outside file KEEPS its bytes, and the tree's file carries the placed bytes as a file of its
#                own (fsutil lists one name for it). THE KILL: the pre-cure copy -- overwrite, and no delete
#                first -- planted back into a copy writes the placed bytes INTO the outside file. (Measured on
#                the runner before the cure: exit 0, 'placed 2', the outside file overwritten.)
#   8 THE EVIDENCE PLANE, CHECKED (found in review), in two fixtures of this row's own:
#                (a) '\r52j\m' -- the ROOT .claude is a junction to a directory holding settings.json and a hook,
#                and an ignored .mission/contract/c.txt is also listed: REFUSED, exit 2, naming
#                .claude\settings.json as skipped through a junction, c.txt placed (the plan was NOT empty),
#                the worker never spawned, the run record finished rc 2. (Measured on the runner before this
#                cure: exit 0, spawned, no .claude\settings.json in the tree.)
#                (b) '\r52n\m' -- .claude/settings.json is TRACKED; an ignored junction node_modules\pkg, pnpm's
#                layout, reaches a store holding pkg\.claude\x.json, and an ignored junction .claude\shared reaches
#                skill.md (the review's drive2 shape): exit 0, spawned, the tree holds its tracked settings.json,
#                neither linked file placed, both named as skipped. (Measured on that runner: REFUSED, 'planned
#                nothing ... has no .claude/', which was false.)
#                THE KILLS: round 2's condition -- plan empty and a link skip -- planted back in place of the
#                invariant spawns (a) with no settings.json and refuses (b); the invariant's "committed at the
#                tree's HEAD and unmodified" half planted out refuses (b).
#   9 AN UNCLASSIFIABLE SOURCE (found in review) -- a copy whose reparse-tag reader cannot compile, and
#                an ignored junction .claude\ext in the mission root (row 5's): exit 2, 'could not tell whether
#                the source', nothing placed in the fresh tree, the worker never spawned, the run record
#                finished rc 2.
#  10 AN UNCLASSIFIABLE DESTINATION (found in review) -- the same copy, tree A reused with its .claude\hooks
#                replaced by a junction (row 4's): exit 2, 'could not tell whether the destination', nothing
#                written at the junction's target, the worker never spawned, the run record finished rc 2.
#  11 A DESTINATION THAT CANNOT BE REMOVED (found in review) -- tree A reused, a STALE copy of its
#                hook written back at the destination row 10 removed, made READ-ONLY, and then (the attribute
#                cleared) HELD OPEN by this process for read with read-write sharing and no delete sharing: each
#                exit 2, 'could not remove the existing', the worker never spawned, the stale bytes untouched,
#                the run record finished rc 2. The second shape is the one an overwrite used to place; the
#                refusal is deliberate (the placement comment says why).
#  12 THE TRIGGER IS THE PATTERN (found in review) -- '\r52p\m' TRACKS .claude/settings.json at HEAD, committed
#                after the seed; the dispatch declares the SEED as its base, which predates it, and nothing is
#                ignored under .claude/ (an ignored .mission/contract/c.txt is): REFUSED, exit 2, saying the
#                mission root TRACKS it and naming the declared base, c.txt placed, the worker never spawned,
#                the run record finished rc 2. (Measured on the runner before this cure: exit 0,
#                spawned, no settings.json in the tree.) THE KILL: round 3's trigger -- an untracked, ignored
#                entry listed under .claude/ -- planted back spawns it with no settings.json.
#  13 COMMITTED MEANS AT THE TREE'S HEAD, AND PLACED MEANS BYTE-EQUAL (found in review) -- '\r52q\m', the main
#                checkout's shape (.claude/ ignored, settings.json untracked). (a) After a first dispatch, the worker
#                writes '{}' over its tree's settings.json and stages it with 'git add -f'; the same dispatch runs
#                again: exit 0, spawned, the tree holds the MISSION ROOT's bytes, placed afresh. (Measured on
#                that runner: exit 0, the tree holding '{}', skipped as tracked.) THE KILL: the tree's INDEX read
#                back as the committed list leaves the worker's '{}' in the tree. (b) A copy whose copy loop
#                alters one byte of the placed settings.json, keeping its length: REFUSED, exit 2, 'not
#                byte-equal', never spawned, run record finished rc 2. THE KILL: the byte comparison planted out
#                of the same copy spawns it.
#  14 A COMMITTED REGISTRATION MUST BE IN THE TREE, UNMODIFIED (found in review) -- '\r52r\m' COMMITS
#                settings.json and ignores nothing: a first dispatch spawns, the tree holding its committed file.
#                Deleted from the reused tree's disk: REFUSED, exit 2, 'committed at the tree's HEAD ... and absent
#                from the tree', never spawned, run record finished rc 2; THE KILL: the in-tree and unmodified
#                conjuncts planted out spawns it with no settings.json. Written back as '{}': REFUSED, exit 2,
#                'modified against HEAD', never spawned; THE KILL: the unmodified conjunct alone planted out
#                spawns it holding '{}'.
#  15 NO REGISTRATION ON THE MISSION ROOT'S DISK, NO CHECK (found in review; the ruling's "decide and state")
#                -- '\r52e\m'. (a) THE STATED RESIDUAL: a root .claude/ holding only an ignored notes.md, no
#                settings.json anywhere: exit 0, spawned, notes.md placed, no settings.json. (b) The mission root
#                COMMITS settings.json at HEAD but has deleted it from its own disk, and the dispatch declares the
#                seed, which predates it: exit 0, spawned, no settings.json -- DECIDED: with no registration on the
#                mission root's own disk there is none to carry. THE KILL, the Exists conjunct planted out: (a)
#                STILL spawns -- the pattern listing is empty when no settings.json is on disk or in the index, so
#                the conjunct is not what spares the residual -- while (b) is REFUSED, saying the mission root
#                TRACKS it; (b) is the shape the conjunct decides.
# The link test reads the reparse TAG (found in review): the junctions of rows 4, 5 and 8 are links by
# their tag. The NON-LINK-TAG BRANCH -- a cloud-files or WOF reparse point read as NOT a link -- cannot be
# fixtured without a sync provider (a WOF-compressed file hides its reparse attribute from user mode, which
# review round 3 measured), so no row here drives it: it is proven only by the read-only tag measurement of
# %USERPROFILE%\OneDrive\Documents (0x9000601A) recorded in the runner's comment above Get-FirstLinkOnPath.
# Rows 9 and 10 drive the reader's FAILURE branch instead, which fails closed.
# Every junction here points INSIDE this sandbox and is removed with `cmd /c rmdir` in a finally right after
# its row (New-R5xJunction / Remove-R5xJunction, above); row 7's hard links are two names inside the sandbox,
# and removing a name never touches the other's bytes. Row 11 clears the attribute and closes the handle in a
# finally.
$r52Base = Join-Path $sandbox 'r52'
$r52Root = Join-Path $r52Base 'm'
$r52Rows = @()
$r52SettingsRel = '.claude\settings.json'
$r52HookRel     = '.claude\hooks\r52-hook.ps1'
$r52Seed = New-R5xFixture -Root $r52Root -GitIgnore ".mission-runtime/`n.claude/`n" -Files ([ordered]@{
    '.worktreeinclude'          = "# R-52 fixture`n.claude/`n.mission/contract/`nr52-plain.txt`n"
    '.mission\contract\c.yaml'  = "contract: tracked at the base`n"
})
$r52ok1 = $false; $r52ok2 = $false; $r52ok3 = $false; $r52ok4 = $false; $r52ok5 = $false; $r52ok6 = $false; $r52ok7 = $false; $r52ok8 = $false; $r52ok9 = $false; $r52ok10 = $false; $r52ok11 = $false
$r52ok12 = $false; $r52ok13 = $false; $r52ok14 = $false; $r52ok15 = $false
if ($r52Seed.refusal -or (-not $r52Seed.head)) {
    $r52Rows += ("    the R-52 fixture was not seeded: {0}" -f $(if ($r52Seed.refusal) { $r52Seed.refusal } else { 'no HEAD after the seed commit' }))
} else {
    Write-Utf8 -Path (Join-Path $r52Root $r52SettingsRel) -Text "{`"r52`": `"the hook registration a worker needs`"}`n"
    Write-Utf8 -Path (Join-Path $r52Root $r52HookRel) -Text "Write-Output 'r52 hook'`nexit 0`n"
    Write-Utf8 -Path (Join-Path $r52Root '.mission\contract\c.yaml') -Text "contract: DIVERGENT working copy, never to reach the tree`n"
    Write-Utf8 -Path (Join-Path $r52Root 'r52-plain.txt') -Text "listed but not ignored`n"
    # The linked worktree, made by git from the verified root, and a file inside it.
    $null = Assert-FixtureGitDir -Root $r52Root
    $r52Linked = Join-Path $r52Root '.claude\worktrees\n'
    $r52la = Get-R5xGit -Root $r52Root -GitArgs @('worktree', 'add', '--detach', $r52Linked, 'HEAD')
    Write-Utf8 -Path (Join-Path $r52Linked 'inside-linked.txt') -Text "inside a linked worktree`n"
    # The nested repository, seeded through the same asserted sequence, and a file inside it.
    $r52Nested = Join-Path $r52Root '.claude\nested'
    New-Item -ItemType Directory -Path $r52Nested -Force | Out-Null
    $r52NestedRefusal = ''
    try { $null = Initialize-FixtureRepo -Root $r52Nested } catch { $r52NestedRefusal = $_.Exception.Message }
    Write-Utf8 -Path (Join-Path $r52Nested 'n.txt') -Text "inside a nested repository`n"
    $r52Shapes = ((Test-Path -LiteralPath (Join-Path $r52Linked '.git') -PathType Leaf) -and (Test-Path -LiteralPath (Join-Path $r52Nested '.git') -PathType Container) -and (-not $r52NestedRefusal))

    # ---- row 1: FIRES -----------------------------------------------------------------------------
    $r52IdA = 'D-R52A'
    $r52TreeA = Get-FixtureWorktreePath -Id $r52IdA -Root $r52Root
    Write-R5xDispatch -Root $r52Root -Id $r52IdA
    $r52r1 = Invoke-R5xRunner -RunnerPath $runner -Root $r52Root -Id $r52IdA -Extra @('-VerifyCommand', $verifyPass, '-WorkerCommand', $r51Worker)
    function Get-R52Sha { param([string]$PathText) if (Test-Path -LiteralPath $PathText -PathType Leaf) { (Get-FileHash -Algorithm SHA256 -LiteralPath $PathText).Hash.ToLowerInvariant() } else { '' } }
    $r52SetSrc = Get-R52Sha (Join-Path $r52Root $r52SettingsRel);  $r52SetDst = Get-R52Sha (Join-Path $r52TreeA $r52SettingsRel)
    $r52HookSrc = Get-R52Sha (Join-Path $r52Root $r52HookRel);     $r52HookDst = Get-R52Sha (Join-Path $r52TreeA $r52HookRel)
    $r52placedEq = ($r52SetSrc -and ($r52SetSrc -eq $r52SetDst) -and $r52HookSrc -and ($r52HookSrc -eq $r52HookDst))
    $r52noLinked = (-not (Test-Path -LiteralPath (Join-Path $r52TreeA '.claude\worktrees')))
    $r52noNested = (-not (Test-Path -LiteralPath (Join-Path $r52TreeA '.claude\nested')))
    $r52noPlain  = (-not (Test-Path -LiteralPath (Join-Path $r52TreeA 'r52-plain.txt')))
    $r52cPath    = Join-Path $r52TreeA '.mission\contract\c.yaml'
    $r52tracked  = if (Test-Path -LiteralPath $r52cPath) { [System.IO.File]::ReadAllText($r52cPath) } else { '(absent)' }
    $r52trackedOk = ($r52tracked -match 'tracked at the base') -and ($r52tracked -notmatch 'DIVERGENT')
    $r52says2    = [bool]($r52r1.out -match '\.worktreeinclude placed 2 ignored file\(s\)')
    $r52spawn1   = Test-Path -LiteralPath (Join-Path $r52TreeA 'worker-created.txt')
    $r52ok1 = ($r52Shapes -and ($r52la.exit -eq 0) -and ($r52r1.exit -eq 0) -and $r52spawn1 -and $r52placedEq -and $r52noLinked -and $r52noNested -and $r52noPlain -and $r52trackedOk -and $r52says2)
    $r52Rows += Format-R2xRow -Id '1 placement fires' -RowOk $r52ok1 `
        -Text ("fixture shapes real={0} exit={1} spawned={2} settings+hook byte-equal={3} linked worktree NOT copied={4} nested repository NOT copied={5} not-ignored file NOT copied={6} tracked entry still at its base={7} runner names 2 placed={8}  (expect True, 0, True x7)" -f `
               $r52Shapes, $r52r1.exit, $r52spawn1, $r52placedEq, $r52noLinked, $r52noNested, $r52noPlain, $r52trackedOk, $r52says2) `
        -Said (Get-R28Said $r52r1.out)

    # ---- row 2: THE PLANTED SHORT COPY ---------------------------------------------------------------
    $r52Copy = New-UncuredCopy -Name 'uncured52' `
        -CuredLine 'foreach ($wtiEntry in $wtiPlan) {' `
        -OldLine   'foreach ($wtiEntry in @($wtiPlan | Select-Object -Skip 1)) {'
    $r52IdB = 'D-R52B'
    $r52TreeB = Get-FixtureWorktreePath -Id $r52IdB -Root $r52Root
    Write-R5xDispatch -Root $r52Root -Id $r52IdB
    $r52Hook = Join-Path $r52Root '.git\hooks\pre-push'
    $r52HookSave = [System.IO.File]::ReadAllText($r52Hook)
    [System.IO.File]::WriteAllText($r52Hook, (Get-EvidencePrePushWrapperText -DeciderPath $r52Copy.decider), (New-Object System.Text.UTF8Encoding($false)))
    try { $r52r2 = Invoke-R5xRunner -RunnerPath $r52Copy.runner -Root $r52Root -Id $r52IdB -Extra @('-VerifyCommand', $verifyPass, '-WorkerCommand', $r51Worker) }
    finally { [System.IO.File]::WriteAllText($r52Hook, $r52HookSave, (New-Object System.Text.UTF8Encoding($false))) }
    $r52rr = Invoke-R5xRunner -RunnerPath $runner -Root $r52Root -Id $r52IdB -Extra @('-CheckRunRecord')
    $r52rrState = if ($r52rr.out -match '(?m)^run-record:\s*(\S+)') { $Matches[1] } else { '(unreadable)' }
    $r52rrRc    = if ($r52rr.out -match '(?m)^\s*rc\s*:\s*(\S+)') { $Matches[1] } else { '(unreadable)' }
    $r52short   = [bool]($r52r2.out -match 'copied 1 of 2 planned file')
    $r52spawn2  = Test-Path -LiteralPath (Join-Path $r52TreeB 'worker-created.txt')
    $r52ok2 = ($r52Copy.planted -and $r52Copy.parses -and ($r52r2.exit -eq 2) -and $r52short -and (-not $r52spawn2) -and ($r52r2.out -notmatch 'WORKER-MARKER-OK') -and ($r52rrState -eq 'finished') -and ($r52rrRc -eq '2'))
    $r52Rows += Format-R2xRow -Id '2 planted short copy' -RowOk $r52ok2 `
        -Text ("plant located={0} parses={1} exit={2} refusal names 1 of 2={3} worker spawned={4} run record={5} rc={6}  (expect True, True, 2, True, False, finished, 2 -- closed before the spawn)" -f `
               $r52Copy.planted, $r52Copy.parses, $r52r2.exit, $r52short, $r52spawn2, $r52rrState, $r52rrRc) `
        -Said (Get-R28Said $r52r2.out)

    # ---- row 3: NO .worktreeinclude ------------------------------------------------------------------
    $r52Include = Join-Path $r52Root '.worktreeinclude'
    $r52IncludeSave = [System.IO.File]::ReadAllText($r52Include)
    Remove-Item -LiteralPath $r52Include -Force
    $r52IdC = 'D-R52C'
    $r52TreeC = Get-FixtureWorktreePath -Id $r52IdC -Root $r52Root
    Write-R5xDispatch -Root $r52Root -Id $r52IdC
    try { $r52r3 = Invoke-R5xRunner -RunnerPath $runner -Root $r52Root -Id $r52IdC -Extra @('-VerifyCommand', $verifyPass, '-WorkerCommand', $r51Worker) }
    finally { [System.IO.File]::WriteAllText($r52Include, $r52IncludeSave, (New-Object System.Text.UTF8Encoding($false))) }
    $r52noneLine = @(@($r52r3.out -split "`n") | Where-Object { $_ -match 'no \.worktreeinclude at .* nothing was placed' })
    $r52spawn3   = Test-Path -LiteralPath (Join-Path $r52TreeC 'worker-created.txt')
    $r52noSet3   = (-not (Test-Path -LiteralPath (Join-Path $r52TreeC $r52SettingsRel)))
    $r52ok3 = (($r52r3.exit -eq 0) -and $r52spawn3 -and ($r52noneLine.Count -eq 1) -and $r52noSet3)
    $r52Rows += Format-R2xRow -Id '3 no .worktreeinclude' -RowOk $r52ok3 `
        -Text ("exit={0} spawned={1} the one 'nothing was placed' line={2} settings not in the tree={3}  (expect 0, True, 1, True)" -f $r52r3.exit, $r52spawn3, $r52noneLine.Count, $r52noSet3) `
        -Said (Get-R28Said $r52r3.out)

    # ---- row 4: A JUNCTION PLANTED IN A REUSED TREE (found in review) -------------------------------------------
    $r52Out4   = Join-Path $r52Base 'outside-f4'
    $r52HooksA = Join-Path $r52TreeA '.claude\hooks'
    New-Item -ItemType Directory -Path $r52Out4 -Force | Out-Null
    $r52j4 = $null; $r52r4 = $null; $r52unlinked4 = $false
    # The stub's marker goes to the runner's stream file, not to its stdout, so "not spawned" is read off the
    # disk: row 1's file is removed first, and a spawn would write it again.
    $r52Made4 = Join-Path $r52TreeA 'worker-created.txt'
    if (Test-Path -LiteralPath $r52Made4) { Remove-Item -LiteralPath $r52Made4 -Force }
    try {
        if (Test-Path -LiteralPath $r52HooksA) { Remove-Item -LiteralPath $r52HooksA -Recurse -Force }
        $r52j4 = New-R5xJunction -Link $r52HooksA -Target $r52Out4
        $r52r4 = Invoke-R5xRunner -RunnerPath $runner -Root $r52Root -Id $r52IdA -Extra @('-VerifyCommand', $verifyPass, '-WorkerCommand', $r51Worker)
    } finally { $r52unlinked4 = Remove-R5xJunction -Link $r52HooksA }
    $r52rr4 = Invoke-R5xRunner -RunnerPath $runner -Root $r52Root -Id $r52IdA -Extra @('-CheckRunRecord')
    $r52rr4State = if ($r52rr4.out -match '(?m)^run-record:\s*(\S+)') { $Matches[1] } else { '(unreadable)' }
    $r52rr4Rc    = if ($r52rr4.out -match '(?m)^\s*rc\s*:\s*(\S+)') { $Matches[1] } else { '(unreadable)' }
    $r52out4Items = @(Get-ChildItem -LiteralPath $r52Out4 -Force -ErrorAction SilentlyContinue)
    $r52names4 = [bool]($r52r4.out -match 'met a junction or symbolic link at .*\\\.claude\\hooks')
    $r52spawn4 = Test-Path -LiteralPath $r52Made4
    $r52ok4 = ($r52j4.isLink -and ($r52r4.exit -eq 2) -and $r52names4 -and ($r52out4Items.Count -eq 0) -and (-not $r52spawn4) -and ($r52rr4State -eq 'finished') -and ($r52rr4Rc -eq '2') -and $r52unlinked4)
    $r52Rows += Format-R2xRow -Id '4 a junction in a reused tree' -RowOk $r52ok4 `
        -Text ("junction made={0} exit={1} refusal names the link={2} entries written at the junction's target={3} worker spawned={4} run record={5} rc={6} junction removed={7}  (expect True, 2, True, 0, False, finished, 2, True)" -f `
               $r52j4.isLink, $r52r4.exit, $r52names4, $r52out4Items.Count, $r52spawn4, $r52rr4State, $r52rr4Rc, $r52unlinked4) `
        -Said (Get-R28Said $r52r4.out)

    # ---- row 5: A JUNCTION AMONG THE MISSION ROOT'S IGNORED ENTRIES (found in review) ---------------------------
    $r52Ext  = Join-Path $r52Root '.claude\ext'
    $r52Out5 = Join-Path $r52Base 'outside-f5'
    Write-Utf8 -Path (Join-Path $r52Out5 'secret.txt') -Text "outside the repository, reached only through a junction`n"
    $r52IdE   = 'D-R52E'
    $r52TreeE = Get-FixtureWorktreePath -Id $r52IdE -Root $r52Root
    Write-R5xDispatch -Root $r52Root -Id $r52IdE
    $r52j5 = $null; $r52r5 = $null; $r52ls5 = $null; $r52unlinked5 = $false
    try {
        $r52j5  = New-R5xJunction -Link $r52Ext -Target $r52Out5
        $r52ls5 = Get-R5xGit -Root $r52Root -GitArgs @('ls-files', '--others', '--ignored', '--exclude-standard')
        $r52r5  = Invoke-R5xRunner -RunnerPath $runner -Root $r52Root -Id $r52IdE -Extra @('-VerifyCommand', $verifyPass, '-WorkerCommand', $r51Worker)
    } finally { $r52unlinked5 = Remove-R5xJunction -Link $r52Ext }
    $r52listed5 = [bool](@($r52ls5.lines) -contains '.claude/ext/secret.txt')
    $r52placed5 = Test-Path -LiteralPath (Join-Path $r52TreeE '.claude\ext')
    $r52named5  = [bool]($r52r5.out -match 'skipped: \.claude/ext/secret\.txt \(its source passes through a junction or symbolic link')
    $r52says5   = [bool]($r52r5.out -match '\.worktreeinclude placed 2 ignored file\(s\)')
    $r52spawn5  = Test-Path -LiteralPath (Join-Path $r52TreeE 'worker-created.txt')
    $r52ok5 = ($r52j5.isLink -and $r52listed5 -and ($r52r5.exit -eq 0) -and $r52spawn5 -and (-not $r52placed5) -and $r52named5 -and $r52says5 -and $r52unlinked5)
    $r52Rows += Format-R2xRow -Id '5 a junction among the ignored entries' -RowOk $r52ok5 `
        -Text ("junction made={0} git lists its file as ignored={1} exit={2} spawned={3} placed in the tree={4} named as skipped={5} the two real files still placed={6} junction removed={7}  (expect True, True, 0, True, False, True, True, True)" -f `
               $r52j5.isLink, $r52listed5, $r52r5.exit, $r52spawn5, $r52placed5, $r52named5, $r52says5, $r52unlinked5) `
        -Said (Get-R28Said $r52r5.out)

    # ---- row 6: A DECLARED OLDER BASE TRACKS A PATH THE MISSION ROOT NOW IGNORES, IN ANOTHER CASE ------------
    $null = Assert-FixtureGitDir -Root $r52Root
    Write-Utf8 -Path (Join-Path $r52Root 'Cfg\app.json') -Text "BASE-TRACKED at the declared base`n"
    $null = Get-R5xGit -Root $r52Root -GitArgs @('add', 'Cfg/app.json')
    $null = Get-R5xGit -Root $r52Root -GitArgs @('commit', '-q', '-m', 'fixture: R-52 row 6, the base tracks Cfg/app.json')
    $r52xRev = Get-R5xGit -Root $r52Root -GitArgs @('rev-parse', 'HEAD')
    $r52X = if (($r52xRev.exit -eq 0) -and ($r52xRev.lines.Count -gt 0)) { $r52xRev.lines[0].Trim() } else { '' }
    $null = Get-R5xGit -Root $r52Root -GitArgs @('rm', '--cached', '-q', 'Cfg/app.json')
    [System.IO.File]::AppendAllText((Join-Path $r52Root '.gitignore'), "cfg/`n")
    [System.IO.File]::AppendAllText((Join-Path $r52Root '.worktreeinclude'), "cfg/`n")
    [System.IO.Directory]::Move((Join-Path $r52Root 'Cfg'), (Join-Path $r52Root 'cfg-r52-case'))
    [System.IO.Directory]::Move((Join-Path $r52Root 'cfg-r52-case'), (Join-Path $r52Root 'cfg'))
    Write-Utf8 -Path (Join-Path $r52Root 'cfg\app.json') -Text "ROOT-DIVERGENT working copy, never to reach the tree`n"
    $null = Get-R5xGit -Root $r52Root -GitArgs @('add', '.gitignore', '.worktreeinclude')
    $null = Get-R5xGit -Root $r52Root -GitArgs @('commit', '-q', '-m', 'fixture: R-52 row 6, HEAD untracks and ignores cfg/')
    $r52ls6 = Get-R5xGit -Root $r52Root -GitArgs @('ls-files', '--others', '--ignored', '--exclude-standard')
    $r52listed6 = [bool](@($r52ls6.lines) -ccontains 'cfg/app.json')
    $r52IdF   = 'D-R52F'
    $r52TreeF = Get-FixtureWorktreePath -Id $r52IdF -Root $r52Root
    Write-R5xDispatch -Root $r52Root -Id $r52IdF -Extra "base_head_at_authoring: $r52X`n"
    $r52r6 = Invoke-R5xRunner -RunnerPath $runner -Root $r52Root -Id $r52IdF -Extra @('-VerifyCommand', $verifyPass, '-WorkerCommand', $r51Worker)
    $r52tracks6 = [bool](@((Get-R5xGit -Root $r52TreeF -GitArgs @('ls-files', 'Cfg')).lines) -ccontains 'Cfg/app.json')
    $r52cfg6Path = Join-Path $r52TreeF 'Cfg\app.json'
    $r52cfg6 = if (Test-Path -LiteralPath $r52cfg6Path) { [System.IO.File]::ReadAllText($r52cfg6Path) } else { '(absent)' }
    $r52kept6  = (($r52cfg6 -match 'BASE-TRACKED') -and ($r52cfg6 -notmatch 'ROOT-DIVERGENT'))
    $r52named6 = [bool]($r52r6.out -match 'skipped: cfg/app\.json \(committed at the tree''s HEAD\)')
    $r52cut6   = [bool]($r52X -and ($r52r6.out -match ('worktree cut at the declared base_head_at_authoring ' + [regex]::Escape($r52X))))
    # THE KILL: the tracked-in-the-tree exclusion planted out.
    $r52Copy6 = New-UncuredCopy -Name 'uncured52t' -CuredLine 'if ($wtiTracked.Contains($wtiName)) {' -OldLine 'if ($false) {'
    $r52IdG   = 'D-R52G'
    $r52TreeG = Get-FixtureWorktreePath -Id $r52IdG -Root $r52Root
    Write-R5xDispatch -Root $r52Root -Id $r52IdG -Extra "base_head_at_authoring: $r52X`n"
    $r52r6k = Invoke-R5xWithDecider -Root $r52Root -Decider $r52Copy6.decider -Body { Invoke-R5xRunner -RunnerPath $r52Copy6.runner -Root $r52Root -Id $r52IdG -Extra @('-VerifyCommand', $verifyPass, '-WorkerCommand', $r51Worker) }
    $r52cfgKPath = Join-Path $r52TreeG 'Cfg\app.json'
    $r52cfgK = if (Test-Path -LiteralPath $r52cfgKPath) { [System.IO.File]::ReadAllText($r52cfgKPath) } else { '(absent)' }
    $r52killed6 = ($r52Copy6.planted -and $r52Copy6.parses -and ($r52cfgK -match 'ROOT-DIVERGENT'))
    $r52ok6 = ($r52X -and $r52listed6 -and ($r52r6.exit -eq 0) -and $r52cut6 -and $r52tracks6 -and $r52kept6 -and $r52named6 -and $r52killed6)
    $r52Rows += Format-R2xRow -Id '6 a declared base tracks a case-variant path' -RowOk $r52ok6 `
        -Text ("base X={0} the mission root lists cfg/app.json as ignored={1} exit={2} cut at X={3} the tree tracks Cfg/app.json={4} the tree keeps its BASE bytes={5} named as skipped, tracked={6}; exclusion planted out: located={7} parses={8} exit={9} base bytes overwritten={10}  (expect a sha, True, 0, True x4; True, True, 0, True -- the kill)" -f `
               $(if ($r52X) { $r52X.Substring(0, [Math]::Min(12, $r52X.Length)) } else { '(none)' }), $r52listed6, $r52r6.exit, $r52cut6, $r52tracks6, $r52kept6, $r52named6, $r52Copy6.planted, $r52Copy6.parses, $r52r6k.exit, $r52killed6) `
        -Said (Get-R28Said $r52r6.out)

    # ---- row 7: A HARD LINK PLANTED AT A DESTINATION IN A REUSED TREE (found in review) ---------------------
    $r52Victim7    = Join-Path $r52Base 'outside-g2\victim.txt'
    $r52VictimText = "OUTSIDE-THE-TREE ORIGINAL BYTES`n"
    $r52Set7       = Join-Path $r52TreeA $r52SettingsRel
    $r52Made7      = Join-Path $r52TreeA 'worker-created.txt'
    Write-Utf8 -Path $r52Victim7 -Text $r52VictimText
    if (Test-Path -LiteralPath $r52Set7) { Remove-Item -LiteralPath $r52Set7 -Force }
    $r52hl7 = New-R5xHardLink -Link $r52Set7 -Target $r52Victim7
    if (Test-Path -LiteralPath $r52Made7) { Remove-Item -LiteralPath $r52Made7 -Force }
    $r52r7 = Invoke-R5xRunner -RunnerPath $runner -Root $r52Root -Id $r52IdA -Extra @('-VerifyCommand', $verifyPass, '-WorkerCommand', $r51Worker)
    $r52kept7   = ([System.IO.File]::ReadAllText($r52Victim7) -ceq $r52VictimText)
    $r52placed7 = [bool]($r52SetSrc -and ((Get-R52Sha $r52Set7) -eq $r52SetSrc))
    $r52names7  = Get-R5xLinkNames -PathText $r52Set7
    $r52spawn7  = Test-Path -LiteralPath $r52Made7
    # THE KILL: the pre-cure shape, which spans two lines -- the copy WITH overwrite, and no delete before it.
    $r52Copy7 = New-UncuredCopy -Name 'uncured52hardlink' `
        -CuredLine '                [System.IO.File]::Copy($wtiEntry.src, $wtiEntry.dst, $false)' `
        -OldLine   '                [System.IO.File]::Copy($wtiEntry.src, $wtiEntry.dst, $true)'
    $r52Plant7b = ($r52Copy7.planted -and $r52Copy7.parses -and (Add-R5xSecondPlant -RunnerPath $r52Copy7.runner -CuredLine '            if ([System.IO.File]::Exists($wtiEntry.dst)) {' -OldLine '            if ($false) {'))
    Write-Utf8 -Path $r52Victim7 -Text $r52VictimText
    if (Test-Path -LiteralPath $r52Set7) { Remove-Item -LiteralPath $r52Set7 -Force }
    $r52hl7k = New-R5xHardLink -Link $r52Set7 -Target $r52Victim7
    $r52r7k = Invoke-R5xWithDecider -Root $r52Root -Decider $r52Copy7.decider -Body { Invoke-R5xRunner -RunnerPath $r52Copy7.runner -Root $r52Root -Id $r52IdA -Extra @('-VerifyCommand', $verifyPass, '-WorkerCommand', $r51Worker) }
    $r52through7k = [bool]($r52SetSrc -and ((Get-R52Sha $r52Victim7) -eq $r52SetSrc))
    $r52killed7 = ($r52Plant7b -and ($r52hl7k.exit -eq 0) -and ($r52hl7k.names -eq 2) -and $r52through7k)
    $r52ok7 = (($r52hl7.exit -eq 0) -and ($r52hl7.names -eq 2) -and ($r52r7.exit -eq 0) -and $r52spawn7 -and $r52kept7 -and $r52placed7 -and ($r52names7 -eq 1) -and $r52killed7)
    $r52Rows += Format-R2xRow -Id '7 a hard link in a reused tree' -RowOk $r52ok7 `
        -Text ("hard link made exit={0} names={1} exit={2} spawned={3} the outside file kept its bytes={4} the tree has the placed bytes={5} names of the tree's file now={6}; pre-cure copy (overwrite, no delete) planted back: located={7} relinked names={8} exit={9} the outside file received the placed bytes={10}  (expect 0, 2, 0, True, True, True, 1; True, 2, 0, True -- the kill)" -f `
               $r52hl7.exit, $r52hl7.names, $r52r7.exit, $r52spawn7, $r52kept7, $r52placed7, $r52names7, $r52Plant7b, $r52hl7k.names, $r52r7k.exit, $r52through7k) `
        -Said (Get-R28Said $r52r7.out)

    # ---- row 8: THE EVIDENCE PLANE, CHECKED (found in review) ---------------------------------------
    function Get-R52RunRecord {
        param([string]$Root, [string]$Id)
        $rr = Invoke-R5xRunner -RunnerPath $runner -Root $Root -Id $Id -Extra @('-CheckRunRecord')
        $state = if ($rr.out -match '(?m)^run-record:\s*(\S+)') { $Matches[1] } else { '(unreadable)' }
        $rc    = if ($rr.out -match '(?m)^\s*rc\s*:\s*(\S+)') { $Matches[1] } else { '(unreadable)' }
        return [pscustomobject]@{ state = $state; rc = $rc; closed2 = (($state -eq 'finished') -and ($rc -eq '2')) }
    }
    # THE KILL COPIES, one of each for both fixtures. K1: round 2's condition -- plan empty and a link skip -- planted
    # back in place of the invariant's, with a body that refuses (the invariant's own denial is empty where it holds).
    # K2: the invariant's "committed at the tree's HEAD and unmodified" half planted out.
    $r52Round2Cond = '        } elseif (($wtiPlan.Count -eq 0) -and (@($wtiSkipped | Where-Object { $_ -match ''its source passes through a junction or symbolic link'' }).Count -gt 0)) {'
    $r52Copy8k1  = New-UncuredCopy -Name 'uncured52round2' -CuredLine '        } elseif ($wtiEvidenceDenial) {' -OldLine $r52Round2Cond
    $r52Plant8k1 = ($r52Copy8k1.planted -and $r52Copy8k1.parses -and (Add-R5xSecondPlant -RunnerPath $r52Copy8k1.runner -CuredLine '            $includeDenial = $wtiEvidenceDenial' -OldLine '            $includeDenial = ''R-52 row 8 kill: the round-2 all-links refusal, planted back'''))
    $r52Copy8k2  = New-UncuredCopy -Name 'uncured52tracked' `
        -CuredLine '            $wtiEvidenceHeld = ($wtiEvidenceInTree -and ($wtiEvidenceSame -or ($wtiEvidenceCommitted -and ($wtiEvidenceDiffExit -eq 0))))' `
        -OldLine   '            $wtiEvidenceHeld = ($wtiEvidenceInTree -and $wtiEvidenceSame)'
    $r52Plant8k2 = ($r52Copy8k2.planted -and $r52Copy8k2.parses)

    # (a) A JUNCTIONED ROOT .claude/ BESIDE A PLANNED FILE.
    $r52aBase = Join-Path $sandbox 'r52j'
    $r52aRoot = Join-Path $r52aBase 'm'
    $r52aOut  = Join-Path $r52aBase 'outside-claude'
    Write-Utf8 -Path (Join-Path $r52aOut 'settings.json') -Text "{`"r52j`": `"a registration reached only through a junction`"}`n"
    Write-Utf8 -Path (Join-Path $r52aOut 'hooks\h.ps1') -Text "exit 0`n"
    $r52aSeed = New-R5xFixture -Root $r52aRoot -GitIgnore ".mission-runtime/`n.claude/`n.mission/contract/`n" -Files ([ordered]@{ '.worktreeinclude' = "# R-52 row 8 (a)`n.claude/`n.mission/contract/`n" })
    $r52aOk = $false; $r52aKilled = $false; $r52aText = '(the fixture was not seeded)'; $r52aSaid = ''
    if ((-not $r52aSeed.refusal) -and $r52aSeed.head) {
        Write-Utf8 -Path (Join-Path $r52aRoot '.mission\contract\c.txt') -Text "an ignored contract file, planned beside the junctioned .claude/`n"
        $r52aId   = 'D-R52J'
        $r52aTree = Get-FixtureWorktreePath -Id $r52aId -Root $r52aRoot
        $r52aMade = Join-Path $r52aTree 'worker-created.txt'
        Write-R5xDispatch -Root $r52aRoot -Id $r52aId
        $r52aJ = $null; $r52aLs = $null; $r52aRun = $null; $r52aRr = $null; $r52aRunK = $null; $r52aUnlinked = $false
        $r52aSpawn = $false; $r52aNoSet = $false; $r52aContract = $false; $r52aSpawnK = $false; $r52aNoSetK = $false
        try {
            $r52aJ   = New-R5xJunction -Link (Join-Path $r52aRoot '.claude') -Target $r52aOut
            $r52aLs  = Get-R5xGit -Root $r52aRoot -GitArgs @('ls-files', '--others', '--ignored', '--exclude-standard')
            $r52aRun = Invoke-R5xRunner -RunnerPath $runner -Root $r52aRoot -Id $r52aId -Extra @('-VerifyCommand', $verifyPass, '-WorkerCommand', $r51Worker)
            $r52aRr  = Get-R52RunRecord -Root $r52aRoot -Id $r52aId
            $r52aSpawn    = Test-Path -LiteralPath $r52aMade
            $r52aNoSet    = (-not (Test-Path -LiteralPath (Join-Path $r52aTree '.claude\settings.json')))
            $r52aContract = Test-Path -LiteralPath (Join-Path $r52aTree '.mission\contract\c.txt')
            $r52aRunK = Invoke-R5xWithDecider -Root $r52aRoot -Decider $r52Copy8k1.decider -Body { Invoke-R5xRunner -RunnerPath $r52Copy8k1.runner -Root $r52aRoot -Id $r52aId -Extra @('-VerifyCommand', $verifyPass, '-WorkerCommand', $r51Worker) }
            $r52aSpawnK = Test-Path -LiteralPath $r52aMade
            $r52aNoSetK = (-not (Test-Path -LiteralPath (Join-Path $r52aTree '.claude\settings.json')))
        } finally { $r52aUnlinked = Remove-R5xJunction -Link (Join-Path $r52aRoot '.claude') }
        $r52aListed = ((@($r52aLs.lines) -contains '.claude/settings.json') -and (@($r52aLs.lines) -contains '.mission/contract/c.txt'))
        $r52aNamed  = [bool]($r52aRun.out -match 'REFUSED -- the \.worktreeinclude placement cannot hand the tree .* its \.claude\\settings\.json: .*because the placement skipped it: \.claude/settings\.json \(its source passes through a junction or symbolic link at .*\\\.claude,')
        $r52aKilled = ($r52Plant8k1 -and ($r52aRunK.exit -eq 0) -and $r52aSpawnK -and $r52aNoSetK)
        $r52aOk = ($r52aJ.isLink -and $r52aListed -and ($r52aRun.exit -eq 2) -and $r52aNamed -and $r52aContract -and (-not $r52aSpawn) -and $r52aNoSet -and $r52aRr.closed2 -and $r52aUnlinked)
        $r52aText = ("(a) junctioned root .claude: junction made={0} git lists .claude/settings.json and c.txt={1} exit={2} refusal names settings.json skipped through the junction={3} c.txt placed, the plan not empty={4} worker spawned={5} settings.json absent from the tree={6} run record={7} rc={8} junction removed={9}; K1 round 2's condition planted back: located={10} exit={11} spawned={12} settings.json absent={13}  (expect True, True, 2, True, True, False, True, finished, 2, True; True, 0, True, True -- the kill)" -f `
                     $r52aJ.isLink, $r52aListed, $r52aRun.exit, $r52aNamed, $r52aContract, $r52aSpawn, $r52aNoSet, $r52aRr.state, $r52aRr.rc, $r52aUnlinked, $r52Plant8k1, $r52aRunK.exit, $r52aSpawnK, $r52aNoSetK)
        $r52aSaid = Get-R28Said $r52aRun.out
    }

    # (b) A TRACKED .claude/settings.json BESIDE LINK-SKIPPED ENTRIES: a pnpm-style node_modules junction and a junctioned .claude/shared.
    $r52bBase   = Join-Path $sandbox 'r52n'
    $r52bRoot   = Join-Path $r52bBase 'm'
    $r52bStore  = Join-Path $r52bBase 'store\pkg'
    $r52bShared = Join-Path $r52bBase 'shared'
    Write-Utf8 -Path (Join-Path $r52bStore '.claude\x.json') -Text "{`"pkg`": `"a package's own .claude file, in a store`"}`n"
    Write-Utf8 -Path (Join-Path $r52bStore 'index.js') -Text "module.exports = 1`n"
    Write-Utf8 -Path (Join-Path $r52bShared 'skill.md') -Text "a shared skill, reached through a junction`n"
    $r52bSeed = New-R5xFixture -Root $r52bRoot -GitIgnore ".mission-runtime/`nnode_modules/`n.claude/shared/`n" -Files ([ordered]@{ '.worktreeinclude' = "# R-52 row 8 (b)`n.claude/`n"; '.claude\settings.json' = "{`"r52n`": `"the TRACKED registration`"}`n" })
    $r52bOk = $false; $r52bKilled = $false; $r52bText = '(the fixture was not seeded)'; $r52bSaid = ''
    if ((-not $r52bSeed.refusal) -and $r52bSeed.head) {
        New-Item -ItemType Directory -Path (Join-Path $r52bRoot 'node_modules') -Force | Out-Null
        $r52bId   = 'D-R52N'
        $r52bTree = Get-FixtureWorktreePath -Id $r52bId -Root $r52bRoot
        $r52bMade = Join-Path $r52bTree 'worker-created.txt'
        Write-R5xDispatch -Root $r52bRoot -Id $r52bId
        $r52bJ1 = $null; $r52bJ2 = $null; $r52bTr = $null; $r52bLs = $null; $r52bRun = $null; $r52bRunK1 = $null; $r52bRunK2 = $null
        $r52bUnlinked1 = $false; $r52bUnlinked2 = $false
        $r52bSpawn = $false; $r52bSet = $false; $r52bNoX = $false; $r52bNoSkill = $false; $r52bSpawnK1 = $true; $r52bSpawnK2 = $true
        try {
            $r52bJ1  = New-R5xJunction -Link (Join-Path $r52bRoot 'node_modules\pkg') -Target $r52bStore
            $r52bJ2  = New-R5xJunction -Link (Join-Path $r52bRoot '.claude\shared') -Target $r52bShared
            $r52bTr  = Get-R5xGit -Root $r52bRoot -GitArgs @('ls-files', '.claude')
            $r52bLs  = Get-R5xGit -Root $r52bRoot -GitArgs @('ls-files', '--others', '--ignored', '--exclude-from=.worktreeinclude')
            $r52bRun = Invoke-R5xRunner -RunnerPath $runner -Root $r52bRoot -Id $r52bId -Extra @('-VerifyCommand', $verifyPass, '-WorkerCommand', $r51Worker)
            $r52bSpawn   = Test-Path -LiteralPath $r52bMade
            $r52bSet     = Test-Path -LiteralPath (Join-Path $r52bTree '.claude\settings.json') -PathType Leaf
            $r52bNoX     = (-not (Test-Path -LiteralPath (Join-Path $r52bTree 'node_modules\pkg\.claude\x.json')))
            $r52bNoSkill = (-not (Test-Path -LiteralPath (Join-Path $r52bTree '.claude\shared\skill.md')))
            if (Test-Path -LiteralPath $r52bMade) { Remove-Item -LiteralPath $r52bMade -Force }
            $r52bRunK1 = Invoke-R5xWithDecider -Root $r52bRoot -Decider $r52Copy8k1.decider -Body { Invoke-R5xRunner -RunnerPath $r52Copy8k1.runner -Root $r52bRoot -Id $r52bId -Extra @('-VerifyCommand', $verifyPass, '-WorkerCommand', $r51Worker) }
            $r52bSpawnK1 = Test-Path -LiteralPath $r52bMade
            if (Test-Path -LiteralPath $r52bMade) { Remove-Item -LiteralPath $r52bMade -Force }
            $r52bRunK2 = Invoke-R5xWithDecider -Root $r52bRoot -Decider $r52Copy8k2.decider -Body { Invoke-R5xRunner -RunnerPath $r52Copy8k2.runner -Root $r52bRoot -Id $r52bId -Extra @('-VerifyCommand', $verifyPass, '-WorkerCommand', $r51Worker) }
            $r52bSpawnK2 = Test-Path -LiteralPath $r52bMade
        } finally {
            $r52bUnlinked1 = Remove-R5xJunction -Link (Join-Path $r52bRoot 'node_modules\pkg')
            $r52bUnlinked2 = Remove-R5xJunction -Link (Join-Path $r52bRoot '.claude\shared')
        }
        $r52bTracked = [bool](@($r52bTr.lines) -contains '.claude/settings.json')
        $r52bListed  = ((@($r52bLs.lines) -contains 'node_modules/pkg/.claude/x.json') -and (@($r52bLs.lines) -contains '.claude/shared/skill.md'))
        $r52bNamed   = ([bool]($r52bRun.out -match 'skipped: node_modules/pkg/\.claude/x\.json \(its source passes through a junction or symbolic link') -and
                        [bool]($r52bRun.out -match 'skipped: \.claude/shared/skill\.md \(its source passes through a junction or symbolic link'))
        $r52bKilled  = ($r52Plant8k1 -and ($r52bRunK1.exit -eq 2) -and (-not $r52bSpawnK1) -and [bool]($r52bRunK1.out -match 'R-52 row 8 kill: the round-2 all-links refusal') -and
                        $r52Plant8k2 -and ($r52bRunK2.exit -eq 2) -and (-not $r52bSpawnK2) -and [bool]($r52bRunK2.out -match 'cannot hand the tree .* its \.claude\\settings\.json: .*committed at the tree''s HEAD'))
        $r52bOk = ($r52bJ1.isLink -and $r52bJ2.isLink -and $r52bTracked -and $r52bListed -and ($r52bRun.exit -eq 0) -and $r52bSpawn -and $r52bSet -and $r52bNoX -and $r52bNoSkill -and $r52bNamed -and $r52bUnlinked1 -and $r52bUnlinked2)
        $r52bText = ("(b) tracked settings.json beside link skips: junctions made={0},{1} settings.json tracked={2} git lists x.json and skill.md={3} exit={4} spawned={5} the tree holds settings.json={6} x.json NOT placed={7} skill.md NOT placed={8} both named as skipped through a link={9} junctions removed={10},{11}; K1 round 2's condition planted back: exit={12} spawned={13}; K2 'committed' half planted out: located={14} exit={15} spawned={16}  (expect True, True, True, True, 0, True x6, True, True; 2, False; True, 2, False -- the kills)" -f `
                     $r52bJ1.isLink, $r52bJ2.isLink, $r52bTracked, $r52bListed, $r52bRun.exit, $r52bSpawn, $r52bSet, $r52bNoX, $r52bNoSkill, $r52bNamed, $r52bUnlinked1, $r52bUnlinked2, $r52bRunK1.exit, $r52bSpawnK1, $r52Plant8k2, $r52bRunK2.exit, $r52bSpawnK2)
        $r52bSaid = Get-R28Said $r52bRun.out
    }
    $r52ok8 = ($r52aOk -and $r52aKilled -and $r52bOk -and $r52bKilled)
    $r52Rows += Format-R2xRow -Id '8 the evidence plane, checked (a)' -RowOk ($r52aOk -and $r52aKilled) -Text $r52aText -Said $r52aSaid
    $r52Rows += Format-R2xRow -Id '8 the evidence plane, checked (b)' -RowOk ($r52bOk -and $r52bKilled) -Text $r52bText -Said $r52bSaid

    # ---- row 9: AN UNCLASSIFIABLE SOURCE (found in review) ----------------------------------------------------
    # ONE PLANTED COPY for rows 9 and 10: its reparse-tag reader does not compile, so any entry carrying a reparse point is unclassifiable.
    $r52CopyTag = New-UncuredCopy -Name 'planted52tagcompile' `
        -CuredLine '        public static bool IsLinkTag(uint tag) { return (tag == 0xA0000003u) || (tag == 0xA000000Cu); }' `
        -OldLine   '        public static bool IsLinkTag(uint tag) { return R52_PLANTED_COMPILE_FAILURE; }'
    $r52IdK   = 'D-R52K'
    $r52TreeK = Get-FixtureWorktreePath -Id $r52IdK -Root $r52Root
    Write-R5xDispatch -Root $r52Root -Id $r52IdK
    $r52j9 = $null; $r52r9 = $null; $r52unlinked9 = $false
    try {
        $r52j9 = New-R5xJunction -Link $r52Ext -Target $r52Out5
        $r52r9 = Invoke-R5xWithDecider -Root $r52Root -Decider $r52CopyTag.decider -Body { Invoke-R5xRunner -RunnerPath $r52CopyTag.runner -Root $r52Root -Id $r52IdK -Extra @('-VerifyCommand', $verifyPass, '-WorkerCommand', $r51Worker) }
    } finally { $r52unlinked9 = Remove-R5xJunction -Link $r52Ext }
    $r52rr9 = Get-R52RunRecord -Root $r52Root -Id $r52IdK
    $r52names9   = [bool]($r52r9.out -match 'REFUSED -- the \.worktreeinclude placement could not tell whether the source of \.claude/ext/secret\.txt passes through a junction or symbolic link: .*\\\.claude\\ext \(it carries a reparse point, and the reparse-tag reader could not be compiled')
    $r52spawn9   = Test-Path -LiteralPath (Join-Path $r52TreeK 'worker-created.txt')
    $r52nothing9 = ((Test-Path -LiteralPath $r52TreeK) -and (-not (Test-Path -LiteralPath (Join-Path $r52TreeK '.claude'))))
    $r52ok9 = ($r52CopyTag.planted -and $r52CopyTag.parses -and $r52j9.isLink -and ($r52r9.exit -eq 2) -and $r52names9 -and (-not $r52spawn9) -and $r52nothing9 -and $r52rr9.closed2 -and $r52unlinked9)
    $r52Rows += Format-R2xRow -Id '9 an unclassifiable source' -RowOk $r52ok9 `
        -Text ("tag reader planted not to compile: located={0} parses={1}; junction .claude\ext made={2} exit={3} refusal names the source it could not classify={4} worker spawned={5} the tree exists with nothing placed={6} run record={7} rc={8} junction removed={9}  (expect True, True; True, 2, True, False, True, finished, 2, True)" -f `
               $r52CopyTag.planted, $r52CopyTag.parses, $r52j9.isLink, $r52r9.exit, $r52names9, $r52spawn9, $r52nothing9, $r52rr9.state, $r52rr9.rc, $r52unlinked9) `
        -Said (Get-R28Said $r52r9.out)

    # ---- row 10: AN UNCLASSIFIABLE DESTINATION (found in review) ------------------------------------------------
    $r52Out10  = Join-Path $r52Base 'outside-h4'
    New-Item -ItemType Directory -Path $r52Out10 -Force | Out-Null
    $r52Made10 = Join-Path $r52TreeA 'worker-created.txt'
    if (Test-Path -LiteralPath $r52Made10) { Remove-Item -LiteralPath $r52Made10 -Force }
    $r52j10 = $null; $r52r10 = $null; $r52unlinked10 = $false
    try {
        if (Test-Path -LiteralPath $r52HooksA) { Remove-Item -LiteralPath $r52HooksA -Recurse -Force }
        $r52j10 = New-R5xJunction -Link $r52HooksA -Target $r52Out10
        $r52r10 = Invoke-R5xWithDecider -Root $r52Root -Decider $r52CopyTag.decider -Body { Invoke-R5xRunner -RunnerPath $r52CopyTag.runner -Root $r52Root -Id $r52IdA -Extra @('-VerifyCommand', $verifyPass, '-WorkerCommand', $r51Worker) }
    } finally { $r52unlinked10 = Remove-R5xJunction -Link $r52HooksA }
    $r52rr10 = Get-R52RunRecord -Root $r52Root -Id $r52IdA
    $r52out10Items = @(Get-ChildItem -LiteralPath $r52Out10 -Force -ErrorAction SilentlyContinue)
    $r52names10 = [bool]($r52r10.out -match 'REFUSED -- the \.worktreeinclude placement could not tell whether the destination path of \.claude\\hooks\\r52-hook\.ps1 inside the tree .*\\\.claude\\hooks \(it carries a reparse point, and the reparse-tag reader could not be compiled')
    $r52spawn10 = Test-Path -LiteralPath $r52Made10
    $r52ok10 = ($r52CopyTag.planted -and $r52CopyTag.parses -and $r52j10.isLink -and ($r52r10.exit -eq 2) -and $r52names10 -and ($r52out10Items.Count -eq 0) -and (-not $r52spawn10) -and $r52rr10.closed2 -and $r52unlinked10)
    $r52Rows += Format-R2xRow -Id '10 an unclassifiable destination' -RowOk $r52ok10 `
        -Text ("the same planted copy, tree A reused: junction .claude\hooks made={0} exit={1} refusal names the destination it could not classify={2} entries written at the junction's target={3} worker spawned={4} run record={5} rc={6} junction removed={7}  (expect True, 2, True, 0, False, finished, 2, True)" -f `
               $r52j10.isLink, $r52r10.exit, $r52names10, $r52out10Items.Count, $r52spawn10, $r52rr10.state, $r52rr10.rc, $r52unlinked10) `
        -Said (Get-R28Said $r52r10.out)

    # ---- row 11: A DESTINATION THAT CANNOT BE REMOVED (found in review) -----------------------------------
    # Row 10 removed tree A's .claude\hooks, so the reused destination is written back here, with bytes the mission root's
    # copy does not have: a refusal that overwrote nothing leaves them exactly as they are.
    $r52Hook11      = Join-Path $r52TreeA $r52HookRel
    $r52Made11      = Join-Path $r52TreeA 'worker-created.txt'
    $r52Stale11Text = "Write-Output 'r52 hook, a STALE copy the refused placement must not touch'`nexit 0`n"
    Write-Utf8 -Path $r52Hook11 -Text $r52Stale11Text
    $r52Stale11 = Get-R52Sha $r52Hook11
    if (Test-Path -LiteralPath $r52Made11) { Remove-Item -LiteralPath $r52Made11 -Force }
    $r52ro11 = $false; $r52r11a = $null
    try {
        (Get-Item -LiteralPath $r52Hook11 -Force).IsReadOnly = $true
        $r52ro11 = (Get-Item -LiteralPath $r52Hook11 -Force).IsReadOnly
        $r52r11a = Invoke-R5xRunner -RunnerPath $runner -Root $r52Root -Id $r52IdA -Extra @('-VerifyCommand', $verifyPass, '-WorkerCommand', $r51Worker)
    } finally { (Get-Item -LiteralPath $r52Hook11 -Force).IsReadOnly = $false }
    $r52names11a = [bool]($r52r11a.out -match 'REFUSED -- the \.worktreeinclude placement could not remove the existing \.claude\\hooks\\r52-hook\.ps1 in the tree')
    $r52spawn11a = Test-Path -LiteralPath $r52Made11
    $r52kept11a  = ((Get-R52Sha $r52Hook11) -eq $r52Stale11)
    $r52rr11a    = Get-R52RunRecord -Root $r52Root -Id $r52IdA
    $r52fs11 = $null; $r52open11 = $false; $r52r11b = $null
    try {
        $r52fs11   = [System.IO.File]::Open($r52Hook11, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, [System.IO.FileShare]::ReadWrite)
        $r52open11 = $true
        $r52r11b   = Invoke-R5xRunner -RunnerPath $runner -Root $r52Root -Id $r52IdA -Extra @('-VerifyCommand', $verifyPass, '-WorkerCommand', $r51Worker)
    } finally { if ($r52fs11) { $r52fs11.Dispose() } }
    $r52names11b = [bool]($r52r11b.out -match 'REFUSED -- the \.worktreeinclude placement could not remove the existing \.claude\\hooks\\r52-hook\.ps1 in the tree')
    $r52spawn11b = Test-Path -LiteralPath $r52Made11
    $r52kept11b  = ((Get-R52Sha $r52Hook11) -eq $r52Stale11)
    $r52rr11b    = Get-R52RunRecord -Root $r52Root -Id $r52IdA
    $r52ok11 = ($r52Stale11 -and $r52ro11 -and ($r52r11a.exit -eq 2) -and $r52names11a -and (-not $r52spawn11a) -and $r52kept11a -and $r52rr11a.closed2 -and
                $r52open11 -and ($r52r11b.exit -eq 2) -and $r52names11b -and (-not $r52spawn11b) -and $r52kept11b -and $r52rr11b.closed2)
    $r52Rows += Format-R2xRow -Id '11 a destination that cannot be removed' -RowOk $r52ok11 `
        -Text ("tree A reused: READ-ONLY set={0} exit={1} refusal names the destination it could not remove={2} worker spawned={3} the stale bytes untouched={4} run record={5} rc={6}; HELD OPEN (read, read-write sharing, no delete) opened={7} exit={8} refusal names it={9} worker spawned={10} the stale bytes untouched={11} run record={12} rc={13}  (expect True, 2, True, False, True, finished, 2; True, 2, True, False, True, finished, 2)" -f `
               $r52ro11, $r52r11a.exit, $r52names11a, $r52spawn11a, $r52kept11a, $r52rr11a.state, $r52rr11a.rc, $r52open11, $r52r11b.exit, $r52names11b, $r52spawn11b, $r52kept11b, $r52rr11b.state, $r52rr11b.rc) `
        -Said (Get-R28Said $(if ($r52names11a) { $r52r11b.out } else { $r52r11a.out }))

    # ---- row 12: THE TRIGGER IS THE PATTERN (found in review) ----------------------------------------------------
    # THE KILL: round 3's trigger -- an untracked, ignored entry listed under the root .claude/ -- planted back in place of the pattern's.
    $r52Copy12k = New-UncuredCopy -Name 'uncured52trigger' `
        -CuredLine '        $wtiEvidenceApplies = ($wtiRootSettingsOnDisk -and ($wtiMatchNames.Count -gt 0))' `
        -OldLine   '        $wtiEvidenceApplies = ($wtiRootSettingsOnDisk -and (@($wtiListedNames | Where-Object { $wtiIgnored.Contains($_) -and $_.StartsWith(''.claude/'', [System.StringComparison]::OrdinalIgnoreCase) }).Count -gt 0))'
    $r52pBase = Join-Path $sandbox 'r52p'
    $r52pRoot = Join-Path $r52pBase 'm'
    $r52pSeed = New-R5xFixture -Root $r52pRoot -GitIgnore ".mission-runtime/`n.mission/contract/`n" -Files ([ordered]@{ '.worktreeinclude' = "# R-52 row 12`n.claude/`n.mission/contract/`n" })
    $r52pText = '(the fixture was not seeded)'; $r52pSaid = ''
    if ((-not $r52pSeed.refusal) -and $r52pSeed.head) {
        $null = Assert-FixtureGitDir -Root $r52pRoot
        Write-Utf8 -Path (Join-Path $r52pRoot $r52SettingsRel) -Text "{`"r52p`": `"the TRACKED registration, committed after the declared base`"}`n"
        $null = Get-R5xGit -Root $r52pRoot -GitArgs @('add', '.claude/settings.json')
        $null = Get-R5xGit -Root $r52pRoot -GitArgs @('commit', '-q', '-m', 'fixture: R-52 row 12, HEAD commits the registration')
        Write-Utf8 -Path (Join-Path $r52pRoot '.mission\contract\c.txt') -Text "an ignored contract file`n"
        $r52pAtHead  = [bool](@((Get-R5xGit -Root $r52pRoot -GitArgs @('ls-tree', '-r', '--name-only', 'HEAD')).lines) -contains '.claude/settings.json')
        $r52pIgnored = @((Get-R5xGit -Root $r52pRoot -GitArgs @('ls-files', '--others', '--ignored', '--exclude-standard')).lines)
        $r52pNoneIgn = ((@($r52pIgnored | Where-Object { $_ -like '.claude/*' }).Count -eq 0) -and (@($r52pIgnored) -contains '.mission/contract/c.txt'))
        $r52pId   = 'D-R52P'
        $r52pTree = Get-FixtureWorktreePath -Id $r52pId -Root $r52pRoot
        $r52pMade = Join-Path $r52pTree 'worker-created.txt'
        Write-R5xDispatch -Root $r52pRoot -Id $r52pId -Extra "base_head_at_authoring: $($r52pSeed.head)`n"
        $r52pRun    = Invoke-R5xRunner -RunnerPath $runner -Root $r52pRoot -Id $r52pId -Extra @('-VerifyCommand', $verifyPass, '-WorkerCommand', $r51Worker)
        $r52pRr     = Get-R52RunRecord -Root $r52pRoot -Id $r52pId
        $r52pSpawn  = Test-Path -LiteralPath $r52pMade
        $r52pNoSet  = (-not (Test-Path -LiteralPath (Join-Path $r52pTree $r52SettingsRel)))
        $r52pC      = Test-Path -LiteralPath (Join-Path $r52pTree '.mission\contract\c.txt')
        $r52pNamed  = [bool]($r52pRun.out -match ('REFUSED -- the \.worktreeinclude placement cannot hand the tree .* its \.claude\\settings\.json: .*the mission root TRACKS it, and it is not committed at the declared base_head_at_authoring ' + [regex]::Escape($r52pSeed.head)))
        $r52pRunK   = Invoke-R5xWithDecider -Root $r52pRoot -Decider $r52Copy12k.decider -Body { Invoke-R5xRunner -RunnerPath $r52Copy12k.runner -Root $r52pRoot -Id $r52pId -Extra @('-VerifyCommand', $verifyPass, '-WorkerCommand', $r51Worker) }
        $r52pSpawnK = Test-Path -LiteralPath $r52pMade
        $r52pNoSetK = (-not (Test-Path -LiteralPath (Join-Path $r52pTree $r52SettingsRel)))
        $r52pKilled = ($r52Copy12k.planted -and $r52Copy12k.parses -and ($r52pRunK.exit -eq 0) -and $r52pSpawnK -and $r52pNoSetK)
        $r52ok12 = ($r52pAtHead -and $r52pNoneIgn -and ($r52pRun.exit -eq 2) -and $r52pNamed -and $r52pC -and (-not $r52pSpawn) -and $r52pNoSet -and $r52pRr.closed2 -and $r52pKilled)
        $r52pText = ("HEAD commits settings.json={0} nothing ignored under .claude/ and c.txt ignored={1} exit={2} refusal says the mission root TRACKS it, naming the declared base={3} c.txt placed={4} worker spawned={5} settings.json absent={6} run record={7} rc={8}; round 3's trigger planted back: located={9} parses={10} exit={11} spawned={12} settings.json absent={13}  (expect True, True, 2, True, True, False, True, finished, 2; True, True, 0, True, True -- the kill)" -f `
                     $r52pAtHead, $r52pNoneIgn, $r52pRun.exit, $r52pNamed, $r52pC, $r52pSpawn, $r52pNoSet, $r52pRr.state, $r52pRr.rc, $r52Copy12k.planted, $r52Copy12k.parses, $r52pRunK.exit, $r52pSpawnK, $r52pNoSetK)
        $r52pSaid = Get-R28Said $r52pRun.out
    }
    $r52Rows += Format-R2xRow -Id '12 a tracked registration the base lacks' -RowOk $r52ok12 -Text $r52pText -Said $r52pSaid

    # ---- row 13: COMMITTED MEANS AT THE TREE'S HEAD, AND PLACED MEANS BYTE-EQUAL (found in review) ----------------
    # THE KILLS: (a) the tree's INDEX read back as its committed list; (b) the byte comparison planted out of a copy
    # whose copy loop already alters one byte of the placed settings.json (the same alteration drives (b) itself).
    $r52Copy13k = New-UncuredCopy -Name 'uncured52index' `
        -CuredLine '                $wtiTrackedOut  = @(& git -C $worktreePath ls-tree -r -z --name-only HEAD 2>&1)' `
        -OldLine   '                $wtiTrackedOut  = @(& git -C $worktreePath ls-files -z 2>&1)'
    $r52ByteCured = '                [System.IO.File]::Copy($wtiEntry.src, $wtiEntry.dst, $false)'
    $r52ByteOld   = '                [System.IO.File]::Copy($wtiEntry.src, $wtiEntry.dst, $false); if ($wtiEntry.rel -eq ''.claude\settings.json'') { $wtiPlantBytes = [System.IO.File]::ReadAllBytes($wtiEntry.dst); $wtiPlantBytes[0] = [byte](($wtiPlantBytes[0] + 1) % 256); [System.IO.File]::WriteAllBytes($wtiEntry.dst, $wtiPlantBytes) }'
    $r52Copy13b   = New-UncuredCopy -Name 'planted52bytes' -CuredLine $r52ByteCured -OldLine $r52ByteOld
    $r52Copy13bk  = New-UncuredCopy -Name 'uncured52bytes' -CuredLine $r52ByteCured -OldLine $r52ByteOld
    $r52Plant13bk = ($r52Copy13bk.planted -and $r52Copy13bk.parses -and (Add-R5xSecondPlant -RunnerPath $r52Copy13bk.runner `
        -CuredLine '            $wtiEvidenceHeld = ($wtiEvidenceInTree -and ($wtiEvidenceSame -or ($wtiEvidenceCommitted -and ($wtiEvidenceDiffExit -eq 0))))' `
        -OldLine   '            $wtiEvidenceHeld = ($wtiEvidenceInTree -and ($wtiEvidencePlanned -or ($wtiEvidenceCommitted -and ($wtiEvidenceDiffExit -eq 0))))'))
    $r52qBase = Join-Path $sandbox 'r52q'
    $r52qRoot = Join-Path $r52qBase 'm'
    $r52qSeed = New-R5xFixture -Root $r52qRoot -GitIgnore ".mission-runtime/`n.claude/`n" -Files ([ordered]@{ '.worktreeinclude' = "# R-52 row 13`n.claude/`n" })
    $r52qText = '(the fixture was not seeded)'; $r52qSaid = ''
    if ((-not $r52qSeed.refusal) -and $r52qSeed.head) {
        Write-Utf8 -Path (Join-Path $r52qRoot $r52SettingsRel) -Text "{`"r52q`": `"the MISSION ROOT registration`"}`n"
        $r52qRootSha = Get-R52Sha (Join-Path $r52qRoot $r52SettingsRel)
        $r52qId   = 'D-R52Q'
        $r52qTree = Get-FixtureWorktreePath -Id $r52qId -Root $r52qRoot
        $r52qSet  = Join-Path $r52qTree $r52SettingsRel
        $r52qMade = Join-Path $r52qTree 'worker-created.txt'
        Write-R5xDispatch -Root $r52qRoot -Id $r52qId
        $r52qRun1 = Invoke-R5xRunner -RunnerPath $runner -Root $r52qRoot -Id $r52qId -Extra @('-VerifyCommand', $verifyPass, '-WorkerCommand', $r51Worker)
        # (a) THE WORKER'S ACT, inside its own tree: '{}' over the registration, staged with 'git add -f', never committed.
        $r52qWorkerText = "{}`n"
        Write-Utf8 -Path $r52qSet -Text $r52qWorkerText
        $r52qWorkerSha = Get-R52Sha $r52qSet
        $null = Assert-FixtureGitDir -Root $r52qBase -From $r52qTree
        $r52qAdd    = Get-R5xGit -Root $r52qTree -GitArgs @('add', '-f', '.claude/settings.json')
        $r52qStaged = ((@((Get-R5xGit -Root $r52qTree -GitArgs @('ls-files', '.claude')).lines) -contains '.claude/settings.json') -and
                       (-not (@((Get-R5xGit -Root $r52qTree -GitArgs @('ls-tree', '-r', '--name-only', 'HEAD')).lines) -contains '.claude/settings.json')))
        if (Test-Path -LiteralPath $r52qMade) { Remove-Item -LiteralPath $r52qMade -Force }
        $r52qRun2       = Invoke-R5xRunner -RunnerPath $runner -Root $r52qRoot -Id $r52qId -Extra @('-VerifyCommand', $verifyPass, '-WorkerCommand', $r51Worker)
        $r52qSpawn2     = Test-Path -LiteralPath $r52qMade
        $r52qRootBytes2 = ((Get-R52Sha $r52qSet) -eq $r52qRootSha)
        $r52qSays2      = [bool]($r52qRun2.out -match '\.worktreeinclude placed 1 ignored file\(s\)')
        Write-Utf8 -Path $r52qSet -Text $r52qWorkerText
        if (Test-Path -LiteralPath $r52qMade) { Remove-Item -LiteralPath $r52qMade -Force }
        $r52qRunK   = Invoke-R5xWithDecider -Root $r52qRoot -Decider $r52Copy13k.decider -Body { Invoke-R5xRunner -RunnerPath $r52Copy13k.runner -Root $r52qRoot -Id $r52qId -Extra @('-VerifyCommand', $verifyPass, '-WorkerCommand', $r51Worker) }
        $r52qKeptK  = ((Get-R52Sha $r52qSet) -eq $r52qWorkerSha)
        $r52qKilled = ($r52Copy13k.planted -and $r52Copy13k.parses -and $r52qKeptK)
        $r52ok13a = (($r52qRun1.exit -eq 0) -and ($r52qAdd.exit -eq 0) -and $r52qStaged -and ($r52qRun2.exit -eq 0) -and $r52qSpawn2 -and $r52qRootBytes2 -and $r52qSays2 -and $r52qKilled)
        # (b) A PLACED COPY THAT IS NOT BYTE-EQUAL, in a fresh tree.
        $r52qIdB    = 'D-R52QB'
        $r52qTreeB  = Get-FixtureWorktreePath -Id $r52qIdB -Root $r52qRoot
        $r52qSetB   = Join-Path $r52qTreeB $r52SettingsRel
        $r52qMadeB  = Join-Path $r52qTreeB 'worker-created.txt'
        Write-R5xDispatch -Root $r52qRoot -Id $r52qIdB
        $r52qRunB   = Invoke-R5xWithDecider -Root $r52qRoot -Decider $r52Copy13b.decider -Body { Invoke-R5xRunner -RunnerPath $r52Copy13b.runner -Root $r52qRoot -Id $r52qIdB -Extra @('-VerifyCommand', $verifyPass, '-WorkerCommand', $r51Worker) }
        $r52qRrB    = Get-R52RunRecord -Root $r52qRoot -Id $r52qIdB
        $r52qSpawnB = Test-Path -LiteralPath $r52qMadeB
        $r52qNamedB = [bool]($r52qRunB.out -match 'REFUSED -- the \.worktreeinclude placement cannot hand the tree .* its \.claude\\settings\.json: .*it was placed by this run and, read back, is not byte-equal to the mission root''s')
        $r52qAltered = ((Test-Path -LiteralPath $r52qSetB -PathType Leaf) -and ((Get-R52Sha $r52qSetB) -ne $r52qRootSha) -and
                        ((Get-Item -LiteralPath $r52qSetB -Force).Length -eq (Get-Item -LiteralPath (Join-Path $r52qRoot $r52SettingsRel) -Force).Length))
        $r52qRunBK   = Invoke-R5xWithDecider -Root $r52qRoot -Decider $r52Copy13bk.decider -Body { Invoke-R5xRunner -RunnerPath $r52Copy13bk.runner -Root $r52qRoot -Id $r52qIdB -Extra @('-VerifyCommand', $verifyPass, '-WorkerCommand', $r51Worker) }
        $r52qSpawnBK = Test-Path -LiteralPath $r52qMadeB
        $r52qKilledB = ($r52Plant13bk -and ($r52qRunBK.exit -eq 0) -and $r52qSpawnBK)
        $r52ok13b = ($r52Copy13b.planted -and $r52Copy13b.parses -and ($r52qRunB.exit -eq 2) -and $r52qNamedB -and $r52qAltered -and (-not $r52qSpawnB) -and $r52qRrB.closed2 -and $r52qKilledB)
        $r52ok13 = ($r52ok13a -and $r52ok13b)
        $r52qText = ("(a) first dispatch exit={0}; the worker's '{{}}' staged exit={1}, in the index and not at HEAD={2}; re-dispatch exit={3} spawned={4} the tree holds the MISSION ROOT's bytes={5} runner names 1 placed={6}; the index read as committed, planted: located={7} exit={8} the worker's '{{}}' left in the tree={9}. (b) a byte-altering copy: located={10} exit={11} refusal says not byte-equal={12} the tree's copy differs at equal length={13} spawned={14} run record={15} rc={16}; the byte comparison planted out of it: located={17} exit={18} spawned={19}  (expect 0; 0, True; 0, True, True, True; True, 2, True. True, 2, True, True, False, finished, 2; True, 0, True -- the kills)" -f `
                     $r52qRun1.exit, $r52qAdd.exit, $r52qStaged, $r52qRun2.exit, $r52qSpawn2, $r52qRootBytes2, $r52qSays2, $r52Copy13k.planted, $r52qRunK.exit, $r52qKeptK,
                     $r52Copy13b.planted, $r52qRunB.exit, $r52qNamedB, $r52qAltered, $r52qSpawnB, $r52qRrB.state, $r52qRrB.rc, $r52Plant13bk, $r52qRunBK.exit, $r52qSpawnBK)
        $r52qSaid = Get-R28Said $(if (-not $r52ok13a) { $r52qRun2.out } else { $r52qRunB.out })
    }
    $r52Rows += Format-R2xRow -Id '13 committed at HEAD, placed byte-equal' -RowOk $r52ok13 -Text $r52qText -Said $r52qSaid

    # ---- row 14: A COMMITTED REGISTRATION MUST BE IN THE TREE, UNMODIFIED (found in review) ---------------------------
    # THE KILLS: the in-tree and unmodified conjuncts planted out together; the unmodified conjunct planted out alone.
    $r52Held14  = '            $wtiEvidenceHeld = ($wtiEvidenceInTree -and ($wtiEvidenceSame -or ($wtiEvidenceCommitted -and ($wtiEvidenceDiffExit -eq 0))))'
    $r52Copy14k = New-UncuredCopy -Name 'uncured52intree' -CuredLine $r52Held14 -OldLine '            $wtiEvidenceHeld = ($wtiEvidencePlanned -or $wtiEvidenceCommitted)'
    $r52Copy14m = New-UncuredCopy -Name 'uncured52diff' -CuredLine $r52Held14 -OldLine '            $wtiEvidenceHeld = ($wtiEvidenceInTree -and ($wtiEvidenceSame -or $wtiEvidenceCommitted))'
    $r52rBase = Join-Path $sandbox 'r52r'
    $r52rRoot = Join-Path $r52rBase 'm'
    $r52rSeed = New-R5xFixture -Root $r52rRoot -GitIgnore ".mission-runtime/`n" -Files ([ordered]@{ '.worktreeinclude' = "# R-52 row 14`n.claude/`n"; '.claude\settings.json' = "{`"r52r`": `"the COMMITTED registration`"}`n" })
    $r52rText = '(the fixture was not seeded)'; $r52rSaid = ''
    if ((-not $r52rSeed.refusal) -and $r52rSeed.head) {
        $r52rId   = 'D-R52R'
        $r52rTree = Get-FixtureWorktreePath -Id $r52rId -Root $r52rRoot
        $r52rSet  = Join-Path $r52rTree $r52SettingsRel
        $r52rMade = Join-Path $r52rTree 'worker-created.txt'
        $r52rAtAt = '.*it is committed at the tree''s HEAD ' + [regex]::Escape($r52rSeed.head)
        Write-R5xDispatch -Root $r52rRoot -Id $r52rId
        $r52rRun1   = Invoke-R5xRunner -RunnerPath $runner -Root $r52rRoot -Id $r52rId -Extra @('-VerifyCommand', $verifyPass, '-WorkerCommand', $r51Worker)
        $r52rSpawn1 = Test-Path -LiteralPath $r52rMade
        $r52rHas1   = Test-Path -LiteralPath $r52rSet -PathType Leaf
        $r52rNone1  = [bool]($r52rRun1.out -match '\.worktreeinclude placed 0 ignored file\(s\)')
        # DELETED FROM THE REUSED TREE'S DISK.
        Remove-Item -LiteralPath $r52rSet -Force
        if (Test-Path -LiteralPath $r52rMade) { Remove-Item -LiteralPath $r52rMade -Force }
        $r52rRun2    = Invoke-R5xRunner -RunnerPath $runner -Root $r52rRoot -Id $r52rId -Extra @('-VerifyCommand', $verifyPass, '-WorkerCommand', $r51Worker)
        $r52rRr2     = Get-R52RunRecord -Root $r52rRoot -Id $r52rId
        $r52rSpawn2  = Test-Path -LiteralPath $r52rMade
        $r52rNamed2  = [bool]($r52rRun2.out -match ('REFUSED -- the \.worktreeinclude placement cannot hand the tree .* its \.claude\\settings\.json: ' + $r52rAtAt + ' and absent from the tree'))
        $r52rRunK2   = Invoke-R5xWithDecider -Root $r52rRoot -Decider $r52Copy14k.decider -Body { Invoke-R5xRunner -RunnerPath $r52Copy14k.runner -Root $r52rRoot -Id $r52rId -Extra @('-VerifyCommand', $verifyPass, '-WorkerCommand', $r51Worker) }
        $r52rSpawnK2 = Test-Path -LiteralPath $r52rMade
        $r52rNoSetK2 = (-not (Test-Path -LiteralPath $r52rSet))
        $r52rKilled2 = ($r52Copy14k.planted -and $r52Copy14k.parses -and ($r52rRunK2.exit -eq 0) -and $r52rSpawnK2 -and $r52rNoSetK2)
        # WRITTEN BACK MODIFIED.
        Write-Utf8 -Path $r52rSet -Text "{}`n"
        if (Test-Path -LiteralPath $r52rMade) { Remove-Item -LiteralPath $r52rMade -Force }
        $r52rRun3    = Invoke-R5xRunner -RunnerPath $runner -Root $r52rRoot -Id $r52rId -Extra @('-VerifyCommand', $verifyPass, '-WorkerCommand', $r51Worker)
        $r52rRr3     = Get-R52RunRecord -Root $r52rRoot -Id $r52rId
        $r52rSpawn3  = Test-Path -LiteralPath $r52rMade
        $r52rNamed3  = [bool]($r52rRun3.out -match ('REFUSED -- the \.worktreeinclude placement cannot hand the tree .* its \.claude\\settings\.json: ' + $r52rAtAt + ' and the tree''s working file is modified against HEAD'))
        $r52rRunK3   = Invoke-R5xWithDecider -Root $r52rRoot -Decider $r52Copy14m.decider -Body { Invoke-R5xRunner -RunnerPath $r52Copy14m.runner -Root $r52rRoot -Id $r52rId -Extra @('-VerifyCommand', $verifyPass, '-WorkerCommand', $r51Worker) }
        $r52rSpawnK3 = Test-Path -LiteralPath $r52rMade
        $r52rKeptK3  = ((Test-Path -LiteralPath $r52rSet -PathType Leaf) -and ([System.IO.File]::ReadAllText($r52rSet).Trim() -ceq '{}'))
        $r52rKilled3 = ($r52Copy14m.planted -and $r52Copy14m.parses -and ($r52rRunK3.exit -eq 0) -and $r52rSpawnK3 -and $r52rKeptK3)
        $r52ok14 = (($r52rRun1.exit -eq 0) -and $r52rSpawn1 -and $r52rHas1 -and $r52rNone1 -and
                    ($r52rRun2.exit -eq 2) -and $r52rNamed2 -and (-not $r52rSpawn2) -and $r52rRr2.closed2 -and $r52rKilled2 -and
                    ($r52rRun3.exit -eq 2) -and $r52rNamed3 -and (-not $r52rSpawn3) -and $r52rRr3.closed2 -and $r52rKilled3)
        $r52rText = ("first dispatch exit={0} spawned={1} the tree holds its committed file={2} runner names 0 placed={3}; DELETED from the reused tree: exit={4} refusal says committed at the tree's HEAD and absent={5} spawned={6} run record={7} rc={8}; in-tree and unmodified conjuncts planted out: located={9} exit={10} spawned={11} settings.json absent={12}; MODIFIED: exit={13} refusal says modified against HEAD={14} spawned={15} run record={16} rc={17}; the unmodified conjunct planted out: located={18} exit={19} spawned={20} the tree holds '{{}}'={21}  (expect 0, True, True, True; 2, True, False, finished, 2; True, 0, True, True; 2, True, False, finished, 2; True, 0, True, True -- the kills)" -f `
                     $r52rRun1.exit, $r52rSpawn1, $r52rHas1, $r52rNone1, $r52rRun2.exit, $r52rNamed2, $r52rSpawn2, $r52rRr2.state, $r52rRr2.rc, $r52Copy14k.planted, $r52rRunK2.exit, $r52rSpawnK2, $r52rNoSetK2,
                     $r52rRun3.exit, $r52rNamed3, $r52rSpawn3, $r52rRr3.state, $r52rRr3.rc, $r52Copy14m.planted, $r52rRunK3.exit, $r52rSpawnK3, $r52rKeptK3)
        $r52rSaid = Get-R28Said $(if (-not $r52rNamed2) { $r52rRun2.out } else { $r52rRun3.out })
    }
    $r52Rows += Format-R2xRow -Id '14 committed, then deleted or modified' -RowOk $r52ok14 -Text $r52rText -Said $r52rSaid

    # ---- row 15: NO REGISTRATION ON THE MISSION ROOT'S DISK, NO CHECK (found in review) --------------------------------
    # THE KILL: the Exists conjunct planted out -- the mission root is taken to have the file on disk whether or not it does.
    $r52Copy15k = New-UncuredCopy -Name 'uncured52exists' `
        -CuredLine '$wtiRootSettingsOnDisk = [System.IO.File]::Exists($wtiRootSettings)' `
        -OldLine   '$wtiRootSettingsOnDisk = $true'
    $r52eBase = Join-Path $sandbox 'r52e'
    $r52eRoot = Join-Path $r52eBase 'm'
    $r52eSeed = New-R5xFixture -Root $r52eRoot -GitIgnore ".mission-runtime/`n.claude/`n" -Files ([ordered]@{ '.worktreeinclude' = "# R-52 row 15`n.claude/`n" })
    $r52eText = '(the fixture was not seeded)'; $r52eSaid = ''
    if ((-not $r52eSeed.refusal) -and $r52eSeed.head) {
        Write-Utf8 -Path (Join-Path $r52eRoot '.claude\notes.md') -Text "notes, and no settings.json`n"
        # (a) THE STATED RESIDUAL: a root .claude/ with no settings.json on disk or in the index.
        $r52eIdA   = 'D-R52EA'
        $r52eTreeA = Get-FixtureWorktreePath -Id $r52eIdA -Root $r52eRoot
        $r52eMadeA = Join-Path $r52eTreeA 'worker-created.txt'
        Write-R5xDispatch -Root $r52eRoot -Id $r52eIdA
        $r52eRunA   = Invoke-R5xRunner -RunnerPath $runner -Root $r52eRoot -Id $r52eIdA -Extra @('-VerifyCommand', $verifyPass, '-WorkerCommand', $r51Worker)
        $r52eSpawnA = Test-Path -LiteralPath $r52eMadeA
        $r52eNotesA = Test-Path -LiteralPath (Join-Path $r52eTreeA '.claude\notes.md') -PathType Leaf
        $r52eNoSetA = (-not (Test-Path -LiteralPath (Join-Path $r52eTreeA $r52SettingsRel)))
        if (Test-Path -LiteralPath $r52eMadeA) { Remove-Item -LiteralPath $r52eMadeA -Force }
        $r52eRunAK   = Invoke-R5xWithDecider -Root $r52eRoot -Decider $r52Copy15k.decider -Body { Invoke-R5xRunner -RunnerPath $r52Copy15k.runner -Root $r52eRoot -Id $r52eIdA -Extra @('-VerifyCommand', $verifyPass, '-WorkerCommand', $r51Worker) }
        $r52eSpawnAK = Test-Path -LiteralPath $r52eMadeA
        # (b) THE MISSION ROOT COMMITS THE REGISTRATION, THEN DELETES IT FROM ITS OWN DISK; the dispatch declares the seed.
        $null = Assert-FixtureGitDir -Root $r52eRoot
        Write-Utf8 -Path (Join-Path $r52eRoot $r52SettingsRel) -Text "{`"r52e`": `"committed, then deleted from the mission root's disk`"}`n"
        $null = Get-R5xGit -Root $r52eRoot -GitArgs @('add', '-f', '.claude/settings.json')
        $null = Get-R5xGit -Root $r52eRoot -GitArgs @('commit', '-q', '-m', 'fixture: R-52 row 15, HEAD commits the registration')
        Remove-Item -LiteralPath (Join-Path $r52eRoot $r52SettingsRel) -Force
        $r52eIndexed = ((@((Get-R5xGit -Root $r52eRoot -GitArgs @('ls-files', '.claude')).lines) -contains '.claude/settings.json') -and (-not (Test-Path -LiteralPath (Join-Path $r52eRoot $r52SettingsRel))))
        $r52eIdB   = 'D-R52EB'
        $r52eTreeB = Get-FixtureWorktreePath -Id $r52eIdB -Root $r52eRoot
        $r52eMadeB = Join-Path $r52eTreeB 'worker-created.txt'
        Write-R5xDispatch -Root $r52eRoot -Id $r52eIdB -Extra "base_head_at_authoring: $($r52eSeed.head)`n"
        $r52eRunB   = Invoke-R5xRunner -RunnerPath $runner -Root $r52eRoot -Id $r52eIdB -Extra @('-VerifyCommand', $verifyPass, '-WorkerCommand', $r51Worker)
        $r52eSpawnB = Test-Path -LiteralPath $r52eMadeB
        $r52eNoSetB = (-not (Test-Path -LiteralPath (Join-Path $r52eTreeB $r52SettingsRel)))
        if (Test-Path -LiteralPath $r52eMadeB) { Remove-Item -LiteralPath $r52eMadeB -Force }
        $r52eRunBK   = Invoke-R5xWithDecider -Root $r52eRoot -Decider $r52Copy15k.decider -Body { Invoke-R5xRunner -RunnerPath $r52Copy15k.runner -Root $r52eRoot -Id $r52eIdB -Extra @('-VerifyCommand', $verifyPass, '-WorkerCommand', $r51Worker) }
        $r52eRrBK    = Get-R52RunRecord -Root $r52eRoot -Id $r52eIdB
        $r52eSpawnBK = Test-Path -LiteralPath $r52eMadeB
        $r52eNamedBK = [bool]($r52eRunBK.out -match ('REFUSED -- the \.worktreeinclude placement cannot hand the tree .* its \.claude\\settings\.json: .*the mission root TRACKS it, and it is not committed at the declared base_head_at_authoring ' + [regex]::Escape($r52eSeed.head)))
        $r52eKilled  = ($r52Copy15k.planted -and $r52Copy15k.parses -and ($r52eRunAK.exit -eq 0) -and $r52eSpawnAK -and ($r52eRunBK.exit -eq 2) -and (-not $r52eSpawnBK) -and $r52eNamedBK -and $r52eRrBK.closed2)
        $r52ok15 = (($r52eRunA.exit -eq 0) -and $r52eSpawnA -and $r52eNotesA -and $r52eNoSetA -and $r52eIndexed -and ($r52eRunB.exit -eq 0) -and $r52eSpawnB -and $r52eNoSetB -and $r52eKilled)
        $r52eText = ("(a) a root .claude/ with notes.md only: exit={0} spawned={1} notes.md placed={2} settings.json absent={3}; (b) HEAD commits settings.json, the mission root's disk lacks it={4}, base = the seed: exit={5} spawned={6} settings.json absent={7}; the Exists conjunct planted out: located={8} parses={9} (a) exit={10} spawned={11} (expected not refused: its pattern listing is empty) (b) exit={12} spawned={13} refusal says the mission root TRACKS it={14} run record={15} rc={16}  (expect 0, True, True, True; True, 0, True, True; True, True, 0, True, 2, False, True, finished, 2 -- the kill)" -f `
                     $r52eRunA.exit, $r52eSpawnA, $r52eNotesA, $r52eNoSetA, $r52eIndexed, $r52eRunB.exit, $r52eSpawnB, $r52eNoSetB, $r52Copy15k.planted, $r52Copy15k.parses, $r52eRunAK.exit, $r52eSpawnAK, $r52eRunBK.exit, $r52eSpawnBK, $r52eNamedBK, $r52eRrBK.state, $r52eRrBK.rc)
        $r52eSaid = Get-R28Said $(if ($r52eRunB.exit -ne 0) { $r52eRunB.out } else { $r52eRunBK.out })
    }
    $r52Rows += Format-R2xRow -Id '15 no registration on the root''s disk' -RowOk $r52ok15 -Text $r52eText -Said $r52eSaid
}
$r52detail = @"
    THE FIFTEEN ROWS, each a real runner in this member's own fixture, the files read back off the disk:
$($r52Rows -join "`n")
    fixture root : $r52Root   (row 8: $(Join-Path $sandbox 'r52j\m') and $(Join-Path $sandbox 'r52n\m'); rows 12-15: $(Join-Path $sandbox 'r52p\m'), $(Join-Path $sandbox 'r52q\m'), $(Join-Path $sandbox 'r52r\m') and $(Join-Path $sandbox 'r52e\m'))
    WHAT THIS MEMBER DOES NOT CLAIM: which names .worktreeinclude SHOULD carry (that is K-2 in WP-5); that a real CLI's hooks
      fire from the placed .claude/ (the lead's single real spawn is the evidence for that, not this stub).
"@
Check -Id 'R-52' -Title 'the runner places into the tree exactly the files .worktreeinclude names that are untracked and ignored in the mission root -- byte-equal, never a linked worktree''s or a nested repository''s files, never a file reached through a junction (skipped and named), never over an entry committed at the tree''s HEAD even when only its case differs (the exclusion planted out overwrites) -- a short copy, or a junction on a destination inside a reused tree, fails the dispatch closed before the spawn with the run record closed and nothing written through the link, a hard link left at a destination in a reused tree is broken and never written through (the pre-cure overwrite planted back writes through it), a tree that does not hold .claude/settings.json -- placed by this run and byte-equal, or committed at the tree''s HEAD and unmodified -- where the mission root has it on disk and .worktreeinclude''s patterns match it, tracked or not, is refused (a junctioned root .claude/ beside a planned file; a registration the mission root tracks and the declared base lacks, with nothing ignored under .claude/, which round 3''s trigger planted back spawns; a committed registration deleted from, or modified in, a reused tree, which each conjunct planted out spawns; a placed copy that is not byte-equal, which the byte comparison planted out spawns) while a tracked settings.json beside link-skipped entries (a pnpm-style node_modules junction, a junctioned .claude/shared) spawns (round 2''s condition planted back does the reverse of both, and the committed half planted out refuses the second), a worker''s altered settings.json only staged in a reused tree is replaced by the mission root''s bytes (the index read as committed leaves it), a mission root with no settings.json on disk is not checked (the Exists conjunct planted out refuses one whose index tracks a file its disk lacks, and still spawns a root .claude/ holding no settings.json), a source or a destination the tag reader cannot classify refuses naming which, a reused destination that cannot be removed (read-only, or held open without delete sharing) refuses with its bytes untouched, and a missing .worktreeinclude proceeds saying nothing was placed' `
      -Ok ($r52ok1 -and $r52ok2 -and $r52ok3 -and $r52ok4 -and $r52ok5 -and $r52ok6 -and $r52ok7 -and $r52ok8 -and $r52ok9 -and $r52ok10 -and $r52ok11 -and $r52ok12 -and $r52ok13 -and $r52ok14 -and $r52ok15) -Detail $r52detail


# =============================================================================================
# R-A -- A DISPATCH ADMITTED ONLY BY THE ORIGIN-ATTESTATION CLASS MUST RECORD A NAMED OUTCOME
#        (the ratification)
# =============================================================================================
# WHAT THIS MEMBER IS FOR. An earlier revision built a FOURTH admission class: a dispatch may proceed
# because the tip an unrevoked push gate authorizes is the tip verify derived from origin. The
# class exists, it is reached, and it admits -- and the runner records the dispatch it carried as
# `outcome: verified-pass`, the same words an ordinary passing verify writes. R-1 calls an outcome
# with no name an UNACCOUNTED ADMISSION and exists to make those impossible rather than to annotate
# them, so the durable artifact a completion review reads cannot tell the two apart.
#
# THIS MEMBER IS RED BEFORE THE RATIFICATION AND GREEN AFTER IT, AND THAT ORDER IS THE POINT.
# R-16 guards the closure of the vocabulary; this member guards that the vocabulary is USED. The
# two are complements: R-16 fails if a name is ASSIGNED without being RATIFIED, and this one fails
# if a class ADMITS without being NAMED. Neither can be satisfied by editing an instrument.
#
# THE CONTROLS ARE THE MEMBER. A row asserting the fourth name alone would also pass on a runner
# that wrote that name for every dispatch. So the other three ruled admissions are driven here too,
# through the earns this instrument already proves -- R-28's advance and PASS-DIB, R-31's declared
# repair -- and each must still record ITS OWN name. Those fixtures are re-driven, not re-derived:
# their members have already asserted them, and `-AllowIdReuse` is what the sandbox is for.
#
# NON-VACUITY IS COUNTED OVER WHAT THE RUNNER DID, not over this table's expectations: the SIX
# driven rows (a-f) must produce at least TWO distinct outcomes read back off disk, or the member
# says so. ERRATUM, ROUND 2 (found in review): this read "the five rows", and the detail block printed
# "THE FIVE ROWS" over EIGHT on every run, because a later change added row (f) and left both figures.
# The printed figure is now derived from the rows themselves; this one is stated, and the two
# count different things -- eight rows are PRINTED, six of them drive a runner and feed the
# non-vacuity split.
$raId       = 'D-WP2-RA'
$raRoot     = Join-Path $sandbox 'ra\m'
$raGates    = Join-Path $raRoot '.mission\gates'
$raAnchors  = Join-Path $raRoot ".mission\dispatches\$raId.anchors.yaml"
$raPrior    = Join-Path $raRoot '.mission\dispatches\D-RAPRIOR.anchors.yaml'
$raCreated  = Join-Path (Get-FixtureWorktreePath -Id $raId -Root $raRoot) 'worker-created.txt'
$raTip      = 'abc1230000000000000000000000000000000def'
$raUrl      = 'https://example.invalid/ra.git'
$raRows     = @()
$raOk       = $true
$raOutcomes = @()

# THE NAME THE CONTRACT RATIFIES, spelled once here and nowhere else in this member.
$raFourth = 'admitted-by-authorized-publication'

function Add-RARow {
    param([string]$Id, [bool]$RowOk, [string]$Text, [string]$Said)
    if (-not $RowOk) { $script:raOk = $false }
    $script:raRows += ("    {0,-42} {1}  {2}" -f $Id, $Text, $(if ($RowOk) { 'ok' } else { 'MISMATCH' }))
    if ((-not $RowOk) -and $Said) { $script:raRows += ("        runner said: {0}" -f $Said) }
}

# THE ANCHOR READER IS BLOCK-SCOPED AND ANCHORED, deliberately. R-31a reads the outcome with a bare
# substring over the whole file and with a disjunct on the literal `gate_outcome: ` -- which the
# runner NEVER writes (it writes `verify_gate:` then two spaces and `outcome:`), so that disjunct
# cannot fire and the substring would also match the note lines and the declared_repair block. This
# reader takes the value of the `outcome:` key inside the `verify_gate:` block and nothing else, so
# a name appearing in prose elsewhere in the artifact cannot satisfy a row here.
function Get-RAOutcome {
    param([string]$Path)
    if (-not (Test-Path -LiteralPath $Path)) { return '(no anchors)' }
    $inBlock = $false
    foreach ($line in [System.IO.File]::ReadAllLines($Path)) {
        if ($line -match '^verify_gate:\s*$') { $inBlock = $true; continue }
        if (-not $inBlock) { continue }
        if ($line -match '^\S') { $inBlock = $false; continue }
        if ($line -match '^\s{2}outcome:\s*(\S+)\s*$') { return $Matches[1] }
    }
    return '(absent)'
}

# ---- THE FIXTURE: a mission root of its own, with an origin remote and one unrevoked push gate ---
# ITEM 7. New-R5xFixture runs the seed's sequence -- git init, the git-dir assertion, then config
# through the VERIFIED -C -- so no config write here can fall through to the host repository. The
# remote is added only after that assertion has admitted the root, and it is asserted again at the
# write because the seed and this line are not the same moment.
$raSeed = New-R5xFixture -Root $raRoot -GitIgnore ".mission-runtime/`n" -Files $null
$raSeeded = ($raSeed.refusal -eq '') -and ($raSeed.head -ne '')
$raRemoteOk = $false
if ($raSeeded) {
    $null = Assert-FixtureGitDir -Root $raRoot
    $prevEap = $ErrorActionPreference
    $ErrorActionPreference = 'Continue'
    try { $null = & git -C $raRoot remote add origin $raUrl 2>&1 } finally { $ErrorActionPreference = $prevEap }
    $raRemote = Get-R5xGit -Root $raRoot -GitArgs @('remote', 'get-url', '--push', 'origin')
    $raRemoteOk = ($raRemote.exit -eq 0) -and (@($raRemote.lines).Count -gt 0) -and ($raRemote.lines[0].Trim() -eq $raUrl)
    New-Item -ItemType Directory -Path $raGates -Force | Out-Null
    # The gate the admission reads. CRLF, one column-0 authorized_tip_sha (two would refuse rather
    # than pick one -- C-1t), kind spelled ordinally `push`, unconsumed and unrevoked.
    Write-Utf8 -Path (Join-Path $raGates 'push-ra.yaml') -Text (
        "kind: push`r`nid: ra`r`nauthorized_tip_sha: $raTip`r`norigin_url: $raUrl`r`n" +
        "remote_ref: refs/heads/main`r`nconsumed_at: null`r`nrevoked_at: null`r`n")
}
# ---- EARN THE CLEAN TREE, R-28's SEQUENCE, IN THIS MEMBER'S OWN ROOT -----------------------------
# The advance admission tests ancestry, cleanliness and provenance for real, so it cannot be
# stubbed. The declaration is written from what git ACTUALLY reports here, plus the prefixes the
# runner itself writes under, and committed together with everything else; the prior's head_sha is
# that HEAD, so the commit range is empty and only cleanliness decides.
# AND IT IS EARNED HERE RATHER THAN BORROWED. The first reading of this member drove the advance
# and PASS-DIB controls through R-28's fixture, which the members between R-28 and here mutate:
# by this point that tree carries uncommitted drift and the admission refuses, correctly. A
# control whose class is unreachable measures the fixture and not the runner, so both moved here.
$raHead = ''
$raDirty = @()
$raEarned = $false
if ($raSeeded -and $raRemoteOk) {
    $prevEap = $ErrorActionPreference
    $ErrorActionPreference = 'Continue'
    Push-Location $raRoot
    try { $raPorc = @(@(& git status --porcelain=v1 2>&1) | ForEach-Object { "$_" } | Where-Object { $_ -match '^\?\? ' }) }
    finally { Pop-Location; $ErrorActionPreference = $prevEap }
    $raPatterns = @(@($raPorc) + @('?? .mission/dispatches/', '?? .mission/evidence/', '?? .mission/gates/', '?? tools/', '?? docs/') | Select-Object -Unique)
    Write-Utf8 -Path (Join-Path $raRoot '.mission\mission.yaml') `
        -Text ("id: mission-wp2-r5x`nstate: executing`nadmitted_porcelain:`n" + ((@($raPatterns) | ForEach-Object { '  - "' + $_ + '"' }) -join "`n") + "`n")
    $null = Get-R5xGit -Root $raRoot -GitArgs @('add', '-A')
    $null = Get-R5xGit -Root $raRoot -GitArgs @('commit', '-q', '-m', 'fixture: R-A declares the live porcelain and commits the gate')
    $raHeadR = Get-R5xGit -Root $raRoot -GitArgs @('rev-parse', 'HEAD')
    if (($raHeadR.exit -eq 0) -and (@($raHeadR.lines).Count -gt 0)) { $raHead = $raHeadR.lines[0].Trim() }
    $raDirtyR = Get-R5xGit -Root $raRoot -GitArgs @('status', '--porcelain=v1')
    $raDirty = @(@($raDirtyR.lines) | Where-Object { $_ -and ($_ -notmatch '^\?\? ') })
    # THE LEDGER DIRECTORY IS CREATED FIRST. R-28 appends to this path in $missionRoot, where
    # earlier members have already made it; a fresh fixture root has no `.mission-runtime\lam`, and
    # Add-Content does not create one. Under this instrument's $ErrorActionPreference = 'Stop' that
    # threw and killed the run 66 rows in -- no summary line, exit 1, and R-A never emitted. The row
    # count beside the summary is what showed it, which is the whole reason the count is reported.
    New-Item -ItemType Directory -Path (Join-Path $raRoot '.mission-runtime\lam') -Force | Out-Null
    Add-Content -LiteralPath (Join-Path $raRoot '.mission-runtime\lam\commit-ledger.jsonl') `
        -Value ('{"event":"commit","repo":"mission-wp2-r5x","sha":"' + $raHead + '","by":"instrument"}')
    $raEarned = ($raHead -match '^[0-9a-f]{40}$') -and ($raDirty.Count -eq 0)
}
Add-RARow -Id 'FIXTURE the advance is EARNED here' -RowOk $raEarned `
    -Text ("declared porcelain entries={0} HEAD={1} tracked-but-modified after the commit={2}  (expect >0, 40 hex, 0)" -f $(if ($raSeeded -and $raRemoteOk) { $raPatterns.Count } else { 0 }), $(if ($raHead) { $raHead.Substring(0, 8) } else { '(none)' }), $raDirty.Count) `
    -Said $(if ($raDirty.Count) { ($raDirty -join ' ; ') } else { '' })

Add-RARow -Id 'FIXTURE seed + origin remote + gate' -RowOk ($raSeeded -and $raRemoteOk) `
    -Text ("seeded={0} head={1} origin url matches the gate={2}  (expect True, 40 hex, True)" -f $raSeeded, $(if ($raSeed.head) { $raSeed.head.Substring(0, [Math]::Min(8, $raSeed.head.Length)) } else { '(none)' }), $raRemoteOk) `
    -Said $raSeed.refusal

# The report: ONE refusing subject, and its last segment is origin_tip. That is what keeps the other
# three buckets empty -- no suite subject, no anchor subject, no declaration -- so a dispatch that
# proceeds on this report proceeds ONLY because the gate authorized the tip verify derived.
$raReport = (
    "refused_by:`n  - ORIGIN-ATTESTATION/origin_tip`n" +
    "arms:`n  - arm: ORIGIN-ATTESTATION`n    subject: origin_tip`n    outcome: DIVERGED`n" +
    "    recorded: 0000000000000000000000000000000000000000`n    derived: $raTip`n" +
    "    detector: git ls-remote origin refs/heads/main`n    residual: 'stale claim'`n")
$raVerifyOrigin = New-ReportStub -Name 'verify-ra-origin' -Report $raReport

function Invoke-RARow {
    param([string]$VerifyStub, [string]$SuiteCommand = '', [string[]]$DeclaredIds = @(), [string[]]$Unexpected = @())
    if (Test-Path -LiteralPath $raAnchors) { Remove-Item -LiteralPath $raAnchors -Force }
    Remove-Item -LiteralPath $raCreated -Force -ErrorAction SilentlyContinue
    $suiteLine = if ($SuiteCommand) { "suite_command: $SuiteCommand`n" } else { '' }
    # A DECLARATION IS A DEBT, so it is written in the dispatch's own idiom, with all
    # three required fields -- a malformed one refuses loudly rather than reading as absent.
    $declBlock = ''
    if (@($DeclaredIds).Count -gt 0) {
        $declBlock = "declared_repairs:`n"
        foreach ($d in @($DeclaredIds)) {
            $declBlock += "  - test_id: $d`n    reason: R-A row (f) -- the basis carries this failure and this dispatch repairs it`n    repairing_commit_label: RA-fix`n"
        }
    }
    Write-R5xDispatch -Root $raRoot -Id $raId -Extra ($suiteLine + $declBlock)
    # THE BASIS IS WRITTEN LAST, so it is the NEWEST anchors file on disk and therefore the basis
    # the basis rule selects. WITHOUT IT THERE IS NO BASIS AT ALL and the runner takes the
    # vacuous-first path -- verify is never invoked, the report below is never read, and every row
    # here would measure a dispatch that did not happen. That is exactly what the first reading of
    # this member did, and the outcome column is what showed it.
    # THE BASIS carries a suite block ONLY when a declaration is in play, because the declared-repair
    # class is granted against the basis's own unexpected-failure set and there is nowhere else to
    # read WHICH ids failed. Without a declaration the basis stays minimal, exactly as rows a-e want it.
    $raBasis = "dispatch_id: D-RAPRIOR`nhead_sha: $raHead`nworktree_tip_sha: $raHead`ncapture_gaps_count: 0`n"
    if (@($Unexpected).Count -gt 0) {
        $raNote = "declared 1; failed $(1 + @($Unexpected).Count); unexpected $(@($Unexpected).Count): $(@($Unexpected) -join ' ')"
        $raBasis += @"
runner_anchors:
  suite:
    command: '$SuiteCommand'
    passed: 0
    failed: 1
    skipped: 0
    expected_failures_matched: false
    expected_failures_note: '$raNote'
    exit_code: 1
    provenance: runner-observed
dispatch_kind: mainline
"@
    }
    Write-Utf8 -Path $raPrior -Text $raBasis
    $r = Invoke-R5xRunner -RunnerPath $runner -Root $raRoot -Id $raId -Extra @('-VerifyCommand', $VerifyStub, '-WorkerCommand', $workerOk)
    return [pscustomobject]@{
        out = $r.out; exit = $r.exit
        spawned = (Test-Path -LiteralPath $raCreated)
        outcome = (Get-RAOutcome -Path $raAnchors)
    }
}

# ---- (a) THE SUBJECT: admitted ONLY by the origin-attestation class ------------------------------
# TWO THINGS ARE ASSERTED AND THEY ARE NOT THE SAME THING: that the run REACHED this class (the
# runner's own admission text names it), and that the ARTIFACT records it. A row that asserted only
# the second would go green on a runner that wrote the name unconditionally; a row that asserted
# only the first would go green on today's runner, which reaches the class and records verified-pass.
$raA = if ($raEarned) { Invoke-RARow -VerifyStub $raVerifyOrigin } else { [pscustomobject]@{ out = ''; exit = -1; spawned = $false; outcome = '(fixture refused)' } }
$raAReached = [bool]($raA.out -match 'ADMITTED-BY-AUTHORIZED-PUBLICATION')
$raANamed   = ($raA.outcome -ceq $raFourth)
$raANotPass = ($raA.outcome -cne 'verified-pass')
$raAOk = ($raA.exit -eq 0) -and $raA.spawned -and $raAReached -and $raANamed -and $raANotPass
$raOutcomes += $raA.outcome
Add-RARow -Id 'a ORIGIN-ATTESTATION only' -RowOk $raAOk `
    -Text ("exit={0} spawned={1} reached the class={2} anchors outcome={3}  (expect 0, True, True, {4})" -f $raA.exit, $raA.spawned, $raAReached, $raA.outcome, $raFourth) `
    -Said (Get-R28Said $raA.out)

# ---- (b) CONTROL: a plain passing verify in the SAME fixture -------------------------------------
# The narrowest control there is: same root, same gate on disk, same dispatch -- only the report
# changes. If row (a) ever passes because of the fixture rather than the report, this row moves too.
$raB = if ($raEarned) { Invoke-RARow -VerifyStub $verifyPass } else { [pscustomobject]@{ out = ''; exit = -1; spawned = $false; outcome = '(fixture refused)' } }
$raBOk = ($raB.exit -eq 0) -and $raB.spawned -and ($raB.outcome -ceq 'verified-pass')
$raOutcomes += $raB.outcome
Add-RARow -Id 'b CONTROL plain verify PASS' -RowOk $raBOk `
    -Text ("exit={0} spawned={1} anchors outcome={2}  (expect 0, True, verified-pass)" -f $raB.exit, $raB.spawned, $raB.outcome) `
    -Said (Get-R28Said $raB.out)

# ---- (c) CONTROL: the ADVANCE admission, through R-28's earned fixture ---------------------------
$raC = if ($raEarned) { Invoke-RARow -VerifyStub $verifyRefuseAnchor } else { [pscustomobject]@{ out = ''; exit = -1; spawned = $false; outcome = '(fixture refused)' } }
$raCReached = [bool]((Test-Path -LiteralPath $raAnchors) -and ([System.IO.File]::ReadAllText($raAnchors) -match 'ANCHOR/head_sha'))
$raCOk = ($raC.exit -eq 0) -and $raC.spawned -and $raCReached -and ($raC.outcome -ceq 'verified-pass')
$raOutcomes += $raC.outcome
Add-RARow -Id 'c CONTROL the advance admission' -RowOk $raCOk `
    -Text ("exit={0} spawned={1} reached the class={2} anchors outcome={3}  (expect 0, True, True, verified-pass)" -f $raC.exit, $raC.spawned, $raCReached, $raC.outcome) `
    -Said (Get-R28Said $raC.out)

# ---- (d) CONTROL: PASS-DIB admitting suite subjects, through R-28's earned fixture ---------------
$raD = if ($raEarned) { Invoke-RARow -VerifyStub $verifyDibGenuine -SuiteCommand $r27SuiteClean } else { [pscustomobject]@{ out = ''; exit = -1; spawned = $false; outcome = '(fixture refused)' } }
$raDText = if (Test-Path -LiteralPath $raAnchors) { [System.IO.File]::ReadAllText($raAnchors) } else { '' }
$raDReached = [bool]($raDText -match '(?m)^verify_admission:') -and [bool]($raDText -match 'suite\.')
$raDOk = ($raD.exit -eq 0) -and $raD.spawned -and $raDReached -and ($raD.outcome -ceq 'verified-pass')
$raOutcomes += $raD.outcome
Add-RARow -Id 'd CONTROL PASS-DIB, suite subjects' -RowOk $raDOk `
    -Text ("exit={0} spawned={1} reached the class={2} anchors outcome={3}  (expect 0, True, True, verified-pass)" -f $raD.exit, $raD.spawned, $raDReached, $raD.outcome) `
    -Said (Get-R28Said $raD.out)

# ---- (e) CONTROL: the DECLARED-REPAIR admission, through R-31's earned fixture -------------------
$raE = Invoke-R31Row -VerifyStub $verifyRepairDiverged -SuiteStub $drSuiteClean -DeclaredIds @($drId1) -Unexpected @($drId1)
$raEOutcome = Get-RAOutcome -Path $drAnchors
$raEReached = [bool]($raE.out -match 'ADMITTED-BY-DECLARED-REPAIR')
$raEOk = ($raE.exit -eq 0) -and $raE.spawned -and $raEReached -and ($raEOutcome -ceq 'admitted-by-declared-repair')
$raOutcomes += $raEOutcome
Add-RARow -Id 'e CONTROL the declared-repair admission' -RowOk $raEOk `
    -Text ("exit={0} spawned={1} reached the class={2} anchors outcome={3}  (expect 0, True, True, admitted-by-declared-repair)" -f $raE.exit, $raE.spawned, $raEReached, $raEOutcome) `
    -Said $raE.said

# ---- (f) BOTH CLASSES ADMIT AT ONCE: precedence decides the NAME, not the RECORD ----------------
# A ROUND-1 VALIDATOR FINDING. The ratification claimed a precedence rule and stated its consequence
# as "this outcome would not have been written" -- true, and not the whole of it. Driven, the
# artifact recorded `admitted-by-declared-repair` with `ORIGIN-ATTESTATION/origin_tip` among its
# admitted subjects and NO GATE ID ANYWHERE, while the runner's own comment calls the gate id the
# only per-subject provenance this class produces and says a completion review has nowhere else to
# get it. Precedence is about which NAME the artifact carries. It is not a licence to drop a fact.
# THE ROW ASSERTS FOUR THINGS AND THE FIRST TWO ARE THE CONTROL: that both classes really did
# admit on this one dispatch -- the runner's own text has to name BOTH -- and only then that the
# name is the declared repair's and the gate ids survive beside it. A row that asserted the gate
# ids alone would pass on a dispatch where the declared repair never fired.
$raFId = 'tests/lam/probe_ra.py::test_row_f'
$raFReport = (
    "verify_version: 1`ndispatch_kind: build`narms:`n" +
    "  - arm: ANCHOR`n    subject: suite.expected_failures_matched`n    outcome: DIVERGED`n" +
    "    recorded: false`n    derived: true`n    residual: 'the recorded claim against the declared home content'`n" +
    "  - arm: ORIGIN-ATTESTATION`n    subject: origin_tip`n    outcome: DIVERGED`n" +
    "    recorded: 0000000000000000000000000000000000000000`n    derived: $raTip`n" +
    "    detector: git ls-remote origin refs/heads/main`n    residual: 'stale claim'`n" +
    "gate: REFUSE`nrefused_by:`n  - ANCHOR/suite.expected_failures_matched`n  - ORIGIN-ATTESTATION/origin_tip`n")
$raVerifyBoth = New-ReportStub -Name 'verify-ra-both' -Report $raFReport
$raF = if ($raEarned) { Invoke-RARow -VerifyStub $raVerifyBoth -SuiteCommand $r27SuiteClean -DeclaredIds @($raFId) -Unexpected @($raFId) } else { [pscustomobject]@{ out = ''; exit = -1; spawned = $false; outcome = '(fixture refused)' } }
$raFText    = if (Test-Path -LiteralPath $raAnchors) { [System.IO.File]::ReadAllText($raAnchors) } else { '' }
$raFBothRan = ([bool]($raF.out -match 'ADMITTED-BY-DECLARED-REPAIR')) -and ([bool]($raF.out -match 'ADMITTED-BY-AUTHORIZED-PUBLICATION'))
$raFGateIds = [bool]($raFText -match '(?m)^\s{2}authorizing_gate_ids:') -and [bool]($raFText -match '(?m)^\s{4}- push-ra\s*$')
$raFOk = ($raF.exit -eq 0) -and $raF.spawned -and $raFBothRan -and ($raF.outcome -ceq 'admitted-by-declared-repair') -and $raFGateIds
$raOutcomes += $raF.outcome
Add-RARow -Id 'f BOTH admit: repair wins, gate ids survive' -RowOk $raFOk `
    -Text ("exit={0} spawned={1} BOTH classes named by the runner={2} anchors outcome={3} authorizing_gate_ids present and naming the gate={4}  (expect 0, True, True, admitted-by-declared-repair, True)" -f $raF.exit, $raF.spawned, $raFBothRan, $raF.outcome, $raFGateIds) `
    -Said (Get-R28Said $raF.out)

# NON-VACUITY: six rows, and the outcomes they actually produced must not be one value.
$raDistinct = @(@($raOutcomes) | Sort-Object -Unique)
$raSplit = ($raDistinct.Count -ge 2)
$raDetail = @"
    THE $(@($raRows | Where-Object { $_ -notlike '        runner said:*' }).Count) ROWS, each a real runner, every outcome read back out of the verify_gate block on disk:
$($raRows -join "`n")
    distinct outcomes the runner produced: $($raDistinct.Count) -> [$($raDistinct -join ', ')]   split: $raSplit
      (counted over what the runner DID; a member whose rows all record one name proves nothing)
    the fixture root : $raRoot   (rows a-d and f are driven here; row e is R-31's earned fixture)
    the basis        : $raPrior   head_sha $raHead -- written LAST on every row, or the runner takes vacuous-first
    the gate         : $(Join-Path $raGates 'push-ra.yaml')   tip $raTip   origin $raUrl
    WHAT THIS MEMBER DOES NOT CLAIM: that the class is correctly GRANTED -- WP-3's C-1q, C-1r, C-1t
      and C-1u drive the reader's predicates, and WP-1's H-21/H-22 drive the mirror. This member is
      about what the ANCHORS say once it has been granted, and nothing else.
"@
Check -Id 'R-A' -Title 'a dispatch that proceeds ONLY because the tip an unrevoked push gate authorizes is the tip verify derived from origin records a NAMED fourth gate outcome on its anchors and never verified-pass, while the other three ruled admissions -- the advance, PASS-DIB over suite subjects, and the declared repair -- each still record their own name through the fixtures this instrument already earns' `
      -Ok ($raOk -and $raSplit) -Detail $raDetail


# =============================================================================================
# R-B -- THE MIRROR MUST BE STRUCTURAL: R-16's CLOSED SET IS DERIVED FROM THE RATIFIED SENTENCE
#        (a round-1 validator finding, against the ratification)
# =============================================================================================
# WHAT WENT WRONG, MEASURED BY AN INDEPENDENT VALIDATOR AND REPRODUCED HERE. R-16's whole design
# statement is that an outcome joins the vocabulary by being RATIFIED and never by being assigned,
# and the ratification restated it harder: "NEITHER can be satisfied by editing an instrument." That
# was FALSE. R-16 compared the runner's assignments against a list ENUMERATED IN THIS FILE, and
# checked the contract only for four FIXED literals. So a fifth outcome -- assigned by the runner,
# declared by the runner, and named nowhere on the contract page -- was admitted by TWO ADDITIVE
# EDITS CONFINED TO THIS FILE: the enumeration and the declared-set regex. Exactly the two edits
# the ratification's own cure made for the fourth outcome. Driven, with three controls:
#     real runner, real contract, instrument as shipped   -> True    (expected True)
#     fiat runner, real contract, instrument as shipped   -> False   (expected False)
#     fiat runner, real contract, TWO instrument edits    -> TRUE    (expected False)  <-- the hole
#
# WHY A HAND-MAINTAINED MIRROR IS THE DEFECT AND NOT THE SPELLING OF ANY ONE ARM. Design v2.3
# SS4.5 law 3 requires the two directions to move together; R-16 implemented that as a PAIR OF
# LITERALS a seat is trusted to update in step. A literal is not a mirror. The contract is the
# ratifying document, so the instrument must take the vocabulary FROM IT and hold no copy of its
# own -- then there is nothing IN R-16 to edit, and the only route to a fifth outcome that R-16
# itself can be made to swallow is the ruled sentence, which is what a ratification is.
# ERRATUM, ROUND 2 (found in review): this read "then there is nothing in this file to edit". ROUND 2
# REFUTED THAT VERBATIM. Three additive lines in Test-GateOutcomeMirror -- this file, outside
# R-16's delimiters -- DEFEAT R-16 AND THIS MEMBER, which are the two that CALL the mirror,
# against a fifth outcome the page never names. R-A also read PASS under that attack, and NOT
# because those lines blinded it: R-A calls neither shared function, and its fixtures never
# produce the planted outcome at all.
# And THIS MEMBER CANNOT SEE THEM: row (2) reads only inside R-16, rows (1) and (3) call the very
# functions that were subverted. A member that tests a function by calling it cannot detect that
# the function was subverted. R-16's header carries the class residual and its real bounds.
# (ERRATUM, CLOSURE ROUND 1 (found in review): this read "turn R-16, R-A and R-B green" -- three verdicts that
# co-occurred, stated as three effects of one cause. R-A's was not.)
#
# WHAT THIS MEMBER GUARDS, AND WHY IT IS SEPARATE FROM R-16. R-16 guards the CLOSURE of the
# vocabulary. R-A guards that the vocabulary is USED. This one guards that R-16's own knowledge of
# the vocabulary is DERIVED -- and it is separate because a member cannot be its own adversary:
# R-16 cannot notice that R-16's list is hand-written.
$rbTok        = 'admitted-by-' + 'round2-fiat'
$rbRows       = @()
$rbOk         = $true
$rbRecord     = Get-LamAcceptRecord
$rbContract   = $rbRecord.text
$rbRunner     = [System.IO.File]::ReadAllText($runner)
$rbInstrument = [System.IO.File]::ReadAllText($PSCommandPath)

function Add-RBRow {
    param([string]$Label, [bool]$Ok, [string]$Said)
    if (-not $Ok) { $script:rbOk = $false }
    $script:rbRows += ("      {0,-76}: {1}   {2}" -f $Label, $Ok, $Said)
}

# THE BODY IS FAIL-CLOSED FROM HERE, in C-1v's idiom. An exception escaping a member does not just
# lose that member: it kills the instrument, so every row after it goes UNMEASURED and the summary
# line -- the thing a reader checks -- is never printed. That happened to this very member, twice
# in this package's history for two different reasons. A member that can abort the run can hide
# every row after it, which is worse than a member that fails.
try {

# ---- (1) THE DERIVATION EXISTS AT ALL -------------------------------------------------------------
# Spelled as a capability test rather than a text search, because what matters is that R-16 can ASK
# the contract, not that some function name appears somewhere in this file.
$rbDeriveFn = Get-Command -Name 'Get-RatifiedGateOutcomes' -CommandType Function -ErrorAction SilentlyContinue
$rbMirrorFn = Get-Command -Name 'Test-GateOutcomeMirror'  -CommandType Function -ErrorAction SilentlyContinue
Add-RBRow -Label '(1) this instrument DERIVES the outcome set from the contract' -Ok ([bool]$rbDeriveFn) `
    -Said $(if ($rbDeriveFn) { 'Get-RatifiedGateOutcomes is defined' } else { 'ABSENT -- the set is enumerated in this file, so this file can admit an unratified outcome' })
Add-RBRow -Label '(1) and the runner/contract comparison is one named predicate' -Ok ([bool]$rbMirrorFn) `
    -Said $(if ($rbMirrorFn) { 'Test-GateOutcomeMirror is defined' } else { 'ABSENT' })

# ---- (2) R-16 HOLDS NO ENUMERATION OF ITS OWN ------------------------------------------------------
# The structural half. A derivation that exists beside a surviving hard-coded list is no better than
# the list: a later edit would simply use the list again. So R-16's OWN TEXT is measured, bounded by
# its own delimiters, and any array literal carrying two or more of the outcome names fails this row.
$rbR16 = ''
$rbStart = $rbInstrument.IndexOf('# R-16 -- THE GATE OUTCOME VOCABULARY IS CLOSED')
$rbEnd   = $rbInstrument.IndexOf("Check -Id 'R-16'")
if (($rbStart -ge 0) -and ($rbEnd -gt $rbStart)) { $rbR16 = $rbInstrument.Substring($rbStart, $rbEnd - $rbStart) }
$rbLive  = @(@($rbR16 -split "`r?`n") | Where-Object { -not (([string]$_).TrimStart().StartsWith('#')) })
$rbHard  = @($rbLive | Where-Object { ($_ -match "'verified-pass'") -and ($_ -match "'vacuous-first'") })
Add-RBRow -Label '(2) R-16 bounded by its own delimiters, and it was found' -Ok ($rbR16.Length -gt 0) -Said ("$($rbR16.Length) chars")
Add-RBRow -Label '(2) THE ROW: no LIVE line in R-16 enumerates the outcome names' -Ok ($rbHard.Count -eq 0) `
    -Said $(if ($rbHard.Count) { 'hard-coded at: ' + (($rbHard | ForEach-Object { $_.Trim().Substring(0, [Math]::Min(60, $_.Trim().Length)) }) -join ' || ') } else { 'none -- the set comes from the page' })

# ---- (3) THE DRIVES ---------------------------------------------------------------------------------
# Mirrors in memory. Nothing on disk is touched: the defect is in what the instrument BELIEVES, and
# a belief is testable against text.
$rbRunnerFiat = $rbRunner
# SINGLE-QUOTED, AND THAT IS THE WHOLE FIX. This regex first stood in a DOUBLE-quoted string,
# so PowerShell expanded the dollar sign before the match ever ran and the reference to an
# undefined variable killed the instrument 67 rows in -- no summary line, and this member never
# emitted. A pattern is data; it does not get interpolated.
if ($rbRunner -match '(?m)^\$closedGateOutcomes = @\((?<body>[^)]*)\)') {
    $rbRunnerFiat = $rbRunner.Replace($Matches[0], ($Matches[0] -replace '\)$', (", '" + $rbTok + "')")))
}
$rbRunnerFiat = $rbRunnerFiat.Replace(
    'if ($closedGateOutcomes -notcontains $gateOutcome) {',
    ("if (`$gateOutcome -eq 'never') { `$gateOutcome = '" + $rbTok + "' }`r`nif (`$closedGateOutcomes -notcontains `$gateOutcome) {"))
$rbFiatPlanted = ([regex]::Matches($rbRunnerFiat, [regex]::Escape($rbTok)).Count -eq 2)
Add-RBRow -Label '(3) FIXTURE the runner mirror assigns AND declares a fifth outcome' -Ok $rbFiatPlanted `
    -Said ("occurrences of the planted name: " + ([regex]::Matches($rbRunnerFiat, [regex]::Escape($rbTok)).Count) + "   (expect 2)")
Add-RBRow -Label '(3) FIXTURE and the REAL contract names it nowhere' -Ok (-not $rbContract.Contains($rbTok)) -Said 'the page is untouched'

$rbContractFive = $rbContract
if ($rbContract -match 'Exactly \*\*four distinguishable\*\* gate outcomes') {
    $rbContractFive = $rbContract.Replace('Exactly **four distinguishable** gate outcomes', 'Exactly **five distinguishable** gate outcomes')
    $rbContractFive = $rbContractFive.Replace('ids listed). **No path records', ("ids listed), and ``" + $rbTok + "`` (a mirror). **No path records"))
}
$rbContractThree = $rbContract.Replace('Exactly **four distinguishable** gate outcomes', 'Exactly **three distinguishable** gate outcomes')

if ($rbDeriveFn -and $rbMirrorFn) {
    $rbD = Get-RatifiedGateOutcomes -ContractText $rbContract
    Add-RBRow -Label '(3) CONTROL the real page yields exactly the runner''s four, and its count word agrees' `
        -Ok ($rbD.ok -and ($rbD.count -eq 4) -and ($rbD.names -contains 'verified-pass') -and ($rbD.names -contains 'admitted-by-authorized-publication')) `
        -Said ("word='" + $rbD.word + "' count=" + $rbD.count + " -> [" + ($rbD.names -join ', ') + "]")
    $rbA = Test-GateOutcomeMirror -RunnerText $rbRunnerFiat -ContractText $rbContract
    Add-RBRow -Label '(3) THE ATTACK a fifth outcome the page does not name is REFUSED' -Ok (-not $rbA.ok) -Said $rbA.reason
    $rbB = Test-GateOutcomeMirror -RunnerText $rbRunnerFiat -ContractText $rbContractFive
    Add-RBRow -Label '(3) THE RATIFICATION ROUTE the same runner with the page amended is ADMITTED' -Ok $rbB.ok -Said $rbB.reason
    $rbC = Test-GateOutcomeMirror -RunnerText $rbRunner -ContractText $rbContractThree
    Add-RBRow -Label '(3) INVERTED a page naming three against the real four-name runner is REFUSED' -Ok (-not $rbC.ok) -Said $rbC.reason
    $rbE = Test-GateOutcomeMirror -RunnerText $rbRunner -ContractText $rbContract
    Add-RBRow -Label '(3) CONTROL the shipped pair agrees' -Ok $rbE.ok -Said $rbE.reason
}
else {
    Add-RBRow -Label '(3) THE FOUR DRIVES ARE UNMEASURED -- there is no derivation to drive' -Ok $false `
        -Said 'R-16 compares the runner against a list this file holds, so this file can admit a fifth outcome by itself'
}

}
catch {
    $rbOk = $false
    $rbRows += '      MEMBER ABORTED -- an exception escaped the body; every row after it is UNMEASURED'
    $rbRows += ('        line ' + $_.InvocationInfo.ScriptLineNumber + ' :: ' + $_.Exception.GetType().Name + ' :: ' + ($_.Exception.Message -replace '[\r\n]+', ' '))
}
$rbDetail = @"
    THE MIRROR IS STRUCTURAL OR IT IS NOT A MIRROR:
$($rbRows -join "`n")
    WHAT THIS MEMBER DOES NOT CLAIM: that the contract's ruled sentence is CORRECT -- that is the
      operator's act and R-16's contract arm. Nor, since round 2 refuted it, that the instrument
      gets no vote on the vocabulary: three additive lines in the shared mirror function defeat
      R-16 AND THIS MEMBER, the two that CALL it. R-A read PASS under the same attack for a
      different reason -- it calls neither function, and its fixtures never produce the planted
      outcome -- so it is not evidence about those lines either way. The bound on all of this is
      the operator's review of the diff, not a row here.
      This one claims that R-16 holds no list of its own.
      The contract, read from: $($rbRecord.from)
"@
Check -Id 'R-B' -Title 'R-16''s closed outcome set is DERIVED FROM THE RATIFIED SENTENCE on the contract page and is enumerated nowhere inside R-16''s own delimiters -- which is NOT the claim this title made until the closure pass, that no edit confined to this file can turn R-16 green against a runner carrying an outcome the page does not name: round 2 REFUTED that verbatim with three additive lines in this file''s shared mirror function, which this member calls and therefore cannot see, and R-16''s header carries it as a class residual -- driven with the fifth-outcome runner that round 1''s validator used to refute the claim, the same runner ADMITTED once the page names it, a page naming three refused against the real four-name runner, and the shipped pair agreeing' `
      -Ok $rbOk -Skipped:(-not $rbRecord.ok) -Detail $(if ($rbRecord.ok) { $rbDetail } else { "      SKIPPED: the contract is not here -- $($rbRecord.from)`n" + $rbDetail })


# =============================================================================================
# R-C / R-D / R-E / R-F -- A DISPATCH GATE IS STAMPED BY THE RUNNER AT SPAWN
#   (operator ruling (i), "Dispatch gates are stamped by the runner at spawn
#   (candidate C5)")
# =============================================================================================
# THE ROW. Both dispatch gates of the validator rounds still read
# `consumed_at: null` after the spawns they authorized, although each says `single_use: true`. The
# runner read no dispatch gate at all; the seat read it by file tool and wrote the spawn ledger.
#
# THE RULINGS THESE MEMBERS HOLD THE RUNNER TO. One dispatch gate authorizes one ROUND -- the ids the
# manifest it binds names in spawn_order. At the first spawn the runner writes consumed_at and
# consumed_basis ("spawn by the runner under this gate") and lists the spawn under consumed_spawns;
# each later spawn appends one line and writes no second consume block. REFUSED before the spawn,
# gate byte-unchanged: an id the manifest does not name; a spawn beyond its count; a gate consumed
# under a different manifest; a revoked gate; an EXPIRED gate at ANY spawn; an artifact whose sha256
# is not the manifest's row for it; an id already listed. The runner's own record of the dispatch
# (its anchors) names the gate it consumed.
#
# THE GATES UNDER TEST START AS THE MINT'S OWN BYTES. `mission-gate.ps1 approve -ComposeOnly` composes
# the artifact exactly as a mint writes it and writes nothing; these members write THOSE bytes into
# the fixture's gates directory, and a row that then edits a gate by hand says so. A hand-rolled gate
# is how a detector once passed on a shape the real writer never produces (lam-gate-class.ps1,
# Get-LamGateState's own note).
#
# EVERY READING HERE IS INDEPENDENT OF THE CODE UNDER TEST. The gate's fields are counted by this
# file's own regexes over the bytes on disk, and the anchors block is read by this file's own reader;
# nothing here asks tools/lam/lam-dispatch-gate.ps1 what it wrote, except R-D's and R-F's probes,
# which DRIVE that library's functions: R-D's still counts the resulting gate bytes itself, and
# R-F's reads the readers' verdicts on texts it builds and writes no gate.
$dgRoot       = Join-Path $sandbox 'dg\m'
$dgGates      = Join-Path $dgRoot '.mission\gates'
$dgGateTool   = Join-Path $repoRoot 'tools\lam\mission-gate.ps1'
$dgGoalCheck  = Join-Path $repoRoot 'tools\lam\mission-goal-check.ps1'
$dgClassLib   = Join-Path $repoRoot 'tools\lam\lam-gate-class.ps1'
$dgGateLib    = Join-Path $repoRoot 'tools\lam\lam-dispatch-gate.ps1'
$dgManifestRel  = '.mission\dispatches\D-DG.manifest.yaml'
$dgManifest2Rel = '.mission\dispatches\D-DG2.manifest.yaml'
$dgManifest3Rel = '.mission\dispatches\D-DG3.manifest.yaml'
$dgManifestFRel = '.mission\dispatches\D-DGF.manifest.yaml'
$dgBasisWords = 'spawn by the runner under this gate'
$dgPast       = '2026-09-20T00:00:00.000Z'
$dgStampRe    = '^20[0-9]{2}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\.[0-9]{3}Z$'

function Get-DGFileSha {
    param([string]$Path)
    if (-not (Test-Path -LiteralPath $Path)) { return '(absent)' }
    return (Get-FileHash -Algorithm SHA256 -LiteralPath $Path).Hash.ToLowerInvariant()
}

# THE MINT'S BYTES, WRITTEN BY THIS MEMBER. Returns ok=$false with what the tool said when the tool
# did not compose exactly one write -- a fixture that cannot be minted fails its rows, loudly.
function New-DGGate {
    param([string]$Id, [string]$BindsRel, [int]$Minutes = 120)
    $prevEap = $ErrorActionPreference
    $ErrorActionPreference = 'Continue'
    try {
        $o = & powershell -NoProfile -ExecutionPolicy Bypass -File $dgGateTool approve -Kind dispatch -Id $Id -Binds $BindsRel -MissionRoot $dgRoot -ExpiresMinutes $Minutes -ComposeOnly 2>&1
        $code = $LASTEXITCODE
    } finally { $ErrorActionPreference = $prevEap }
    $said = ((@($o) | ForEach-Object { [string]$_ }) -join "`n")
    $ws = @([regex]::Matches($said, '(?m)^LAMCOMPOSE write (\S+) (\d+) (\S+)\s*$'))
    if (($code -ne 0) -or ($ws.Count -ne 1)) { return [pscustomobject]@{ ok = $false; path = (Join-Path $dgGates "dispatch-$Id.yaml"); name = ''; said = $said } }
    $name = [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($ws[0].Groups[1].Value))
    $bytes = [Convert]::FromBase64String($ws[0].Groups[3].Value)
    New-Item -ItemType Directory -Path $dgGates -Force | Out-Null
    $path = Join-Path $dgGates $name
    [System.IO.File]::WriteAllBytes($path, $bytes)
    return [pscustomobject]@{ ok = $true; path = $path; name = $name; said = '' }
}

# THE GATE'S FIELDS, COUNTED FROM ITS BYTES BY THIS FILE'S OWN REGEXES.
function Get-DGGateFacts {
    param([string]$Path)
    if (-not (Test-Path -LiteralPath $Path)) {
        return [pscustomobject]@{ exists = $false; text = ''; sha = '(absent)'; bytes = 0; cr = 0; lf = 0; bareLf = 0
            at = @(); sentinel = 0; basis = @(); ms = @(); spawnKey = 0; spawns = @() }
    }
    $b = [System.IO.File]::ReadAllBytes($Path)
    $t = [System.IO.File]::ReadAllText($Path)
    $cr = 0; $lf = 0
    foreach ($x in $b) { if ($x -eq 13) { $cr++ } elseif ($x -eq 10) { $lf++ } }
    $at = @([regex]::Matches($t, '(?m)^consumed_at:[ \t]*([^\r\n]*?)[ \t]*\r?$') | ForEach-Object { $_.Groups[1].Value })
    $basis = @([regex]::Matches($t, '(?m)^consumed_basis:[ \t]*([^\r\n]*?)[ \t]*\r?$') | ForEach-Object { $_.Groups[1].Value })
    $ms = @([regex]::Matches($t, '(?m)^consumed_manifest_sha256:[ \t]*([^\r\n]*?)[ \t]*\r?$') | ForEach-Object { $_.Groups[1].Value })
    $spawns = @([regex]::Matches($t, '(?m)^  - \{seq: ([0-9]+), dispatch_id: ([^}\r\n]+)\}\r?$') | ForEach-Object { $_.Groups[1].Value + ':' + $_.Groups[2].Value })
    return [pscustomobject]@{
        exists = $true; text = $t; sha = (Get-DGFileSha -Path $Path); bytes = $b.Length; cr = $cr; lf = $lf
        bareLf = ([regex]::Matches($t, '(?<!\r)\n')).Count
        at = @($at); sentinel = ([regex]::Matches($t, '(?m)^consumed_at:[ \t]*null[ \t]*\r?$')).Count
        basis = @($basis); ms = @($ms); spawnKey = ([regex]::Matches($t, '(?m)^consumed_spawns:')).Count; spawns = @($spawns)
    }
}

# THE RUNNER'S RECORD OF THE GATE IT CONSUMED: the `dispatch_gate:` block of the dispatch's anchors,
# read by this file's own block-scoped reader. `present` is whether the block exists at all; a value
# the writer single-quotes is compared with its quotes removed.
function Get-DGAnchorGate {
    param([string]$Id)
    $an = Join-Path $dgRoot ".mission\dispatches\$Id.anchors.yaml"
    $h = @{}
    if (-not (Test-Path -LiteralPath $an)) { return [pscustomobject]@{ anchors = $false; present = $false; fields = $h; sha = '(absent)' } }
    $in = $false
    $present = $false
    foreach ($line in [System.IO.File]::ReadAllLines($an)) {
        if ($line -match '^dispatch_gate:\s*$') { $in = $true; $present = $true; continue }
        if (-not $in) { continue }
        if ($line -match '^\S') { $in = $false; continue }
        if ($line -match '^  ([a-z_0-9]+):\s*(.*?)\s*$') { $h[$Matches[1]] = ($Matches[2] -replace "^'(.*)'$", '$1') }
    }
    return [pscustomobject]@{ anchors = $true; present = $present; fields = $h; sha = (Get-DGFileSha -Path $an) }
}
function Get-DGField {
    param($Anchor, [string]$Key)
    if ($Anchor.fields.ContainsKey($Key)) { return [string]$Anchor.fields[$Key] }
    return '(absent)'
}

# ONE RUN OF THE REAL RUNNER. The worker stub leaves worker-created.txt in the dispatch's own tree, so
# "spawned" is read off the disk and never off the runner's word; the file is removed before each run.
function Invoke-DGRun {
    param([string]$Id, [string]$Gate = '', [switch]$Plan)
    $wtCreated = Join-Path (Get-FixtureWorktreePath -Id $Id -Root $dgRoot) 'worker-created.txt'
    Remove-Item -LiteralPath $wtCreated -Force -ErrorAction SilentlyContinue
    $extra = @('-VerifyCommand', $verifyPass, '-WorkerCommand', $workerOk)
    if ($Gate) { $extra += @('-DispatchGate', $Gate) }
    if ($Plan) { $extra += @('-PlanOnly') }
    $r = Invoke-R5xRunner -RunnerPath $runner -Root $dgRoot -Id $Id -Extra $extra
    $cm = [regex]::Match([string]$r.out, 'DISPATCH-GATE-([A-Z]+(?:-[A-Z]+)*)')
    return [pscustomobject]@{
        out = [string]$r.out; exit = $r.exit; spawned = (Test-Path -LiteralPath $wtCreated)
        code = $(if ($cm.Success) { $cm.Groups[1].Value } else { '' })
    }
}

# A CONSUME BLOCK IN THE RUNNER'S SHAPE, PLANTED BY HAND onto a freshly composed gate -- the route
# an earlier design note used to show a precondition is REACHABLE: `.mission/gates` is in no
# protected-path list, and a halt's refusal text instructs an operator to annotate a gate at column 0.
function Set-DGPlantedBlock {
    param([string]$Path, [string]$ManifestSha, [string[]]$SpawnLines)
    $t = [System.IO.File]::ReadAllText($Path)
    $t = [regex]::Replace($t, '(?m)^consumed_at:[^\r\n]*', 'consumed_at: 2026-09-24T00:00:00.000Z')
    $t = $t.TrimEnd() + "`r`nconsumed_basis: $dgBasisWords`r`nconsumed_manifest_sha256: $ManifestSha`r`nconsumed_spawns:`r`n"
    foreach ($s in $SpawnLines) { $t += ($s + "`r`n") }
    [System.IO.File]::WriteAllText($Path, $t, (New-Object System.Text.UTF8Encoding($false)))
}
function Set-DGExpiry {
    param([string]$Path, [string]$Value)
    $t = [System.IO.File]::ReadAllText($Path)
    $t = [regex]::Replace($t, '(?m)^expires_at:[^\r\n]*', ('expires_at: ' + $Value))
    [System.IO.File]::WriteAllText($Path, $t, (New-Object System.Text.UTF8Encoding($false)))
}
function Write-DGManifest {
    param([string]$Rel, [string]$Id, [string]$SpawnOrderText, [string[]]$RowIds)
    $rows = ''
    foreach ($r in $RowIds) { $rows += ("- path: .mission/dispatches/$r.yaml`n  sha256: " + (Get-DGFileSha -Path (Join-Path $dgRoot ".mission\dispatches\$r.yaml")) + "`n") }
    Write-Utf8 -Path (Join-Path $dgRoot $Rel) -Text ("id: $Id`nkind: validator-manifest`nround: R-$Id`n" + $SpawnOrderText + "artifacts:`n" + $rows)
}

# ---- THE FIXTURE, shared by R-C, R-D and R-E (R-F builds its own texts) -----------------------------
$dgSeed = New-R5xFixture -Root $dgRoot -GitIgnore ".mission-runtime/`n" -Files $null
$dgSeeded = ($dgSeed.refusal -eq '') -and ($dgSeed.head -ne '')
$dgShaA = ''; $dgShaB = ''; $dgShaM = ''; $dgShaM2 = ''
$dgPathA = Join-Path $dgRoot '.mission\dispatches\D-DGA.yaml'
$dgPathB = Join-Path $dgRoot '.mission\dispatches\D-DGB.yaml'
if ($dgSeeded) {
    Write-R5xDispatch -Root $dgRoot -Id 'D-DGA'
    Write-R5xDispatch -Root $dgRoot -Id 'D-DGB'
    Write-R5xDispatch -Root $dgRoot -Id 'D-DGX'
    $dgShaA = Get-DGFileSha -Path $dgPathA
    $dgShaB = Get-DGFileSha -Path $dgPathB
    # THE ROUND'S MANIFEST, in the shape D-V-R-PB-1.manifest.yaml carries: spawn_order as a
    # column-0 block list, and one artifacts row per dispatch with that artifact's sha256.
    Write-DGManifest -Rel $dgManifestRel -Id 'D-DG' -SpawnOrderText "spawn_order:`n- D-DGA`n- D-DGB`n" -RowIds @('D-DGA', 'D-DGB')
    # A SECOND MANIFEST with different bytes, whose sha256 is what a gate "consumed under another
    # manifest" carries.
    Write-DGManifest -Rel $dgManifest2Rel -Id 'D-DG2' -SpawnOrderText "spawn_order:`n- D-DGB`n- D-DGA`n" -RowIds @('D-DGB', 'D-DGA')
    # A THIRD, naming both ids but carrying an artifacts row for D-DGB only.
    Write-DGManifest -Rel $dgManifest3Rel -Id 'D-DG3' -SpawnOrderText "spawn_order:`n- D-DGA`n- D-DGB`n" -RowIds @('D-DGB')
    # A FOURTH, in the one-line FLOW form most manifests on this mission use (D-V-R-S3's shape).
    Write-DGManifest -Rel $dgManifestFRel -Id 'D-DGF' -SpawnOrderText "spawn_order: [D-DGA, D-DGB]`n" -RowIds @('D-DGA', 'D-DGB')
    $dgShaM  = Get-DGFileSha -Path (Join-Path $dgRoot $dgManifestRel)
    $dgShaM2 = Get-DGFileSha -Path (Join-Path $dgRoot $dgManifest2Rel)
}

# =============================================================================================
# R-C -- THE STAMP, THE LIST, AND EVERY REFUSAL, THROUGH THE REAL RUNNER
# =============================================================================================
$rcRows = @()
$rcOk = $true
$rcCodes = @()
$rcRefusalRows = 0
function Add-RCRow {
    param([string]$Id, [bool]$RowOk, [string]$Text, [string]$Said)
    if (-not $RowOk) { $script:rcOk = $false }
    $script:rcRows += ("    {0,-48} {1}  {2}" -f $Id, $Text, $(if ($RowOk) { 'ok' } else { 'MISMATCH' }))
    if ((-not $RowOk) -and $Said) { $script:rcRows += ("        runner said: {0}" -f (($Said -replace '\s+', ' ').Trim())) }
}
# A REFUSAL ROW asserts the four things a refusal owes: exit 2, the named code, NO spawn, and the gate
# BYTE-UNCHANGED by sha256 and length. A row asserting only the exit code would pass on a runner that
# refused everything for any reason, and on the uncured runner, which cannot parse the parameter.
function Add-RCRefusalRow {
    param([string]$Id, $Run, [string]$Code, $Before, $After)
    $same = ($Before.sha -eq $After.sha) -and ($Before.bytes -eq $After.bytes)
    $rowOk = ($Run.exit -eq 2) -and ($Run.code -ceq $Code) -and (-not $Run.spawned) -and $same
    $script:rcCodes += $Run.code
    $script:rcRefusalRows++
    Add-RCRow -Id $Id -RowOk $rowOk -Text ("exit={0} code={1} spawned={2} gate byte-unchanged={3} ({4} B)  (expect 2, {5}, False, True)" -f $Run.exit, $(if ($Run.code) { $Run.code } else { '(none)' }), $Run.spawned, $same, $After.bytes, $Code) -Said (Get-R28Said $Run.out)
}

try {
$dg1 = if ($dgSeeded) { New-DGGate -Id 'dg1' -BindsRel $dgManifestRel } else { [pscustomobject]@{ ok = $false; path = ''; name = ''; said = $dgSeed.refusal } }
$dg1F = Get-DGGateFacts -Path $dg1.path
$dg1Shape = $dg1.ok -and ($dg1.name -ceq 'dispatch-dg1.yaml') -and ($dg1F.text -match '(?m)^kind: dispatch\r?$') -and ($dg1F.sentinel -eq 1) -and
            ($dg1F.text -match ('(?m)^binds_sha256: ' + $dgShaM + '\r?$')) -and ($dg1F.cr -eq $dg1F.lf) -and ($dg1F.bareLf -eq 0)
Add-RCRow -Id 'FIXTURE the gate is the mint''s own bytes' -RowOk $dg1Shape `
    -Text ("composed={0} name={1} kind dispatch, one consumed_at: null, binds_sha256 = the manifest's, CRLF uniform (CR {2} = LF {3})  (expect all)" -f $dg1.ok, $dg1.name, $dg1F.cr, $dg1F.lf) -Said $dg1.said

# ---- (a) THE PLAN names the gate and writes nothing ---------------------------------------------
$b0 = Get-DGGateFacts -Path $dg1.path
$rA = Invoke-DGRun -Id 'D-DGA' -Gate 'dg1' -Plan
$a0 = Get-DGGateFacts -Path $dg1.path
$rAOk = ($rA.exit -eq 0) -and ($rA.out -match 'dispatch-dg1\.yaml') -and ($rA.out -match 'would CONSUME') -and (-not $rA.spawned) -and ($b0.sha -eq $a0.sha)
Add-RCRow -Id 'a -PlanOnly names the gate' -RowOk $rAOk `
    -Text ("exit={0} names dispatch-dg1.yaml={1} says it would CONSUME={2} spawned={3} gate byte-unchanged={4}  (expect 0, True, True, False, True)" -f $rA.exit, [bool]($rA.out -match 'dispatch-dg1\.yaml'), [bool]($rA.out -match 'would CONSUME'), $rA.spawned, ($b0.sha -eq $a0.sha)) -Said (Get-R28Said $rA.out)

# ---- (b) AN ID THE MANIFEST DOES NOT NAME -------------------------------------------------------
$b0 = Get-DGGateFacts -Path $dg1.path
$rB = Invoke-DGRun -Id 'D-DGX' -Gate 'dg1'
Add-RCRefusalRow -Id 'b an unnamed id refuses' -Run $rB -Code 'UNNAMED' -Before $b0 -After (Get-DGGateFacts -Path $dg1.path)

# ---- (c) THE FIRST SPAWN STAMPS AND LISTS ---------------------------------------------------------
$b0 = Get-DGGateFacts -Path $dg1.path
$anBefore = Get-DGAnchorGate -Id 'D-DGA'
$rC = Invoke-DGRun -Id 'D-DGA' -Gate 'dg1'
$a0 = Get-DGGateFacts -Path $dg1.path
$anC = Get-DGAnchorGate -Id 'D-DGA'
# WHAT MAY MOVE ON THE FIRST STAMP: the sentinel line, and what is appended after the gate's last
# line. The mint writes the sentinel as its LAST line, so every byte before it must be untouched.
$sentAt = $b0.text.IndexOf('consumed_at: null')
$headKept = ($sentAt -gt 0) -and ($a0.text.Length -gt $sentAt) -and ($a0.text.Substring(0, $sentAt) -ceq $b0.text.Substring(0, $sentAt))
$stampOk = (@($a0.at).Count -eq 1) -and ($a0.at[0] -match $dgStampRe) -and ($a0.sentinel -eq 0)
$blockOk = (@($a0.basis).Count -eq 1) -and ($a0.basis[0] -ceq $dgBasisWords) -and (@($a0.ms).Count -eq 1) -and ($a0.ms[0] -ceq $dgShaM) -and ($a0.spawnKey -eq 1)
$listOk = (@($a0.spawns).Count -eq 1) -and ($a0.spawns[0] -ceq '1:D-DGA')
$order = ($a0.text.IndexOf('consumed_at: 20') -ge 0) -and ($a0.text.IndexOf('consumed_at: 20') -lt $a0.text.IndexOf('consumed_basis:')) -and
         ($a0.text.IndexOf('consumed_basis:') -lt $a0.text.IndexOf('consumed_manifest_sha256:')) -and ($a0.text.IndexOf('consumed_manifest_sha256:') -lt $a0.text.IndexOf('consumed_spawns:'))
$crlfOk = ($a0.cr -eq $a0.lf) -and ($a0.bareLf -eq 0)
$rCOk = ($rC.exit -eq 0) -and $rC.spawned -and $headKept -and $stampOk -and $blockOk -and $listOk -and $order -and $crlfOk
Add-RCRow -Id 'c the FIRST spawn stamps and lists' -RowOk $rCOk `
    -Text ("exit={0} spawned={1} mint bytes before the sentinel untouched={2} one consumed_at, a stamp, no sentinel={3} basis words + manifest sha + one list key={4} list=[{5}] consumed_at first, then the rest in order={6} CRLF uniform={7}  (expect 0, True, True x6, [1:D-DGA])" -f $rC.exit, $rC.spawned, $headKept, $stampOk, $blockOk, (@($a0.spawns) -join ' '), $order, $crlfOk) -Said (Get-R28Said $rC.out)
$anCOk = $anC.present -and ((Get-DGField $anC 'gate_id') -ceq 'dg1') -and ((Get-DGField $anC 'spawn_seq') -ceq '1') -and ((Get-DGField $anC 'first_stamp') -ceq 'true') -and ($anC.sha -ne $anBefore.sha)
Add-RCRow -Id 'c the runner''s record names the gate' -RowOk $anCOk `
    -Text ("anchors rewritten={0} dispatch_gate block present={1} gate_id={2} spawn_seq={3} first_stamp={4}  (expect True, True, dg1, 1, true)" -f ($anC.sha -ne $anBefore.sha), $anC.present, (Get-DGField $anC 'gate_id'), (Get-DGField $anC 'spawn_seq'), (Get-DGField $anC 'first_stamp')) -Said ''

# ---- (c2) A HAND-ANNOTATED GATE: the first stamp touches no byte but the sentinel line -------------
# The mint writes the sentinel LAST, so (c) cannot see what happens to bytes AFTER it. Here an
# annotation line with trailing spaces and a blank line follow the sentinel; the stamped gate must
# be the old text with only the sentinel line replaced, followed by the appended block.
$dg16 = if ($dgSeeded) { New-DGGate -Id 'dg16' -BindsRel $dgManifestRel } else { $dg1 }
if ($dg16.ok) { [System.IO.File]::AppendAllText($dg16.path, "note: operator annotation   `r`n`r`n", (New-Object System.Text.UTF8Encoding($false))) }
$b16 = Get-DGGateFacts -Path $dg16.path
$r16 = Invoke-DGRun -Id 'D-DGA' -Gate 'dg16'
$a16 = Get-DGGateFacts -Path $dg16.path
$a16At = if (@($a16.at).Count -eq 1) { [string]$a16.at[0] } else { '' }
$kept16 = [regex]::Replace($b16.text, '(?m)^consumed_at:[^\r\n]*', ('consumed_at: ' + $a16At))
$rC2Ok = ($r16.exit -eq 0) -and ($a16At -match $dgStampRe) -and $a16.text.StartsWith($kept16, [System.StringComparison]::Ordinal) -and ((@($a16.spawns) -join ' ') -ceq '1:D-DGA')
Add-RCRow -Id 'c2 an annotated gate keeps every other byte' -RowOk $rC2Ok `
    -Text ("exit={0} the old text with only the sentinel line replaced is the new text's prefix={1} list=[{2}]  (expect 0, True, [1:D-DGA])" -f $r16.exit, $a16.text.StartsWith($kept16, [System.StringComparison]::Ordinal), (@($a16.spawns) -join ' ')) -Said (Get-R28Said $r16.out)

# ---- (d) THE SAME ID AGAIN ------------------------------------------------------------------------
$b0 = Get-DGGateFacts -Path $dg1.path
$rD = Invoke-DGRun -Id 'D-DGA' -Gate 'dg1'
Add-RCRefusalRow -Id 'd the same id again refuses' -Run $rD -Code 'RESPAWN' -Before $b0 -After (Get-DGGateFacts -Path $dg1.path)

# ---- (e) A NAMED ID WHOSE ARTIFACT'S SHA256 IS NOT THE MANIFEST'S ROW FOR IT ----------------------
$saveB = [System.IO.File]::ReadAllBytes($dgPathB)
[System.IO.File]::WriteAllText($dgPathB, ([System.IO.File]::ReadAllText($dgPathB) + "# edited after the manifest was authored`n"), (New-Object System.Text.UTF8Encoding($false)))
$b0 = Get-DGGateFacts -Path $dg1.path
$rE = Invoke-DGRun -Id 'D-DGB' -Gate 'dg1'
Add-RCRefusalRow -Id 'e an artifact whose sha is not its row refuses' -Run $rE -Code 'ARTIFACT-SHA' -Before $b0 -After (Get-DGGateFacts -Path $dg1.path)
[System.IO.File]::WriteAllBytes($dgPathB, $saveB)

# ---- (e2) A NAMED ID THE MANIFEST CARRIES NO ARTIFACTS ROW FOR ------------------------------------
$dg13 = if ($dgSeeded) { New-DGGate -Id 'dg13' -BindsRel $dgManifest3Rel } else { $dg1 }
$b0 = Get-DGGateFacts -Path $dg13.path
$rE2 = Invoke-DGRun -Id 'D-DGA' -Gate 'dg13'
Add-RCRefusalRow -Id 'e2 a named id with no artifacts row refuses' -Run $rE2 -Code 'ARTIFACT-SHA' -Before $b0 -After (Get-DGGateFacts -Path $dg13.path)

# ---- (f) THE SECOND NAMED SPAWN APPENDS ONE LINE AND NO SECOND BLOCK (the matching-sha control) --
$restored = ((Get-DGFileSha -Path $dgPathB) -ceq $dgShaB)
$b0 = Get-DGGateFacts -Path $dg1.path
$rF = Invoke-DGRun -Id 'D-DGB' -Gate 'dg1'
$a0 = Get-DGGateFacts -Path $dg1.path
$anF = Get-DGAnchorGate -Id 'D-DGB'
$expectTail = "  - {seq: 2, dispatch_id: D-DGB}`r`n"
$appendOnly = $a0.text.StartsWith($b0.text, [System.StringComparison]::Ordinal) -and ($a0.text.Substring($b0.text.Length) -ceq $expectTail)
$oneBlock = (@($a0.at).Count -eq 1) -and (@($a0.basis).Count -eq 1) -and (@($a0.ms).Count -eq 1) -and ($a0.spawnKey -eq 1)
$rFOk = $restored -and ($rF.exit -eq 0) -and $rF.spawned -and $appendOnly -and $oneBlock -and ((@($a0.spawns) -join ' ') -ceq '1:D-DGA 2:D-DGB') -and ($a0.cr -eq $a0.lf)
Add-RCRow -Id 'f the SECOND spawn appends one line' -RowOk $rFOk `
    -Text ("artifact restored={0} exit={1} spawned={2} the gate grew by exactly one CRLF spawn line and nothing else={3} consume keys each once={4} list=[{5}]  (expect True, 0, True, True, True, [1:D-DGA 2:D-DGB])" -f $restored, $rF.exit, $rF.spawned, $appendOnly, $oneBlock, (@($a0.spawns) -join ' ')) -Said (Get-R28Said $rF.out)
$anFOk = $anF.present -and ((Get-DGField $anF 'gate_id') -ceq 'dg1') -and ((Get-DGField $anF 'spawn_seq') -ceq '2') -and ((Get-DGField $anF 'first_stamp') -ceq 'false')
Add-RCRow -Id 'f ...and its record names the gate' -RowOk $anFOk `
    -Text ("dispatch_gate present={0} gate_id={1} spawn_seq={2} first_stamp={3}  (expect True, dg1, 2, false)" -f $anF.present, (Get-DGField $anF 'gate_id'), (Get-DGField $anF 'spawn_seq'), (Get-DGField $anF 'first_stamp')) -Said ''

# ---- (g) A FULL ROUND, AND A NAMED ID AGAIN ---------------------------------------------------------
# This input is BOTH beyond the count and a respawn -- D-DGA is already listed -- and the decision
# tests the count first, so it reports BEYOND-COUNT. (g2) is the row that isolates the count.
$b0 = Get-DGGateFacts -Path $dg1.path
$rG = Invoke-DGRun -Id 'D-DGA' -Gate 'dg1'
Add-RCRefusalRow -Id 'g a full round refuses (count tested first)' -Run $rG -Code 'BEYOND-COUNT' -Before $b0 -After (Get-DGGateFacts -Path $dg1.path)

# ---- (g2) THE COUNT ALONE: two spawns listed under THIS manifest, both of ids it does not name -----
# Only the count can refuse a named, unlisted id here, so a count check that counted only named ids
# would admit a THIRD spawn under a two-id manifest and this row would read it.
$dg12 = if ($dgSeeded) { New-DGGate -Id 'dg12' -BindsRel $dgManifestRel } else { $dg1 }
if ($dg12.ok) { Set-DGPlantedBlock -Path $dg12.path -ManifestSha $dgShaM -SpawnLines @('  - {seq: 1, dispatch_id: D-DGX}', '  - {seq: 2, dispatch_id: D-DGY}') }
$b0 = Get-DGGateFacts -Path $dg12.path
$rG2 = Invoke-DGRun -Id 'D-DGA' -Gate 'dg12'
Add-RCRefusalRow -Id 'g2 the count alone refuses a named, unlisted id' -Run $rG2 -Code 'BEYOND-COUNT' -Before $b0 -After (Get-DGGateFacts -Path $dg12.path)

# ---- (h) A GATE CONSUMED UNDER ANOTHER MANIFEST, and its control --------------------------------
$dg3 = if ($dgSeeded) { New-DGGate -Id 'dg3' -BindsRel $dgManifestRel } else { $dg1 }
if ($dg3.ok) { Set-DGPlantedBlock -Path $dg3.path -ManifestSha $dgShaM2 -SpawnLines @('  - {seq: 1, dispatch_id: D-DGA}') }
$b0 = Get-DGGateFacts -Path $dg3.path
$rH = Invoke-DGRun -Id 'D-DGB' -Gate 'dg3'
Add-RCRefusalRow -Id 'h consumed under another manifest refuses' -Run $rH -Code 'OTHER-MANIFEST' -Before $b0 -After (Get-DGGateFacts -Path $dg3.path)
# THE CONTROL: the identical plant naming THIS manifest's sha256 admits the next spawn, so the
# refusal above is about the manifest and not about a planted block.
$dg3c = if ($dgSeeded) { New-DGGate -Id 'dg3c' -BindsRel $dgManifestRel } else { $dg1 }
if ($dg3c.ok) { Set-DGPlantedBlock -Path $dg3c.path -ManifestSha $dgShaM -SpawnLines @('  - {seq: 1, dispatch_id: D-DGA}') }
$rHc = Invoke-DGRun -Id 'D-DGB' -Gate 'dg3c'
$hc = Get-DGGateFacts -Path $dg3c.path
$rHcOk = ($rHc.exit -eq 0) -and $rHc.spawned -and ((@($hc.spawns) -join ' ') -ceq '1:D-DGA 2:D-DGB')
Add-RCRow -Id 'h CONTROL the same plant under THIS manifest' -RowOk $rHcOk `
    -Text ("exit={0} spawned={1} list=[{2}]  (expect 0, True, [1:D-DGA 2:D-DGB])" -f $rHc.exit, $rHc.spawned, (@($hc.spawns) -join ' ')) -Said (Get-R28Said $rHc.out)

# ---- (i) A REVOKED GATE ---------------------------------------------------------------------------
$dg4 = if ($dgSeeded) { New-DGGate -Id 'dg4' -BindsRel $dgManifestRel } else { $dg1 }
if ($dg4.ok) { [System.IO.File]::AppendAllText($dg4.path, "revoked_at: 2026-09-24T00:00:00.000Z`r`n", (New-Object System.Text.UTF8Encoding($false))) }
$b0 = Get-DGGateFacts -Path $dg4.path
$rI = Invoke-DGRun -Id 'D-DGA' -Gate 'dg4'
Add-RCRefusalRow -Id 'i a revoked gate refuses' -Run $rI -Code 'REVOKED' -Before $b0 -After (Get-DGGateFacts -Path $dg4.path)

# ---- (j) AN EXPIRED GATE, AT THE FIRST SPAWN ------------------------------------------------------
$dg5 = if ($dgSeeded) { New-DGGate -Id 'dg5' -BindsRel $dgManifestRel } else { $dg1 }
if ($dg5.ok) { Set-DGExpiry -Path $dg5.path -Value $dgPast }
$b0 = Get-DGGateFacts -Path $dg5.path
$rJ = Invoke-DGRun -Id 'D-DGA' -Gate 'dg5'
Add-RCRefusalRow -Id 'j an expired gate refuses (first spawn)' -Run $rJ -Code 'EXPIRED' -Before $b0 -After (Get-DGGateFacts -Path $dg5.path)

# ---- (k) AN EXPIRED GATE, AT A LATER SPAWN: expiry binds EVERY spawn -----------------------------
$dg6 = if ($dgSeeded) { New-DGGate -Id 'dg6' -BindsRel $dgManifestRel } else { $dg1 }
$rK1 = Invoke-DGRun -Id 'D-DGA' -Gate 'dg6'
$k1 = Get-DGGateFacts -Path $dg6.path
if ($dg6.ok) { Set-DGExpiry -Path $dg6.path -Value $dgPast }
$b0 = Get-DGGateFacts -Path $dg6.path
$rK = Invoke-DGRun -Id 'D-DGB' -Gate 'dg6'
Add-RCRow -Id 'k the gate admitted its first spawn in time' -RowOk (($rK1.exit -eq 0) -and ((@($k1.spawns) -join ' ') -ceq '1:D-DGA')) `
    -Text ("exit={0} list=[{1}]  (expect 0, [1:D-DGA])" -f $rK1.exit, (@($k1.spawns) -join ' ')) -Said (Get-R28Said $rK1.out)
Add-RCRefusalRow -Id 'k ...then expired: the later spawn refuses' -Run $rK -Code 'EXPIRED' -Before $b0 -After (Get-DGGateFacts -Path $dg6.path)

# ---- (l) AN LF BODY IS STAMPED, IN LF --------------------------------------------------------------
# The control for (c)'s CRLF row: a writer that appended CRLF whatever the body carried would pass (c)
# and fail here, and one whose sentinel replacement needed a CR would leave the sentinel standing.
$dg7 = if ($dgSeeded) { New-DGGate -Id 'dg7' -BindsRel $dgManifestRel } else { $dg1 }
if ($dg7.ok) { [System.IO.File]::WriteAllText($dg7.path, ([System.IO.File]::ReadAllText($dg7.path) -replace "`r`n", "`n"), (New-Object System.Text.UTF8Encoding($false))) }
$l0 = Get-DGGateFacts -Path $dg7.path
$rL = Invoke-DGRun -Id 'D-DGA' -Gate 'dg7'
$l1 = Get-DGGateFacts -Path $dg7.path
$lStamped = ($l1.sentinel -eq 0) -and (@($l1.at).Count -eq 1) -and ($l1.at[0] -match $dgStampRe)
$rLOk = ($l0.cr -eq 0) -and ($rL.exit -eq 0) -and ($l1.cr -eq 0) -and $lStamped -and ((@($l1.spawns) -join ' ') -ceq '1:D-DGA') -and (@($l1.basis).Count -eq 1)
Add-RCRow -Id 'l an LF gate is stamped, in LF' -RowOk $rLOk `
    -Text ("CR before={0} exit={1} CR after={2} sentinel gone and one stamped consumed_at={3} list=[{4}]  (expect 0, 0, 0, True, [1:D-DGA])" -f $l0.cr, $rL.exit, $l1.cr, $lStamped, (@($l1.spawns) -join ' ')) -Said (Get-R28Said $rL.out)

# ---- (n) A FILE NAMED FOR ONE GATE THAT DECLARES ANOTHER -------------------------------------------
$dg14 = if ($dgSeeded) { New-DGGate -Id 'dg14' -BindsRel $dgManifestRel } else { $dg1 }
$dg14x = Join-Path $dgGates 'dispatch-dg14x.yaml'
if ($dg14.ok) { [System.IO.File]::WriteAllBytes($dg14x, [System.IO.File]::ReadAllBytes($dg14.path)) }
$b0 = Get-DGGateFacts -Path $dg14x
$rN = Invoke-DGRun -Id 'D-DGA' -Gate 'dg14x'
Add-RCRefusalRow -Id 'n a file whose own id is another gate refuses' -Run $rN -Code 'ID-MISMATCH' -Before $b0 -After (Get-DGGateFacts -Path $dg14x)

# ---- (o) A GATE ID THAT IS NOT AN ID ----------------------------------------------------------------
$b0 = Get-DGGateFacts -Path $dg1.path
$rO = Invoke-DGRun -Id 'D-DGA' -Gate '..\dg1'
Add-RCRefusalRow -Id 'o a gate id that is a path refuses' -Run $rO -Code 'BAD-ID' -Before $b0 -After (Get-DGGateFacts -Path $dg1.path)

# ---- (p) A FLOW-FORM MANIFEST ADMITS ------------------------------------------------------------
$dg15 = if ($dgSeeded) { New-DGGate -Id 'dg15' -BindsRel $dgManifestFRel } else { $dg1 }
$rP = Invoke-DGRun -Id 'D-DGA' -Gate 'dg15'
$p1 = Get-DGGateFacts -Path $dg15.path
Add-RCRow -Id 'p a flow-form spawn_order admits and stamps' -RowOk (($rP.exit -eq 0) -and $rP.spawned -and ((@($p1.spawns) -join ' ') -ceq '1:D-DGA')) `
    -Text ("exit={0} spawned={1} list=[{2}]  (expect 0, True, [1:D-DGA])" -f $rP.exit, $rP.spawned, (@($p1.spawns) -join ' ')) -Said (Get-R28Said $rP.out)

# ---- (m) NO GATE NAMED: THE RUNNER IS UNCHANGED ---------------------------------------------------
# The control that must read the SAME on the uncured runner and the cured one: without -DispatchGate
# the dispatch runs as it always has and its anchors carry no dispatch_gate block.
$rM = Invoke-DGRun -Id 'D-DGA'
$anM = Get-DGAnchorGate -Id 'D-DGA'
Add-RCRow -Id 'm CONTROL no gate named' -RowOk (($rM.exit -eq 0) -and $rM.spawned -and $anM.anchors -and (-not $anM.present)) `
    -Text ("exit={0} spawned={1} anchors written={2} dispatch_gate block present={3}  (expect 0, True, True, False)" -f $rM.exit, $rM.spawned, $anM.anchors, $anM.present) -Said (Get-R28Said $rM.out)
}
catch {
    $rcOk = $false
    $rcRows += '      MEMBER ABORTED -- an exception escaped the body; every row after it is UNMEASURED'
    $rcRows += ('        line ' + $_.InvocationInfo.ScriptLineNumber + ' :: ' + $_.Exception.GetType().Name + ' :: ' + ($_.Exception.Message -replace '[\r\n]+', ' '))
}
$rcDistinct = @(@($rcCodes | Where-Object { $_ }) | Sort-Object -Unique)
# NON-VACUITY, COUNTED OVER WHAT THE RUNNER EMITTED: a runner that refused every refusal row with one
# code would fail here even if each row's own assertion had somehow passed.
$rcExpectCodes = 'ARTIFACT-SHA,BAD-ID,BEYOND-COUNT,EXPIRED,ID-MISMATCH,OTHER-MANIFEST,RESPAWN,REVOKED,UNNAMED'
$rcDetail = @"
    THE $(@($rcRows | Where-Object { $_ -notlike '        runner said:*' -and $_ -notlike '      MEMBER ABORTED*' -and $_ -notlike '        line *' }).Count) ROWS, each a real runner or a fixture check, over gates the mint composed (several then edited by hand, as each row says); every gate field counted from the bytes on disk:
$($rcRows -join "`n")
    refusal rows: $rcRefusalRows; distinct codes they emitted: $($rcDistinct.Count) -> [$($rcDistinct -join ', ')]   (expect exactly [$($rcExpectCodes -replace ',', ', ')])
    the fixture root : $dgRoot
    the manifest     : $dgManifestRel  sha256 $dgShaM
    WHAT THIS MEMBER DOES NOT CLAIM: that two runners racing one gate are serialised -- that is R-D --
      nor what any other writer does to a dispatch gate, which is WP-4's T-36.
"@
Check -Id 'R-C' -Title 'ruling (i) candidate C5: the runner stamps a dispatch gate at spawn -- the first spawn replaces the consumed_at: null line in place, touching no other byte, and appends consumed_basis, consumed_manifest_sha256 and consumed_spawns with one line; a second manifest-named spawn appends one line and no second consume block; the runner''s anchors name the gate; and an unnamed id, a respawn, an artifact whose sha256 is not its manifest row, an id with no row, a full round, a spawn beyond the count on its own, a gate consumed under another manifest, a revoked gate, an expired gate at the first AND a later spawn, a file declaring another gate id and a gate id that is a path each REFUSE with exit 2, a named code, no spawn and the gate byte-unchanged -- with a flow-form manifest admitted, an LF-body control and a no-gate control' `
      -Ok ($rcOk -and (($rcDistinct -join ',') -ceq $rcExpectCodes)) -Detail $rcDetail

# =============================================================================================
# R-D -- FIRST STAMP WINS AGAINST THE OTHER WRITER OF A DISPATCH GATE'S CONSUME BLOCK, PLAYED HERE
# =============================================================================================
# WHICH WRITER. Only the runner writes a dispatch gate's consume block: mission-gate.ps1's settle is
# scoped to `push`, and the hook-side settle selects push gates only (WP-4's T-36 drives both and
# censuses the writers of consume keys). So the second writer of a consume block that exists is a
# SECOND RUNNER spawning under the same gate. The stamp opens the gate FileShare.None, re-reads it
# through that handle and DECIDES AGAIN over those bytes.
# NO SECOND RUNNER PROCESS IS STARTED BY THIS MEMBER (validator round 1).
# The second writer is PLAYED: in rows a and b by this instrument's own file handle, held open
# around one real runner; in rows d1-d5 inside one probe process -- by a file handle the probe
# holds in d1, and by calls to the library in d2-d5.
#
# END TO END, TWO HOLDS: an exclusive hold makes the runner's plain early read fail; a READ hold lets
# the early read through and makes the exclusive open at the stamp fail -- the second is the stamp's
# own refusal, reached through the real runner after the worktree is cut, which is why the run record
# must read closed. THE LIBRARY, DRIVEN DIRECTLY in a child under Set-StrictMode -Version Latest: the
# held stamp; two early decisions both saying "first" followed by two stamps; and a race placed by
# the library's -BeforeExclusiveOpen seam -- another stamp lands AFTER the call begins and BEFORE the
# exclusive open, so a stamp that had decided before its open would write a second block, and one
# that decides under the handle appends seq 2.
$rdRows = @()
$rdOk = $true
function Add-RDRow {
    param([string]$Id, [bool]$RowOk, [string]$Text, [string]$Said)
    if (-not $RowOk) { $script:rdOk = $false }
    $script:rdRows += ("    {0,-48} {1}  {2}" -f $Id, $Text, $(if ($RowOk) { 'ok' } else { 'MISMATCH' }))
    if ((-not $RowOk) -and $Said) { $script:rdRows += ("        said: {0}" -f (($Said -replace '\s+', ' ').Trim())) }
}
try {
# ---- (a) EXCLUSIVE HOLD: the early read fails, nothing is written ---------------------------------
$dg8 = if ($dgSeeded) { New-DGGate -Id 'dg8' -BindsRel $dgManifestRel } else { [pscustomobject]@{ ok = $false; path = (Join-Path $dgGates 'dispatch-dg8.yaml'); name = ''; said = '' } }
$b0 = Get-DGGateFacts -Path $dg8.path
$holdX = $null
$rDa = $null
try {
    $holdX = [System.IO.File]::Open($dg8.path, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, [System.IO.FileShare]::None)
    $rDa = Invoke-DGRun -Id 'D-DGA' -Gate 'dg8'
} finally { if ($null -ne $holdX) { $holdX.Dispose() } }
$a0 = Get-DGGateFacts -Path $dg8.path
$sameA = ($b0.sha -eq $a0.sha) -and ($b0.bytes -eq $a0.bytes)
Add-RDRow -Id 'a an EXCLUSIVE hold: the early read refuses' -RowOk (($rDa.exit -eq 2) -and ($rDa.code -ceq 'UNREADABLE') -and (-not $rDa.spawned) -and $sameA) `
    -Text ("exit={0} code={1} spawned={2} gate byte-unchanged={3}  (expect 2, UNREADABLE, False, True)" -f $rDa.exit, $(if ($rDa.code) { $rDa.code } else { '(none)' }), $rDa.spawned, $sameA) -Said (Get-R28Said $rDa.out)

# ---- (b) READ HOLD: the early read passes, the STAMP refuses, the run record closes ----------------
$rcPath = Join-Path $dgRoot '.mission-runtime\evidence\session-D-DGA\D-DGA.rc'
Remove-Item -LiteralPath $rcPath -Force -ErrorAction SilentlyContinue
$b0 = Get-DGGateFacts -Path $dg8.path
$holdR = $null
$rDb = $null
try {
    $holdR = [System.IO.File]::Open($dg8.path, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, [System.IO.FileShare]::Read)
    $rDb = Invoke-DGRun -Id 'D-DGA' -Gate 'dg8'
} finally { if ($null -ne $holdR) { $holdR.Dispose() } }
$a0 = Get-DGGateFacts -Path $dg8.path
$sameB = ($b0.sha -eq $a0.sha) -and ($b0.bytes -eq $a0.bytes)
$rcRead = if (Test-Path -LiteralPath $rcPath) { ([System.IO.File]::ReadAllText($rcPath)).Trim() } else { '(absent)' }
Add-RDRow -Id 'b a READ hold: the stamp refuses HELD' -RowOk (($rDb.exit -eq 2) -and ($rDb.code -ceq 'HELD') -and (-not $rDb.spawned) -and $sameB -and ($rcRead -ceq '2')) `
    -Text ("exit={0} code={1} spawned={2} gate byte-unchanged={3} run record rc={4}  (expect 2, HELD, False, True, 2)" -f $rDb.exit, $(if ($rDb.code) { $rDb.code } else { '(none)' }), $rDb.spawned, $sameB, $rcRead) -Said (Get-R28Said $rDb.out)

# ---- (c) CONTROL: released, the same spawn stamps -------------------------------------------------
$rDc = Invoke-DGRun -Id 'D-DGA' -Gate 'dg8'
$c0 = Get-DGGateFacts -Path $dg8.path
Add-RDRow -Id 'c CONTROL released: the same spawn stamps' -RowOk (($rDc.exit -eq 0) -and $rDc.spawned -and ((@($c0.spawns) -join ' ') -ceq '1:D-DGA') -and (@($c0.at).Count -eq 1)) `
    -Text ("exit={0} spawned={1} list=[{2}]  (expect 0, True, [1:D-DGA])" -f $rDc.exit, $rDc.spawned, (@($c0.spawns) -join ' ')) -Said (Get-R28Said $rDc.out)

# ---- (d) THE LIBRARY, DRIVEN DIRECTLY, UNDER Set-StrictMode -Version Latest ------------------------
$dg9 = if ($dgSeeded) { New-DGGate -Id 'dg9' -BindsRel $dgManifestRel } else { $dg8 }
$dg17 = if ($dgSeeded) { New-DGGate -Id 'dg17' -BindsRel $dgManifestRel } else { $dg8 }
$rdProbe = Join-Path $stubDir 'rd-stamp-probe.ps1'
$rdOut   = Join-Path $stubDir 'rd-stamp-probe.out.txt'
Remove-Item -LiteralPath $rdOut -Force -ErrorAction SilentlyContinue
Write-Utf8 -Path $rdProbe -Text @'
param([string]$ClassLib, [string]$GateLib, [string]$Root, [string]$Out)
Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'
$rows = New-Object System.Collections.Generic.List[string]
function Add-ProbeRow { param([string]$K, [string]$V) $rows.Add($K + '=' + $V) }
function Get-ProbeSha { param([string]$P) (Get-FileHash -Algorithm SHA256 -LiteralPath $P).Hash.ToLowerInvariant() }
function Get-ProbeKeys {
    param([string]$T)
    return (([regex]::Matches($T, '(?m)^consumed_at:')).Count.ToString() + '/' + ([regex]::Matches($T, '(?m)^consumed_basis:')).Count + '/' +
            ([regex]::Matches($T, '(?m)^consumed_manifest_sha256:')).Count + '/' + ([regex]::Matches($T, '(?m)^consumed_spawns:')).Count)
}
function Get-ProbeLines {
    param([string]$T)
    return ((@([regex]::Matches($T, '(?m)^  - \{seq: ([0-9]+), dispatch_id: ([^}\r\n]+)\}\r?$') | ForEach-Object { $_.Groups[1].Value + ':' + $_.Groups[2].Value })) -join ' ')
}
try {
    . $ClassLib
    . $GateLib
    $gate = Join-Path $Root '.mission\gates\dispatch-dg9.yaml'
    $pa = Join-Path $Root '.mission\dispatches\D-DGA.yaml'
    $pb = Join-Path $Root '.mission\dispatches\D-DGB.yaml'
    $s0 = Get-ProbeSha $gate
    $hold = [System.IO.File]::Open($gate, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, [System.IO.FileShare]::Read)
    try { $h = Invoke-LamDispatchGateStamp -MissionRoot $Root -GateId 'dg9' -DispatchId 'D-DGA' -DispatchPath $pa }
    finally { $hold.Dispose() }
    Add-ProbeRow 'held.ok' ([string]$h.ok)
    Add-ProbeRow 'held.code' ([string]$h.code)
    Add-ProbeRow 'held.unchanged' ([string]((Get-ProbeSha $gate) -ceq $s0))
    $ea = Get-LamDispatchGateDecision -MissionRoot $Root -GateId 'dg9' -DispatchId 'D-DGA' -DispatchPath $pa
    $eb = Get-LamDispatchGateDecision -MissionRoot $Root -GateId 'dg9' -DispatchId 'D-DGB' -DispatchPath $pb
    Add-ProbeRow 'early.A.first' ([string]$ea.first)
    Add-ProbeRow 'early.B.first' ([string]$eb.first)
    $sa = Invoke-LamDispatchGateStamp -MissionRoot $Root -GateId 'dg9' -DispatchId 'D-DGA' -DispatchPath $pa
    Add-ProbeRow 'stampA' ([string]$sa.ok + '/' + [string]$sa.first + '/' + [string]$sa.spawn_seq)
    $s1 = Get-ProbeSha $gate
    $sc = Invoke-LamDispatchGateStamp -MissionRoot $Root -GateId 'dg9' -DispatchId 'D-DGA' -DispatchPath $pa
    Add-ProbeRow 'stampAgainA' ([string]$sc.ok + '/' + [string]$sc.code)
    Add-ProbeRow 'stampAgainA.unchanged' ([string]((Get-ProbeSha $gate) -ceq $s1))
    $sb2 = Invoke-LamDispatchGateStamp -MissionRoot $Root -GateId 'dg9' -DispatchId 'D-DGB' -DispatchPath $pb
    Add-ProbeRow 'stampB' ([string]$sb2.ok + '/' + [string]$sb2.first + '/' + [string]$sb2.spawn_seq)
    $t = [System.IO.File]::ReadAllText($gate)
    Add-ProbeRow 'keys' (Get-ProbeKeys $t)
    Add-ProbeRow 'spawnLines' (Get-ProbeLines $t)
    # THE RACE, PLACED BY THE SEAM: on a fresh gate, a stamp of D-DGB whose -BeforeExclusiveOpen runs
    # another stamp of D-DGA to completion -- after the D-DGB call began, before its exclusive open.
    $gate17 = Join-Path $Root '.mission\gates\dispatch-dg17.yaml'
    # The seam's scriptblock runs in a scope below the library function, so it finds $Root and $pa
    # here by lookup and hands its result back through this hashtable, a shared reference.
    $raceBox = @{ contender = $null }
    $outer = Invoke-LamDispatchGateStamp -MissionRoot $Root -GateId 'dg17' -DispatchId 'D-DGB' -DispatchPath $pb -BeforeExclusiveOpen {
        $raceBox['contender'] = Invoke-LamDispatchGateStamp -MissionRoot $Root -GateId 'dg17' -DispatchId 'D-DGA' -DispatchPath $pa
    }
    $cont = $raceBox['contender']
    if ($null -eq $cont) { Add-ProbeRow 'race.contender' '(the seam did not run)' }
    else { Add-ProbeRow 'race.contender' ([string]$cont.ok + '/' + [string]$cont.first + '/' + [string]$cont.spawn_seq) }
    Add-ProbeRow 'race.outer' ([string]$outer.ok + '/' + [string]$outer.first + '/' + [string]$outer.spawn_seq)
    $t17 = [System.IO.File]::ReadAllText($gate17)
    Add-ProbeRow 'race.keys' (Get-ProbeKeys $t17)
    Add-ProbeRow 'race.spawnLines' (Get-ProbeLines $t17)
} catch {
    Add-ProbeRow 'ABORTED' ('line ' + $_.InvocationInfo.ScriptLineNumber + ' :: ' + $_.Exception.GetType().Name + ' :: ' + ($_.Exception.Message -replace '[\r\n]+', ' '))
}
[System.IO.File]::WriteAllLines($Out, $rows.ToArray())
'@
$prevEap = $ErrorActionPreference
$ErrorActionPreference = 'Continue'
try { $rdSaid = & powershell -NoProfile -ExecutionPolicy Bypass -File $rdProbe -ClassLib $dgClassLib -GateLib $dgGateLib -Root $dgRoot -Out $rdOut 2>&1 }
finally { $ErrorActionPreference = $prevEap }
$rdP = @{}
if (Test-Path -LiteralPath $rdOut) {
    foreach ($pl in [System.IO.File]::ReadAllLines($rdOut)) { $eq = $pl.IndexOf('='); if ($eq -gt 0) { $rdP[$pl.Substring(0, $eq)] = $pl.Substring($eq + 1) } }
}
function Get-RDP { param([string]$K) if ($rdP.ContainsKey($K)) { return [string]$rdP[$K] } return '(absent)' }
Add-RDRow -Id 'd1 the library''s stamp, held: refuses HELD' -RowOk (((Get-RDP 'held.ok') -ceq 'False') -and ((Get-RDP 'held.code') -ceq 'HELD') -and ((Get-RDP 'held.unchanged') -ceq 'True')) `
    -Text ("ok={0} code={1} gate unchanged={2}  (expect False, HELD, True)" -f (Get-RDP 'held.ok'), (Get-RDP 'held.code'), (Get-RDP 'held.unchanged')) -Said (Get-RDP 'ABORTED')
Add-RDRow -Id 'd2 two early decisions both say FIRST' -RowOk (((Get-RDP 'early.A.first') -ceq 'True') -and ((Get-RDP 'early.B.first') -ceq 'True')) `
    -Text ("A first={0} B first={1}  (expect True, True -- both read the fresh gate)" -f (Get-RDP 'early.A.first'), (Get-RDP 'early.B.first')) -Said (Get-RDP 'ABORTED')
Add-RDRow -Id 'd3 A stamps; A again refuses; B APPENDS' -RowOk (((Get-RDP 'stampA') -ceq 'True/True/1') -and ((Get-RDP 'stampAgainA') -ceq 'False/RESPAWN') -and ((Get-RDP 'stampAgainA.unchanged') -ceq 'True') -and ((Get-RDP 'stampB') -ceq 'True/False/2')) `
    -Text ("A={0} A again={1} (unchanged {2}) B={3}  (expect True/True/1, False/RESPAWN, True, True/False/2)" -f (Get-RDP 'stampA'), (Get-RDP 'stampAgainA'), (Get-RDP 'stampAgainA.unchanged'), (Get-RDP 'stampB')) -Said (Get-RDP 'ABORTED')
Add-RDRow -Id 'd4 ONE consume block, two spawn lines' -RowOk (((Get-RDP 'keys') -ceq '1/1/1/1') -and ((Get-RDP 'spawnLines') -ceq '1:D-DGA 2:D-DGB')) `
    -Text ("consumed_at/basis/manifest/spawns keys={0} spawn lines=[{1}]  (expect 1/1/1/1, [1:D-DGA 2:D-DGB])" -f (Get-RDP 'keys'), (Get-RDP 'spawnLines')) -Said ((@($rdSaid) | ForEach-Object { [string]$_ }) -join ' ')
Add-RDRow -Id 'd5 a stamp landing before the open is SEEN' -RowOk (((Get-RDP 'race.contender') -ceq 'True/True/1') -and ((Get-RDP 'race.outer') -ceq 'True/False/2') -and ((Get-RDP 'race.keys') -ceq '1/1/1/1') -and ((Get-RDP 'race.spawnLines') -ceq '1:D-DGA 2:D-DGB')) `
    -Text ("contender={0} outer={1} keys={2} lines=[{3}]  (expect True/True/1, True/False/2, 1/1/1/1, [1:D-DGA 2:D-DGB] -- a decision taken before the open would stamp FIRST again)" -f (Get-RDP 'race.contender'), (Get-RDP 'race.outer'), (Get-RDP 'race.keys'), (Get-RDP 'race.spawnLines')) -Said (Get-RDP 'ABORTED')
}
catch {
    $rdOk = $false
    $rdRows += '      MEMBER ABORTED -- an exception escaped the body; every row after it is UNMEASURED'
    $rdRows += ('        line ' + $_.InvocationInfo.ScriptLineNumber + ' :: ' + $_.Exception.GetType().Name + ' :: ' + ($_.Exception.Message -replace '[\r\n]+', ' '))
}
$rdDetail = @"
    THE $(@($rdRows | Where-Object { $_ -notlike '        said:*' -and $_ -notlike '      MEMBER ABORTED*' -and $_ -notlike '        line *' }).Count) ROWS:
$($rdRows -join "`n")
    the probe (Set-StrictMode -Version Latest, ErrorActionPreference Stop): $rdProbe
    WHAT THIS MEMBER DOES NOT CLAIM: that a writer which does NOT take the gate's exclusive handle is
      serialised against the stamp. mission-gate.ps1's revoke and reapprove read and rewrite a gate
      without it; they write no consume block, and a revoke landing between its own read and write
      can put back the bytes it read. Nor that a second runner PROCESS was driven: rows a and b
      hold the gate with this instrument's own file handle around one real runner, and rows d1-d5
      call the library inside one probe process.
"@
Check -Id 'R-D' -Title 'first stamp wins on a dispatch gate, the second writer PLAYED by this instrument and not by a second runner process: around one real runner, the instrument''s own file handle holding the gate exclusively refuses the early read and holding it for read refuses the stamp itself (HELD, run record closed rc 2), each with no spawn and the gate byte-unchanged; released, the same spawn stamps; and through calls to the library inside one probe process under StrictMode, two early decisions that both read FIRST end as one stamp and one appended line, and a stamp placed by the library''s seam between the call and its exclusive open is read by the decision taken under the handle, which appends seq 2' `
      -Ok $rdOk -Detail $rdDetail

# =============================================================================================
# R-E -- WHAT gate_present READS FOR A DISPATCH GATE THE RUNNER CONSUMED, AND WHO ASKS
# =============================================================================================
# FROM THE CODE: mission-goal-check.ps1's gate_present reads Get-LamGateState and sets
# ok = exists AND unconsumed AND NOT revoked AND NOT disqualified AND no kind mismatch, where
# unconsumed is `not consumed` and consumed is consumed_at set. So a dispatch gate the runner has
# stamped reads unconsumed=False, state=CONSUMED, and the detector fails. This member MEASURES that
# through the real evaluator, before and after a real spawn, and then reads the repository's own
# tracked goal files THROUGH THE EVALUATOR'S OWN DETECTOR READER (Read-GoalDetectors, lifted from
# mission-goal-check.ps1 by its AST) to find every gate_present detector and the gate file it opens.
$reRows = @()
$reOk = $true
function Add-RERow {
    param([string]$Id, [bool]$RowOk, [string]$Text, [string]$Said)
    if (-not $RowOk) { $script:reOk = $false }
    $script:reRows += ("    {0,-48} {1}  {2}" -f $Id, $Text, $(if ($RowOk) { 'ok' } else { 'MISMATCH' }))
    if ((-not $RowOk) -and $Said) { $script:reRows += ("        said: {0}" -f (($Said -replace '\s+', ' ').Trim())) }
}
function Invoke-REEval {
    param([string]$GoalId)
    $vp = Join-Path $dgRoot ".mission\goals\$GoalId.verdict.yaml"
    Remove-Item -LiteralPath $vp -Force -ErrorAction SilentlyContinue
    $prevEap = $ErrorActionPreference
    $ErrorActionPreference = 'Continue'
    try { $o = & powershell -NoProfile -ExecutionPolicy Bypass -File $dgGoalCheck -Goal $GoalId -MissionRoot $dgRoot 2>&1 }
    finally { $ErrorActionPreference = $prevEap }
    $txt = ((@($o) | ForEach-Object { [string]$_ }) -join "`n")
    $verdict = '(no verdict file)'
    if (Test-Path -LiteralPath $vp) { if ([System.IO.File]::ReadAllText($vp) -match '(?m)^verdict:\s*(\S+)') { $verdict = $Matches[1] } }
    $line = @(@($txt -split "`n") | Where-Object { $_ -match 'gate_present' } | Select-Object -First 1)
    return [pscustomobject]@{ verdict = $verdict; line = $(if ($line.Count) { ([string]$line[0]).Trim() } else { '' }); out = $txt }
}
try {
$dg10 = if ($dgSeeded) { New-DGGate -Id 'dg10' -BindsRel $dgManifestRel } else { [pscustomobject]@{ ok = $false; path = ''; name = ''; said = '' } }
Write-Utf8 -Path (Join-Path $dgRoot '.mission\goals\G-DGE.yaml') -Text "id: G-DGE`ndescription: `"R-E: one detector, gate_present over a dispatch gate`"`ndetectors:`n  - type: gate_present`n    kind: dispatch`n    id: dg10`n"
$re1 = Invoke-REEval -GoalId 'G-DGE'
Add-RERow -Id 'a before any spawn: present, unconsumed, MET' -RowOk (($re1.verdict -ceq 'MET') -and ($re1.line -match 'unconsumed=True') -and ($re1.line -match 'state=open')) `
    -Text ("verdict={0} unconsumed=True={1} state=open={2}  (expect MET, True, True)" -f $re1.verdict, [bool]($re1.line -match 'unconsumed=True'), [bool]($re1.line -match 'state=open')) -Said $re1.line
$reRun = Invoke-DGRun -Id 'D-DGA' -Gate 'dg10'
$re2 = Invoke-REEval -GoalId 'G-DGE'
Add-RERow -Id 'b after a spawn under it: CONSUMED, NOT_MET' -RowOk (($reRun.exit -eq 0) -and ($re2.verdict -ceq 'NOT_MET') -and ($re2.line -match 'unconsumed=False') -and ($re2.line -match 'state=CONSUMED')) `
    -Text ("runner exit={0} verdict={1} unconsumed=False={2} state=CONSUMED={3}  (expect 0, NOT_MET, True, True)" -f $reRun.exit, $re2.verdict, [bool]($re2.line -match 'unconsumed=False'), [bool]($re2.line -match 'state=CONSUMED')) -Said $re2.line

# ---- THE CENSUS, THROUGH THE EVALUATOR'S OWN READER ----------------------------------------------
$reTok = $null; $reErr = $null
$reAst = [System.Management.Automation.Language.Parser]::ParseFile($dgGoalCheck, [ref]$reTok, [ref]$reErr)
$reFn = @($reAst.FindAll({ param($n) ($n -is [System.Management.Automation.Language.FunctionDefinitionAst]) -and ($n.Name -ceq 'Read-GoalDetectors') }, $true))
$reLifted = ($reFn.Count -eq 1)
if ($reLifted) { . ([scriptblock]::Create($reFn[0].Extent.Text)) }
# THE READER'S CONTROL: a synthetic goal naming a dispatch gate three ways the evaluator honours -- a
# quoted kind, a list item opening on kind:, and a path: override -- must read as three detectors
# that open dispatch gates, or the census below could miss the same shapes.
$reCtl = Join-Path $sandbox 'r-e-census-control.yaml'
Write-Utf8 -Path $reCtl -Text "id: G-CTL`ndetectors:`n  - type: gate_present`n    kind: 'dispatch'`n    id: q1`n  - kind: dispatch`n    type: gate_present`n    id: q2`n  - type: gate_present`n    path: .mission/gates/dispatch-q3.yaml`n"
function Get-REGateFile {
    param($D)
    if ($D.ContainsKey('path') -and [string]$D['path']) { return ([string]$D['path'] -replace '\\', '/') }
    return ('.mission/gates/' + [string]$D['kind'] + '-' + [string]$D['id'] + '.yaml')
}
function Test-REDispatch {
    param($D)
    return (([string]$D['kind'] -ceq 'dispatch') -or ((Split-Path -Leaf (Get-REGateFile $D)) -clike 'dispatch-*'))
}
$reCtlHits = 0
if ($reLifted) { foreach ($d in @(Read-GoalDetectors -Path $reCtl)) { if (([string]$d['type'] -ceq 'gate_present') -and (Test-REDispatch $d)) { $reCtlHits++ } } }
Add-RERow -Id 'c CONTROL the evaluator''s reader sees three spellings' -RowOk ($reLifted -and ($reCtlHits -eq 3)) `
    -Text ("Read-GoalDetectors lifted by AST={0} dispatch gate_present detectors in the control goal={1}  (expect True, 3)" -f $reLifted, $reCtlHits) -Said ''
$reGoalLines = @()
$prevEap = $ErrorActionPreference
$ErrorActionPreference = 'Continue'
# EVERY GOAL FILE THIS TREE TRACKS, .mission/goals at any depth (WP-3's one pathspec): a repository of
# record's own root goals; in the framework repository, which runs no mission, its fixtures' -- the smoke mission's
# goal and the framework's synthetic goal of record.
try { $reGoalLines = @(& git -C $repoRoot ls-files -- ':(glob)**/.mission/goals/**' 2>&1 | ForEach-Object { [string]$_ }) }
finally { $ErrorActionPreference = $prevEap }
$reGoals = @($reGoalLines | Where-Object { ($_ -match '\.ya?ml$') -and ($_ -notmatch '\.verdict\.ya?ml$') })
$reFound = @()
$reDispatch = @()
if ($reLifted) {
    foreach ($g in $reGoals) {
        $gp = Join-Path $repoRoot ($g -replace '/', '\')
        if (-not (Test-Path -LiteralPath $gp)) { continue }
        foreach ($d in @(Read-GoalDetectors -Path $gp)) {
            if ([string]$d['type'] -cne 'gate_present') { continue }
            $reFound += ($g + ' -> ' + (Get-REGateFile $d))
            if (Test-REDispatch $d) { $reDispatch += ($g + ' -> ' + (Get-REGateFile $d)) }
        }
    }
}
Add-RERow -Id 'd the tracked goals open no dispatch gate' -RowOk ($reLifted -and ($reGoals.Count -gt 0) -and ($reFound.Count -gt 0) -and ($reDispatch.Count -eq 0)) `
    -Text ("goal files={0} gate_present detectors={1} opening a dispatch gate={2}  (expect >0, >0, 0) [{3}]" -f $reGoals.Count, $reFound.Count, $reDispatch.Count, ($reFound -join ', ')) -Said ''
}
catch {
    $reOk = $false
    $reRows += '      MEMBER ABORTED -- an exception escaped the body; every row after it is UNMEASURED'
    $reRows += ('        line ' + $_.InvocationInfo.ScriptLineNumber + ' :: ' + $_.Exception.GetType().Name + ' :: ' + ($_.Exception.Message -replace '[\r\n]+', ' '))
}
$reDetail = @"
    THE $(@($reRows | Where-Object { $_ -notlike '        said:*' -and $_ -notlike '      MEMBER ABORTED*' -and $_ -notlike '        line *' }).Count) ROWS:
$($reRows -join "`n")
    WHAT THIS MEMBER DOES NOT CLAIM: anything about untracked goal files in a checkout it cannot see,
      or about a goal written after this reading. The census is over git ls-files at this tree, every
      .mission/goals it tracks at any depth.
"@
Check -Id 'R-E' -Title 'what mission-goal-check''s gate_present reads for a dispatch gate the runner consumed: MET and unconsumed=True state=open before any spawn, NOT_MET and unconsumed=False state=CONSUMED after one, through the real evaluator -- and, read through the evaluator''s own Read-GoalDetectors (its reach shown on a control goal naming a dispatch gate three ways), this repository''s tracked goal files carry no gate_present detector that opens a dispatch gate' `
      -Ok $reOk -Detail $reDetail

# =============================================================================================
# R-F -- THE DISPATCH-GATE READERS REFUSE THE SHAPES THEY DO NOT WRITE, AND NEVER THROW ON THEM
# =============================================================================================
# The decision's readers are driven directly, under Set-StrictMode -Version Latest, over texts built
# here. Each refusing text has a control that the same reader accepts, so a reader that refused
# everything would fail the controls. THE -B ITEM is refused in the BLOCK form and its control here
# is the FLOW form only; the block form is admitted in R-C's fixture, not in this member.
$rfRows = @()
$rfOk = $true
function Add-RFRow {
    param([string]$Id, [bool]$RowOk, [string]$Text)
    if (-not $RowOk) { $script:rfOk = $false }
    $script:rfRows += ("    {0,-56} {1}  {2}" -f $Id, $Text, $(if ($RowOk) { 'ok' } else { 'MISMATCH' }))
}
try {
$rfProbe = Join-Path $stubDir 'rf-reader-probe.ps1'
$rfOut   = Join-Path $stubDir 'rf-reader-probe.out.txt'
Remove-Item -LiteralPath $rfOut -Force -ErrorAction SilentlyContinue
Write-Utf8 -Path $rfProbe -Text @'
param([string]$ClassLib, [string]$GateLib, [string]$Out)
Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'
$rows = New-Object System.Collections.Generic.List[string]
function Add-ProbeRow { param([string]$K, [string]$V) $rows.Add($K + '=' + $V) }
function Get-Verdict {
    param([scriptblock]$Call)
    try { $r = & $Call; return [string]$r.ok }
    catch { return 'THREW' }
}
try {
    . $ClassLib
    . $GateLib
    $sha = 'a' * 64
    $head = "kind: dispatch`r`nid: g`r`nconsumed_at: 2026-09-24T00:00:00.000Z`r`nconsumed_basis: spawn by the runner under this gate`r`nconsumed_manifest_sha256: $sha`r`nconsumed_spawns:`r`n"
    Add-ProbeRow 'id.plain' ([string](Test-LamDispatchId -Text 'dg1'))
    Add-ProbeRow 'id.lf' ([string](Test-LamDispatchId -Text ("dg1" + [char]10)))
    Add-ProbeRow 'id.kelvin' ([string](Test-LamDispatchId -Text ('D-' + [char]0x212A)))
    Add-ProbeRow 'order.flow' ((Read-LamDispatchManifestSpawnOrder -Text "spawn_order: [D-A, D-B]`n").ids -join ',')
    Add-ProbeRow 'order.flowOpen' (Get-Verdict { Read-LamDispatchManifestSpawnOrder -Text "spawn_order: [D-A,`n  D-B]`n" })
    Add-ProbeRow 'order.kelvin' (Get-Verdict { Read-LamDispatchManifestSpawnOrder -Text ("spawn_order: [D-" + [char]0x212A + "]`n") })
    Add-ProbeRow 'order.dashNoSpace' (Get-Verdict { Read-LamDispatchManifestSpawnOrder -Text "spawn_order:`n- D-A`n-D-B`n- D-C`nartifacts:`n" })
    Add-ProbeRow 'block.control' (Get-Verdict { Read-LamDispatchConsumeBlock -Text ($head + "  - {seq: 1, dispatch_id: D-A}`r`n") })
    Add-ProbeRow 'block.leadingZero' (Get-Verdict { Read-LamDispatchConsumeBlock -Text ($head + "  - {seq: 01, dispatch_id: D-A}`r`n") })
    Add-ProbeRow 'block.overflow' (Get-Verdict { Read-LamDispatchConsumeBlock -Text ($head + "  - {seq: 99999999999, dispatch_id: D-A}`r`n") })
    Add-ProbeRow 'block.trailingBlank' (Get-Verdict { Read-LamDispatchConsumeBlock -Text ($head + "  - {seq: 1, dispatch_id: D-A}`r`n`r`n") })
    Add-ProbeRow 'block.stampNotAStamp' (Get-Verdict { Read-LamDispatchConsumeBlock -Text ($head.Replace('2026-09-24T00:00:00.000Z', 'yesterday') + "  - {seq: 1, dispatch_id: D-A}`r`n") })
    $reordered = "consumed_basis: spawn by the runner under this gate`r`nconsumed_manifest_sha256: $sha`r`nkind: dispatch`r`nid: g`r`nconsumed_at: 2026-09-24T00:00:00.000Z`r`nconsumed_spawns:`r`n  - {seq: 1, dispatch_id: D-A}`r`n"
    Add-ProbeRow 'block.reordered' (Get-Verdict { Read-LamDispatchConsumeBlock -Text $reordered })
} catch {
    Add-ProbeRow 'ABORTED' ('line ' + $_.InvocationInfo.ScriptLineNumber + ' :: ' + $_.Exception.GetType().Name + ' :: ' + ($_.Exception.Message -replace '[\r\n]+', ' '))
}
[System.IO.File]::WriteAllLines($Out, $rows.ToArray())
'@
$prevEap = $ErrorActionPreference
$ErrorActionPreference = 'Continue'
try { $null = & powershell -NoProfile -ExecutionPolicy Bypass -File $rfProbe -ClassLib $dgClassLib -GateLib $dgGateLib -Out $rfOut 2>&1 }
finally { $ErrorActionPreference = $prevEap }
$rfP = @{}
if (Test-Path -LiteralPath $rfOut) {
    foreach ($pl in [System.IO.File]::ReadAllLines($rfOut)) { $eq = $pl.IndexOf('='); if ($eq -gt 0) { $rfP[$pl.Substring(0, $eq)] = $pl.Substring($eq + 1) } }
}
function Get-RFP { param([string]$K) if ($rfP.ContainsKey($K)) { return [string]$rfP[$K] } return '(absent)' }
Add-RFRow -Id 'id: a plain id passes; a trailing LF and a KELVIN SIGN do not' -RowOk (((Get-RFP 'id.plain') -ceq 'True') -and ((Get-RFP 'id.lf') -ceq 'False') -and ((Get-RFP 'id.kelvin') -ceq 'False')) `
    -Text ("plain={0} lf={1} kelvin={2}  (expect True, False, False)" -f (Get-RFP 'id.plain'), (Get-RFP 'id.lf'), (Get-RFP 'id.kelvin'))
Add-RFRow -Id 'spawn_order: a flow list reads; an open one, a KELVIN id and -B refuse' -RowOk (((Get-RFP 'order.flow') -ceq 'D-A,D-B') -and ((Get-RFP 'order.flowOpen') -ceq 'False') -and ((Get-RFP 'order.kelvin') -ceq 'False') -and ((Get-RFP 'order.dashNoSpace') -ceq 'False')) `
    -Text ("flow=[{0}] open={1} kelvin={2} -B={3}  (expect [D-A,D-B], False, False, False)" -f (Get-RFP 'order.flow'), (Get-RFP 'order.flowOpen'), (Get-RFP 'order.kelvin'), (Get-RFP 'order.dashNoSpace'))
Add-RFRow -Id 'consume block: the control reads' -RowOk ((Get-RFP 'block.control') -ceq 'True') -Text ("ok={0}  (expect True)" -f (Get-RFP 'block.control'))
Add-RFRow -Id 'consume block: seq 01, an Int32 overflow, a trailing blank refuse' -RowOk (((Get-RFP 'block.leadingZero') -ceq 'False') -and ((Get-RFP 'block.overflow') -ceq 'False') -and ((Get-RFP 'block.trailingBlank') -ceq 'False')) `
    -Text ("seq 01={0} overflow={1} trailing blank={2}  (expect False, False, False -- never THREW)" -f (Get-RFP 'block.leadingZero'), (Get-RFP 'block.overflow'), (Get-RFP 'block.trailingBlank'))
Add-RFRow -Id 'consume block: a non-stamp consumed_at and reordered keys refuse' -RowOk (((Get-RFP 'block.stampNotAStamp') -ceq 'False') -and ((Get-RFP 'block.reordered') -ceq 'False')) `
    -Text ("consumed_at: yesterday={0} keys reordered={1}  (expect False, False)" -f (Get-RFP 'block.stampNotAStamp'), (Get-RFP 'block.reordered'))
Add-RFRow -Id 'the probe completed' -RowOk (-not $rfP.ContainsKey('ABORTED')) -Text ("aborted={0}" -f (Get-RFP 'ABORTED'))
}
catch {
    $rfOk = $false
    $rfRows += '      MEMBER ABORTED -- an exception escaped the body; every row after it is UNMEASURED'
    $rfRows += ('        line ' + $_.InvocationInfo.ScriptLineNumber + ' :: ' + $_.Exception.GetType().Name + ' :: ' + ($_.Exception.Message -replace '[\r\n]+', ' '))
}
$rfDetail = @"
    THE $(@($rfRows | Where-Object { $_ -notlike '      MEMBER ABORTED*' -and $_ -notlike '        line *' }).Count) ROWS (the library driven in $rfProbe, StrictMode Latest):
$($rfRows -join "`n")
"@
Check -Id 'R-F' -Title 'the dispatch-gate readers, driven directly under Set-StrictMode -Version Latest: the gate id is matched ordinally with its end anchored (a trailing LF and a KELVIN SIGN refused; the start anchor is R-C''s row o), spawn_order reads a one-line flow list and refuses an open flow list, a KELVIN id and a block item written -B -- the -B refusal''s only control in this member is the flow-form one, the block form being admitted in R-C''s fixture and not here -- and the consume-block reader refuses a leading-zero seq, an Int32-overflowing seq, a trailing blank line, a consumed_at that is not a stamp and keys out of the order the runner writes them, returning a refusal rather than throwing, each against a control this member accepts' `
      -Ok $rfOk -Detail $rfDetail

# =============================================================================================
# BATCH-2 WP-G -- R-53 AND R-54 SHARE THIS FIXTURE
# =============================================================================================
# EACH MEMBER BUILDS ITS OWN MISSION ROOT: `git init`, then Assert-FixtureGitDir through
# Initialize-FixtureRepo BEFORE any git config call, then the seed commit through the verified -C; the pre-push
# decider installed; a prior anchors file so the verify stub is the gate; and an EMPTY spawn ledger at the path the
# runtime plane gives it, so every line the runner composes into it is visible and nothing else writes there. The
# worker is stubbed as every member here stubs it. No member below runs a real `claude -p`, touches a live mission
# plane, or points the runner at this repository.
function New-WpgMissionRoot {
    param([Parameter(Mandatory = $true)][string]$Name)
    $wpgBase = Join-Path $sandbox $Name
    $wpgRoot = Join-Path $wpgBase 'm'
    New-Item -ItemType Directory -Path (Join-Path $wpgRoot '.mission\dispatches') -Force | Out-Null
    Write-Utf8 -Path (Join-Path $wpgRoot '.mission\mission.yaml') -Text "id: mission-wpg-$Name`nstate: executing`n"
    Write-Utf8 -Path (Join-Path $wpgRoot 'src\seed.txt') -Text "seed`n"
    Write-Utf8 -Path (Join-Path $wpgRoot '.gitignore') -Text ".mission-runtime/`n"
    $wpgInit = Initialize-FixtureRepo -Root $wpgRoot -Config ([ordered]@{
        'user.email'     = 'wpg@instrument.local'
        'user.name'      = 'WP-G Instrument'
        'core.longpaths' = 'true'
    })
    $wpgPrev = $ErrorActionPreference
    $ErrorActionPreference = 'Continue'
    try {
        $null = & git -C $wpgRoot add -A 2>&1
        $null = & git -C $wpgRoot commit -q -m 'fixture seed' 2>&1
        $wpgHead = ("$(& git -C $wpgRoot rev-parse HEAD 2>&1)").Trim()
    } finally { $ErrorActionPreference = $wpgPrev }
    Install-DeciderIn -Repo $wpgRoot
    Write-Utf8 -Path (Join-Path $wpgRoot '.mission\dispatches\D-PRIOR.anchors.yaml') -Text "dispatch_id: D-PRIOR`nworktree_tip_sha: $wpgHead`ncapture_gaps_count: 0`n"
    $wpgLedger = Join-Path $wpgRoot '.mission-runtime\lam\spawn-ledger.jsonl'
    Write-Utf8 -Path $wpgLedger -Text ''
    return [pscustomobject]@{ root = $wpgRoot; head = $wpgHead; ledger = $wpgLedger; gitDir = $wpgInit.GitDir; commonDir = $wpgInit.CommonDir }
}
function Write-WpgDispatch {
    param([string]$Root, [string]$Id, [string]$ModelClass = 'coding-strong', [string]$Kind = 'mainline', [string]$Extra = '')
    Write-Utf8 -Path (Join-Path $Root ".mission\dispatches\$Id.yaml") -Text ("id: $Id`nmission_id: mission-wpg`nworker_id: w-$($Id.ToLower())`nkind: $Kind`nfeature_id: F-001`nassertion_targets: [A-001]`nspec_version: 1`nworktree_id: wt-$($Id.ToLower())`nmodel_class: $ModelClass`n" + $Extra + "goal_condition: `"the $Id fixture dispatch`"`n")
}
function Invoke-WpgRunner {
    # The real runner in a child process against the member's own root, the verify stub the gate. No -AllowIdReuse
    # unless -ReuseId: R-53 row 2 reads what the id-reuse guard does with an id a refusal left behind.
    param([string]$Root, [string]$Id, [string[]]$Extra = @(), [switch]$ReuseId)
    $wpgArgv = @('-NoProfile','-ExecutionPolicy','Bypass','-File',$runner,'-MissionRoot',$Root,'-Dispatch',$Id,'-VerifyCommand',$verifyPass) + @($Extra)
    if ($ReuseId) { $wpgArgv += '-AllowIdReuse' }
    $wpgSw = [System.Diagnostics.Stopwatch]::StartNew()
    $wpgPrev = $ErrorActionPreference
    $ErrorActionPreference = 'Continue'
    try { $wpgOut = & powershell @wpgArgv 2>&1; $wpgCode = $LASTEXITCODE }
    finally { $ErrorActionPreference = $wpgPrev }
    $wpgSw.Stop()
    return [pscustomobject]@{ out = ((@($wpgOut) | ForEach-Object { "$_" }) -join "`n"); exit = $wpgCode; ms = $wpgSw.ElapsedMilliseconds }
}
function Get-WpgLedgerLines {
    param([string]$Ledger)
    if (-not (Test-Path -LiteralPath $Ledger -PathType Leaf)) { return @() }
    return @(([System.IO.File]::ReadAllText($Ledger) -split "`n") | Where-Object { $_.Trim() })
}
function Get-WpgSha {
    param([string]$Path)
    if (-not (Test-Path -LiteralPath $Path -PathType Leaf)) { return '(absent)' }
    return (Get-FileHash -Algorithm SHA256 -LiteralPath $Path).Hash.ToLowerInvariant()
}
function Get-WpgAnchorField {
    param([string]$Path, [string]$Key)
    if (-not (Test-Path -LiteralPath $Path -PathType Leaf)) { return '(no anchors)' }
    $wpgText = [System.IO.File]::ReadAllText($Path)
    if ($wpgText -match ("(?m)^" + [regex]::Escape($Key) + ":[ \t]*(.*?)\r?$")) { return $Matches[1].Trim().Trim("'") }
    return '(absent)'
}
function Get-WpgFirstLines {
    param([string]$Text, [int]$Count = 3)
    return ((@($Text -split "`n") | Where-Object { $_.Trim() } | Select-Object -First $Count) -join ' // ')
}
# THE INTERPRETER, resolved as the runner resolves one (python, then py -3), for the composer rows.
$wpgPy = $null
foreach ($wpgCand in @([pscustomobject]@{ exe = 'python'; pre = @() }, [pscustomobject]@{ exe = 'py'; pre = @('-3') })) {
    $wpgCmd = @(Get-Command $wpgCand.exe -CommandType Application -ErrorAction SilentlyContinue) | Select-Object -First 1
    if ($wpgCmd) { $wpgPy = [pscustomobject]@{ source = $wpgCmd.Source; pre = @($wpgCand.pre) }; break }
}
$wpgComposer = Join-Path $repoRoot 'tools\lam\spawn_ledger.py'
function Invoke-WpgComposer {
    param([string[]]$PyArgs)
    if (-not $wpgPy) { return [pscustomobject]@{ code = $null; text = 'no Python interpreter on PATH (python, py -3)' } }
    $wpgPrev = $ErrorActionPreference
    $ErrorActionPreference = 'Continue'
    try { $wpgRaw = & $wpgPy.source @($wpgPy.pre) $wpgComposer @PyArgs 2>&1; $wpgCode = $LASTEXITCODE }
    finally { $ErrorActionPreference = $wpgPrev }
    return [pscustomobject]@{ code = $wpgCode; text = ((@($wpgRaw) | ForEach-Object { "$_" }) -join "`n") }
}
# THE STAMP THE TREE'S COMPOSER WRITES, from git (T-41's derivation): a line the runner composes must carry it.
$wpgPrevStamp = $ErrorActionPreference
$ErrorActionPreference = 'Continue'
try { $wpgBlob = ("$(& git -C $repoRoot rev-parse HEAD:tools/lam/spawn_ledger.py 2>&1)").Trim() } finally { $ErrorActionPreference = $wpgPrevStamp }
$wpgStamp = if ($wpgBlob -match '^[0-9a-f]{40}$') { 'tools/lam/spawn_ledger.py@' + $wpgBlob.Substring(0, 8) } else { '' }

# =============================================================================================
# R-53 -- THE PRE-SPAWN LOGIN PROBE (BATCH-2 WP-G (a))
# =============================================================================================
# THE ROW. Spawn seq 184, D-PB-2-S1: the runner verified, cut the tree and spawned a worker whose
# CLI could not authenticate -- "Failed to authenticate: OAuth session expired and could not be refreshed", worker
# exit 1 after 7 s. Nothing asked the CLI first. THE CHARTER'S FALSIFIER: "a probe returning
# anything but OK -> refused pre-spawn, no spawn line; OK -> spawns."
#
# THE STUB, SHOWN BEFORE THE FIRST RED. The worker is $workerOk, as everywhere in this file. The PROBE is stubbed
# too: the runner takes -LoginProbeCommand, a PowerShell script it runs in place of
#     claude -p "Reply with exactly the word OK and nothing else." --output-format text
# with those same arguments after it, from the same empty working directory, reading its stdout and exit code
# within -LoginProbeTimeoutSeconds. Each stub below has NO param() block (this file's stub rule: -p and
# --output-format then arrive in $args verbatim), writes what it saw -- its working directory, how many entries the
# directory held, its pid and its arguments -- to a file OUTSIDE that directory, so the directory stays as empty as
# the runner made it, and then answers: OK; NOT OK; nothing; OK with exit 1; or nothing at all for 60 s against a
# 4 s bound. NO real `claude -p` runs here.
#
# ON A TREE WITHOUT THE PROBE a runner that declares no -LoginProbeCommand cannot be handed one (PowerShell refuses
# the unknown parameter before the runner's body runs), so there the rows run WITHOUT the probe arguments and read
# what such a runner does -- it spawns -- instead of a parameter-binding error.
$r53ok = $true
$r53rows = New-Object System.Collections.Generic.List[string]
function Add-R53Row {
    param([string]$Label, [bool]$Ok, [string]$Said)
    if (-not $Ok) { $script:r53ok = $false }
    $script:r53rows.Add(('      {0,-108} : {1}{2}' -f $Label, $Ok, $(if ($Said) { '  -- ' + (($Said -replace '\s+', ' ').Trim()) } else { '' })))
}
function New-R53ProbeStub {
    param([string]$Path, [string]$Obs, [string]$Say, [int]$Exit = 0, [int]$SleepSeconds = 0)
    $r53Sleep = if ($SleepSeconds -gt 0) { "Start-Sleep -Seconds $SleepSeconds`n[System.IO.File]::WriteAllText('$Obs.finished', 'the sleep ended')`n" } else { '' }
    $r53Say = if ($Say) { "Write-Output '$Say'`n" } else { '' }
    Write-Utf8 -Path $Path -Text ("`$cwd = [Environment]::CurrentDirectory`n" +
        "`$n = @([System.IO.Directory]::GetFileSystemEntries(`$cwd)).Count`n" +
        "[System.IO.File]::WriteAllText('$Obs', ('cwd=' + `$cwd + [char]10 + 'entries=' + `$n + [char]10 + 'pid=' + `$PID + [char]10 + 'argc=' + `$args.Count + [char]10 + 'args=' + (`$args -join [string][char]31) + [char]10))`n" +
        $r53Sleep + $r53Say + "exit $Exit`n")
}
function Read-R53Obs {
    param([string]$Path)
    $o = @{}
    if (-not (Test-Path -LiteralPath $Path -PathType Leaf)) { return $o }
    foreach ($l in ([System.IO.File]::ReadAllText($Path) -split "`n")) { if ($l -match '^([a-z]+)=(.*)$') { $o[$Matches[1]] = $Matches[2] } }
    return $o
}
function Test-R53UnderOrAt {
    param([string]$Path, [string]$Root)
    if ((-not $Path) -or (-not $Root)) { return $false }
    try {
        $p = [System.IO.Path]::GetFullPath($Path).TrimEnd('\') + '\'
        $r = [System.IO.Path]::GetFullPath($Root).TrimEnd('\') + '\'
    } catch { return $false }
    return $p.StartsWith($r, [System.StringComparison]::OrdinalIgnoreCase)
}
$r53Prompt = 'Reply with exactly the word OK and nothing else.'
try {
$r53Seam = $false
try { $r53Seam = [bool]((Get-Command -Name $runner -ErrorAction Stop).Parameters.ContainsKey('LoginProbeCommand')) } catch { $r53Seam = $false }
$r53rows.Add('      the runner declares -LoginProbeCommand: ' + $r53Seam + $(if (-not $r53Seam) { ' -- NO PROBE SEAM ON THIS TREE: every row runs without the probe arguments and reads what this runner does' } else { '' }))
$r53rows.Add('      the stamp the tree''s composer writes (git rev-parse HEAD:tools/lam/spawn_ledger.py): ' + $(if ($wpgStamp) { $wpgStamp } else { '(none)' }))
$r53 = New-WpgMissionRoot -Name 'r53'
$r53rows.Add('      the member''s own mission root: ' + $r53.root + ' ; git dir ' + $r53.gitDir + ' ; common dir ' + $r53.commonDir)
$r53Obs = Join-Path $sandbox 'r53-obs'
New-Item -ItemType Directory -Path $r53Obs -Force | Out-Null
$r53Stubs = @{}
foreach ($r53Spec in @(
        @('notok-a', 'NOT OK', 0, 0), @('ok-a', 'OK', 0, 0), @('empty-b', '', 0, 0),
        @('nonzero-c', 'OK', 1, 0), @('timeout-d', '', 0, 60))) {
    $r53P = Join-Path $stubDir ('probe-r53-' + $r53Spec[0] + '.ps1')
    $r53O = Join-Path $r53Obs ($r53Spec[0] + '.txt')
    New-R53ProbeStub -Path $r53P -Obs $r53O -Say $r53Spec[1] -Exit $r53Spec[2] -SleepSeconds $r53Spec[3]
    $r53Stubs[$r53Spec[0]] = [pscustomobject]@{ path = $r53P; obs = $r53O }
}
$r53rows.Add('      the NOT OK stub, verbatim (the others differ only in the answer line, the exit and the sleep):')
foreach ($r53SL in ([System.IO.File]::ReadAllText($r53Stubs['notok-a'].path) -split "`n")) { if ($r53SL.Trim()) { $r53rows.Add('        | ' + $r53SL.TrimEnd("`r")) } }
function Get-R53ProbeArgs {
    param([string]$Key, [int]$Timeout = 0)
    if (-not $r53Seam) { return @() }
    $a = @('-LoginProbeCommand', $r53Stubs[$Key].path)
    if ($Timeout -gt 0) { $a += @('-LoginProbeTimeoutSeconds', [string]$Timeout) }
    return $a
}
function Get-R53Spawned {
    param([string]$Id)
    return (Test-Path -LiteralPath (Join-Path (Get-FixtureWorktreePath -Id $Id -Root $r53.root) 'worker-created.txt'))
}
foreach ($r53Id in @('D-R53-A', 'D-R53-B', 'D-R53-C', 'D-R53-D', 'D-R53-E')) { Write-WpgDispatch -Root $r53.root -Id $r53Id }

# ---- (1) NOT OK: refused before the spawn, nothing created, one refusal line ---------------------------------
$r53L0 = @(Get-WpgLedgerLines $r53.ledger).Count
$r53a = Invoke-WpgRunner -Root $r53.root -Id 'D-R53-A' -Extra (@('-WorkerCommand', $workerOk) + @(Get-R53ProbeArgs 'notok-a'))
$r53aSpawned = Get-R53Spawned 'D-R53-A'
Add-R53Row -Label '(1) FALSIFIER the probe answers NOT OK: REFUSED before the spawn -- exit 7, LOGIN-PROBE-NOT-OK named with its reason, no worker' `
    -Ok (($r53a.exit -eq 7) -and ($r53a.out -match '(?m)^mission-dispatch: REFUSED -- LOGIN-PROBE-NOT-OK: \S') -and (-not $r53aSpawned)) `
    -Said ("exit $($r53a.exit) spawned=$r53aSpawned :: " + (Get-WpgFirstLines $r53a.out 4))
$r53aWt = Get-FixtureWorktreePath -Id 'D-R53-A' -Root $r53.root
$r53aEv = Join-Path $r53.root '.mission-runtime\evidence\session-D-R53-A'
$r53aAn = Join-Path $r53.root '.mission\dispatches\D-R53-A.anchors.yaml'
$r53aHo = Join-Path $r53.root '.mission\dispatches\D-R53-A.handoff.yaml'
$r53aWake = Join-Path $r53.root '.mission-runtime\inbox\D-R53-A.wake'
$r53Prev = $ErrorActionPreference
$ErrorActionPreference = 'Continue'
try {
    $r53aWl = ((@(& git -C $r53.root worktree list --porcelain 2>&1) | ForEach-Object { "$_" }) -join "`n")
    $null = & git -C $r53.root show-ref --verify --quiet 'refs/heads/worktree-wt-D-R53-A' 2>&1
    $r53aBranch = ($LASTEXITCODE -eq 0)
    $r53aRr = @(& powershell -NoProfile -ExecutionPolicy Bypass -File $runner -MissionRoot $r53.root -Dispatch 'D-R53-A' -CheckRunRecord 2>&1 | ForEach-Object { "$_" })
    $r53aRrExit = $LASTEXITCODE
} finally { $ErrorActionPreference = $r53Prev }
$r53aNothing = (-not (Test-Path -LiteralPath $r53aWt)) -and ($r53aWl -notmatch 'wt-D-R53-A') -and (-not $r53aBranch) -and
               (-not (Test-Path -LiteralPath $r53aEv)) -and (-not (Test-Path -LiteralPath $r53aAn)) -and (-not (Test-Path -LiteralPath $r53aHo)) -and
               (-not (Test-Path -LiteralPath $r53aWake)) -and ($r53aRrExit -eq 1) -and ((@($r53aRr) -join ' ') -match 'run-record: never-started')
Add-R53Row -Label '(1b) and NOTHING was created: no worktree, no branch, no evidence session, no anchors, no handoff, no wake; the run record reads never-started' `
    -Ok $r53aNothing `
    -Said ("tree=$(Test-Path -LiteralPath $r53aWt) listed=$([bool]($r53aWl -match 'wt-D-R53-A')) branch=$r53aBranch session=$(Test-Path -LiteralPath $r53aEv) anchors=$(Test-Path -LiteralPath $r53aAn) handoff=$(Test-Path -LiteralPath $r53aHo) wake=$(Test-Path -LiteralPath $r53aWake) -CheckRunRecord exit $r53aRrExit :: " + ((@($r53aRr) | Select-Object -First 1) -join ''))
$r53aLines = @(Get-WpgLedgerLines $r53.ledger)
$r53aNew = @($r53aLines | Select-Object -Skip $r53L0)
$r53aObj = $null
if ($r53aNew.Count -eq 1) { try { $r53aObj = $r53aNew[0] | ConvertFrom-Json } catch { $r53aObj = $null } }
$r53aNote = ($null -ne $r53aObj) -and ($r53aObj.event -ceq 'note') -and ($r53aObj.refusal -ceq 'LOGIN-PROBE-NOT-OK') -and
            ($r53aObj.outcome -ceq 'REFUSED-BEFORE-SPAWN') -and ($r53aObj.dispatch_id -ceq 'D-R53-A') -and ($r53aObj.runner_exit -eq 7) -and
            ([string]$r53aObj.reason).Trim() -and [bool]$wpgStamp -and ($r53aObj.composed_by -ceq $wpgStamp)
Add-R53Row -Label '(1c) the refusal reaches the spawn ledger as ONE note composed by tools/lam/spawn_ledger.py: refusal LOGIN-PROBE-NOT-OK, its reason, runner_exit 7' `
    -Ok $r53aNote -Said ("new lines $($r53aNew.Count) :: " + $(if ($r53aNew.Count) { $r53aNew[0] } else { '(none)' }))

# ---- (2) the same id again, the probe answering OK, and NO -AllowIdReuse: the refusal burned nothing ------------
$r53b = Invoke-WpgRunner -Root $r53.root -Id 'D-R53-A' -Extra (@('-WorkerCommand', $workerOk) + @(Get-R53ProbeArgs 'ok-a'))
$r53bSpawned = Get-R53Spawned 'D-R53-A'
$r53bLines = @(Get-WpgLedgerLines $r53.ledger).Count
Add-R53Row -Label '(2) CONTROL the probe answers OK: the SAME id runs with no -AllowIdReuse, spawns, exit 0, and no line is added to the ledger' `
    -Ok (($r53b.exit -eq 0) -and $r53bSpawned -and ($r53b.out -match '(?m)^mission-dispatch: login probe -- OK') -and ($r53bLines -eq $r53aLines.Count)) `
    -Said ("exit $($r53b.exit) spawned=$r53bSpawned ledger lines $r53bLines (expect $($r53aLines.Count)) :: " + (Get-WpgFirstLines $r53b.out 3))

# ---- (3) the probe's working directory ---------------------------------------------------------------------------
$r53o = Read-R53Obs $r53Stubs['ok-a'].obs
$r53oCwd = [string]$r53o['cwd']
$r53oArgs = @(([string]$r53o['args']) -split [string][char]31)
$r53Home = [Environment]::GetFolderPath('UserProfile')
$r53oEmpty = ([string]$r53o['entries'] -ceq '0')
$r53oNotHere = $r53oCwd -and (-not (Test-R53UnderOrAt -Path $r53oCwd -Root $r53.root)) -and (-not (Test-R53UnderOrAt -Path $r53oCwd -Root $repoRoot)) -and
               (-not (Test-R53UnderOrAt -Path $r53oCwd -Root (Get-FixtureWorktreePath -Id 'D-R53-A' -Root $r53.root))) -and
               (-not (Test-R53UnderOrAt -Path $r53oCwd -Root $sandbox)) -and
               ([System.IO.Path]::GetFullPath($r53oCwd).TrimEnd('\') -ine [System.IO.Path]::GetFullPath($r53Home).TrimEnd('\'))
$r53oGone = $r53oCwd -and (-not (Test-Path -LiteralPath $r53oCwd))
$r53oArgv = (([string]$r53o['argc']) -ceq '4') -and ($r53oArgs.Count -eq 4) -and ($r53oArgs[0] -ceq '-p') -and ($r53oArgs[1] -ceq $r53Prompt) -and ($r53oArgs[2] -ceq '--output-format') -and ($r53oArgs[3] -ceq 'text')
Add-R53Row -Label '(3) the probe ran from an EMPTY scratch folder the runner made -- not the mission root, this repository, the tree or the home directory -- and removed' `
    -Ok ($r53oEmpty -and $r53oNotHere -and $r53oGone) -Said ("cwd '$r53oCwd' entries=$($r53o['entries']) removed=$r53oGone home '$r53Home'")
Add-R53Row -Label '(3b) and was handed exactly the real line''s arguments: -p, the prompt, --output-format, text' `
    -Ok $r53oArgv -Said ("argc=$($r53o['argc']) :: " + ($r53oArgs -join ' | '))

# ---- (4) nothing, a non-zero exit, no exit at all: each refused under its own name ---------------------------------
$r53c = Invoke-WpgRunner -Root $r53.root -Id 'D-R53-B' -Extra (@('-WorkerCommand', $workerOk) + @(Get-R53ProbeArgs 'empty-b'))
Add-R53Row -Label '(4a) FALSIFIER the probe prints NOTHING and exits 0: exit 7, LOGIN-PROBE-EMPTY, no worker' `
    -Ok (($r53c.exit -eq 7) -and ($r53c.out -match '(?m)^mission-dispatch: REFUSED -- LOGIN-PROBE-EMPTY: \S') -and (-not (Get-R53Spawned 'D-R53-B'))) `
    -Said ("exit $($r53c.exit) :: " + (Get-WpgFirstLines $r53c.out 3))
$r53d = Invoke-WpgRunner -Root $r53.root -Id 'D-R53-C' -Extra (@('-WorkerCommand', $workerOk) + @(Get-R53ProbeArgs 'nonzero-c'))
Add-R53Row -Label '(4b) FALSIFIER the probe prints OK and EXITS 1: exit 7, LOGIN-PROBE-NONZERO-EXIT -- the exit decides, not the word -- no worker' `
    -Ok (($r53d.exit -eq 7) -and ($r53d.out -match '(?m)^mission-dispatch: REFUSED -- LOGIN-PROBE-NONZERO-EXIT: \S') -and (-not (Get-R53Spawned 'D-R53-C'))) `
    -Said ("exit $($r53d.exit) :: " + (Get-WpgFirstLines $r53d.out 3))
$r53e = Invoke-WpgRunner -Root $r53.root -Id 'D-R53-D' -Extra (@('-WorkerCommand', $workerOk) + @(Get-R53ProbeArgs 'timeout-d' -Timeout 4))
$r53eObs = Read-R53Obs $r53Stubs['timeout-d'].obs
$r53ePid = 0
[void][int]::TryParse([string]$r53eObs['pid'], [ref]$r53ePid)
$r53eAlive = ($r53ePid -gt 0) -and ($null -ne (Get-Process -Id $r53ePid -ErrorAction SilentlyContinue))
$r53eFinished = Test-Path -LiteralPath ($r53Stubs['timeout-d'].obs + '.finished')
Add-R53Row -Label '(4c) FALSIFIER the probe never answers (60 s against -LoginProbeTimeoutSeconds 4): exit 7, LOGIN-PROBE-TIMEOUT inside 45 s, the probe killed, no worker' `
    -Ok (($r53e.exit -eq 7) -and ($r53e.out -match '(?m)^mission-dispatch: REFUSED -- LOGIN-PROBE-TIMEOUT: \S') -and ($r53e.ms -lt 45000) -and ($r53ePid -gt 0) -and (-not $r53eAlive) -and (-not $r53eFinished) -and (-not (Get-R53Spawned 'D-R53-D'))) `
    -Said ("exit $($r53e.exit) runner wall $($r53e.ms) ms; probe pid $r53ePid alive=$r53eAlive finished=$r53eFinished :: " + (Get-WpgFirstLines $r53e.out 3))

# ---- (5) the refusal lines, together -------------------------------------------------------------------------------
$r53All = @(Get-WpgLedgerLines $r53.ledger)
$r53Objs = @()
foreach ($r53Line in $r53All) { try { $r53Objs += ($r53Line | ConvertFrom-Json) } catch { $r53Objs += $null } }
$r53Codes = @($r53Objs | ForEach-Object { if ($null -ne $_) { [string]$_.refusal } else { '(not JSON)' } })
$r53WantCodes = @('LOGIN-PROBE-NOT-OK', 'LOGIN-PROBE-EMPTY', 'LOGIN-PROBE-NONZERO-EXIT', 'LOGIN-PROBE-TIMEOUT')
$r53CodesOk = ($r53Codes.Count -eq $r53WantCodes.Count)
if ($r53CodesOk) { for ($r53I = 0; $r53I -lt $r53WantCodes.Count; $r53I++) { if ($r53Codes[$r53I] -cne $r53WantCodes[$r53I]) { $r53CodesOk = $false } } }
$r53NoSpawn = (@($r53Objs | Where-Object { ($null -ne $_) -and ([string]$_.event -ceq 'spawn') }).Count -eq 0)
$r53Stamped = [bool]$wpgStamp -and (@($r53Objs | Where-Object { ($null -ne $_) -and ([string]$_.composed_by -ceq $wpgStamp) -and ([string]$_.event -ceq 'note') }).Count -eq $r53All.Count)
$r53Audit = Invoke-WpgComposer -PyArgs @('audit', '--ledger', $r53.ledger, '--after', '0', '--prefix-sha256', 'e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855')
$r53AuditOk = ($r53Audit.code -eq 0) -and ($r53Audit.text -match ('(?m)^RESULT PASS after_cutoff=' + $r53WantCodes.Count + ' violations=0 '))
Add-R53Row -Label '(5) the ledger holds exactly the four refusal notes in order -- NOT-OK, EMPTY, NONZERO-EXIT, TIMEOUT -- each stamped by the composer, NO spawn line' `
    -Ok ($r53CodesOk -and $r53NoSpawn -and $r53Stamped) -Said ("lines $($r53All.Count): " + ($r53Codes -join ', '))
Add-R53Row -Label '(5b) and the composer''s own forward-only audit, cut off at 0, PASSES over that ledger' `
    -Ok $r53AuditOk -Said ("exit $($r53Audit.code) :: " + (@($r53Audit.text -split "`n") | Where-Object { $_ -match '^RESULT ' } | Select-Object -First 1))

# ---- (6) the scope: a stubbed worker with no probe command -------------------------------------------------------------
$r53f = Invoke-WpgRunner -Root $r53.root -Id 'D-R53-E' -Extra @('-WorkerCommand', $workerOk)
Add-R53Row -Label '(6) a stubbed worker and NO -LoginProbeCommand: the probe is SKIPPED and says so -- no claude CLI is spawned by such a run -- and the worker spawns' `
    -Ok (($r53f.exit -eq 0) -and (Get-R53Spawned 'D-R53-E') -and ($r53f.out -match '(?m)^mission-dispatch: login probe -- SKIPPED')) `
    -Said ("exit $($r53f.exit) spawned=$(Get-R53Spawned 'D-R53-E') :: " + (Get-WpgFirstLines $r53f.out 3))
}
catch {
    Add-R53Row -Label 'MEMBER ABORTED -- an exception escaped the body; every row after it is UNMEASURED' `
        -Ok $false -Said ("line " + $_.InvocationInfo.ScriptLineNumber + " :: " + $_.Exception.GetType().Name + " :: " + ($_.Exception.Message -replace '[\r\n]+', ' '))
}
Check -Id 'R-53' -Title 'THE PRE-SPAWN LOGIN PROBE (BATCH-2 WP-G (a)): with the probe stubbed through -LoginProbeCommand and the worker stubbed, a probe answering NOT OK, nothing, OK with a non-zero exit, or nothing within the bound is REFUSED before the spawn with exit 7, its own LOGIN-PROBE-* name and no worker -- the NOT OK refusal read whole: no worktree, no branch, no evidence session, no anchors, no handoff, no wake, the run record never-started -- and each refusal reaches the spawn ledger as one note composed by tools/lam/spawn_ledger.py under its own refusal name, the NOT OK note read with its reason and runner_exit 7, with no spawn line and the composer''s audit passing; a probe answering OK spawns, and the same id refused earlier runs without -AllowIdReuse; the probe runs from an empty scratch folder that is not under the mission root, this repository or the tree and is not the home directory, which the runner removes, with exactly the real line''s arguments; and a stubbed worker with no probe command skips the probe and says so' `
      -Ok $r53ok -Detail ("      THE $(@($r53rows | Where-Object { $_ -match ' : (True|False)' }).Count) ROWS:`n" + ($r53rows -join "`n"))

# =============================================================================================
# R-54 -- THE RUNNER PLACES A VALIDATOR'S RESULT (BATCH-2 WP-G (b))
# =============================================================================================
# THE ROW. The runner read a validator's declared result_path in the validator's worktree first and
# the mission root second, recorded the verdict, and copied nothing; the goal's validator_pass_count reads tests/lam at
# the ROOT, so every validator result reached it only by an operator's act (the placement loop of standing C.5).
# THE CHARTER'S FALSIFIERS: "A complete with no file at the destination -> copy
# present, both hashes on the line, EQUAL; a complete with the destination present -> refused, destination
# byte-unchanged, the refusal ledgered; a complete whose source moved between hash and copy -> refused."
#
# THE VALIDATOR IS STUBBED IN ITS REAL SHAPE: it writes its result file in its own tree at the declared result_path
# and NO handoff -- tools/lam/settings/validator.json allows it exactly one edit path -- so the runner rejects the
# missing handoff at the shared path and exits 3, the designed validator completion. The probe is stubbed OK where
# the runner takes it (R-53), and skipped where it does not.
#
# THE COMPLETE LINE IS THE CEREMONY'S (the design this package states): rows (1b) and (2c) PLAY that step with the
# tree's own composer, reading the fields from the anchors the runner wrote, and read the result through the goal
# evaluator's unchanged reader, Test-LamLedgerBound, lifted by the parser from tools/lam/lam-verify-admission.ps1.
#
# ROW (3) DRIVES THE RUNNER'S OWN PLACEMENT FUNCTION, lifted from the shipped runner by the parser as R-49 lifts its
# name rules, through its -AfterSourceHash seam -- a scriptblock run after the source is hashed and before it is
# copied, which the runner never passes -- because no stub can move a file between two statements of another
# process. A tree whose runner defines no such function reads ABSENT there.
$r54ok = $true
$r54rows = New-Object System.Collections.Generic.List[string]
function Add-R54Row {
    param([string]$Label, [bool]$Ok, [string]$Said)
    if (-not $Ok) { $script:r54ok = $false }
    $script:r54rows.Add(('      {0,-108} : {1}{2}' -f $Label, $Ok, $(if ($Said) { '  -- ' + (($Said -replace '\s+', ' ').Trim()) } else { '' })))
}
function New-R54ValidatorStub {
    param([string]$Path, [string]$BodyFile, [string]$Rel)
    Write-Utf8 -Path $Path -Text ("`$root = `$env:LAM_WORKTREE`n" +
        "New-Item -ItemType File -Path (Join-Path `$root 'worker-created.txt') -Force | Out-Null`n" +
        "Write-Output 'R54-VALIDATOR-STUB'`n" +
        "`$dst = Join-Path `$root '$Rel'`n" +
        "New-Item -ItemType Directory -Path (Split-Path -Parent `$dst) -Force | Out-Null`n" +
        "Copy-Item -LiteralPath '$BodyFile' -Destination `$dst -Force`n" +
        "exit 0`n")
}
$r54BodyPass  = "# written by the R-54 fixture validator`nid: validator-A-R54`nvalidates: A-R54`nverdict: PASS`n"
$r54BodyPrior = "# the prior round's result at the same name, not yet archived`nid: validator-A-R54B`nverdict: REFUTED`n"
function Invoke-R54Validator {
    param([string]$Id, [string]$Rel, [string]$ModelClass = 'qa-validator')
    $r54Body = Join-Path $sandbox ("r54-body-$Id.yaml")
    Write-Utf8 -Path $r54Body -Text $r54BodyPass
    $r54Stub = Join-Path $stubDir ("validator-r54-$Id.ps1")
    New-R54ValidatorStub -Path $r54Stub -BodyFile $r54Body -Rel $Rel
    $r54Kind = if ($ModelClass -eq 'qa-validator') { 'read-only' } else { 'mainline' }
    Write-WpgDispatch -Root $r54.root -Id $Id -ModelClass $ModelClass -Kind $r54Kind -Extra ("validates: A-R54`nround: 1`nresult_path: $Rel`n")
    $r54Probe = if ($r54Seam) { @('-LoginProbeCommand', $r54ProbeOk) } else { @() }
    $r54Run = Invoke-WpgRunner -Root $r54.root -Id $Id -Extra (@('-WorkerCommand', $r54Stub) + $r54Probe)
    $r54Src = Join-Path (Get-FixtureWorktreePath -Id $Id -Root $r54.root) ($Rel -replace '/', '\')
    return [pscustomobject]@{ run = $r54Run; src = $r54Src; anchors = (Join-Path $r54.root ".mission\dispatches\$Id.anchors.yaml"); handoff = (Join-Path $r54.root ".mission\dispatches\$Id.handoff.yaml") }
}
function Invoke-R54Bound {
    # THE GOAL EVALUATOR'S UNCHANGED READER, lifted by the parser (Get-LamLedgerPath and Test-LamLedgerBound), asked
    # whether the file at $File is bound by a complete line of the root's ledger.
    param([string]$Root, [string]$File)
    return (& {
        $t = $null; $e = $null
        $ast = [System.Management.Automation.Language.Parser]::ParseFile((Join-Path $repoRoot 'tools\lam\lam-verify-admission.ps1'), [ref]$t, [ref]$e)
        $want = @('Get-LamLedgerPath', 'Test-LamLedgerBound')
        $fns = @($ast.FindAll({ param($n) $n -is [System.Management.Automation.Language.FunctionDefinitionAst] }, $true) | Where-Object { $want -ccontains $_.Name })
        if ($fns.Count -ne 2) { return [pscustomobject]@{ bound = $false; reason = "lifted $($fns.Count) of 2 functions" } }
        foreach ($fn in $fns) { . ([scriptblock]::Create($fn.Extent.Text)) }
        return (Test-LamLedgerBound -MissionRoot $Root -FilePath $File)
    })
}
try {
$r54Seam = $false
try { $r54Seam = [bool]((Get-Command -Name $runner -ErrorAction Stop).Parameters.ContainsKey('LoginProbeCommand')) } catch { $r54Seam = $false }
$r54ProbeOk = Join-Path $stubDir 'probe-r54-ok.ps1'
New-R53ProbeStub -Path $r54ProbeOk -Obs (Join-Path $sandbox 'r54-probe-obs.txt') -Say 'OK'
$r54 = New-WpgMissionRoot -Name 'r54'
$r54rows.Add('      the member''s own mission root: ' + $r54.root + ' ; git dir ' + $r54.gitDir + ' ; common dir ' + $r54.commonDir + ' ; probe stubbed OK: ' + $r54Seam)

# ---- (1) the destination absent: placed -------------------------------------------------------------------------
$r54Rel1 = 'tests/lam/validator-A-R54.result.yaml'
$r54Dst1 = Join-Path $r54.root ($r54Rel1 -replace '/', '\')
$r54Absent1 = -not (Test-Path -LiteralPath $r54Dst1)
$r54a = Invoke-R54Validator -Id 'D-R54-A' -Rel $r54Rel1
$r54aSrcSha = Get-WpgSha $r54a.src
$r54aDstSha = Get-WpgSha $r54Dst1
$r54aTimes = $false
if ((Test-Path -LiteralPath $r54Dst1 -PathType Leaf) -and (Test-Path -LiteralPath $r54a.src -PathType Leaf)) {
    $r54aS = Get-Item -LiteralPath $r54a.src
    $r54aD = Get-Item -LiteralPath $r54Dst1
    $r54aTimes = ($r54aS.LastWriteTimeUtc -eq $r54aD.LastWriteTimeUtc) -and ($r54aS.CreationTimeUtc -eq $r54aD.CreationTimeUtc)
}
$r54aPl = Get-WpgAnchorField $r54a.anchors 'validator_result_placement'
$r54aPlSha = Get-WpgAnchorField $r54a.anchors 'validator_result_placement_sha256'
$r54aPlSrcSha = Get-WpgAnchorField $r54a.anchors 'validator_result_placement_source_sha256'
Add-R54Row -Label '(1) FALSIFIER a validator complete, the destination ABSENT before: the result is PLACED at the root''s tests/lam, byte-equal to the source, creation and last-write times kept' `
    -Ok ($r54Absent1 -and ($r54a.run.exit -eq 3) -and ($r54aSrcSha -match '^[0-9a-f]{64}$') -and ($r54aDstSha -ceq $r54aSrcSha) -and $r54aTimes -and
         ($r54a.run.out -match '(?m)^mission-dispatch: validator result PLACED') -and ($r54a.run.out -notmatch 'RESULT-PLACEMENT-REFUSED')) `
    -Said ("absent before=$r54Absent1 exit $($r54a.run.exit) (3: the handoff rejected at the shared path, the designed validator completion); source $r54aSrcSha; copy $r54aDstSha; times equal=$r54aTimes :: " + (Get-WpgFirstLines ((@($r54a.run.out -split "`n") | Where-Object { $_ -match 'validator result|PLACE' }) -join "`n") 2))
Add-R54Row -Label '(1a) the anchors carry the placement: placed, the copy''s sha256 and the source''s, EQUAL, both equal to the file now at the destination' `
    -Ok (($r54aPl -ceq 'placed') -and ($r54aPlSha -ceq $r54aDstSha) -and ($r54aPlSrcSha -ceq $r54aSrcSha) -and ($r54aPlSha -ceq $r54aPlSrcSha)) `
    -Said ("validator_result_placement=$r54aPl sha256=$r54aPlSha source_sha256=$r54aPlSrcSha")
$r54aLedgerBefore = @(Get-WpgLedgerLines $r54.ledger).Count
$r54aLine = Join-Path $sandbox 'r54-complete-a.json'
$r54aRec = [ordered]@{
    event = 'complete'; seq = 1; kind = 'validator'; role = 'qa-validator'; dispatch_id = 'D-R54-A'; validates = 'A-R54'; round = 1
    verdict = 'PASS'; result_path = $r54Rel1; result_sha256 = $r54aPlSha; result_source_sha256 = $r54aPlSrcSha
    result_source_path = (Get-WpgAnchorField $r54a.anchors 'validator_result_placement_source'); result_dest_path = (Get-WpgAnchorField $r54a.anchors 'validator_result_placement_destination')
}
Write-Utf8 -Path $r54aLine -Text ($r54aRec | ConvertTo-Json -Compress)
$r54aAp = Invoke-WpgComposer -PyArgs @('append', '--ledger', $r54.ledger, '--line-file', $r54aLine)
$r54aApObj = $null
if (($r54aAp.code -eq 0) -and ($r54aAp.text -match '(?m)^APPENDED line \d+ to .*?: (\{.*\})\r?$')) { try { $r54aApObj = $Matches[1] | ConvertFrom-Json } catch { $r54aApObj = $null } }
$r54aBound = Invoke-R54Bound -Root $r54.root -File $r54Dst1
Add-R54Row -Label '(1b) THE CEREMONY''S STEP, PLAYED: the composer APPENDS the complete line from those anchors, result_sha256 (the copy''s) EQUAL to result_source_sha256' `
    -Ok (($null -ne $r54aApObj) -and ([string]$r54aApObj.result_sha256 -ceq $r54aDstSha) -and ([string]$r54aApObj.result_source_sha256 -ceq $r54aSrcSha) -and
         ([string]$r54aApObj.result_dest_path).Trim() -and ([string]$r54aApObj.result_source_path).Trim() -and ($r54aLedgerBefore -eq 0)) `
    -Said ("exit $($r54aAp.code) :: " + (Get-WpgFirstLines $r54aAp.text 2))
Add-R54Row -Label '(1c) and the goal evaluator''s UNCHANGED reader, Test-LamLedgerBound, binds the placed copy through result_sha256' `
    -Ok ([bool]$r54aBound.bound) -Said ("bound=$($r54aBound.bound) :: $($r54aBound.reason)")

# ---- (2) the destination present: refused, byte-unchanged, ledgered ---------------------------------------------------
$r54Rel2 = 'tests/lam/validator-A-R54B.result.yaml'
$r54Dst2 = Join-Path $r54.root ($r54Rel2 -replace '/', '\')
Write-Utf8 -Path $r54Dst2 -Text $r54BodyPrior
[System.IO.File]::SetLastWriteTimeUtc($r54Dst2, [datetime]::new(2026, 1, 1, 0, 0, 0, [System.DateTimeKind]::Utc))
$r54bBefore = Get-WpgSha $r54Dst2
$r54bTimeBefore = [System.IO.File]::GetLastWriteTimeUtc($r54Dst2)
$r54bLedger0 = @(Get-WpgLedgerLines $r54.ledger).Count
$r54b = Invoke-R54Validator -Id 'D-R54-B' -Rel $r54Rel2
$r54bAfter = Get-WpgSha $r54Dst2
$r54bTimeAfter = [System.IO.File]::GetLastWriteTimeUtc($r54Dst2)
$r54bHo = if (Test-Path -LiteralPath $r54b.handoff) { [System.IO.File]::ReadAllText($r54b.handoff) } else { '' }
Add-R54Row -Label '(2) FALSIFIER a validator complete, the destination PRESENT before: the copy is REFUSED, the destination byte-unchanged (hashed before and after)' `
    -Ok (($r54b.run.out -match '(?m)^mission-dispatch: RESULT-PLACEMENT-REFUSED-DESTINATION-PRESENT') -and ($r54bAfter -ceq $r54bBefore) -and ($r54bTimeAfter -eq $r54bTimeBefore) -and
         ($r54b.run.exit -eq 3) -and ($r54bHo -match 'RESULT-PLACEMENT-REFUSED-DESTINATION-PRESENT')) `
    -Said ("exit $($r54b.run.exit); before $r54bBefore after $r54bAfter; mtime unchanged=$($r54bTimeAfter -eq $r54bTimeBefore); in the rejection record=$([bool]($r54bHo -match 'RESULT-PLACEMENT-REFUSED'))")
Add-R54Row -Label '(2a) the anchors record it: refused-destination-present, the destination''s sha256 before and after, EQUAL' `
    -Ok (((Get-WpgAnchorField $r54b.anchors 'validator_result_placement') -ceq 'refused-destination-present') -and
         ((Get-WpgAnchorField $r54b.anchors 'validator_result_placement_destination_sha256_before') -ceq $r54bBefore) -and
         ((Get-WpgAnchorField $r54b.anchors 'validator_result_placement_destination_sha256_after') -ceq $r54bBefore)) `
    -Said ("placement=$(Get-WpgAnchorField $r54b.anchors 'validator_result_placement') before=$(Get-WpgAnchorField $r54b.anchors 'validator_result_placement_destination_sha256_before') after=$(Get-WpgAnchorField $r54b.anchors 'validator_result_placement_destination_sha256_after')")
$r54bNew = @(@(Get-WpgLedgerLines $r54.ledger) | Select-Object -Skip $r54bLedger0)
$r54bObj = $null
if ($r54bNew.Count -eq 1) { try { $r54bObj = $r54bNew[0] | ConvertFrom-Json } catch { $r54bObj = $null } }
Add-R54Row -Label '(2b) the refusal LEDGERED: one note composed by tools/lam/spawn_ledger.py, refusal RESULT-PLACEMENT-DESTINATION-PRESENT, both destination hashes' `
    -Ok (($null -ne $r54bObj) -and ($r54bObj.event -ceq 'note') -and ($r54bObj.refusal -ceq 'RESULT-PLACEMENT-DESTINATION-PRESENT') -and ($r54bObj.dispatch_id -ceq 'D-R54-B') -and
         ($r54bObj.runner_exit -eq 3) -and ([string]$r54bObj.reason).Trim() -and ([string]$r54bObj.destination_sha256_before -ceq $r54bBefore) -and
         ([string]$r54bObj.destination_sha256_after -ceq $r54bBefore) -and [bool]$wpgStamp -and ($r54bObj.composed_by -ceq $wpgStamp)) `
    -Said ("new lines $($r54bNew.Count) :: " + $(if ($r54bNew.Count) { $r54bNew[0] } else { '(none)' }))
$r54bSrcSha = Get-WpgSha $r54b.src
$r54bLine = Join-Path $sandbox 'r54-complete-b.json'
$r54bRec = [ordered]@{
    event = 'complete'; seq = 2; kind = 'validator'; role = 'qa-validator'; dispatch_id = 'D-R54-B'; validates = 'A-R54'; round = 1
    verdict = 'PASS'; result_path = $r54Rel2; result_sha256 = $r54bSrcSha; result_source_sha256 = $r54bSrcSha
    result_source_path = $r54b.src; result_dest_path = $r54Dst2
}
Write-Utf8 -Path $r54bLine -Text ($r54bRec | ConvertTo-Json -Compress)
$r54bLedgerSha = Get-WpgSha $r54.ledger
$r54bAp = Invoke-WpgComposer -PyArgs @('append', '--ledger', $r54.ledger, '--line-file', $r54bLine)
Add-R54Row -Label '(2c) and the ceremony CANNOT bind the source over the stale destination: the composer REFUSES that complete line, the ledger byte-unchanged' `
    -Ok (($r54bAp.code -eq 2) -and ($r54bAp.text -match '(?m)^REFUSED: ') -and ($r54bAp.text -match 'result_dest_path') -and ((Get-WpgSha $r54.ledger) -ceq $r54bLedgerSha)) `
    -Said ("exit $($r54bAp.code) :: " + (Get-WpgFirstLines $r54bAp.text 2))

# ---- (3) the source moved between the hash and the copy -------------------------------------------------------------
$r54c = & {
    $t = $null; $e = $null
    $ast = [System.Management.Automation.Language.Parser]::ParseFile($runner, [ref]$t, [ref]$e)
    $fn = @($ast.FindAll({ param($n) ($n -is [System.Management.Automation.Language.FunctionDefinitionAst]) -and ($n.Name -ceq 'Invoke-LamResultPlacement') }, $true))
    $o = [pscustomobject]@{ lifted = $fn.Count; moved = $null; control = $null; movedDst = $true; leftovers = -1; controlSha = ''; srcSha = '' }
    if ($fn.Count -ne 1) { return $o }
    . ([scriptblock]::Create($fn[0].Extent.Text))
    $dir = Join-Path $sandbox 'r54-l3'
    $src = Join-Path $dir 'wt\tests\lam\validator-A-R54M.result.yaml'
    $dst = Join-Path $dir 'root\tests\lam\validator-A-R54M.result.yaml'
    Write-Utf8 -Path $src -Text $r54BodyPass
    $mover = { [System.IO.File]::WriteAllText($src, "# rewritten after the runner hashed it`nverdict: REFUTED`n") }.GetNewClosure()
    $o.moved = Invoke-LamResultPlacement -Source $src -Destination $dst -AfterSourceHash $mover
    $o.movedDst = (Test-Path -LiteralPath $dst)
    $o.leftovers = @(Get-ChildItem -LiteralPath (Split-Path -Parent $dst) -Force -ErrorAction SilentlyContinue).Count
    Write-Utf8 -Path $src -Text $r54BodyPass
    $o.control = Invoke-LamResultPlacement -Source $src -Destination $dst
    $o.controlSha = if (Test-Path -LiteralPath $dst -PathType Leaf) { (Get-FileHash -Algorithm SHA256 -LiteralPath $dst).Hash.ToLowerInvariant() } else { '(absent)' }
    $o.srcSha = (Get-FileHash -Algorithm SHA256 -LiteralPath $src).Hash.ToLowerInvariant()
    return $o
}
Add-R54Row -Label '(3) FALSIFIER the source MOVED between the hash and the copy (the runner''s own function, its seam between them): REFUSED, nothing at the destination, no temp left' `
    -Ok (($r54c.lifted -eq 1) -and ($null -ne $r54c.moved) -and ($r54c.moved.outcome -ceq 'refused-source-moved') -and (-not $r54c.movedDst) -and ($r54c.leftovers -eq 0) -and
         ($r54c.moved.source_sha256 -cne $r54c.moved.source_sha256_after)) `
    -Said $(if ($r54c.lifted -ne 1) { "ABSENT: the runner defines $($r54c.lifted) function(s) named Invoke-LamResultPlacement" } else { "outcome=$($r54c.moved.outcome) destination present=$($r54c.movedDst) entries left in its folder=$($r54c.leftovers) hashed $($r54c.moved.source_sha256) re-read $($r54c.moved.source_sha256_after) :: $($r54c.moved.reason)" })
Add-R54Row -Label '(3c) CONTROL the same function with no seam PLACES the file, byte-equal' `
    -Ok (($r54c.lifted -eq 1) -and ($null -ne $r54c.control) -and ($r54c.control.outcome -ceq 'placed') -and ($r54c.controlSha -ceq $r54c.srcSha)) `
    -Said $(if ($r54c.lifted -ne 1) { 'ABSENT' } else { "outcome=$($r54c.control.outcome) copy $($r54c.controlSha) source $($r54c.srcSha)" })

# ---- (4) a worker's complete places nothing ----------------------------------------------------------------------------
$r54Rel4 = 'tests/lam/validator-A-R54W.result.yaml'
$r54Dst4 = Join-Path $r54.root ($r54Rel4 -replace '/', '\')
$r54d = Invoke-R54Validator -Id 'D-R54-C' -Rel $r54Rel4 -ModelClass 'coding-strong'
$r54dPl = Get-WpgAnchorField $r54d.anchors 'validator_result_placement'
Add-R54Row -Label '(4) CONTROL a WORKER dispatch with the same file in its tree: nothing is placed at the root''s tests/lam' `
    -Ok ((Test-Path -LiteralPath $r54d.src -PathType Leaf) -and (-not (Test-Path -LiteralPath $r54Dst4)) -and (($r54dPl -ceq 'not-applicable') -or ($r54dPl -ceq '(absent)'))) `
    -Said ("in its tree=$(Test-Path -LiteralPath $r54d.src) at the root=$(Test-Path -LiteralPath $r54Dst4) placement=$r54dPl exit $($r54d.run.exit)")

# ---- (5) a declared result_path outside tests/lam -------------------------------------------------------------------
$r54Rel5 = 'out/validator-A-R54P.result.yaml'
$r54Dst5 = Join-Path $r54.root ($r54Rel5 -replace '/', '\')
$r54e = Invoke-R54Validator -Id 'D-R54-D' -Rel $r54Rel5
Add-R54Row -Label '(5) a validator whose declared result_path is not tests/lam/<name>.result.yaml: the placement is REFUSED by name and nothing is written at the root' `
    -Ok (($r54e.run.out -match '(?m)^mission-dispatch: RESULT-PLACEMENT-REFUSED-PATH') -and (-not (Test-Path -LiteralPath $r54Dst5)) -and ($r54e.run.exit -eq 3) -and
         ((Get-WpgAnchorField $r54e.anchors 'validator_result_placement') -ceq 'refused-path')) `
    -Said ("exit $($r54e.run.exit) at the root=$(Test-Path -LiteralPath $r54Dst5) placement=$(Get-WpgAnchorField $r54e.anchors 'validator_result_placement')")
}
catch {
    Add-R54Row -Label 'MEMBER ABORTED -- an exception escaped the body; every row after it is UNMEASURED' `
        -Ok $false -Said ("line " + $_.InvocationInfo.ScriptLineNumber + " :: " + $_.Exception.GetType().Name + " :: " + ($_.Exception.Message -replace '[\r\n]+', ' '))
}
Check -Id 'R-54' -Title 'THE RUNNER PLACES A VALIDATOR''S RESULT (BATCH-2 WP-G (b)): on a validator complete -- the exit-3 path, the handoff rejected at the shared path -- whose result carries PASS in its own tree (a REFUTED result takes the same branch in the runner; no row here drives one), the runner copies it to the mission root''s tests/lam/<name>.result.yaml, byte-equal, its creation and last-write times the source''s, the anchors carrying the copy''s sha256 and the source''s, EQUAL; the composer appends the complete line binding them and the goal evaluator''s unchanged Test-LamLedgerBound binds the copy; with the destination present the copy is REFUSED, the destination byte-unchanged, the refusal named in the rejection record and the anchors and ledgered as one composed note, and the composer refuses a complete line binding the source over it; the runner''s own placement function refuses a source moved between its hash and its copy, leaving nothing at the destination; a worker dispatch places nothing; and a declared result_path outside tests/lam is refused by name' `
      -Ok $r54ok -Detail ("      THE $(@($r54rows | Where-Object { $_ -match ' : (True|False)' }).Count) ROWS:`n" + ($r54rows -join "`n"))

# =============================================================================================
# R-55 -- NO RESULT AT SESSION END (BATCH-3 WP-K (a))
# =============================================================================================
# THE ROW. D-V-A-596-R2, spawn seq 211: a headless validator backgrounded its suite,
# ended its turn and left no result; the runner read "validator result -- not-found", exited 3, and the complete
# line the ceremony composed for it was a bare null-result line (live spawn-ledger line 428: result_path,
# result_bytes and result_sha256 null beside a null_reason). THE CHARTER'S FALSIFIERS: "a stub
# session that exits with a child still running and no result -> the runner waits <= bound, the child ends, the
# result appears -> placed and bound as today; the child ends with no result -> the refusal line with its code, the
# roster gate sets it aside; the bound elapses with the child alive -> the refusal line names the elapsed bound and
# the pid count; a stub that writes its result before exit -> byte-identical behaviour to today."
#
# THE FIXTURE IS ITS OWN, UNDER %TEMP%: mission roots made by `git init` and Assert-FixtureGitDir (through
# Initialize-FixtureRepo) before any git config call, each printing its git dir and common dir; an EMPTY spawn
# ledger at the path the runtime plane gives it. Nothing here points the runner at this repository or at a live
# mission plane.
#
# THE SESSION IS STUBBED, AND THE STUB IS SHOWN ON THE MEMBER'S FACE. -WorkerCommand names a PowerShell script
# with no param() block (this file's stub rule). It prints a marker; where the row wants the result written before
# the session exits it copies the result body to the declared result_path in its own tree (LAM_WORKTREE); where
# the row wants a descendant it starts ONE detached child with Start-Process -WindowStyle Hidden -- a child that
# inherits none of the session's handles, as a tool's background task does not hold the session's stdout -- and
# then it exits 0 AT ONCE. The child sleeps a stated number of seconds and then either copies the result body to
# that path ("write") or ends having written nothing ("none"). No real `claude -p` runs: -WorkerCommand names the
# stub, no -LoginProbeCommand is given so the probe is SKIPPED and says so, and a TRIPWIRE `claude.cmd` stands
# first on PATH for every runner this member starts and counts its invocations (row (t)).
#
# THE COMPLETE LINE IS THE CEREMONY'S (the runner writes notes). The rows marked
# CEREMONY play that step with the tree's own composer, reading every field from the anchors the runner wrote: a
# refusal and its reason ride the line only where the anchors name one, so over a runner that names none the line
# is the bare null-result line of live line 428. THE TWO READERS a later revision cured -- the close CLI's roster gate
# (Resolve-LamRosterRecord, tools/mission-close-milestone.ps1) and the transcription tool's bare-id path
# (resolve_seq, tools/lam/transcribe_validator_results.py) -- are the tree's own files, driven over a byte copy of
# this fixture's ledger in a scratch reader root (the CLI resolves its root from its own location).
#
# ON A TREE WHOSE RUNNER DECLARES NO -NoResultWaitSeconds the rows run without that argument and read what such a
# runner does, rather than a parameter-binding error.
$r55ok = $true
$r55rows = New-Object System.Collections.Generic.List[string]
function Add-R55Row {
    param([string]$Label, [bool]$Ok, [string]$Said)
    if (-not $Ok) { $script:r55ok = $false }
    $script:r55rows.Add(('      {0,-108} : {1}{2}' -f $Label, $Ok, $(if ($Said) { '  -- ' + (($Said -replace '\s+', ' ').Trim()) } else { '' })))
}
# THE BASE RUNNER: the blob tools/lam/mission-dispatch.ps1 had at the tip this package was cut from (and
# at the tip the ceremony was ratified at). Read through Get-LamBaseBytes: the installed synthetic base
# base-700e19e5-s06 -- that version's program, built from the framework's file at the import commit -- held to the
# sha256 of its bytes.
$r55BaseRunnerCommit = '700e19e5-s06'
$r55BaseRunnerSha  = '93cfb5fa9f151cf4bf729d9e0a0d4fed5315646565526599543472f78a16248d'
$r55Temp = Join-Path ([System.IO.Path]::GetTempPath()) ('lam-wp2-r55-' + [guid]::NewGuid().ToString('N').Substring(0, 8))
$r55PathBefore = $env:PATH
function New-R55MissionRoot {
    param([Parameter(Mandatory = $true)][string]$Name)
    $r55Root = Join-Path (Join-Path $r55Temp $Name) 'm'
    New-Item -ItemType Directory -Path (Join-Path $r55Root '.mission\dispatches') -Force | Out-Null
    Write-Utf8 -Path (Join-Path $r55Root '.mission\mission.yaml') -Text "id: mission-r55-$Name`nstate: executing`n"
    Write-Utf8 -Path (Join-Path $r55Root 'src\seed.txt') -Text "seed`n"
    Write-Utf8 -Path (Join-Path $r55Root '.gitignore') -Text ".mission-runtime/`n"
    $r55Init = Initialize-FixtureRepo -Root $r55Root -Config ([ordered]@{
        'user.email'     = 'r55@instrument.local'
        'user.name'      = 'R-55 Instrument'
        'core.longpaths' = 'true'
    })
    $r55Prev = $ErrorActionPreference
    $ErrorActionPreference = 'Continue'
    try {
        $null = & git -C $r55Root add -A 2>&1
        $null = & git -C $r55Root commit -q -m 'fixture seed' 2>&1
        $r55Head = ("$(& git -C $r55Root rev-parse HEAD 2>&1)").Trim()
    } finally { $ErrorActionPreference = $r55Prev }
    Install-DeciderIn -Repo $r55Root
    Write-Utf8 -Path (Join-Path $r55Root '.mission\dispatches\D-PRIOR.anchors.yaml') -Text "dispatch_id: D-PRIOR`nworktree_tip_sha: $r55Head`ncapture_gaps_count: 0`n"
    $r55Ledger = Join-Path $r55Root '.mission-runtime\lam\spawn-ledger.jsonl'
    Write-Utf8 -Path $r55Ledger -Text ''
    return [pscustomobject]@{ root = $r55Root; base = (Join-Path $r55Temp $Name); head = $r55Head; ledger = $r55Ledger; gitDir = $r55Init.GitDir; commonDir = $r55Init.CommonDir }
}
function Get-R55Body {
    param([string]$Aid)
    return ("verdict: PASS`nid: D-V-$Aid`nvalidates: $Aid`nchecks:`n  - check: the R-55 fixture check`n    verdict: PASS`nfindings: []`n")
}
function New-R55ValidatorStub {
    # THE SESSION. -WriteBefore: it writes its result itself before it exits. -ChildSeconds 0 or more: it starts ONE
    # detached child that sleeps that long and then writes the result (-ChildMode write) or nothing (none).
    param([string]$Path, [string]$Rel, [string]$BodyFile, [string]$Obs, [int]$ChildSeconds = -1, [string]$ChildMode = 'none', [switch]$WriteBefore)
    $r55T = "`$root = `$env:LAM_WORKTREE`n" +
            "Write-Output 'R55-VALIDATOR-STUB'`n" +
            "`$dst = Join-Path `$root '$Rel'`n"
    if ($WriteBefore) {
        $r55T += "New-Item -ItemType Directory -Path (Split-Path -Parent `$dst) -Force | Out-Null`n" +
                 "Copy-Item -LiteralPath '$BodyFile' -Destination `$dst -Force`n"
    }
    $r55T += "`$childPid = ''`n"
    if ($ChildSeconds -ge 0) {
        $r55T += "`$child = Start-Process -FilePath (Join-Path `$PSHOME 'powershell.exe') -WindowStyle Hidden -PassThru -ArgumentList @('-NoProfile', '-ExecutionPolicy', 'Bypass', '-File', '`"$r55ChildScript`"', '$ChildSeconds', '$ChildMode', ('`"' + `$dst + '`"'), '`"$BodyFile`"', '`"$Obs`"')`n" +
                 "`$childPid = [string]`$child.Id`n"
    }
    $r55T += "[System.IO.File]::WriteAllText('$Obs.session', ('session_pid=' + `$PID + [char]10 + 'child_pid=' + `$childPid + [char]10))`n" +
             "exit 0`n"
    Write-Utf8 -Path $Path -Text $r55T
}
function Get-R55Obs {
    param([string]$Path)
    $o = @{}
    if (-not (Test-Path -LiteralPath $Path -PathType Leaf)) { return $o }
    foreach ($l in ([System.IO.File]::ReadAllText($Path) -split "`n")) { if ($l -match '^([a-z_]+)=(.*)$') { $o[$Matches[1]] = $Matches[2].Trim() } }
    return $o
}
function Invoke-R55Runner {
    # A runner -- the tree's, or the base blob's copy -- in a child process against one of this member's roots.
    param([string]$RunnerPath, [string]$Root, [string]$Id, [string[]]$Extra = @())
    $r55Argv = @('-NoProfile', '-ExecutionPolicy', 'Bypass', '-File', $RunnerPath, '-MissionRoot', $Root, '-Dispatch', $Id, '-VerifyCommand', $r55Verify) + @($Extra)
    $r55Sw = [System.Diagnostics.Stopwatch]::StartNew()
    $r55Prev = $ErrorActionPreference
    $ErrorActionPreference = 'Continue'
    try { $r55Out = & powershell @r55Argv 2>&1; $r55Code = $LASTEXITCODE }
    finally { $ErrorActionPreference = $r55Prev }
    $r55Sw.Stop()
    return [pscustomobject]@{ out = ((@($r55Out) | ForEach-Object { "$_" }) -join "`n"); exit = $r55Code; ms = $r55Sw.ElapsedMilliseconds }
}
function Invoke-R55Validator {
    # One validator dispatch: the artifact, the stub, the run. -Bound below 0 passes no -NoResultWaitSeconds.
    param($Mission, [string]$Id, [string]$Aid, [string]$Rel, [int]$Bound = -1, [int]$ChildSeconds = -1, [string]$ChildMode = 'none', [switch]$WriteBefore, [string]$RunnerPath = $runner)
    $r55Tag = (Split-Path -Leaf $Mission.base) + '-' + $Id
    $r55Body = Join-Path $r55Temp ("body-$r55Tag.yaml")
    Write-Utf8 -Path $r55Body -Text (Get-R55Body -Aid $Aid)
    $r55Obs = Join-Path $r55Temp ("obs-$r55Tag")
    $r55Stub = Join-Path $r55StubDir ("validator-$r55Tag.ps1")
    New-R55ValidatorStub -Path $r55Stub -Rel $Rel -BodyFile $r55Body -Obs $r55Obs -ChildSeconds $ChildSeconds -ChildMode $ChildMode -WriteBefore:$WriteBefore
    Write-WpgDispatch -Root $Mission.root -Id $Id -ModelClass 'qa-validator' -Kind 'read-only' -Extra ("validates: $Aid`nround: 1`nresult_path: $Rel`n")
    $r55Extra = @('-WorkerCommand', $r55Stub)
    if ($r55Seam -and ($Bound -ge 0)) { $r55Extra += @('-NoResultWaitSeconds', [string]$Bound) }
    $r55LedgerBefore = @(Get-WpgLedgerLines $Mission.ledger).Count
    $r55Run = Invoke-R55Runner -RunnerPath $RunnerPath -Root $Mission.root -Id $Id -Extra $r55Extra
    $script:r55Runs += $r55Run
    return [pscustomobject]@{
        run = $r55Run; id = $Id; aid = $Aid; rel = $Rel; body = $r55Body; bodySha = (Get-WpgSha $r55Body); obs = $r55Obs; stub = $r55Stub
        src = (Join-Path (Get-FixtureWorktreePath -Id $Id -Root $Mission.root) ($Rel -replace '/', '\'))
        dst = (Join-Path $Mission.root ($Rel -replace '/', '\'))
        anchors = (Join-Path $Mission.root ".mission\dispatches\$Id.anchors.yaml"); handoff = (Join-Path $Mission.root ".mission\dispatches\$Id.handoff.yaml")
        newLines = @(@(Get-WpgLedgerLines $Mission.ledger) | Select-Object -Skip $r55LedgerBefore)
    }
}
function Add-R55Line {
    # THE CEREMONY'S HAND: one line through the tree's composer. Returns the exit, the text and the appended line parsed.
    param([string]$Ledger, [System.Collections.IDictionary]$Record, [string]$Name)
    $r55File = Join-Path $r55Temp ("line-$Name.json")
    Write-Utf8 -Path $r55File -Text ($Record | ConvertTo-Json -Compress -Depth 4)
    $r55Ap = Invoke-WpgComposer -PyArgs @('append', '--ledger', $Ledger, '--line-file', $r55File)
    $r55Obj = $null
    if (($r55Ap.code -eq 0) -and ($r55Ap.text -match '(?m)^APPENDED line \d+ to .*?: (\{.*\})\r?$')) { try { $r55Obj = $Matches[1] | ConvertFrom-Json } catch { $r55Obj = $null } }
    return [pscustomobject]@{ code = $r55Ap.code; text = $r55Ap.text; obj = $r55Obj }
}
function Get-R55Anchor {
    # One top-level anchors scalar, a single-quoted scalar un-doubled.
    param([string]$Path, [string]$Key)
    $r55V = Get-WpgAnchorField $Path $Key
    return ($r55V -replace "''", "'")
}
function New-R55PlacedComplete {
    # The complete line of a PLACED result, every placement field read from the anchors (R-54 row (1b)'s form).
    param([int]$Seq, $Run)
    return [ordered]@{
        event = 'complete'; seq = $Seq; kind = 'validator'; role = 'qa-validator'; dispatch_id = $Run.id; validates = $Run.aid; round = 1
        verdict = (Get-R55Anchor $Run.anchors 'validator_result'); result_path = $Run.rel
        result_sha256 = (Get-R55Anchor $Run.anchors 'validator_result_placement_sha256'); result_source_sha256 = (Get-R55Anchor $Run.anchors 'validator_result_placement_source_sha256')
        result_source_path = (Get-R55Anchor $Run.anchors 'validator_result_placement_source'); result_dest_path = (Get-R55Anchor $Run.anchors 'validator_result_placement_destination')
    }
}
function New-R55NoResultComplete {
    # The complete line of a run that left NO result, in the null form of live line 428; `refusal` and `reason`
    # ride it only where the anchors name them.
    param([int]$Seq, $Run)
    $r55Rec = [ordered]@{
        event = 'complete'; seq = $Seq; kind = 'validator'; role = 'qa-validator'; dispatch_id = $Run.id; validates = $Run.aid; round = 1
        result_path = $null; result_bytes = $null; result_sha256 = $null; worker_exit_code = 0; runner_exit = [int]$Run.run.exit
    }
    $r55Code = Get-R55Anchor $Run.anchors 'validator_result_refusal'
    if ($r55Code -and ($r55Code -notmatch '^\(')) {
        $r55Rec['refusal'] = $r55Code
        $r55Rec['reason'] = (Get-R55Anchor $Run.anchors 'validator_result_refusal_reason')
    }
    return $r55Rec
}
function Get-R55AnchorKeys {
    # Every key of an anchors file in file order, its indentation kept: the artifact's shape, values aside.
    param([string]$Path)
    if (-not (Test-Path -LiteralPath $Path -PathType Leaf)) { return @('(no anchors)') }
    return @([System.IO.File]::ReadAllLines($Path) | ForEach-Object { if ($_ -match '^(\s*(?:-\s+)?[A-Za-z_][A-Za-z0-9_]*):') { $Matches[1] } })
}
function New-R55ReaderRoot {
    # A scratch root for the two readers, T-30's layout (WP-4): the tree's own CLI and library copied into
    # <root>\tools so the CLI's root is this root; the roster; the result files; and a BYTE COPY of the ledger.
    param([string]$Name, [string]$Ledger, [string[]]$Roster, [hashtable]$ResultFiles)
    $r55R = Join-Path $r55Temp $Name
    foreach ($d in @('tools', '.mission\spec', '.mission\amendments', '.mission\ledger', 'tests\lam', '.mission-runtime\lam')) {
        New-Item -ItemType Directory -Path (Join-Path $r55R $d) -Force | Out-Null
    }
    Copy-Item -LiteralPath (Join-Path $repoRoot 'tools\mission-close-milestone.ps1') -Destination (Join-Path $r55R 'tools\mission-close-milestone.ps1')
    Copy-Item -LiteralPath (Join-Path $repoRoot 'tools\mission-lib.ps1') -Destination (Join-Path $r55R 'tools\mission-lib.ps1')
    Write-Utf8 -Path (Join-Path $r55R '.mission\mission.yaml') -Text "id: R55-FIXTURE`nstate: Reworking`ncurrent_spec_version: v010`ncurrent_milestone: M-98`n"
    Write-Utf8 -Path (Join-Path $r55R '.mission\spec\current.txt') -Text "v010`n"
    Write-Utf8 -Path (Join-Path $r55R '.mission\spec\v010.yaml') -Text ("version: v010`nfeatures:`n  - id: F-930`n    status: pending`nmilestones:`n  - id: M-99`n    status: pending`n    features: [F-930]`n    contract_assertion_ids: [" + ($Roster -join ', ') + "]`ntrailer: end`n")
    Write-Utf8 -Path (Join-Path $r55R '.mission\amendments\AM-099-r55.yaml') -Text "id: AM-099`n"
    Write-Utf8 -Path (Join-Path $r55R '.mission\ledger\entries.jsonl') -Text ''
    Write-Utf8 -Path (Join-Path $r55R 'led.txt') -Text "R-55 fixture ledger content`n"
    foreach ($rel in $ResultFiles.Keys) { Copy-Item -LiteralPath $ResultFiles[$rel] -Destination (Join-Path $r55R ($rel -replace '/', '\')) -Force }
    Copy-Item -LiteralPath $Ledger -Destination (Join-Path $r55R '.mission-runtime\lam\spawn-ledger.jsonl') -Force
    return $r55R
}
function Invoke-R55Gate {
    param([string]$Root)
    $r55Prev = $ErrorActionPreference
    $ErrorActionPreference = 'Continue'
    $r55Raw = @(); $r55Code = $null
    try {
        $r55Raw = & powershell -NoProfile -ExecutionPolicy Bypass -File (Join-Path $Root 'tools\mission-close-milestone.ps1') -Milestone M-99 -AmendmentId AM-099 -LedgerContentFile (Join-Path $Root 'led.txt') -NoCommit -RosterGateOnly 2>&1
        $r55Code = $LASTEXITCODE
    } finally { $ErrorActionPreference = $r55Prev }
    return [pscustomobject]@{ code = $r55Code; text = ((@($r55Raw) | ForEach-Object { "$_" }) -join "`n") }
}
function Invoke-R55Tool {
    param([string]$Root, [string]$Target)
    if (-not $wpgPy) { return [pscustomobject]@{ code = $null; text = 'no Python interpreter on PATH (python, py -3)' } }
    # The store the tool transcribes INTO must exist (it does not create one); an empty one, as T-41 row (u2) gives it.
    New-Item -ItemType Directory -Path (Join-Path $Root '.mission\validator-results') -Force | Out-Null
    Write-Utf8 -Path (Join-Path $Root '.mission\validator-results\manifest.json') -Text "{`"entries`": []}`n"
    $r55Prev = $ErrorActionPreference
    $ErrorActionPreference = 'Continue'
    $r55Raw = @(); $r55Code = $null
    try {
        $r55Raw = & $wpgPy.source @($wpgPy.pre) (Join-Path $repoRoot 'tools\lam\transcribe_validator_results.py') $Target --root $Root --arc R55 2>&1
        $r55Code = $LASTEXITCODE
    } finally { $ErrorActionPreference = $r55Prev }
    return [pscustomobject]@{ code = $r55Code; text = ((@($r55Raw) | ForEach-Object { "$_" }) -join "`n") }
}
function Get-R55Lines {
    param([string]$Text, [string]$Pattern)
    return ((@($Text -split "`n") | Where-Object { $_ -match $Pattern } | ForEach-Object { $_.TrimEnd("`r") }) -join ' // ')
}
$r55Runs = @()
try {
New-Item -ItemType Directory -Path $r55Temp -Force | Out-Null
$r55StubDir = Join-Path $r55Temp 'stubs'
New-Item -ItemType Directory -Path $r55StubDir -Force | Out-Null
$r55Verify = Join-Path $r55StubDir 'verify-pass.ps1'
Write-Utf8 -Path $r55Verify -Text "Write-Output 'gate: PASS'`nexit 0`n"
$r55ChildScript = Join-Path $r55StubDir 'descendant.ps1'
Write-Utf8 -Path $r55ChildScript -Text ("`$secs = [int]`$args[0]`n`$mode = [string]`$args[1]`n`$dst = [string]`$args[2]`n`$body = [string]`$args[3]`n`$obs = [string]`$args[4]`n" +
    "[System.IO.File]::WriteAllText((`$obs + '.child-started'), ('pid=' + `$PID + [char]10))`n" +
    "Start-Sleep -Seconds `$secs`n" +
    "if (`$mode -eq 'write') {`n    New-Item -ItemType Directory -Path (Split-Path -Parent `$dst) -Force | Out-Null`n    Copy-Item -LiteralPath `$body -Destination `$dst -Force`n}`n" +
    "[System.IO.File]::WriteAllText((`$obs + '.child-ended'), ('pid=' + `$PID + [char]10 + 'mode=' + `$mode + [char]10))`n" +
    "exit 0`n")
$r55Seam = $false
try { $r55Seam = [bool]((Get-Command -Name $runner -ErrorAction Stop).Parameters.ContainsKey('NoResultWaitSeconds')) } catch { $r55Seam = $false }
# THE TRIPWIRE: a `claude` first on PATH for every process this member starts. It answers nothing and counts.
