$r55 = New-R55MissionRoot -Name 'a'
$r55rows.Add('      the member''s own mission root, under %TEMP%: ' + $r55.root + ' ; git dir ' + $r55.gitDir + ' ; common dir ' + $r55.commonDir + ' ; the runner declares -NoResultWaitSeconds: ' + $r55Seam)
$r55rows.Add('      THE SESSION STUB, the row-(2) one, verbatim: ' + ((@("`$root = `$env:LAM_WORKTREE", "Write-Output 'R55-VALIDATOR-STUB'", "`$dst = Join-Path `$root '<result_path>'", "`$child = Start-Process -FilePath (Join-Path `$PSHOME 'powershell.exe') -WindowStyle Hidden -PassThru -ArgumentList @(..., '-File', '<descendant.ps1>', '<seconds>', '<write|none>', `$dst, '<body>', '<obs>')", "[System.IO.File]::WriteAllText('<obs>.session', ...)", 'exit 0') -join ' | ')) + ' ; the descendant sleeps <seconds>, copies <body> to $dst when its mode is write, and exits')

# ---- (4) the result written BEFORE the session exits: as today -----------------------------------------------------
$r55Aid = 'A-9365'
$r55Rel = 'tests/lam/validator-A-9365.result.yaml'
$r55Sp1 = Add-R55Line -Ledger $r55.ledger -Name 'spawn-1' -Record ([ordered]@{ event = 'spawn'; seq = 1; kind = 'validator'; dispatch_id = 'D-R55-P'; validates = $r55Aid; round = 1; tip_judged = $r55.head })
$r55p = Invoke-R55Validator -Mission $r55 -Id 'D-R55-P' -Aid $r55Aid -Rel $r55Rel -Bound 60 -WriteBefore
$r55pKeys = @(Get-R55AnchorKeys $r55p.anchors)
$r55pTrace = @($r55pKeys | Where-Object { $_ -match 'validator_result_(session_end|wait|refusal)' })
Add-R55Row -Label '(4) CONTROL the session wrote its result BEFORE it exited: PLACED as today, and nothing of this row on the run -- no wait line, no anchors key, no ledger line' `
    -Ok (($r55p.run.exit -eq 3) -and ($r55p.run.out -match '(?m)^mission-dispatch: validator result PLACED') -and ((Get-WpgSha $r55p.dst) -ceq $r55p.bodySha) -and
         ($r55p.run.out -notmatch 'NO-RESULT-AT-SESSION-END|register row 365|descendant') -and ($r55pTrace.Count -eq 0) -and ($r55p.newLines.Count -eq 0)) `
    -Said ("exit $($r55p.run.exit); copy $(Get-WpgSha $r55p.dst) body $($r55p.bodySha); session-end anchors keys: $($r55pTrace.Count); ledger lines from the runner: $($r55p.newLines.Count); $($r55p.run.ms) ms :: " + (Get-R55Lines $r55p.run.out 'validator result'))
$r55C1 = Add-R55Line -Ledger $r55.ledger -Name 'complete-1' -Record (New-R55PlacedComplete -Seq 1 -Run $r55p)
$r55C1Bound = Invoke-R54Bound -Root $r55.root -File $r55p.dst
Add-R55Row -Label '(4b) CEREMONY the complete line of that placement is APPENDED from the anchors and the goal evaluator''s unchanged Test-LamLedgerBound binds the copy' `
    -Ok (($r55Sp1.code -eq 0) -and ($null -ne $r55C1.obj) -and ([string]$r55C1.obj.result_sha256 -ceq $r55p.bodySha) -and [bool]$r55C1Bound.bound) `
    -Said ("spawn append exit $($r55Sp1.code); complete append exit $($r55C1.code); bound=$($r55C1Bound.bound) :: $($r55C1Bound.reason)")

# ---- (4a) the same stub and artifact through THE BASE RUNNER, in a twin root ---------------------------------------
# THE BASE RUNNER'S TREE: a scratch copy of what the runner reads beside itself -- tools\lam, the next-gen hooks and
# the guard library they load (tools\framework\hooks, READ and copied, nothing under it written), model-routing.yaml
# -- with the runner replaced by the base blob. The composer's copy there stamps nothing; this row writes no note.
$r55BaseTree = Join-Path $r55Temp 'base-tree'
New-Item -ItemType Directory -Path (Join-Path $r55BaseTree 'tools\framework') -Force | Out-Null
Copy-Item -LiteralPath (Join-Path $repoRoot 'tools\lam') -Destination (Join-Path $r55BaseTree 'tools\lam') -Recurse -Force
Copy-Item -LiteralPath (Join-Path $repoRoot 'tools\evidence-hooks-next') -Destination (Join-Path $r55BaseTree 'tools\evidence-hooks-next') -Recurse -Force
Copy-Item -LiteralPath (Join-Path $repoRoot 'tools\framework\hooks') -Destination (Join-Path $r55BaseTree 'tools\framework\hooks') -Recurse -Force
Copy-Item -LiteralPath $routing -Destination (Join-Path $r55BaseTree 'model-routing.yaml') -Force
$r55BaseRunner = Join-Path $r55BaseTree 'tools\lam\mission-dispatch.ps1'
$r55BaseRead = Get-LamBaseBytes -Base $r55BaseRunnerCommit -Path 'tools/lam/mission-dispatch.ps1' -Pin $r55BaseRunnerSha
if ($r55BaseRead.ok) { [System.IO.File]::WriteAllBytes($r55BaseRunner, $r55BaseRead.bytes) }
$r55BaseHeld = $r55BaseRead.ok
$r55b = New-R55MissionRoot -Name 'b'
$r55bSp = Add-R55Line -Ledger $r55b.ledger -Name 'b-spawn-1' -Record ([ordered]@{ event = 'spawn'; seq = 1; kind = 'validator'; dispatch_id = 'D-R55-P'; validates = $r55Aid; round = 1; tip_judged = $r55b.head })
$r55q = $null
$r55qC = $null
if ($r55BaseHeld) {
    $r55SeamKeep = $r55Seam
    $r55Seam = $false
    try { $r55q = Invoke-R55Validator -Mission $r55b -Id 'D-R55-P' -Aid $r55Aid -Rel $r55Rel -WriteBefore -RunnerPath $r55BaseRunner } finally { $r55Seam = $r55SeamKeep }
    $r55qC = Add-R55Line -Ledger $r55b.ledger -Name 'b-complete-1' -Record (New-R55PlacedComplete -Seq 1 -Run $r55q)
}
$r55KeysSame = $false
$r55Differ = @('(the base runner did not run)')
$r55OutSame = $false
$r55OutSaid = '(the base runner did not run)'
if ($null -ne $r55q) {
    # THE TWO RUNS' STDOUT, line for line, each run's own root read as <base> and every sha as <hex>.
    $r55Shape = { param([string]$Text, [string]$Base) @(@($Text -split "`n") | ForEach-Object { (($_.TrimEnd("`r")).Replace($Base, '<base>').Replace($Base.Replace('\', '/'), '<base>') -replace '[0-9a-f]{40,64}', '<hex>') }) }
    $r55ShapeA = @(& $r55Shape $r55p.run.out $r55.base)
    $r55ShapeB = @(& $r55Shape $r55q.run.out $r55b.base)
    $r55OutSame = (($r55ShapeA -join "`n") -ceq ($r55ShapeB -join "`n")) -and ($r55ShapeA.Count -gt 5)
    $r55OutSaid = "$($r55ShapeA.Count) and $($r55ShapeB.Count) lines"
    if (-not $r55OutSame) {
        for ($r55I = 0; $r55I -lt [Math]::Max($r55ShapeA.Count, $r55ShapeB.Count); $r55I++) {
            if ([string]$r55ShapeA[$r55I] -cne [string]$r55ShapeB[$r55I]) { $r55OutSaid += "; first difference at line $($r55I + 1): tree [" + [string]$r55ShapeA[$r55I] + '] base [' + [string]$r55ShapeB[$r55I] + ']'; break }
        }
    }
}
if (($null -ne $r55q) -and ($null -ne $r55qC.obj) -and ($null -ne $r55C1.obj)) {
    $r55qKeys = @(Get-R55AnchorKeys $r55q.anchors)
    $r55KeysSame = (($r55pKeys -join "`n") -ceq ($r55qKeys -join "`n")) -and ($r55pKeys.Count -gt 20)
    $r55Differ = @()
    $r55NamesA = @($r55C1.obj.PSObject.Properties.Name)
    $r55NamesB = @($r55qC.obj.PSObject.Properties.Name)
    if (($r55NamesA -join ',') -cne ($r55NamesB -join ',')) { $r55Differ += 'the field names or their order' }
    foreach ($r55N in $r55NamesA) {
        $r55Va = ([string]$r55C1.obj.$r55N).Replace($r55.base, '<base>')
        $r55Vb = ([string]$r55qC.obj.$r55N).Replace($r55b.base, '<base>')
        if ($r55Va -cne $r55Vb) { $r55Differ += $r55N }
    }
}
Add-R55Row -Label '(4a) CONTROL the same stub and artifact through THE BASE RUNNER (the installed synthetic base base-700e19e5-s06, pinned by sha256) in a twin root: the same exit, the same stdout line for line, the anchors'' keys in the same order, the complete line EQUAL field by field' `
    -Ok ($r55BaseHeld -and ($null -ne $r55q) -and ($r55q.run.exit -eq $r55p.run.exit) -and $r55OutSame -and $r55KeysSame -and ($r55Differ.Count -eq 0) -and ($r55q.run.out -match '(?m)^mission-dispatch: validator result PLACED')) `
    -Said ("base runner read from $($r55BaseRead.from): $(if ($r55BaseHeld) { 'held to its pin' } else { 'NOT HELD, sha256 ' + $r55BaseRead.sha }); exits tree $($r55p.run.exit) / base $(if ($r55q) { $r55q.run.exit } else { '(none)' }); stdout (each root read as <base>, each sha as <hex>) equal=$r55OutSame, $r55OutSaid; anchors keys $($r55pKeys.Count), same sequence=$r55KeysSame; fields that differ (each run's own root read as <base>): $(if ($r55Differ.Count) { $r55Differ -join ', ' } else { 'none of ' + @($r55C1.obj.PSObject.Properties.Name).Count }) :: the base runner said: $(if ($r55q) { Get-R55Lines $r55q.run.out 'REFUSED|validator result' } else { '(nothing)' })")

# ---- (2) the descendant ends having written NOTHING ------------------------------------------------------------------
$r55Sp2 = Add-R55Line -Ledger $r55.ledger -Name 'spawn-2' -Record ([ordered]@{ event = 'spawn'; seq = 2; kind = 'validator'; dispatch_id = 'D-R55-B'; validates = $r55Aid; round = 1; tip_judged = $r55.head })
$r55n = Invoke-R55Validator -Mission $r55 -Id 'D-R55-B' -Aid $r55Aid -Rel 'tests/lam/validator-A-9365-reissue.result.yaml' -Bound 60 -ChildSeconds 3 -ChildMode 'none'
$r55nObs = Get-R55Obs ($r55n.obs + '.session')
$r55nCode = Get-R55Anchor $r55n.anchors 'validator_result_refusal'
$r55nHo = if (Test-Path -LiteralPath $r55n.handoff) { [System.IO.File]::ReadAllText($r55n.handoff) } else { '' }
Add-R55Row -Label '(2) FALSIFIER the session exits with a descendant alive and no result, and the descendant ENDS having written none: the refusal is NAMED, exit 3, and the not-found line stands as it was' `
    -Ok (($r55n.run.exit -eq 3) -and ($r55n.run.out -match '(?m)^mission-dispatch: NO-RESULT-AT-SESSION-END-DESCENDANTS-ENDED -- ') -and ($r55n.run.out -match '(?m)^mission-dispatch: VALIDATOR-RESULT-NOT-FOUND -- ') -and
         ($r55nCode -ceq 'NO-RESULT-AT-SESSION-END-DESCENDANTS-ENDED') -and ($r55nHo -match 'NO-RESULT-AT-SESSION-END-DESCENDANTS-ENDED') -and (Test-Path -LiteralPath ($r55n.obs + '.child-ended'))) `
    -Said ("exit $($r55n.run.exit); anchors validator_result=$(Get-R55Anchor $r55n.anchors 'validator_result') validator_result_refusal=$r55nCode; the descendant ended=$(Test-Path -LiteralPath ($r55n.obs + '.child-ended')); $($r55n.run.ms) ms :: " + (Get-R55Lines $r55n.run.out 'NO-RESULT|validator result'))
$r55nSeen = Get-R55Anchor $r55n.anchors 'validator_result_wait_descendants'
$r55nMs = 0
[void][int]::TryParse((Get-R55Anchor $r55n.anchors 'validator_result_wait_ms'), [ref]$r55nMs)
Add-R55Row -Label '(2a) the anchors say what the runner saw and did: the descendant''s pid among those alive at the session''s exit, the wait ended by their ending inside the bound' `
    -Ok (((Get-R55Anchor $r55n.anchors 'validator_result_wait') -ceq 'descendants-ended') -and [bool]$r55nObs['child_pid'] -and ((' ' + ($r55nSeen -replace ';', ' ') + ' ') -match (' ' + [regex]::Escape([string]$r55nObs['child_pid']) + ' ')) -and
         ($r55nMs -ge 200) -and ($r55nMs -lt 60000) -and ((Get-R55Anchor $r55n.anchors 'validator_result_wait_bound_seconds') -ceq '60')) `
    -Said ("validator_result_wait=$(Get-R55Anchor $r55n.anchors 'validator_result_wait') bound=$(Get-R55Anchor $r55n.anchors 'validator_result_wait_bound_seconds') s waited=$r55nMs ms seen=$(Get-R55Anchor $r55n.anchors 'validator_result_wait_descendants_seen'): $r55nSeen ; the stub's child pid $($r55nObs['child_pid'])")
$r55nNote = $null
if ($r55n.newLines.Count -eq 1) { try { $r55nNote = $r55n.newLines[0] | ConvertFrom-Json } catch { $r55nNote = $null } }
Add-R55Row -Label '(2b) the refusal LEDGERED at the moment of the act: ONE note composed by tools/lam/spawn_ledger.py, its refusal the code, runner_exit 3, a reason, the pids it saw' `
    -Ok (($null -ne $r55nNote) -and ($r55nNote.event -ceq 'note') -and ($r55nNote.refusal -ceq 'NO-RESULT-AT-SESSION-END-DESCENDANTS-ENDED') -and ($r55nNote.dispatch_id -ceq 'D-R55-B') -and ($r55nNote.runner_exit -eq 3) -and
         ([string]$r55nNote.reason).Trim() -and (@($r55nNote.descendant_pids) -contains [int]$r55nObs['child_pid']) -and ($r55nNote.bound_elapsed -eq $false) -and [bool]$wpgStamp -and ($r55nNote.composed_by -ceq $wpgStamp)) `
    -Said ("new lines $($r55n.newLines.Count) :: " + $(if ($r55n.newLines.Count) { $r55n.newLines[0] } else { '(none)' }))
$r55C2 = Add-R55Line -Ledger $r55.ledger -Name 'complete-2' -Record (New-R55NoResultComplete -Seq 2 -Run $r55n)
# The line's `refusal` and `reason` are read by NAME: over a runner that names none the line carries neither.
$r55C2Names = if ($r55C2.obj) { @($r55C2.obj.PSObject.Properties.Name) } else { @() }
$r55C2Refusal = if ($r55C2Names -contains 'refusal') { [string]$r55C2.obj.refusal } else { '' }
$r55C2Reason = if ($r55C2Names -contains 'reason') { [string]$r55C2.obj.reason } else { '' }
Add-R55Row -Label '(2c) CEREMONY the complete line composed from those anchors NAMES the refusal and its reason beside its null result -- it is not a bare null-result line -- and the composer APPENDS it' `
    -Ok (($null -ne $r55C2.obj) -and ($null -eq $r55C2.obj.result_sha256) -and ($r55C2Refusal -ceq 'NO-RESULT-AT-SESSION-END-DESCENDANTS-ENDED') -and [bool]$r55C2Reason.Trim() -and ($r55C2.obj.runner_exit -eq 3)) `
    -Said ("append exit $($r55C2.code) :: " + $(if ($r55C2.obj) { 'refusal=' + $(if ($r55C2.obj.PSObject.Properties.Name -contains 'refusal') { [string]$r55C2.obj.refusal } else { '(NONE: a bare null-result line)' }) + ' result_sha256=' + $(if ($null -eq $r55C2.obj.result_sha256) { 'null' } else { [string]$r55C2.obj.result_sha256 }) + ' :: ' + (Get-WpgFirstLines $r55C2.text 1) } else { Get-WpgFirstLines $r55C2.text 2 }))
# THE TWO READERS, over a byte copy of this ledger: the bound line seq 1 and the null-result line seq 2 share round 1.
$r55Readers = New-R55ReaderRoot -Name 'readers' -Ledger $r55.ledger -Roster @($r55Aid) -ResultFiles @{ $r55Rel = $r55p.dst }
$r55LedSame = ((Get-WpgSha $r55.ledger) -ceq (Get-WpgSha (Join-Path $r55Readers '.mission-runtime\lam\spawn-ledger.jsonl')))
$r55G = Invoke-R55Gate -Root $r55Readers
Add-R55Row -Label '(2d) THE REAL ROSTER GATE over that ledger (Resolve-LamRosterRecord, -RosterGateOnly): it PERMITS on the bound line and its [PASS] line names the null-result line as SET ASIDE' `
    -Ok ($r55LedSame -and ($r55G.code -eq 0) -and ($r55G.text -match 'roster gate PERMITS M-99') -and ($r55G.text -match ("(?m)^.*\[PASS\] roster closable: .*SET ASIDE, claiming no round: 1 'complete' line\(s\) that bind no result -- " + [regex]::Escape($r55Aid) + ' seq 2 \(round 1\)\.'))) `
    -Said ("ledger copy byte-equal=$r55LedSame; exit $($r55G.code) :: " + (Get-R55Lines $r55G.text 'roster closable|PERMITS|REFUSED'))
$r55T = Invoke-R55Tool -Root $r55Readers -Target $r55Aid
Add-R55Row -Label '(2e) THE REAL TRANSCRIPTION TOOL''s bare-id path over it (resolve_seq): it resolves the bound seq 1 and names seq 2 SET ASIDE' `
    -Ok (($r55T.code -eq 0) -and ($r55T.text -match ([regex]::Escape($r55Aid) + '\s+seq 1\s')) -and ($r55T.text -match 'SET ASIDE, claiming no round: 1 complete line\(s\) that bind no result -- seq 2 \(round 1\)')) `
    -Said ("exit $($r55T.code) :: " + (Get-R55Lines $r55T.text ([regex]::Escape($r55Aid) + '|SET ASIDE|STOP')))
$r55C1Again = Invoke-R54Bound -Root $r55.root -File $r55p.dst
Add-R55Row -Label '(2f) CONTROL the goal evaluator''s unchanged Test-LamLedgerBound, the refusal line now on the ledger: the placed copy is still bound to seq 1' `
    -Ok ([bool]$r55C1Again.bound) -Said ("bound=$($r55C1Again.bound) :: $($r55C1Again.reason)")

# ---- (1) the descendant writes the result INSIDE the bound ---------------------------------------------------------
$r55Aid1 = 'A-9366'
$r55Sp3 = Add-R55Line -Ledger $r55.ledger -Name 'spawn-3' -Record ([ordered]@{ event = 'spawn'; seq = 3; kind = 'validator'; dispatch_id = 'D-R55-A'; validates = $r55Aid1; round = 1; tip_judged = $r55.head })
$r55w = Invoke-R55Validator -Mission $r55 -Id 'D-R55-A' -Aid $r55Aid1 -Rel 'tests/lam/validator-A-9366.result.yaml' -Bound 60 -ChildSeconds 12 -ChildMode 'write'
$r55wObs = Get-R55Obs ($r55w.obs + '.session')
Add-R55Row -Label '(1) FALSIFIER the session exits with a descendant alive and no result, and the descendant WRITES the result inside the bound: the runner waited for it and the result is PLACED' `
    -Ok (($r55w.run.exit -eq 3) -and ($r55w.run.out -match '(?m)^mission-dispatch: validator result PLACED') -and ((Get-WpgSha $r55w.dst) -ceq $r55w.bodySha) -and ((Get-R55Anchor $r55w.anchors 'validator_result') -ceq 'PASS') -and
         ($r55w.run.out -notmatch 'NO-RESULT-AT-SESSION-END-')) `
    -Said ("exit $($r55w.run.exit); anchors validator_result=$(Get-R55Anchor $r55w.anchors 'validator_result') placement=$(Get-R55Anchor $r55w.anchors 'validator_result_placement'); copy $(Get-WpgSha $r55w.dst) body $($r55w.bodySha); $($r55w.run.ms) ms :: " + (Get-R55Lines $r55w.run.out 'validator result|no result at'))
$r55wMs = 0
[void][int]::TryParse((Get-R55Anchor $r55w.anchors 'validator_result_wait_ms'), [ref]$r55wMs)
Add-R55Row -Label '(1a) and the wait is on the record: no result at the source when the session exited, the descendant seen, the wait ended by its ending, inside the bound' `
    -Ok (((Get-R55Anchor $r55w.anchors 'validator_result_wait') -ceq 'descendants-ended') -and ($r55wMs -ge 1000) -and ($r55wMs -lt 60000) -and [bool]$r55wObs['child_pid'] -and
         ((' ' + ((Get-R55Anchor $r55w.anchors 'validator_result_wait_descendants') -replace ';', ' ') + ' ') -match (' ' + [regex]::Escape([string]$r55wObs['child_pid']) + ' ')) -and ($r55w.newLines.Count -eq 0)) `
    -Said ("validator_result_session_end=$(Get-R55Anchor $r55w.anchors 'validator_result_session_end') validator_result_wait=$(Get-R55Anchor $r55w.anchors 'validator_result_wait') waited=$r55wMs ms of 60 s; seen: $(Get-R55Anchor $r55w.anchors 'validator_result_wait_descendants'); the stub's child pid $($r55wObs['child_pid']); ledger lines from the runner: $($r55w.newLines.Count)")
$r55C3 = if ((Get-R55Anchor $r55w.anchors 'validator_result_placement') -ceq 'placed') { Add-R55Line -Ledger $r55.ledger -Name 'complete-3' -Record (New-R55PlacedComplete -Seq 3 -Run $r55w) } else { [pscustomobject]@{ code = $null; text = 'not composed: the anchors record no placement'; obj = $null } }
$r55C3Bound = Invoke-R54Bound -Root $r55.root -File $r55w.dst
Add-R55Row -Label '(1b) CEREMONY placed and BOUND as today: the complete line appended from the anchors, and Test-LamLedgerBound binds the copy the descendant''s result became' `
    -Ok (($null -ne $r55C3.obj) -and ([string]$r55C3.obj.result_sha256 -ceq $r55w.bodySha) -and [bool]$r55C3Bound.bound) `
    -Said ("complete append exit $($r55C3.code); bound=$($r55C3Bound.bound) :: $($r55C3Bound.reason)")

# ---- (3) the bound ELAPSES with the descendant alive -----------------------------------------------------------------
$r55e = Invoke-R55Validator -Mission $r55 -Id 'D-R55-C' -Aid 'A-9367' -Rel 'tests/lam/validator-A-9367.result.yaml' -Bound 4 -ChildSeconds 45 -ChildMode 'none'
$r55eObs = Get-R55Obs ($r55e.obs + '.session')
$r55eAliveAfter = $false
if ($r55eObs['child_pid']) { $r55eAliveAfter = [bool](Get-Process -Id ([int]$r55eObs['child_pid']) -ErrorAction SilentlyContinue) -and (-not (Test-Path -LiteralPath ($r55e.obs + '.child-ended'))) }
$r55eReason = Get-R55Anchor $r55e.anchors 'validator_result_refusal_reason'
$r55eMs = 0
[void][int]::TryParse((Get-R55Anchor $r55e.anchors 'validator_result_wait_ms'), [ref]$r55eMs)
$r55eAlive = Get-R55Anchor $r55e.anchors 'validator_result_wait_alive_at_end'
Add-R55Row -Label '(3) FALSIFIER the bound ELAPSES with the descendant alive: the refusal names the elapsed bound and how many were still alive, by pid' `
    -Ok (($r55e.run.exit -eq 3) -and ($r55e.run.out -match '(?m)^mission-dispatch: NO-RESULT-AT-SESSION-END-BOUND-ELAPSED -- ') -and ($r55eReason -match 'the 4 s bound ELAPSED') -and ($r55eAlive -match '^[1-9][0-9]*$') -and
         ($r55eReason -match ([regex]::Escape($r55eAlive) + ' still alive')) -and [bool]$r55eObs['child_pid'] -and ($r55eReason -match ('pid ' + [regex]::Escape([string]$r55eObs['child_pid']) + ' '))) `
    -Said ("exit $($r55e.run.exit); validator_result_wait=$(Get-R55Anchor $r55e.anchors 'validator_result_wait') alive at the bound=$r55eAlive; reason: $r55eReason")
Add-R55Row -Label '(3a) and the runner did NOT hang past the bound: it waited the 4 s and no more than 3 s over, and returned with the descendant still alive behind it' `
    -Ok (($r55eMs -ge 4000) -and ($r55eMs -lt 7000) -and $r55eAliveAfter -and ($r55e.run.ms -lt ($r55p.run.ms + 4000 + 15000))) `
    -Said ("waited $r55eMs ms against a 4000 ms bound; this run $($r55e.run.ms) ms wall, row (4)'s run with no wait $($r55p.run.ms) ms; the descendant (45 s sleep) alive after the runner returned=$r55eAliveAfter")
if ($r55eObs['child_pid']) { try { Stop-Process -Id ([int]$r55eObs['child_pid']) -Force -ErrorAction Stop } catch { } }

# ---- (5) the wait switched OFF ---------------------------------------------------------------------------------------
$r55o = Invoke-R55Validator -Mission $r55 -Id 'D-R55-D' -Aid 'A-9368' -Rel 'tests/lam/validator-A-9368.result.yaml' -Bound 0 -ChildSeconds 6 -ChildMode 'none'
$r55oMs = -1
[void][int]::TryParse((Get-R55Anchor $r55o.anchors 'validator_result_wait_ms'), [ref]$r55oMs)
Add-R55Row -Label '(5) -NoResultWaitSeconds 0 switches the wait OFF: nothing is enumerated or waited for, and the refusal is still NAMED -- NO-RESULT-AT-SESSION-END-DESCENDANTS-UNKNOWN' `
    -Ok (($r55o.run.exit -eq 3) -and ($r55o.run.out -match '(?m)^mission-dispatch: NO-RESULT-AT-SESSION-END-DESCENDANTS-UNKNOWN -- ') -and ($r55oMs -eq 0) -and ((Get-R55Anchor $r55o.anchors 'validator_result_wait') -ceq 'descendants-unknown')) `
    -Said ("exit $($r55o.run.exit); validator_result_wait=$(Get-R55Anchor $r55o.anchors 'validator_result_wait') waited=$r55oMs ms; reason: $(Get-R55Anchor $r55o.anchors 'validator_result_refusal_reason')")

# ---- (6) the incident's own shape: no descendant alive when the session exits -------------------------------------------
$r55i = Invoke-R55Validator -Mission $r55 -Id 'D-R55-E' -Aid 'A-9369' -Rel 'tests/lam/validator-A-9369.result.yaml' -Bound 60
$r55iMs = -1
[void][int]::TryParse((Get-R55Anchor $r55i.anchors 'validator_result_wait_ms'), [ref]$r55iMs)
Add-R55Row -Label '(6) seq 211''s shape -- no result, and NO descendant alive when the session exits (there the CLI had killed its own): named NO-RESULT-AT-SESSION-END-NO-DESCENDANTS, and nothing waited for' `
    -Ok (($r55i.run.exit -eq 3) -and ($r55i.run.out -match '(?m)^mission-dispatch: NO-RESULT-AT-SESSION-END-NO-DESCENDANTS -- ') -and ($r55iMs -eq 0) -and ((Get-R55Anchor $r55i.anchors 'validator_result_wait_descendants_seen') -ceq '0') -and ($r55i.newLines.Count -eq 1)) `
    -Said ("exit $($r55i.run.exit); validator_result_wait=$(Get-R55Anchor $r55i.anchors 'validator_result_wait') seen=$(Get-R55Anchor $r55i.anchors 'validator_result_wait_descendants_seen') waited=$r55iMs ms; ledger lines from the runner: $($r55i.newLines.Count); $($r55i.run.ms) ms")

# ---- (t) the tripwire ------------------------------------------------------------------------------------------------
$r55TripCount = if (Test-Path -LiteralPath $r55TripLog -PathType Leaf) { @([System.IO.File]::ReadAllLines($r55TripLog) | Where-Object { $_.Trim() }).Count } else { 0 }
$r55Skipped = @($r55Runs | Where-Object { $_.out -match '(?m)^mission-dispatch: login probe -- SKIPPED' }).Count
Add-R55Row -Label '(t) NO REAL CLI: `claude` resolved to this member''s tripwire for every runner it started, the tripwire counted 0 invocations, and every run printed the probe SKIPPED' `
    -Ok (($r55Resolved -ieq (Join-Path $r55Trip 'claude.cmd')) -and ($r55TripCount -eq 0) -and ($r55Runs.Count -eq 7) -and ($r55Skipped -eq $r55Runs.Count)) `
    -Said ("claude resolves to $r55Resolved; invocations counted $r55TripCount; runner runs $($r55Runs.Count), each printing the probe SKIPPED: $r55Skipped")
}
catch {
    Add-R55Row -Label 'MEMBER ABORTED -- an exception escaped the body; every row after it is UNMEASURED' `
        -Ok $false -Said ("line " + $_.InvocationInfo.ScriptLineNumber + " :: " + $_.Exception.GetType().Name + " :: " + ($_.Exception.Message -replace '[\r\n]+', ' '))
}
finally {
    $env:PATH = $r55PathBefore
    # BATCH-6 WP-P (e): THE REMOVAL IS MEASURED, NOT SWALLOWED. Until this row the catch below was empty, and
    # every run left its %TEMP%\lam-wp2-r55-<8 hex> without a word; row (z) says whether the folder is gone and, when it
    # is not, what Remove-Item said and how many entries it left.
    $r55RmWhy = ''
    $r55Stopped = @()
    if (-not $KeepSandbox) {
        # THE CURE, IN R-50's IDIOM (:8926-:8935). THE CAUSE, MEASURED BY ROW (z)'s FIRST READING: Remove-Item met
        # "The process cannot access the file '<root>\a\m-worktrees\wt-D-R55-D' because it is being used by another
        # process" -- row (5)'s descendant (six seconds under a bound of 0, so nothing waits for it) still stood in the
        # tree the runner gave its session. So every descendant a stub recorded (child_pid= in its .session file) that is
        # still alive is stopped and waited for FIRST -- and only when its own command line names this member's root, so
        # a pid the system has since handed to another process is never touched. Row (3a) read its descendant's liveness
        # above, before this. Then the removal, and R-50's fallback.
        foreach ($r55SessFile in @(Get-ChildItem -LiteralPath $r55Temp -Filter 'obs-*.session' -File -ErrorAction SilentlyContinue)) {
            $r55Cp = [string](Get-R55Obs -Path $r55SessFile.FullName)['child_pid']
            if ($r55Cp -notmatch '^[0-9]+$') { continue }
            $r55Proc = @(Get-CimInstance -ClassName Win32_Process -Filter ('ProcessId=' + $r55Cp) -ErrorAction SilentlyContinue)
            if (($r55Proc.Count -eq 1) -and ([string]$r55Proc[0].CommandLine).Contains($r55Temp)) {
                try { Stop-Process -Id ([int]$r55Cp) -Force -ErrorAction Stop } catch { }
                try { Wait-Process -Id ([int]$r55Cp) -Timeout 10 -ErrorAction Stop } catch { }
                $r55Stopped += $r55Cp
            }
        }
        try { Remove-Item -LiteralPath $r55Temp -Recurse -Force -ErrorAction Stop } catch { $r55RmWhy = ($_.Exception.Message -replace '[\r\n]+', ' ') }
        if (Test-Path -LiteralPath $r55Temp) {
            try {
                Get-ChildItem -LiteralPath $r55Temp -Recurse -Force -ErrorAction SilentlyContinue | ForEach-Object { $_.Attributes = 'Normal' }
                [System.IO.Directory]::Delete($r55Temp, $true)
            } catch { $r55RmWhy += ('; Directory.Delete said: ' + ($_.Exception.Message -replace '[\r\n]+', ' ')) }
        }
    }
    if ($KeepSandbox) {
        Add-R55Row -Label '(z) the member''s %TEMP% root is KEPT, as -KeepSandbox asks' -Ok $true -Said $r55Temp
    } else {
        $r55Left = @(Get-ChildItem -LiteralPath $r55Temp -Recurse -Force -ErrorAction SilentlyContinue).Count
        Add-R55Row -Label '(z) the member''s own %TEMP% root is GONE after its teardown' -Ok (-not (Test-Path -LiteralPath $r55Temp)) `
            -Said ($r55Temp + ' exists=' + (Test-Path -LiteralPath $r55Temp) + ' entries left=' + $r55Left + ' descendants stopped first=[' + ($r55Stopped -join ',') + ']' + $(if ($r55RmWhy) { '; Remove-Item said: ' + $r55RmWhy } else { '' }))
    }
}
Check -Id 'R-55' -Title 'NO RESULT AT SESSION END (BATCH-3 WP-K (a)): a validator session, stubbed, that exits leaving no result at its declared result_path in its own tree while a descendant process of it is alive makes the runner WAIT, no longer than -NoResultWaitSeconds, for the descendants to end, and read the result once more -- where the descendant wrote the result inside the bound it is PLACED and bound as a result written before the exit is; where the descendant ended with none, the runner exits 3 under a NAMED refusal, NO-RESULT-AT-SESSION-END-DESCENDANTS-ENDED, in its anchors, in the rejection record and in ONE note composed by tools/lam/spawn_ledger.py carrying the pids it saw, the complete line composed from those anchors names the refusal beside its null result, and the close CLI''s roster gate and the transcription tool''s bare-id path, the tree''s own, each set that line aside beside a bound line at the same round, the gate naming it on its [PASS] line; where the bound elapses with the descendant alive the refusal is NO-RESULT-AT-SESSION-END-BOUND-ELAPSED, naming the bound and the count still alive, and the runner returns without waiting for it; a bound of 0 switches the wait off and no descendant alive is not waited for, each under its own name; and a session that writes its result before it exits is placed with no trace of any of this, its anchors'' keys and its complete line equal to the base runner''s over the same stub; no real claude CLI ran, by a tripwire first on PATH' `
      -Ok $r55ok -Detail ("      THE $(@($r55rows | Where-Object { $_ -match ' : (True|False)' }).Count) ROWS:`n" + ($r55rows -join "`n"))

# =============================================================================================
# R-56 -- THE RUNNER'S MODEL ARGUMENT REACHES THE COMPLETE LINE (BATCH-4 WP-M (d))
# =============================================================================================
# THE ROW. The runner resolves a model from model-routing.yaml and hands it to the session as `--model`; a validator
# names a model in its own result's validator_identity, in prose, or names none. Neither reached a spawn-ledger line
# as a field. THE CHARTER'S FALSIFIER: the complete line carries the runner's argument beside the
# validator's own report, and says so where they differ.
#
# THE RUNNER IS NOT EDITED. It already writes its argument on the durable anchors (`model_id:`), and the ceremony's
# complete line already names those anchors (anchors_path, anchors_sha256, as the live lines do). So the COMPOSER
# reads the anchors at the moment of the act and stamps runner_model, validator_model_reported and -- where they
# differ or none is named -- model_note. Rows (1) and (1a) are therefore CONTROLS that hold on any tree: the session's
# argv carries --model, and the anchors carry the same value. The rows marked CEREMONY play the complete line through
# the tree's own composer, reading every placement field from the anchors the runner wrote and naming those anchors
# by the relative path the live ceremony writes.
#
# THE SESSION IS STUBBED IN A VALIDATOR'S REAL SHAPE (R-54's): a script with no param() block, so the runner's argv
# arrives in $args verbatim. It records that argv, takes the token after --model, and writes its result in its own
# tree at the declared result_path with a validator_identity the row chooses: another model after the word "model",
# the very model its argv carried, or no model at all. No -LoginProbeCommand is given, so the probe is SKIPPED and
# says so; no real `claude -p` runs. The fixture is this member's own mission root (the row-193 standing).
$r56ok = $true
$r56rows = New-Object System.Collections.Generic.List[string]
function Add-R56Row {
    param([string]$Label, [bool]$Ok, [string]$Said)
    if (-not $Ok) { $script:r56ok = $false }
    $script:r56rows.Add(('      {0,-108} : {1}{2}' -f $Label, $Ok, $(if ($Said) { '  -- ' + (($Said -replace '\s+', ' ').Trim()) } else { '' })))
}
function New-R56ValidatorStub {
    # -IdentityExpr: a PowerShell expression the stub evaluates for its validator_identity; $m is its argv's model.
    param([string]$Path, [string]$Rel, [string]$Obs, [string]$Aid, [string]$IdentityExpr)
    Write-Utf8 -Path $Path -Text ("`$root = `$env:LAM_WORKTREE`n" +
        "New-Item -ItemType File -Path (Join-Path `$root 'worker-created.txt') -Force | Out-Null`n" +
        "Write-Output 'R56-VALIDATOR-STUB'`n" +
        "`$m = ''`n" +
        "for (`$i = 0; `$i -lt (`$args.Count - 1); `$i++) { if ([string]`$args[`$i] -ceq '--model') { `$m = [string]`$args[`$i + 1] } }`n" +
        "[System.IO.File]::WriteAllText('$Obs', ('argc=' + `$args.Count + [char]10 + 'model=' + `$m + [char]10))`n" +
        "`$ident = $IdentityExpr`n" +
        "`$dst = Join-Path `$root '$Rel'`n" +
        "New-Item -ItemType Directory -Path (Split-Path -Parent `$dst) -Force | Out-Null`n" +
        "[System.IO.File]::WriteAllText(`$dst, ('verdict: PASS' + [char]10 + 'id: D-V-$Aid' + [char]10 + 'validates: $Aid' + [char]10 + 'validator_identity: ' + [char]39 + `$ident + [char]39 + [char]10 + 'findings: []' + [char]10))`n" +
        "exit 0`n")
}
function Invoke-R56Validator {
    param([string]$Id, [string]$Aid, [string]$IdentityExpr)
    $r56Rel = "tests/lam/validator-$Aid.result.yaml"
    $r56Obs = Join-Path $sandbox ("r56-obs-$Id.txt")
    $r56Stub = Join-Path $stubDir ("validator-r56-$Id.ps1")
    New-R56ValidatorStub -Path $r56Stub -Rel $r56Rel -Obs $r56Obs -Aid $Aid -IdentityExpr $IdentityExpr
    Write-WpgDispatch -Root $r56.root -Id $Id -ModelClass 'qa-validator' -Kind 'read-only' -Extra ("validates: $Aid`nround: 1`nresult_path: $r56Rel`n")
    $r56Run = Invoke-WpgRunner -Root $r56.root -Id $Id -Extra @('-WorkerCommand', $r56Stub)
    $r56Seen = @{}
    if (Test-Path -LiteralPath $r56Obs -PathType Leaf) { foreach ($l in ([System.IO.File]::ReadAllText($r56Obs) -split "`n")) { if ($l -match '^([a-z]+)=(.*)$') { $r56Seen[$Matches[1]] = $Matches[2].Trim() } } }
    $r56AnchorsFile = Join-Path $r56.root ".mission\dispatches\$Id.anchors.yaml"
    return [pscustomobject]@{
        run = $r56Run; id = $Id; aid = $Aid; rel = $r56Rel; argvModel = [string]$r56Seen['model']; argc = [string]$r56Seen['argc']
        anchors = $r56AnchorsFile; anchorsRel = ".mission/dispatches/$Id.anchors.yaml"; dst = (Join-Path $r56.root ($r56Rel -replace '/', '\'))
    }
}
function New-R56Complete {
    # THE CEREMONY'S LINE for a placed result: every placement field read from the anchors (R-54 row (1b)'s form),
    # and the anchors NAMED -- by the relative path the live lines write, and the sha256 of the file as it stands.
    param([int]$Seq, $Run)
    return [ordered]@{
        event = 'complete'; seq = $Seq; kind = 'validator'; role = 'qa-validator'; dispatch_id = $Run.id; validates = $Run.aid; round = 1
        verdict = (Get-WpgAnchorField $Run.anchors 'validator_result'); result_path = $Run.rel
        result_sha256 = (Get-WpgAnchorField $Run.anchors 'validator_result_placement_sha256'); result_source_sha256 = (Get-WpgAnchorField $Run.anchors 'validator_result_placement_source_sha256')
        result_source_path = (Get-WpgAnchorField $Run.anchors 'validator_result_placement_source'); result_dest_path = (Get-WpgAnchorField $Run.anchors 'validator_result_placement_destination')
        anchors_path = $Run.anchorsRel; anchors_sha256 = (Get-WpgSha $Run.anchors)
    }
}
function Add-R56Line {
    # One line through the tree's composer. Returns the exit, the text, the appended line parsed, and its key names.
    param([System.Collections.IDictionary]$Record, [string]$Name)
    $r56File = Join-Path $sandbox ("r56-line-$Name.json")
    Write-Utf8 -Path $r56File -Text ($Record | ConvertTo-Json -Compress -Depth 4)
    $r56Ap = Invoke-WpgComposer -PyArgs @('append', '--ledger', $r56.ledger, '--line-file', $r56File)
    $r56Obj = $null
    if (($r56Ap.code -eq 0) -and ($r56Ap.text -match '(?m)^APPENDED line \d+ to .*?: (\{.*\})\r?$')) { try { $r56Obj = $Matches[1] | ConvertFrom-Json } catch { $r56Obj = $null } }
    $r56Names = if ($null -ne $r56Obj) { @($r56Obj.PSObject.Properties.Name) } else { @() }
    return [pscustomobject]@{ code = $r56Ap.code; text = $r56Ap.text; obj = $r56Obj; names = $r56Names }
}
function Get-R56Field {
    # A field of an appended line read BY NAME: '(no such key)' where the line does not carry it, '(null)' where it is JSON null.
    param($Line, [string]$Key)
    if ($Line.names -notcontains $Key) { return '(no such key)' }
    if ($null -eq $Line.obj.$Key) { return '(null)' }
    return [string]$Line.obj.$Key
}
try {
$r56 = New-WpgMissionRoot -Name 'r56'
$r56rows.Add('      the member''s own mission root: ' + $r56.root + ' ; git dir ' + $r56.gitDir + ' ; common dir ' + $r56.commonDir)
$r56rows.Add('      the stamp the tree''s composer writes (git rev-parse HEAD:tools/lam/spawn_ledger.py): ' + $(if ($wpgStamp) { $wpgStamp } else { '(none)' }))
$r56Other = 'claude-r56-another-9'

# ---- (1) the runner's argument, on the session's argv and on the anchors ----------------------------------------------
$r56a = Invoke-R56Validator -Id 'D-R56-A' -Aid 'A-9371' -IdentityExpr ("'D-V-A-9371, session r56-fixture, model " + $r56Other + ", rung L3, qa-validator, read-only'")
$r56X = $r56a.argvModel
