    -Ok (($r56a.run.exit -eq 3) -and [bool]$r56X -and ($r56a.run.out -match '(?m)^mission-dispatch: validator result PLACED') -and ($r56a.run.out -match '(?m)^mission-dispatch: login probe -- SKIPPED')) `
