$r56aAnchorModel = Get-WpgAnchorField $r56a.anchors 'model_id'
Add-R56Row -Label '(1a) CONTROL the anchors the runner wrote carry that same value at column 0, model_id -- the durable record the complete line names' `
    -Ok ([bool]$r56X -and ($r56aAnchorModel -ceq $r56X)) -Said ("anchors model_id '$r56aAnchorModel' ; argv --model '$r56X'")

# ---- (2) CEREMONY: the validator reports ANOTHER model ---------------------------------------------------------------
$r56C1 = Add-R56Line -Name 'complete-a' -Record (New-R56Complete -Seq 1 -Run $r56a)
$r56WantNote = 'MODEL DIFFERENCE: the runner''s argument was ' + $r56X + '; the result''s validator_identity reports ' + $r56Other
Add-R56Row -Label '(2) FALSIFIER CEREMONY the complete line composed from those anchors carries runner_model, the argv''s value; validator_model_reported, the OTHER model the result names; and model_note, MODEL DIFFERENCE naming both' `
    -Ok ([bool]$r56X -and ((Get-R56Field $r56C1 'runner_model') -ceq $r56X) -and ((Get-R56Field $r56C1 'validator_model_reported') -ceq $r56Other) -and ((Get-R56Field $r56C1 'model_note') -ceq $r56WantNote) -and
         ($r56C1.names.Count -gt 0) -and ($r56C1.names[$r56C1.names.Count - 1] -ceq 'composed_by') -and [bool]$wpgStamp -and ((Get-R56Field $r56C1 'composed_by') -ceq $wpgStamp)) `
    -Said ("append exit $($r56C1.code); runner_model=$(Get-R56Field $r56C1 'runner_model') validator_model_reported=$(Get-R56Field $r56C1 'validator_model_reported') model_note=$(Get-R56Field $r56C1 'model_note') :: " + (Get-WpgFirstLines $r56C1.text 1))
$r56Bound = Invoke-R54Bound -Root $r56.root -File $r56a.dst
Add-R56Row -Label '(2a) CONTROL the goal evaluator''s UNCHANGED reader, Test-LamLedgerBound, binds the placed copy through result_sha256 on that line -- it reads three fields and none of the new ones' `
    -Ok ([bool]$r56Bound.bound) -Said ("bound=$($r56Bound.bound) :: $($r56Bound.reason)")

# ---- (3) CEREMONY: the validator reports the SAME model -----------------------------------------------------------------
$r56b = Invoke-R56Validator -Id 'D-R56-B' -Aid 'A-9372' -IdentityExpr "('D-V-A-9372, session r56-fixture, model ' + `$m + ', rung L3, qa-validator, read-only')"
$r56C2 = Add-R56Line -Name 'complete-b' -Record (New-R56Complete -Seq 2 -Run $r56b)
Add-R56Row -Label '(3) FALSIFIER CEREMONY a validator whose result names the very model its argv carried: runner_model and validator_model_reported are EQUAL, and the line carries NO model_note' `
    -Ok ([bool]$r56b.argvModel -and ($r56b.argvModel -ceq $r56X) -and ((Get-R56Field $r56C2 'runner_model') -ceq $r56X) -and ((Get-R56Field $r56C2 'validator_model_reported') -ceq $r56X) -and ((Get-R56Field $r56C2 'model_note') -ceq '(no such key)')) `
    -Said ("runner exit $($r56b.run.exit); append exit $($r56C2.code); runner_model=$(Get-R56Field $r56C2 'runner_model') validator_model_reported=$(Get-R56Field $r56C2 'validator_model_reported') model_note=$(Get-R56Field $r56C2 'model_note') :: " + (Get-WpgFirstLines $r56C2.text 1))

# ---- (4) CEREMONY: the validator names NO model ------------------------------------------------------------------------
$r56c = Invoke-R56Validator -Id 'D-R56-C' -Aid 'A-9373' -IdentityExpr "'claude-code:qa-validator D-V-A-9373, session r56-fixture, rung L3, read-only'"
$r56C3 = Add-R56Line -Name 'complete-c' -Record (New-R56Complete -Seq 3 -Run $r56c)
Add-R56Row -Label '(4) FALSIFIER CEREMONY a validator whose result names NO model ("claude-code" is not one): validator_model_reported is JSON null, present, and model_note says none is named' `
    -Ok (((Get-R56Field $r56C3 'runner_model') -ceq $r56X) -and [bool]$r56X -and ((Get-R56Field $r56C3 'validator_model_reported') -ceq '(null)') -and
         ((Get-R56Field $r56C3 'model_note') -ceq ('NO MODEL REPORTED: the runner''s argument was ' + $r56X + '; the result''s validator_identity names no model'))) `
    -Said ("runner exit $($r56c.run.exit); append exit $($r56C3.code); runner_model=$(Get-R56Field $r56C3 'runner_model') validator_model_reported=$(Get-R56Field $r56C3 'validator_model_reported') model_note=$(Get-R56Field $r56C3 'model_note') :: " + (Get-WpgFirstLines $r56C3.text 1))

