$r56d = Invoke-R56Validator -Id 'D-R56-D' -Aid 'A-9374' -IdentityExpr "('D-V-A-9374, session r56-fixture, model ' + `$m + ', rung L3')"
$r56Typed = New-R56Complete -Seq 4 -Run $r56d
$r56Typed['runner_model'] = 'a-model-the-seat-typed'
