$r56Stale['anchors_sha256'] = (Get-WpgSha $r56a.anchors)
$r56C5 = Add-R56Line -Name 'complete-d-stale' -Record $r56Stale
Add-R56Row -Label '(6) FALSIFIER nor name anchors that are not the bytes on disk: a complete line whose anchors_sha256 is ANOTHER dispatch''s anchors is REFUSED, the ledger byte-unchanged' `
    -Ok (($r56C5.code -eq 2) -and ($r56C5.text -match '(?m)^REFUSED: ') -and ($r56C5.text -match 'not anchors_sha256') -and ((Get-WpgSha $r56.ledger) -ceq $r56LedgerSha)) `
    -Said ("exit $($r56C5.code) :: " + (Get-WpgFirstLines $r56C5.text 1))
$r56C6 = Add-R56Line -Name 'complete-d' -Record (New-R56Complete -Seq 6 -Run $r56d)
$r56Audit = Invoke-WpgComposer -PyArgs @('audit', '--ledger', $r56.ledger, '--after', '0', '--prefix-sha256', 'e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855')
Add-R56Row -Label '(7) CONTROL the same line as the anchors give it is APPENDED, and the composer''s own forward-only audit, cut off at 0, PASSES over this ledger' `
    -Ok (($null -ne $r56C6.obj) -and ($r56Audit.code -eq 0) -and ($r56Audit.text -match '(?m)^RESULT PASS after_cutoff=[1-9][0-9]* violations=0 ')) `
    -Said ("append exit $($r56C6.code); audit exit $($r56Audit.code) :: " + (@($r56Audit.text -split "`n") | Where-Object { $_ -match '^RESULT ' } | Select-Object -First 1))
}
catch {
    Add-R56Row -Label 'MEMBER ABORTED -- an exception escaped the body; every row after it is UNMEASURED' `
        -Ok $false -Said ("line " + $_.InvocationInfo.ScriptLineNumber + " :: " + $_.Exception.GetType().Name + " :: " + ($_.Exception.Message -replace '[\r\n]+', ' '))
}
Check -Id 'R-56' -Title 'THE RUNNER''S MODEL ARGUMENT REACHES THE COMPLETE LINE (BATCH-4 WP-M (d)): a validator dispatch through the real runner, its session stubbed, is handed --model on its argv and the anchors the runner writes carry that same value as model_id; the complete line composed by tools/lam/spawn_ledger.py from those anchors, naming them by anchors_path and anchors_sha256, carries runner_model, that value, and validator_model_reported, the model the placed result''s validator_identity names -- with model_note saying MODEL DIFFERENCE and naming both where the result names another model, no model_note where it names the same one, and JSON null with a note where it names none -- and the goal evaluator''s unchanged Test-LamLedgerBound still binds the placed copy; the composer REFUSES a complete line that carries a runner_model of its own, and one whose anchors_sha256 is not the anchors on disk; the forward-only audit passes the ledger so composed; no runner file is edited by this, and no real claude CLI ran -- the probe is skipped for a stubbed worker and says so' `
      -Ok $r56ok -Detail ("      THE $(@($r56rows | Where-Object { $_ -match ' : (True|False)' }).Count) ROWS:`n" + ($r56rows -join "`n") +
          "`n      WHAT THIS MEMBER DOES NOT CLAIM: that the runner writes any of the three keys -- it writes the anchors, and the complete line is the`n" +
          "        ceremony's; that the routed model is any particular one (it is read from the session's own argv); or that a seat names its anchors.")

# =============================================================================================
# R-57 -- THE PRODUCT INSTRUMENT'S PER-TEST TIMEOUT NAMES THE HUNG TEST, AND THE TREE IS KILLED (the per-test
#         timeout charter, clause (c))
# =============================================================================================
# THE ROW: at a live 900 s wall-kill, -KeepPytestOutput kept 30 lines of pytest's output ending after
# [ 73%] and no faulthandler dump -- the stall was not named. THE CHARTER'S FALSIFIER (clause (c)): a
# fixture test that sleeps past n is named in the kept output and the exit is today's failure; without the flag the
# instrument is byte-identical.
# THE RULE (the product instrument ALONE; tools\lam\lam-instrument-run.ps1 is held to a pinned blob, row (8)):
# -PerTestTimeoutSeconds <n>, 0 by default and declared last. Given, the pytest line gains ` -o faulthandler_timeout=<n>`
# after -KeepPytestOutput's own (the last -o wins); a STDERR line at column 0 reading `Timeout (h:mm:ss)!` -- the dump's
# header -- arms a short drain and then the instrument's EXISTING tree kill (the snapshot from the live root, taskkill
# /T /F, survivors, the bounded drain), never faulthandler_exit_on_timeout, whose _exit skips every fixture teardown.
# The test is read from the dump -- walking inward from pytest_pyfunc_call (or call_fixture_func for a fixture) to the
# first frame under the suite's folder and outside site-packages -- and named on ONE WALL note, before the KEPT line, and on M2's LEADING conjunct C5; C4 is not claimed; TALLY keeps its
# nine fields with pytest_exit=124; the exit is today's failure. Given and not below -WallSeconds, it is REFUSED before
# anything runs. Off, no printed byte moves, stdout or stderr.
# THE FIXTURE is C-1be's (WP-3): a scratch root under %TEMP%, a BYTE COPY of the instrument (the base version's bytes
# written over it for the BASE rows, read from its synthetic fixture and held to their pin), stored_floor 1, the mirror's
# exact LF bytes, src\ a one-test pytest project, run DIRECTLY with UV_PROJECT_ENVIRONMENT naming this tree's own
# src\.venv, UV_NO_SYNC=1 and UV_OFFLINE=1 for the child alone. The sleeping test spawns a child of its own and both
# write their pids, so the kill is seen to take the tree. The rows that run pytest need that venv and are NOT MEASURED
# where it is absent (C-1k's words); the base's refusal of the flag, the n-not-below-the-wall refusal,
# the helper's blob and the plane row need none and are measured either way.
$r57ok = $true
$r57rows = New-Object System.Collections.Generic.List[string]
$r57Live = New-Object System.Collections.Generic.List[object]
function Add-R57Row {
    param([string]$Label, [bool]$Ok, [string]$Said)
    if (-not $Ok) { $script:r57ok = $false }
    $script:r57rows.Add(('      {0,-108} : {1}{2}' -f $Label, $Ok, $(if ($Said) { '  -- ' + (($Said -replace '\s+', ' ').Trim()) } else { '' })))
}
function Stop-R57Tree {
    param($Proc)
    if ($null -eq $Proc) { return }
    try { if ($Proc.HasExited) { return } } catch { return }
    $prevEap = $ErrorActionPreference; $ErrorActionPreference = 'Continue'
    try { $null = (& taskkill.exe /T /F /PID $Proc.Id 2>&1) } finally { $ErrorActionPreference = $prevEap }
    try { [void]$Proc.WaitForExit(15000) } catch { }
}
function Invoke-R57Run {
    # ONE DIRECT RUN of the fixture's instrument (C-1be's form): `powershell -NoProfile -ExecutionPolicy Bypass -File
    # <the copy> <-Arguments>` in the scratch root, the three uv variables set for the child alone, stdout and stderr
    # read apart, waited for -TimeoutSeconds and no longer (its tree killed past it). CRs are dropped from both texts.
    param([string]$Arguments, [int]$TimeoutSeconds = 240)
    $r57RnPsi = New-Object System.Diagnostics.ProcessStartInfo
    $r57RnPsi.FileName = 'powershell.exe'
    $r57RnPsi.Arguments = '-NoProfile -ExecutionPolicy Bypass -File "' + $script:r57Inst + '" ' + $Arguments
    $r57RnPsi.WorkingDirectory = $script:r57Root
    $r57RnPsi.UseShellExecute = $false
    $r57RnPsi.CreateNoWindow = $true
    $r57RnPsi.RedirectStandardOutput = $true
    $r57RnPsi.RedirectStandardError = $true
    $r57RnPsi.EnvironmentVariables['UV_PROJECT_ENVIRONMENT'] = $script:r57Venv
    $r57RnPsi.EnvironmentVariables['UV_NO_SYNC'] = '1'
    $r57RnPsi.EnvironmentVariables['UV_OFFLINE'] = '1'
    $r57RnClock = [System.Diagnostics.Stopwatch]::StartNew()
    $r57RnProc = [System.Diagnostics.Process]::Start($r57RnPsi)
    $script:r57Live.Add($r57RnProc)
    $r57RnOut = $r57RnProc.StandardOutput.ReadToEndAsync()
    $r57RnErr = $r57RnProc.StandardError.ReadToEndAsync()
    $r57RnTimedOut = -not $r57RnProc.WaitForExit($TimeoutSeconds * 1000)
    if ($r57RnTimedOut) { Stop-R57Tree -Proc $r57RnProc } else { $r57RnProc.WaitForExit() }
    $r57RnO = ''; $r57RnE = ''
    try { if ($r57RnOut.Wait(15000)) { $r57RnO = [string]$r57RnOut.Result } } catch { }
    try { if ($r57RnErr.Wait(5000)) { $r57RnE = [string]$r57RnErr.Result } } catch { }
    $r57RnExit = $null
    try { if ($r57RnProc.HasExited) { $r57RnExit = $r57RnProc.ExitCode } } catch { }
    return [pscustomobject]@{ exit = $r57RnExit; out = ($r57RnO -replace "`r", ''); err = ($r57RnE -replace "`r", '')
                              seconds = [Math]::Round($r57RnClock.Elapsed.TotalSeconds, 1); timedOut = $r57RnTimedOut }
}
function Get-R57Kept {
    # The kept file as it stands: exists, bytes, and its text with CRs dropped.
    param([string]$Path)
    if (-not (Test-Path -LiteralPath $Path -PathType Leaf)) { return [pscustomobject]@{ exists = $false; bytes = 0; text = '' } }
    $r57KpB = [System.IO.File]::ReadAllBytes($Path)
    return [pscustomobject]@{ exists = $true; bytes = $r57KpB.Length; text = ((New-Object System.Text.UTF8Encoding($false)).GetString($r57KpB) -replace "`r", '') }
}
function Test-R57MarkerAlive {
    # C-1k's reading of a pid file: alive only while a process with that pid exists that started BEFORE the file was
    # written, so a reused pid is not mistaken for it.
    param([string]$Marker)
    if (-not (Test-Path -LiteralPath $Marker)) { return $false }
    $r57Mp = 0
    try { $r57Mp = [int]([System.IO.File]::ReadAllText($Marker).Trim()) } catch { return $false }
    $r57Gp = Get-Process -Id $r57Mp -ErrorAction SilentlyContinue
    if ($null -eq $r57Gp) { return $false }
    try {
        if ($r57Gp.HasExited) { return $false }
        if ($r57Gp.StartTime -gt (Get-Item -LiteralPath $Marker).LastWriteTime) { return $false }
    } catch { }
    return $true
}
function Get-R57RootNamers {
    # Every live process whose command line names the scratch root -- the sleeping test's child runs a script under it.
    return @(Get-CimInstance -ClassName Win32_Process -ErrorAction SilentlyContinue |
             Where-Object { ([string]$_.CommandLine).IndexOf($script:r57Root, [System.StringComparison]::OrdinalIgnoreCase) -ge 0 })
}
function Get-R57Masked {
    # A run's text "but for the clock and the elapsed seconds" (C-1be's mask): TALLY's elapsed_seconds and pytest's own
    # "in <s>s". Nothing else is masked.
    param([string]$Text)
    return (([string]$Text -replace 'elapsed_seconds=\d+', 'elapsed_seconds=MASKED') -replace '\bin \d+(\.\d+)?s\b', 'in MASKEDs')
}
function Get-R57TallyKeys {
    param([string]$Out)
    $r57Tk = [regex]::Match([string]$Out, '(?m)^TALLY (.*)$')
    if (-not $r57Tk.Success) { return '' }
    return ((@([regex]::Matches($r57Tk.Groups[1].Value, '(\w+)=') | ForEach-Object { $_.Groups[1].Value })) -join ' ')
}
function Get-R57LineIndexes {
    param([string]$Out, [string]$Prefix)
    $r57LiLines = @(([string]$Out) -split "`n")
    return @(for ($r57Li = 0; $r57Li -lt $r57LiLines.Count; $r57Li++) { if ($r57LiLines[$r57Li].StartsWith($Prefix, [System.StringComparison]::Ordinal)) { $r57Li } })
}
function Get-R57Said {
    param([string]$Tools, $Run)
    $r57SdLines = @(([string]$Run.out) -split "`n" | Where-Object { $_ -match '^(TALLY|WALL|KEPT|PASS|FAIL|EXIT)\b' })
    return ($Tools + ': exit ' + $Run.exit + ', ' + $Run.seconds + ' s' + $(if ($Run.timedOut) { ', TIMED OUT' } else { '' }) + '; lines [' + ($r57SdLines -join ' | ') + ']' +
            $(if ([string]$Run.err) { '; stderr: ' + ((([string]$Run.err) -replace '\s+', ' ').Trim()) } else { '' }))
}
function Clear-R57Markers {
    foreach ($r57Cm in @($script:r57Marker, $script:r57ChildMark)) { if (Test-Path -LiteralPath $r57Cm) { Remove-Item -LiteralPath $r57Cm -Force } }
}
function Get-R57RunsSnapshot {
    # This tree's own instrument-runs, as names, lengths and write times: what the plane row holds unchanged.
    if (-not (Test-Path -LiteralPath $script:r57RunsDir)) { return '(absent)' }
    return ((@(Get-ChildItem -LiteralPath $script:r57RunsDir -File -Force | Sort-Object Name | ForEach-Object { $_.Name + ' ' + $_.Length + ' ' + $_.LastWriteTimeUtc.Ticks })) -join "`n")
}
# THE INSTRUMENT AND THE VENV: Get-LamArcInstrument -- the synthetic suite instrument
# with its fixture held to its pin -- and Get-LamPytestVenv, a venv that holds pytest.
$r57Arc        = Get-LamArcInstrument
$r57Instrument = $r57Arc.path
$r57HelperRel  = 'tools/lam/lam-instrument-run.ps1'
$r57HelperBlob = '4f2503ae18562d20fc78794a773d18267efdfebc'
$r57VenvPick   = Get-LamPytestVenv
$r57Venv       = $r57VenvPick.path
$r57RunsDir    = Join-Path $repoRoot '.mission-runtime\lam\instrument-runs'
$r57BaseVersion = '700e19e5-s11'
$r57BaseSpec   = 'the sample suite instrument at its base version'
$r57BaseSha256 = $lamSuitePins[$r57BaseVersion]
$r57Root       = [System.IO.Path]::GetFullPath((Join-Path ([System.IO.Path]::GetTempPath()) ('lam-wp2-r57-' + [guid]::NewGuid().ToString('N').Substring(0, 8))))
$r57Inst       = Join-Path $r57Root 'tests\lam\instrument-sample-suite.ps1'
$r57Test       = Join-Path $r57Root 'src\test_r57.py'
$r57Marker     = Join-Path $r57Root 'src\sleep.pid'
$r57ChildMark  = Join-Path $r57Root 'src\child.pid'
$r57KeepBase   = Join-Path $r57Root '.mission-runtime\keep\r57-base.pytest-output.txt'
$r57KeepTree   = Join-Path $r57Root '.mission-runtime\keep\r57-tree.pytest-output.txt'
$r57TallyWant  = 'passed failed skipped deselected runnable stored_floor collection_error pytest_exit elapsed_seconds'
$r57KeysWant   = 'writer capture_format run_key goal detector_ordinal instrument cwd captured_at ran exit_code tally_count body_bytes body_sha256 head tree_clean tree_reason instrument_sha256 instrument_resolved'
$r57SleepTest  = "import os`nimport subprocess`nimport sys`nimport time`n`nHERE = os.path.dirname(os.path.abspath(__file__))`n`n`n" +
                 "def test_sleeps_past_n():`n" +
                 "    child = subprocess.Popen([sys.executable, os.path.join(HERE, 'child_sleep.py')])`n" +
                 "    with open(os.path.join(HERE, 'child.pid'), 'w') as f:`n        f.write(str(child.pid))`n" +
                 "    with open(os.path.join(HERE, 'sleep.pid'), 'w') as f:`n        f.write(str(os.getpid()))`n" +
                 "    time.sleep(3600)`n"
$r57SleepLine  = [array]::IndexOf([string[]]($r57SleepTest -split "`n"), '    time.sleep(3600)') + 1
$r57FixtureTest = "import time`n`nimport pytest`n`n`n@pytest.fixture`ndef sleepy_fixture():`n    time.sleep(3600)`n    yield`n`n`n" +
                  "def test_uses_the_sleepy_fixture(sleepy_fixture):`n    assert True`n"
$r57PassTest   = "def test_passes_at_once():`n    assert True`n"
$r57AsyncTest  = "import asyncio`n`nimport pytest`n`n`n@pytest.mark.asyncio`nasync def test_awaits_past_n():`n    await asyncio.sleep(3600)`n"
$r57EchoTest   = "def test_prints_the_header_and_fails():`n    print('Timeout (0:00:05)!')`n    assert False`n"
$r57PatchedTest = "import time`nimport unittest.mock`n`n`n@unittest.mock.patch('os.getcwd')`ndef test_patched_sleeper(mocked):`n    time.sleep(3600)`n"
$r57PatchedLine = [array]::IndexOf([string[]]($r57PatchedTest -split "`n"), '    time.sleep(3600)') + 1
$r57Name       = 'test_r57.py::test_sleeps_past_n (line ' + $r57SleepLine + ')'
$r57FxName     = 'fixture test_r57.py::sleepy_fixture'
$r57Skip = ''
$r57NoSubject = (-not $r57Instrument)
if ($r57NoSubject) {
    $r57Skip = 'the instrument under test: ' + $r57Arc.from + ', so it is absent and nothing was built'
} elseif (-not $r57Venv) {
    $r57Skip = "no venv to run the fixture's pytest under: none of $($r57VenvPick.tried) has a Scripts\python.exe"
} elseif (-not (Test-Path -LiteralPath (Join-Path $r57Venv 'Lib\site-packages\_pytest\faulthandler.py') -PathType Leaf)) {
    $r57Skip = "the venv at $r57Venv holds no _pytest\faulthandler.py"
}
$r57RunsBefore = Get-R57RunsSnapshot
try {
  if ($r57NoSubject) { $r57rows.Add('      NOTHING WAS BUILT: ' + $r57Arc.from) } else {
    # THE FIXTURE, built whether or not the venv stands.
    $null = New-Item -ItemType Directory -Path (Join-Path $r57Root 'tests\lam') -Force
    Copy-Item -LiteralPath $r57Instrument -Destination $r57Inst -Force
    $r57TreeBytes = [System.IO.File]::ReadAllBytes($r57Inst)
    $r57ShaTree = (Get-FileHash -Algorithm SHA256 -LiteralPath $r57Instrument).Hash.ToLowerInvariant()
    $r57ShaCopy = (Get-FileHash -Algorithm SHA256 -LiteralPath $r57Inst).Hash.ToLowerInvariant()
    $r57BaseFile = Join-Path $r57Root 'base\instrument-sample-suite.base0002.ps1'
    # Read through Get-LamSuiteBytes: the synthetic fixture of that version, held to its pin.
    $r57BaseRead = Get-LamSuiteBytes -Version $r57BaseVersion
    $r57BaseGot = $r57BaseRead.sha
    $r57BaseOk = ($r57BaseRead.ok -and ($r57BaseGot -ceq $r57BaseSha256))
    $r57BaseBytes = [byte[]]@()
    if ($r57BaseOk) { $r57BaseBytes = $r57BaseRead.bytes; $null = New-Item -ItemType Directory -Path (Split-Path -Parent $r57BaseFile) -Force; [System.IO.File]::WriteAllBytes($r57BaseFile, $r57BaseBytes) }
    Write-Utf8 -Path (Join-Path $r57Root '.mission\green-gate\product.json') -Text "{`n  `"stored_floor`": 1,`n  `"expected_failure_test_ids`": []`n}`n"
    Write-Utf8 -Path (Join-Path $r57Root 'tools\mission-cli\config\expected-failures.yaml') `
               -Text ('# DERIVED MIRROR of .mission/green-gate/product.json `expected_failure_test_ids` (the GOVERNING home).' + "`n" +
                      '# Re-derived at every close; tests/lam/instrument-sample-suite.ps1 FAILS on any byte difference.' + "`n" +
                      'expected_failures:' + "`n")
    Write-Utf8 -Path (Join-Path $r57Root 'src\pyproject.toml') -Text "[project]`nname = `"r57-fixture`"`nversion = `"0.0.0`"`nrequires-python = `">=3.13`"`n`n[tool.pytest.ini_options]`n"
    Write-Utf8 -Path (Join-Path $r57Root 'src\child_sleep.py') -Text "import time`ntime.sleep(3600)`n"
    Write-Utf8 -Path $r57Test -Text $r57PassTest
    Add-R57Row -Label 'FIXTURE a scratch root under %TEMP% laid out as the instrument expects (C-1be''s): a BYTE COPY of the instrument read (the synthetic suite instrument); the base version''s bytes read at their pin 0174561e; stored_floor 1, the mirror''s LF bytes; src\ a one-test project' `
        -Ok (($r57ShaTree -ceq $r57ShaCopy) -and $r57BaseOk -and $r57Root.StartsWith([System.IO.Path]::GetFullPath([System.IO.Path]::GetTempPath()), [System.StringComparison]::OrdinalIgnoreCase)) `
        -Said ('root ' + $r57Root + '; instrument read from ' + $r57Arc.from + ', sha256 ' + $r57ShaTree + ', copy ' + $r57ShaCopy + '; base ' + $r57BaseSpec + ' read from ' + $r57BaseRead.from + ': ' + $r57BaseGot + '; venv: ' + $(if ($r57Skip) { 'NOT USABLE -- ' + $r57Skip } else { $r57Venv }))

    # ---- (1) BASE: the base instrument has no such parameter (needs no venv) ---------------------------------------------
    [System.IO.File]::WriteAllBytes($r57Inst, $r57BaseBytes)
    Write-Utf8 -Path $r57Test -Text $r57SleepTest
    Clear-R57Markers
    $r57B1 = Invoke-R57Run -Arguments '-Member M2 -WallSeconds 60 -PerTestTimeoutSeconds 5' -TimeoutSeconds 120
    Add-R57Row -Label '(1) BASE instrument handed -PerTestTimeoutSeconds 5: NO SUCH PARAMETER -- the binder names it, exit non-zero, no banner, no TALLY, the test never started' `
        -Ok ($r57BaseOk -and ($null -ne $r57B1.exit) -and ($r57B1.exit -ne 0) -and (($r57B1.out + $r57B1.err).Contains('PerTestTimeoutSeconds')) -and (-not $r57B1.out.Contains('SAMPLE-SUITE INSTRUMENT')) -and
             (-not $r57B1.out.Contains('TALLY ')) -and (-not (Test-Path -LiteralPath $r57Marker))) `
        -Said (Get-R57Said -Tools 'base' -Run $r57B1)

    if (-not $r57Skip) {
        # ---- (2) BASE over the sleeper, a 30 s wall: today's face -- killed at the wall, and nothing names the test ------
        Clear-R57Markers
        $r57B2 = Invoke-R57Run -Arguments ('-Member M2 -WallSeconds 30 -KeepPytestOutput "' + $r57KeepBase + '"') -TimeoutSeconds 150
        $r57B2Kept = Get-R57Kept -Path $r57KeepBase
        Add-R57Row -Label '(2) BASE instrument over a test sleeping 3600 s, -WallSeconds 30 -KeepPytestOutput: killed at the wall -- TALLY pytest_exit=124, C4 -- and NOTHING names the test, in stdout or in the kept file' `
            -Ok ($r57BaseOk -and ($null -ne $r57B2.exit) -and ($r57B2.exit -ne 0) -and (-not $r57B2.timedOut) -and [regex]::IsMatch($r57B2.out, '(?m)^TALLY .*\bpytest_exit=124\b') -and
                 $r57B2.out.Contains('C4 wall-guard [pytest killed after') -and (Test-Path -LiteralPath $r57Marker) -and $r57B2Kept.exists -and
                 (-not ($r57B2.out + $r57B2Kept.text).Contains('test_sleeps_past_n')) -and (-not $r57B2Kept.text.Contains('Timeout ('))) `
            -Said ((Get-R57Said -Tools 'base' -Run $r57B2) + ' | kept: exists ' + $r57B2Kept.exists + ', ' + $r57B2Kept.bytes + ' B')

        # ---- (3) TREE: the flag at 5 s under a 60 s wall, -KeepPytestOutput --------------------------------------------
        [System.IO.File]::WriteAllBytes($r57Inst, $r57TreeBytes)
        Clear-R57Markers
        $r57T1 = Invoke-R57Run -Arguments ('-Member M2 -WallSeconds 60 -PerTestTimeoutSeconds 5 -KeepPytestOutput "' + $r57KeepTree + '"') -TimeoutSeconds 150
        $r57T1Kept = Get-R57Kept -Path $r57KeepTree
        $r57T1Tally = [regex]::Match($r57T1.out, '(?m)^TALLY .*\belapsed_seconds=(\d+)\s*$')
        $r57C5 = 'FAIL M2 -- the product green gate is RED: C5 per-test-timeout [' + $r57Name + ' ran past 5 s; the tree killed]'
        Add-R57Row -Label '(3) TREE -PerTestTimeoutSeconds 5 -WallSeconds 60 -KeepPytestOutput over the same sleeper: exit 1 WELL INSIDE THE WALL (elapsed under half of it), TALLY pytest_exit=124; M2 FAILS on a LEADING C5 naming the test''s file, function and line; no C4' `
            -Ok (($r57T1.exit -eq 1) -and (-not $r57T1.timedOut) -and $r57T1Tally.Success -and ([int]$r57T1Tally.Groups[1].Value -lt 30) -and [regex]::IsMatch($r57T1.out, '(?m)^TALLY .*\bpytest_exit=124\b') -and
                 [regex]::IsMatch($r57T1.out, '(?m)^' + [regex]::Escape($r57C5)) -and (-not $r57T1.out.Contains('C4 wall-guard'))) `
            -Said (Get-R57Said -Tools 'tree' -Run $r57T1)
        $r57T1Wall = @(Get-R57LineIndexes -Out $r57T1.out -Prefix 'WALL ')
        $r57T1Keep = @(Get-R57LineIndexes -Out $r57T1.out -Prefix 'KEPT ')
        $r57T1Lines = @($r57T1.out -split "`n")
        $r57T1WallText = ''
        if ($r57T1Wall.Count -eq 1) { $r57T1WallText = $r57T1Lines[$r57T1Wall[0]] }
        Add-R57Row -Label '(3a) TREE ONE WALL note, BEFORE the one KEPT line, saying the per-test timeout fired and the tree was killed, and naming the test; the TALLY''s fields the nine of a flag-off run' `
            -Ok (($r57T1Wall.Count -eq 1) -and ($r57T1Keep.Count -eq 1) -and ($r57T1Wall[0] -lt $r57T1Keep[0]) -and $r57T1WallText.Contains('per-test timeout') -and $r57T1WallText.Contains($r57Name) -and
                 $r57T1WallText.Contains('taskkill /T /F') -and ((Get-R57TallyKeys -Out $r57T1.out) -ceq $r57TallyWant)) `
            -Said ('WALL at [' + ($r57T1Wall -join ',') + '], KEPT at [' + ($r57T1Keep -join ',') + ']; ' + $r57T1WallText + ' | TALLY fields: ' + (Get-R57TallyKeys -Out $r57T1.out))
        $r57SleeperAlive = Test-R57MarkerAlive -Marker $r57Marker
        $r57ChildAlive = Test-R57MarkerAlive -Marker $r57ChildMark
        $r57Namers = @(Get-R57RootNamers)
        Add-R57Row -Label '(3b) TREE the kept file holds the dump -- "Timeout (0:00:05)!" at column 0, frames naming test_r57.py, test_sleeps_past_n and pytest_pyfunc_call --; the sleeper AND the child it spawned are dead, no process names the root' `
            -Ok ($r57T1Kept.exists -and [regex]::IsMatch($r57T1Kept.text, '(?m)^Timeout \(0:00:05\)!$') -and $r57T1Kept.text.Contains('test_r57.py') -and $r57T1Kept.text.Contains('test_sleeps_past_n') -and
                 $r57T1Kept.text.Contains('pytest_pyfunc_call') -and (Test-Path -LiteralPath $r57Marker) -and (Test-Path -LiteralPath $r57ChildMark) -and (-not $r57SleeperAlive) -and (-not $r57ChildAlive) -and
                 ($r57Namers.Count -eq 0)) `
            -Said ('kept: exists ' + $r57T1Kept.exists + ', ' + $r57T1Kept.bytes + ' B; its lines [' + (@($r57T1Kept.text -split "`n" | Where-Object { $_ -match 'Timeout \(|test_sleeps_past_n|pytest_pyfunc_call' } | Select-Object -First 4) -join ' | ') +
                   ']; sleeper alive ' + $r57SleeperAlive + ', child alive ' + $r57ChildAlive + ', processes naming the root ' + $r57Namers.Count)

        # ---- (4) TREE: a fixture that sleeps in its setup is named as a fixture ------------------------------------------
        Write-Utf8 -Path $r57Test -Text $r57FixtureTest
        $r57T2 = Invoke-R57Run -Arguments '-Member M2 -WallSeconds 60 -PerTestTimeoutSeconds 5' -TimeoutSeconds 150
        Add-R57Row -Label '(4) TREE a FIXTURE that sleeps in its setup, -PerTestTimeoutSeconds 5 -WallSeconds 60: the leading C5 and the WALL note name "fixture test_r57.py::sleepy_fixture"; exit 1, no C4' `
            -Ok (($r57T2.exit -eq 1) -and (-not $r57T2.timedOut) -and [regex]::IsMatch($r57T2.out, '(?m)^' + [regex]::Escape('FAIL M2 -- the product green gate is RED: C5 per-test-timeout [' + $r57FxName + ' ran past 5 s; the tree killed]')) -and
                 [regex]::IsMatch($r57T2.out, '(?m)^WALL .*' + [regex]::Escape($r57FxName)) -and (-not $r57T2.out.Contains('C4 wall-guard'))) `
            -Said (Get-R57Said -Tools 'tree' -Run $r57T2)

        # ---- (4a) TREE: an ASYNC test -- pytest-asyncio's wrapper is not the test, and the coroutine is on no stack -------
        Write-Utf8 -Path $r57Test -Text $r57AsyncTest
        $r57T5 = Invoke-R57Run -Arguments '-Member M2 -WallSeconds 60 -PerTestTimeoutSeconds 5' -TimeoutSeconds 150
        Add-R57Row -Label '(4a) TREE an ASYNC test awaiting past n (pytest-asyncio runs it through its own wrapper): the leading C5 says the frames name no test function -- no plugin frame named as the test; exit 1, no C4' `
            -Ok (($r57T5.exit -eq 1) -and (-not $r57T5.timedOut) -and [regex]::IsMatch($r57T5.out, '(?m)^' + [regex]::Escape('FAIL M2 -- the product green gate is RED: C5 per-test-timeout [an item ran past 5 s and the frames name no test function; the tree killed]')) -and
                 [regex]::IsMatch($r57T5.out, '(?m)^WALL .*the frames name no test function') -and (-not $r57T5.out.Contains('plugin.py::')) -and (-not $r57T5.out.Contains('C4 wall-guard'))) `
            -Said (Get-R57Said -Tools 'tree' -Run $r57T5)

        # ---- (4b) TREE: a test wrapped by unittest.mock.patch is named by its own frame, not the wrapper's (found in review) ----
        Write-Utf8 -Path $r57Test -Text $r57PatchedTest
        $r57KeepPatched = Join-Path $r57Root '.mission-runtime\keep\r57-patched.pytest-output.txt'
        $r57T7 = Invoke-R57Run -Arguments ('-Member M2 -WallSeconds 60 -PerTestTimeoutSeconds 5 -KeepPytestOutput "' + $r57KeepPatched + '"') -TimeoutSeconds 150
        $r57T7Kept = Get-R57Kept -Path $r57KeepPatched
        $r57PatchedName = 'test_r57.py::test_patched_sleeper (line ' + $r57PatchedLine + ')'
        Add-R57Row -Label '(4b) TREE a test wrapped by unittest.mock.patch (its frame in the standard library, outside site-packages), -PerTestTimeoutSeconds 5 -WallSeconds 60 -KeepPytestOutput: the kept dump holds the wrapper''s frame and the test''s; the leading C5 and the WALL note name test_r57.py::test_patched_sleeper and its line, never mock.py::; exit 1, no C4' `
            -Ok (($r57T7.exit -eq 1) -and (-not $r57T7.timedOut) -and $r57T7Kept.text.Contains('mock.py') -and $r57T7Kept.text.Contains('in patched') -and $r57T7Kept.text.Contains('in test_patched_sleeper') -and
                 [regex]::IsMatch($r57T7.out, '(?m)^' + [regex]::Escape('FAIL M2 -- the product green gate is RED: C5 per-test-timeout [' + $r57PatchedName + ' ran past 5 s; the tree killed]')) -and
