        -Ok (($null -ne $r57R.exit) -and ($r57R.exit -ne 0) -and [regex]::IsMatch($r57R.out, '(?m)^' + [regex]::Escape($r57RWant) + '$') -and (-not $r57R.out.Contains(' M1 -- ')) -and (-not $r57R.out.Contains('TALLY ')) -and
