    Add-R57Row -Label '(7a) TREE the parameter as the parser reads it: Member, WallSeconds, KeepPytestOutput, then PerTestTimeoutSeconds LAST -- [ValidateRange(0, 86400)][int], default 0' `
        -Ok ((@($r57ParseErr).Count -eq 0) -and ($r57ParamNames -ceq 'Member WallSeconds KeepPytestOutput PerTestTimeoutSeconds') -and ($r57Range -ceq '0,86400') -and
             ($r57Last.StaticType -eq [int]) -and ($null -ne $r57Last.DefaultValue) -and ($r57Last.DefaultValue.Extent.Text -ceq '0')) `
        -Said ('parameters: ' + $r57ParamNames + '; the last''s ValidateRange: ' + $r57Range + '; type ' + $(if ($null -ne $r57Last) { $r57Last.StaticType } else { '' }) + '; default ' + $(if (($null -ne $r57Last) -and ($null -ne $r57Last.DefaultValue)) { $r57Last.DefaultValue.Extent.Text } else { '(none)' }))

