    Add-R57Row -Label '(8) the shared helper tools/lam/lam-instrument-run.ps1 is held to its pin: its bytes hash to blob 4f2503ae, the pinned blob' `
        -Ok ($r57HelperGot -ceq $r57HelperBlob) -Said ('git hash-object ' + $r57HelperRel + ' -> ' + $r57HelperGot)
    if (-not $r57Skip) {
        Write-Utf8 -Path $r57Test -Text $r57PassTest
        $r57EnvBefore = @{}
        foreach ($r57K in @('UV_PROJECT_ENVIRONMENT', 'UV_NO_SYNC', 'UV_OFFLINE')) { $r57EnvBefore[$r57K] = [Environment]::GetEnvironmentVariable($r57K, 'Process') }
        try {
            [Environment]::SetEnvironmentVariable('UV_PROJECT_ENVIRONMENT', $r57Venv, 'Process')
            [Environment]::SetEnvironmentVariable('UV_NO_SYNC', '1', 'Process')
            [Environment]::SetEnvironmentVariable('UV_OFFLINE', '1', 'Process')
            $r57Cap = Save-LamInstrumentRun -InstrumentPath $r57Inst -MissionRoot $r57Root -RunKey 'R57-FLAG-OFF'
        } finally {
            foreach ($r57K in @($r57EnvBefore.Keys)) { [Environment]::SetEnvironmentVariable($r57K, $r57EnvBefore[$r57K], 'Process') }
        }
        $r57CapKeys = ''
        if ($r57Cap.persisted -and (Test-Path -LiteralPath $r57Cap.stdout_path -PathType Leaf)) {
