    Add-R57Row -Label 'PLANE this tree''s instrument-runs unchanged since the member began; no process names the scratch root; the member''s own %TEMP% root is GONE after its teardown' `
        -Ok (($r57RunsAfter -ceq $r57RunsBefore) -and ($r57NamersLeft -eq 0) -and $r57Gone -and (-not (Test-Path -LiteralPath $r57Root))) `
        -Said ('instrument-runs equal: ' + ($r57RunsAfter -ceq $r57RunsBefore) + '; processes naming the root ' + $r57NamersLeft + '; ' + $r57Root + ' exists=' + (Test-Path -LiteralPath $r57Root) + $(if ($r57RmWhy -and -not $r57Gone) { '; Remove-Item said: ' + $r57RmWhy } else { '' }))
